INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('skillcreatorai/Ai-Agent-Skills/vercel-deploy', 'community', 'skillcreatorai', 'Ai-Agent-Skills', 'skillcreatorai/Ai-Agent-Skills', 'vercel-deploy', 0, 0, 40, '2026-02-20T04:13:19.578Z', '2026-02-20T04:54:58.123Z', '22878a184192800486298174d524851ddfbfbcd182714e9e20637582278f5c7d', '{"id":"skillcreatorai/Ai-Agent-Skills/vercel-deploy","name":"vercel-deploy","description":{"zh":"Vercel 部署技能允许您将应用程序部署到 Vercel，支持边缘函数、无服务器和 ISR。","ja":"Vercel デプロイ スキルは、アプリケーションを Vercel にデプロイし、エッジ関数、サーバーレス、ISR をサポートします。","ko":"버셀 배포 스킬을 사용하면 애플리케이션을 버셀에 배포하고 에지 함수, 서버리스, ISR을 지원할 수 있습니다.","es":"El despliegue en Vercel permite implementar aplicaciones con funciones de edge, servidor menos y regeneración estática incremental. Es ideal para aplicaciones Next.js","fr":"Le déploiement sur Vercel permet de mettre en œuvre des applications avec des fonctions de edge, un serveur moins et une régénération statique incrémentale. Il est idéal pour les applications Next.js","de":"Das Vercel-Deploy ermöglicht die Implementierung von Anwendungen mit Edge-Funktionen, serverloser Architektur und inkrementeller statischer Regeneration. Es ist ideal für Next.js-Anwendungen","pt":"O Vercel Deploy é uma habilidade do agente AI que permite implantar aplicativos no Vercel com funções de borda, servidor menos e ISR. Ele é ideal para implantação de aplicativos Next.js e configuração de funções de borda.","ru":"Vercel Deploy — это навык агента AI, который позволяет развернуть приложения на Vercel с помощью функций edge, serverless и ISR. Он идеален для развертывания приложений Next.js и настройки функций edge.","ar":"توزيع Vercel هو مهارة وسيط إصدار AI التي تمكن من توزيع التطبيقات على Vercel باستخدام وظائف الحافة والخادم أقل و ISR. وهو مثالي لتشغيل تطبيقات Next.js وضبط وظائف الحافة.","en":"Homebrew for AI Agent Skills."},"seo":{"title":{"zh":"Vercel 部署技能","ja":"Vercel デプロイ スキル","ko":"버셀 배포 스킬","es":"Despliegue en Vercel con funciones de edge y servidor menos","fr":"Déploiement Vercel avec des fonctions de edge et sans ser...","de":"Vercel-Deploy mit Edge-Funktionen und serverloser Archite...","pt":"Implantação Vercel: Desenvolvimento de Aplicativos","ru":"Vercel Deploy: Развертывание Приложений","ar":"توزيع Vercel: تطوير التطبيقات","en":"vercel-deploy"},"description":{"zh":"Vercel 部署技能允许您将应用程序部署到 Vercel，支持边缘函数、无服务器和 ISR。","ja":"Vercel デプロイ スキルは、アプリケーションを Vercel にデプロイし、エッジ関数、サーバーレス、ISR をサポートします。","ko":"버셀 배포 스킬을 사용하면 애플리케이션을 버셀에 배포하고 에지 함수, 서버리스, ISR을 지원할 수 있습니다.","es":"El despliegue en Vercel permite implementar aplicaciones con funciones de edge, servidor menos y regeneración estática incremental. Es ideal para aplicacione...","fr":"Le déploiement sur Vercel permet de mettre en œuvre des applications avec des fonctions de edge, un serveur moins et une régénération statique incrémentale. ...","de":"Das Vercel-Deploy ermöglicht die Implementierung von Anwendungen mit Edge-Funktionen, serverloser Architektur und inkrementeller statischer Regeneration. Es ...","pt":"O Vercel Deploy é uma habilidade do agente AI que permite implantar aplicativos no Vercel com funções de borda, servidor menos e ISR. Ele é ideal para implan...","ru":"Vercel Deploy — это навык агента AI, который позволяет развернуть приложения на Vercel с помощью функций edge, serverless и ISR. Он идеален для развертывания...","ar":"توزيع Vercel هو مهارة وسيط إصدار AI التي تمكن من توزيع التطبيقات على Vercel باستخدام وظائف الحافة والخادم أقل و ISR. وهو مثالي لتشغيل تطبيقات Next.js وضبط وظ...","en":"Homebrew for AI Agent Skills."},"definition":{"en":"Homebrew for AI Agent Skills."},"features":{"zh":["边缘函数","无服务器","ISR","Next.js 应用部署"],"ja":["エッジ関数","サーバーレス","ISR","Next.js アプリケーション デプロイ"],"ko":["에지 함수","서버리스","ISR","Next.js 애플리케이션 배포"],"es":["Despliegue de aplicaciones Next.js","Configuración de funciones de edge","Regeneración estática incremental","Despliegue sin servidor","Integración con Vercel"],"fr":["Déploiement d''applications Next.js","Configuration de fonctions de edge","Régénération statique incrémentale","Déploiement sans serveur","Intégration avec Vercel"],"de":["Bereitstellung von Next.js-Anwendungen","Konfiguration von Edge-Funktionen","Inkrementelle statische Regeneration","Serverlose Bereitstellung","Integration mit Vercel"],"pt":["Implantação de aplicativos Next.js","Configuração de funções de borda","ISR (Regeneração Estática Incremental)","Deploy servidor menos","Otimização de desempenho","Escalabilidade"],"ru":["Развертывание приложений Next.js","Настройка функций edge","ISR (Инкрементная Статическая Регенерация)","Развертывание serverless","Оптимизация производительности","Масштабируемость"],"ar":["تشغيل تطبيقات Next.js","ضبط وظائف الحافة","ISR (التجديد الثابت المتزايد)","نشر خادم أقل","تحسين الأداء","المرنة"]},"keywords":{"zh":["Vercel","部署","Next.js","边缘函数","无服务器","ISR","云计算"],"ja":["Vercel","デプロイ","Next.js","エッジ関数","サーバーレス","ISR","クラウド コンピューティング"],"ko":["버셀","배포","Next.js","에지 함수","서버리스","ISR","클라우드 컴퓨팅"],"es":["despliegue en Vercel","funciones de edge","servidor menos","regeneración estática incremental","Next.js","desarrollo de aplicaciones web"],"fr":["déploiement sur Vercel","fonctions de edge","serveur moins","régénération statique incrémentale","Next.js","développement d''applications web"],"de":["Vercel-Deploy","Edge-Funktionen","serverlose Architektur","inkrementelle statische Regeneration","Next.js","Webanwendungsentwicklung"],"pt":["Vercel Deploy","Implantação de aplicativos","Funções de borda","Serverless","ISR","Next.js","Desenvolvimento de aplicativos","Otimização de desempenho","Escalabilidade"],"ru":["Vercel Deploy","Развертывание приложений","Функции edge","Serverless","ISR","Next.js","Разработка приложений","Оптимизация производительности","Масштабируемость"],"ar":["توزيع Vercel","توزيع التطبيقات","وظائف الحافة","خادم أقل","ISR","Next.js","تطوير التطبيقات","تحسين الأداء","المرنة"]}},"owner":"skillcreatorai","repo":"Ai-Agent-Skills","repoPath":"skillcreatorai/Ai-Agent-Skills","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.578Z","topics":[],"category":"community","skillMd":{"name":"vercel-deploy","description":"Deploy applications to Vercel with edge functions, serverless, and ISR.","tags":["nextjs","node","typescript"],"bodyPreview":"# Vercel Deploy\n\nDeploy applications to Vercel with edge functions, serverless, and ISR.\n\n## When to Use\n\n- Deploying Next.js applications\n- Setting up edge functions\n- Configuring ISR (Incremental Static Regeneration)\n- Serverless deployments\n\n## Source\n\nThis skill references patterns from [Vercel''s agent-skills](https://github.com/vercel-labs/agent-skills).","body":"# Vercel Deploy\n\nDeploy applications to Vercel with edge functions, serverless, and ISR.\n\n## When to Use\n\n- Deploying Next.js applications\n- Setting up edge functions\n- Configuring ISR (Incremental Static Regeneration)\n- Serverless deployments\n\n## Source\n\nThis skill references patterns from [Vercel''s agent-skills](https://github.com/vercel-labs/agent-skills).\n"},"lastSynced":"2026-02-20T04:54:58.123Z","agentAnalysis":{"suitability":{"en":"Perfect for Full Stack Agents needing streamlined Next.js deployments with edge functions and serverless capabilities.","zh":"非常适合需要简化 Next.js 部署的全栈代理，拥有边缘函数和无服务器功能。","ja":"Next.js のデプロイをストリームライン化する必要があるフルスタックエージェントに最適です。エッジ関数とサーバーレス機能を備えています。","ko":"Next.js 배포를 간소화해야 하는 풀스택 에이전트에게 적합합니다. 에지 함수 및 서버리스 기능을 제공합니다.","es":"Perfecto para agentes Full Stack que necesitan despliegues de Next.js optimizados con funciones de edge y capacidades sin servidor.","fr":"Parfait pour les agents Full Stack nécessitant des déploiements Next.js rationalisés avec des fonctions de bord et des capacités sans serveur.","de":"Perfekt für Full-Stack-Agents, die optimierte Next.js-Deployments mit Edge-Funktionen und serverlosen Funktionen benötigen.","pt":"Perfeito para Agentes Full Stack que necessitam de implantações do Next.js otimizadas com funções de bordo e capacidades sem servidor.","ru":"Идеально подходит для агентов Full Stack, которым необходимы упрощенные развертывания Next.js с функциями edge и возможностями без сервера.","ar":"مثالي لعميل الوكلاء الكاملين الذين يحتاجون إلى توزيعات Next.js مبسطة مع وظائف حافة وقدرات بدون خادم."},"recommendation":{"en":"Empowers agents to deploy applications to Vercel with advanced features like edge functions, serverless, and Incremental Static Regeneration (ISR), leveraging Vercel''s agent-skills patterns for seamless integration with Next.js applications.","zh":"赋予代理部署应用于 Vercel 的能力，具有边缘函数、无服务器和增量静态再生成（ISR）等高级功能，利用 Vercel 的代理技能模式实现与 Next.js 应用的无缝集成。","ja":"エージェントに、エッジ関数、サーバーレス、インクリメンタル・スタティック・リジェネレーション（ISR）などの高度な機能を使用して、Vercel にアプリケーションをデプロイする能力を付与します。Vercel のエージェントスキルパターンを使用して、Next.js アプリケーションとのシームレスな統合を実現します。","ko":"에이전트가 Vercel에 애플리케이션을 배포할 수 있는 기능을 제공하며, 에지 함수, 서버리스, 증분 정적 재생성(ISR) 등의 고급 기능을 제공합니다. Vercel의 에이전트 스킬 패턴을 사용하여 Next.js 애플리케이션과의 無縫な 統合을 실현합니다.","es":"Habilita a los agentes para implementar aplicaciones en Vercel con funciones avanzadas como funciones de edge, sin servidor y Regeneración Estática Incremental (ISR), aprovechando los patrones de habilidades de agente de Vercel para una integración sin problemas con aplicaciones Next.js.","fr":"Permet aux agents de déployer des applications sur Vercel avec des fonctionnalités avancées telles que des fonctions de bord, sans serveur et régénération statique incrémentale (ISR), en exploitant les modèles de compétences d''agent de Vercel pour une intégration transparente avec les applications Next.js.","de":"Ermächtigt Agenten, Anwendungen auf Vercel mit erweiterten Funktionen wie Edge-Funktionen, Serverlos und inkrementeller statischer Regeneration (ISR) zu deployen, indem es die Agentenfähigkeitsmuster von Vercel nutzt, um eine nahtlose Integration mit Next.js-Anwendungen zu ermöglichen.","pt":"Habilita os agentes a implantar aplicações no Vercel com recursos avançados, como funções de bordo, sem servidor e Regeneração Estática Incremental (ISR), aproveitando os padrões de habilidades do agente do Vercel para integração perfeita com aplicações Next.js.","ru":"Наделяет агентов возможностью развертывать приложения в Vercel с продвинутыми функциями, такими как функции edge, без сервера и Инкрементная Статическая Регенерация (ISR), используя шаблоны навыков агента Vercel для бесшовной интеграции с приложениями Next.js.","ar":"يمنح الوكلاء القدرة على نشر التطبيقات على Vercel مع الميزات المتقدمة مثل وظائف حافة، بدون خادم وتجديد ثابت متزايد (ISR)، مستفيداً من أنماط مهارات الوكيل من Vercel من أجل التكامل السلس مع تطبيقات Next.js."},"useCases":{"en":["Deploying Next.js applications with optimized edge functions","Configuring Incremental Static Regeneration (ISR) for dynamic content","Setting up serverless deployments for scalable backend services"],"zh":["使用优化的边缘函数部署 Next.js 应用","配置增量静态再生成（ISR）以处理动态内容","设置服务器端部署以实现可扩展的后端服务"],"ja":["最適化されたエッジ関数を使用して Next.js アプリケーションをデプロイする","動的コンテンツのためにインクリメンタル・スタティック・リジェネレーション（ISR）を構成する","スケーラブルなバックエンドサービスを実現するためにサーバーレスデプロイを設定する"],"ko":["최적화된 에지 함수를 사용하여 Next.js 애플리케이션을 배포하는 것","동적 콘텐츠를 위해 증분 정적 재생성(ISR)을 구성하는 것","확장 가능한 백엔드 서비스를 위해 서버리스 배포를 설정하는 것"],"es":["Implementación de aplicaciones Next.js con funciones de edge optimizadas","Configuración de la Regeneración Estática Incremental (ISR) para contenido dinámico","Configuración de despliegues sin servidor para servicios de backend escalables"],"fr":["Déploiement d''applications Next.js avec des fonctions de bord optimisées","Configuration de la régénération statique incrémentale (ISR) pour du contenu dynamique","Configuration de déploiements sans serveur pour des services de backend évolutifs"],"de":["Bereitstellung von Next.js-Anwendungen mit optimierten Edge-Funktionen","Konfiguration der inkrementellen statischen Regeneration (ISR) für dynamischen Inhalt","Einrichtung von serverlosen Deployments für skalierbare Backend-Dienste"],"pt":["Implantação de aplicações Next.js com funções de bordo otimizadas","Configuração da Regeneração Estática Incremental (ISR) para conteúdo dinâmico","Configuração de implantações sem servidor para serviços de backend escaláveis"],"ru":["Развертывание приложений Next.js с оптимизированными функциями edge","Настройка Инкрементной Статической Регенерации (ISR) для динамического контента","Настройка развертываний без сервера для масштабируемых сервисов бэкэнда"],"ar":["نشر تطبيقات Next.js مع وظائف حافة محسنة","تكوين التجديد الثابت المتزايد (ISR) لمحتوى ديناميكي","تكوين توزيعات بدون خادم لخدمات الخلفية القابلة للتوسيع"]},"limitations":{"en":["Requires Vercel account and project setup","Limited to Next.js applications and compatible frameworks"],"zh":["需要 Vercel 账户和项目设置","仅限 Next.js 应用和兼容框架"],"ja":["Vercel アカウントとプロジェクトの設定が必要","Next.js アプリケーションと互換性のあるフレームワークのみ"],"ko":["Vercel 계정 및 프로젝트 설정이 필요합니다.","Next.js 애플리케이션 및 호환 프레임워크만 해당"],"es":["Requiere una cuenta y configuración de proyecto de Vercel","Limitado a aplicaciones Next.js y marcos compatibles"],"fr":["Nécessite un compte et une configuration de projet Vercel","Limité aux applications Next.js et aux frameworks compatibles"],"de":["Benötigt ein Vercel-Konto und eine Projektkonfiguration","Begrenzt auf Next.js-Anwendungen und kompatible Frameworks"],"pt":["Exige conta e configuração de projeto do Vercel","Limitado a aplicações Next.js e estruturas compatíveis"],"ru":["Требует учетной записи и настройки проекта Vercel","Ограничен приложениями Next.js и совместимыми фреймворками"],"ar":["يتطلب حساب و إعداد مشروع Vercel","محدود بتطبيقات Next.js و الإطارات المتوافقة"]},"version":3},"contentHash":"22878a184192800486298174d524851ddfbfbcd182714e9e20637582278f5c7d","qualityScore":40}');
