INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('skillcreatorai/Ai-Agent-Skills/vercel-deploy', 'vercel-deploy', 'skillcreatorai', 'Ai-Agent-Skills', 'community', 'vercel-deploy skillcreatorai Ai-Agent-Skills community Vercel 部署技能允许您将应用程序部署到 Vercel，支持边缘函数、无服务器和 ISR。 Vercel デプロイ スキルは、アプリケーションを Vercel にデプロイし、エッジ関数、サーバーレス、ISR をサポートします。 버셀 배포 스킬을 사용하면 애플리케이션을 버셀에 배포하고 에지 함수, 서버리스, ISR을 지원할 수 있습니다. El despliegue en Vercel permite implementar aplicaciones con funciones de edge, servidor menos y regeneración estática incremental. Es ideal para aplicaciones Next.js Le déploiement sur Vercel permet de mettre en œuvre des applications avec des fonctions de edge, un serveur moins et une régénération statique incrémentale. Il est idéal pour les applications Next.js Das Vercel-Deploy ermöglicht die Implementierung von Anwendungen mit Edge-Funktionen, serverloser Architektur und inkrementeller statischer Regeneration. Es ist ideal für Next.js-Anwendungen O Vercel Deploy é uma habilidade do agente AI que permite implantar aplicativos no Vercel com funções de borda, servidor menos e ISR. Ele é ideal para implantação de aplicativos Next.js e configuração de funções de borda. Vercel Deploy — это навык агента AI, который позволяет развернуть приложения на Vercel с помощью функций edge, serverless и ISR. Он идеален для развертывания приложений Next.js и настройки функций edge. توزيع Vercel هو مهارة وسيط إصدار AI التي تمكن من توزيع التطبيقات على Vercel باستخدام وظائف الحافة والخادم أقل و ISR. وهو مثالي لتشغيل تطبيقات Next.js وضبط وظائف الحافة. Homebrew for AI Agent Skills. Vercel 部署 Next.js 边缘函数 无服务器 ISR 云计算 Homebrew for AI Agent Skills.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ajiu9/skills/vite', 'community', 'ajiu9', 'skills', 'ajiu9/skills', 'vite', 0, 0, 40, '2026-02-20T04:13:19.580Z', '2026-02-20T05:05:19.247Z', '3cb7a75336e338faa9be15dd8b97479721ac8ceac6f1ff4061c9b9eefccd9983', '{"id":"ajiu9/skills/vite","name":"vite","description":{"zh":"Vite 是一个快速且高效的前端构建工具，支持 TypeScript 和 ES 模块","ja":"Vite は高速で効率的なフロントエンドビルドツールで、TypeScript と ES モジュールをサポートしています","ko":"Vite는 빠르고 효율적인 프론트엔드 빌드 도구로 TypeScript와 ES 모듈을 지원합니다","es":"Vite es una herramienta de compilación frontend de próxima generación con servidor de desarrollo rápido y construcciones de producción optimizadas","fr":"Vite est un outil de construction frontend de nouvelle génération avec serveur de développement rapide et constructions de production optimisées","de":"Vite ist ein Next-Generation-Frontend-Build-Tool mit schnellem Entwicklungsserver und optimierten Produktionsbuilds","pt":"Vite é uma ferramenta de build frontend de próxima geração, com servidor de desenvolvimento rápido e compilação de produção otimizada. Ela suporta TypeScript e ESM.","ru":"Vite - это инструмент построения frontend нового поколения, с быстрым сервером разработки и оптимизированным производством. Он поддерживает TypeScript и ESM.","ar":"Vite هي أداة بناء واجهة المستخدم الأمامية من الجيل التالي، مع خادم تطوير سريع وترجمة إنتاج محسنة. تدعم TypeScript و ESM.","en":"Ajiu9''s curated collection of agent skills."},"seo":{"title":{"zh":"Vite 前端构建工具","ja":"Vite フロントエンドビルドツール","ko":"Vite 프론트엔드 빌드 도구","es":"Vite: Herramienta de compilación frontend de próxima gene...","fr":"Vite: Outil de construction frontend de nouvelle génération","de":"Vite: Next-Generation-Frontend-Build-Tool","pt":"Vite: Ferramenta de Build Frontend de Próxima Geração","ru":"Vite: Инструмент построения frontend нового поколения","ar":"Vite: أداة بناء واجهة المستخدم الأمامية من الجيل التالي","en":"vite"},"description":{"zh":"Vite 是一个快速且高效的前端构建工具，支持 TypeScript 和 ES 模块","ja":"Vite は高速で効率的なフロントエンドビルドツールで、TypeScript と ES モジュールをサポートしています","ko":"Vite는 빠르고 효율적인 프론트엔드 빌드 도구로 TypeScript와 ES 모듈을 지원합니다","es":"Vite es una herramienta de compilación frontend de próxima generación con servidor de desarrollo rápido y construcciones de producción optimizadas","fr":"Vite est un outil de construction frontend de nouvelle génération avec serveur de développement rapide et constructions de production optimisées","de":"Vite ist ein Next-Generation-Frontend-Build-Tool mit schnellem Entwicklungsserver und optimierten Produktionsbuilds","pt":"Vite é uma ferramenta de build frontend de próxima geração, com servidor de desenvolvimento rápido e compilação de produção otimizada. Ela suporta TypeScript...","ru":"Vite - это инструмент построения frontend нового поколения, с быстрым сервером разработки и оптимизированным производством. Он поддерживает TypeScript и ESM.","ar":"Vite هي أداة بناء واجهة المستخدم الأمامية من الجيل التالي، مع خادم تطوير سريع وترجمة إنتاج محسنة. تدعم TypeScript و ESM.","en":"Ajiu9''s curated collection of agent skills."},"definition":{"en":"Ajiu9''s curated collection of agent skills."},"features":{"zh":["快速开发服务器","优化的生产构建","TypeScript 支持","ES 模块支持","条件配置"],"ja":["高速な開発サーバー","最適化されたプロダクションビルド","TypeScript サポート","ES モジュールサポート","条件コンフィグ"],"ko":["빠른 개발 서버","최적화된 프로덕션 빌드","TypeScript 지원","ES 모듈 지원","조건부 구성"],"es":["Servidor de desarrollo rápido con ESM y HMR","Construcciones de producción optimizadas","Compatibilidad con TypeScript","Uso de Rolldown y Oxc","Configuración condicional","Carga de entornos"],"fr":["Serveur de développement rapide avec ESM et HMR","Constructions de production optimisées","Compatibilité avec TypeScript","Utilisation de Rolldown et Oxc","Configuration conditionnelle","Chargement des environnements"],"de":["Schneller Entwicklungsserver mit ESM und HMR","Optimierte Produktionsbuilds","Unterstützung für TypeScript","Verwendung von Rolldown und Oxc","Bedingte Konfiguration","Laden von Umgebungen"],"pt":["Servidor de desenvolvimento rápido","Compilação de produção otimizada","Suporte a TypeScript","Suporte a ESM","Configuração condicional","Carregamento de ambiente"],"ru":["Быстрый сервер разработки","Оптимизированное производство","Поддержка TypeScript","Поддержка ESM","Условная конфигурация","Загрузка окружения"],"ar":["خادم تطوير سريع","ترجمة إنتاج محسنة","دعم TypeScript","دعم ESM","تكوين شرطي","تحميل البيئة"]},"keywords":{"zh":["Vite","前端构建工具","TypeScript","ES 模块","快速开发服务器","优化的生产构建"],"ja":["Vite","フロントエンドビルドツール","TypeScript","ES モジュール","高速な開発サーバー","最適化されたプロダクションビルド"],"ko":["Vite","프론트엔드 빌드 도구","TypeScript","ES 모듈","빠른 개발 서버","최적화된 프로덕션 빌드"],"es":["Vite","herramienta de compilación frontend","Rolldown","Oxc","TypeScript","ESM","HMR","desarrollo frontend","construcción de producción"],"fr":["Vite","outil de construction frontend","Rolldown","Oxc","TypeScript","ESM","HMR","développement frontend","construction de production"],"de":["Vite","Frontend-Build-Tool","Rolldown","Oxc","TypeScript","ESM","HMR","Frontend-Entwicklung","Produktionsbuild"],"pt":["Vite","ferramenta de build frontend","servidor de desenvolvimento rápido","compilação de produção otimizada","TypeScript","ESM","desenvolvimento web"],"ru":["Vite","инструмент построения frontend","быстрый сервер разработки","оптимизированное производство","TypeScript","ESM","веб-разработка"],"ar":["Vite","أداة بناء واجهة المستخدم الأمامية","خادم تطوير سريع","ترجمة إنتاج فعالة","TypeScript","ESM","تطوير الويب"]}},"owner":"ajiu9","repo":"skills","repoPath":"ajiu9/skills","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.580Z","topics":[],"category":"community","skillMd":{"name":"vite","description":"Vite build tool configuration, plugin API, SSR, and Vite 8 Rolldown migration. Use when working with Vite projects, vite.config.ts, Vite plugins, or building libraries/SSR apps with Vite.","version":"2026.1.31","bodyPreview":"# Vite\n\n> Based on Vite 8 beta (Rolldown-powered). Vite 8 uses Rolldown bundler and Oxc transformer.\n\nVite is a next-generation frontend build tool with fast dev server (native ESM + HMR) and optimized production builds.\n\n## Preferences\n\n- Use TypeScript: prefer `vite.config.ts`\n- Always use ESM, avoid CommonJS\n\n## Core\n\n| Topic | Description | Reference |\n|-------|-------------|-----------|\n| Configuration | `vite.config.ts`, `defineConfig`, conditional configs, `loadEnv` | [core-config](refere","body":"# Vite\n\n> Based on Vite 8 beta (Rolldown-powered). Vite 8 uses Rolldown bundler and Oxc transformer.\n\nVite is a next-generation frontend build tool with fast dev server (native ESM + HMR) and optimized production builds.\n\n## Preferences\n\n- Use TypeScript: prefer `vite.config.ts`\n- Always use ESM, avoid CommonJS\n\n## Core\n\n| Topic | Description | Reference |\n|-------|-------------|-----------|\n| Configuration | `vite.config.ts`, `defineConfig`, conditional configs, `loadEnv` | [core-config](references/core-config.md) |\n| Features | `import.meta.glob`, asset queries (`?raw`, `?url`), `import.meta.env`, HMR API | [core-features](references/core-features.md) |\n| Plugin API | Vite-specific hooks, virtual modules, plugin ordering | [core-plugin-api](references/core-plugin-api.md) |\n\n## Build & SSR\n\n| Topic | Description | Reference |\n|-------|-------------|-----------|\n| Build & SSR | Library mode, SSR middleware mode, `ssrLoadModule`, JavaScript API | [build-and-ssr](references/build-and-ssr.md) |\n\n## Advanced\n\n| Topic | Description | Reference |\n|-------|-------------|-----------|\n| Environment API | Vite 6+ multi-environment support, custom runtimes | [environment-api](references/environment-api.md) |\n| Rolldown Migration | Vite 8 changes: Rolldown bundler, Oxc transformer, config migration | [rolldown-migration](references/rolldown-migration.md) |\n\n## Quick Reference\n\n### CLI Commands\n\n```bash\nvite              # Start dev server\nvite build        # Production build\nvite preview      # Preview production build\nvite build --ssr  # SSR build\n```\n\n### Common Config\n\n```ts\nimport { defineConfig } from ''vite''\n\nexport default defineConfig({\n  plugins: [],\n  resolve: { alias: { ''@'': ''/src'' } },\n  server: { port: 3000, proxy: { ''/api'': ''http://localhost:8080'' } },\n  build: { target: ''esnext'', outDir: ''dist'' },\n})\n```\n\n### Official Plugins\n\n- `@vitejs/plugin-vue` - Vue 3 SFC support\n- `@vitejs/plugin-vue-jsx` - Vue 3 JSX\n- `@vitejs/plugin-react` - React with Oxc/Babel\n- `@vitejs/plugin-react-swc` - React with SWC\n- `@vitejs/plugin-legacy` - Legacy browser support\n"},"lastSynced":"2026-02-20T05:05:19.247Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Development Agents requiring rapid and optimized build processes with native ESM and HMR support.","zh":"适用于需要快速和优化的构建过程，支持原生 ESM 和 HMR 的前端开发代理。","ja":"ネイティブの ESM と HMR をサポートする高速化されたビルド プロセスを必要とするフロントエンド開発エージェントに最適です。","ko":"네이티브 ESM과 HMR를 지원하는 빠르고 최적화된 빌드 프로세스가 필요한 프론트엔드 개발 에이전트에 적합합니다.","es":"Ideal para Agentes de Desarrollo Frontend que requieren procesos de compilación rápidos y optimizados con soporte nativo de ESM y HMR.","fr":"Idéal pour les agents de développement frontend nécessitant des processus de construction rapides et optimisés avec un support natif ESM et HMR.","de":"Ideal für Frontend-Entwicklungsagenten, die schnelle und optimierte Build-Prozesse mit nativem ESM- und HMR-Unterstützung erfordern.","pt":"Ideal para agentes de desenvolvimento frontend que requerem processos de compilação rápidos e otimizados com suporte nativo a ESM e HMR.","ru":"Идеально подходит для агентов разработки frontend, требующих быстрых и оптимизированных процессов сборки с родной поддержкой ESM и HMR.","ar":"مثالي لوكلاء تطوير الواجهة الأمامية الذين يحتاجون إلى عمليات بناء سريعة ومحسنة مع دعم أصلي لـ ESM و HMR."},"recommendation":{"en":"Empowers agents to leverage Vite''s fast dev server and optimized production builds, utilizing Rolldown bundler and Oxc transformer for enhanced performance, while preferring TypeScript and ESM over CommonJS.","zh":"赋予代理使用 Vite 快速的开发服务器和优化的生产构建，利用 Rolldown 捆绑器和 Oxc 转换器来提高性能，同时更喜欢使用 TypeScript 和 ESM 而不是 CommonJS。","ja":"Vite の高速開発サーバーと最適化されたプロダクション ビルドを利用し、Rolldown バンドラーと Oxc トランスフォーマーを使用してパフォーマンスを向上させ、TypeScript と ESM を CommonJS よりも好みます。","ko":"Vite의 빠른 개발 서버와 최적화된 프로덕션 빌드를 사용하고, Rolldown 번들러와 Oxc 트랜스포ーマ를 사용하여 성능을 향상시키며, TypeScript와 ESM을 CommonJS보다 선호합니다.","es":"Habilita a los agentes a aprovechar el servidor de desarrollo rápido de Vite y las compilaciones de producción optimizadas, utilizando el empacador Rolldown y el transformador Oxc para un rendimiento mejorado, prefiriendo TypeScript y ESM sobre CommonJS.","fr":"Permet aux agents de tirer parti du serveur de développement rapide de Vite et des builds de production optimisés, en utilisant le bundleur Rolldown et le transformateur Oxc pour des performances améliorées, en préférant TypeScript et ESM à CommonJS.","de":"Ermächtigt Agenten, Vites schnellen Dev-Server und optimierte Produktionsbuilds zu nutzen, indem sie den Rolldown-Bundler und den Oxc-Transformer für verbesserte Leistung verwenden, wobei TypeScript und ESM gegenüber CommonJS bevorzugt werden.","pt":"Habilita os agentes a aproveitar o servidor de desenvolvimento rápido do Vite e compilações de produção otimizadas, utilizando o empacotador Rolldown e o transformador Oxc para desempenho aprimorado, preferindo TypeScript e ESM em relação ao CommonJS.","ru":"Наделяет агентов возможностью использовать быстрый сервер разработки Vite и оптимизированные сборки для производства, используя пакетный менеджер Rolldown и трансформатор Oxc для повышения производительности, отдавая предпочтение TypeScript и ESM над CommonJS.","ar":"تمكّن الوكلاء من الاستفادة من خادم التطوير السريع من Vite وعمليات البناء المُحسنة للإنتاج، باستخدام حزمة Rolldown ومحول Oxc لتحسين الأداء، مع تفضيل TypeScript و ESM على CommonJS."},"useCases":{"en":["Configuring Vite projects with conditional configs and environment variables using `vite.config.ts` and `loadEnv`","Optimizing frontend builds for production with Vite''s native ESM and HMR capabilities","Developing high-performance web applications with Vite''s Rolldown-powered bundler and Oxc transformer"],"zh":["使用 `vite.config.ts` 和 `loadEnv` 配置 Vite 项目，包括条件配置和环境变量","使用 Vite 的原生 ESM 和 HMR 功能优化前端构建以适应生产环境","使用 Vite 的 Rolldown 驱动的捆绑器和 Oxc 转换器开发高性能 Web 应用程序"],"ja":["Vite プロジェクトを `vite.config.ts` と `loadEnv` で設定し、条件設定と環境変数を使用する","Vite のネイティブ ESM と HMR 機能を使用して、フロントエンド ビルドをプロダクション環境に最適化する","Vite の Rolldown駆動のバンドラーと Oxc トランスフォーマーを使用して、高パフォーマンスの Web アプリケーションを開発する"],"ko":["Vite 프로젝트를 `vite.config.ts`와 `loadEnv`로 설정하고, 조건 설정과 환경 변수를 사용한다","Vite의 네이티브 ESM과 HMR 기능을 사용하여 프론트엔드 빌드를 프로덕션 환경에 최적화한다","Vite의 Rolldown 기반 번들러와 Oxc 트랜스포머를 사용하여 고성능 웹 애플리케이션을 개발한다"],"es":["Configuración de proyectos Vite con configuraciones condicionales y variables de entorno mediante `vite.config.ts` y `loadEnv`","Optimización de compilaciones frontend para producción con las capacidades nativas de ESM y HMR de Vite","Desarrollo de aplicaciones web de alto rendimiento con el bundleador Rolldown y el transformador Oxc de Vite"],"fr":["Configuration de projets Vite avec des configurations conditionnelles et des variables d''environnement à l''aide de `vite.config.ts` et `loadEnv`","Optimisation des builds frontend pour la production avec les capacités natives ESM et HMR de Vite","Développement d''applications web à haute performance avec le bundleur Rolldown et le transformateur Oxc de Vite"],"de":["Konfiguration von Vite-Projekten mit bedingten Konfigurationen und Umgebungsvariablen unter Verwendung von `vite.config.ts` und `loadEnv`","Optimierung von Frontend-Builds für die Produktion mit den nativen ESM- und HMR-Funktionen von Vite","Entwicklung von High-Performance-Webanwendungen mit dem von Vite bereitgestellten Rolldown-Bundler und Oxc-Transformer"],"pt":["Configurando projetos Vite com configurações condicionais e variáveis de ambiente usando `vite.config.ts` e `loadEnv`","Otimizando compilações frontend para produção com as capacidades nativas de ESM e HMR do Vite","Desenvolvendo aplicações web de alto desempenho com o empacotador Rolldown e o transformador Oxc do Vite"],"ru":["Настройка проектов Vite с условными конфигурациями и переменными среды с помощью `vite.config.ts` и `loadEnv`","Оптимизация сборок frontend для производства с помощью родных возможностей ESM и HMR Vite","Разработка веб-приложений с высоким уровнем производительности с помощью пакетного менеджера Rolldown и трансформатора Oxc Vite"],"ar":["تكوين مشاريع Vite باستخدام التهيئة الشرطية ومتغيرات البيئة باستخدام `vite.config.ts` و `loadEnv`","تحسين عمليات البناء الأمامية للإنتاج باستخدام القدرات الأصلية لـ ESM و HMR من Vite","تطوير تطبيقات الويب ذات الأداء العالي باستخدام حزمة Rolldown ومحول Oxc من Vite"]},"limitations":{"en":["Requires TypeScript preference for `vite.config.ts`","Limited to ESM, avoiding CommonJS for optimal performance"],"zh":["需要对 `vite.config.ts` 有 TypeScript 首选项","仅限 ESM，避免使用 CommonJS 以获得最佳性能"],"ja":["TypeScript を `vite.config.ts` に対して優先する必要がある","CommonJS を避け、ESM に限定して最高のパフォーマンスを実現する"],"ko":["TypeScript를 `vite.config.ts`에 대해 선호해야 한다","CommonJS를 피하고 ESM에 한정하여 최상의 성능을 달성한다"],"es":["Requiere preferencia de TypeScript para `vite.config.ts`","Limitado a ESM, evitando CommonJS para un rendimiento óptimo"],"fr":["Nécessite une préférence pour TypeScript pour `vite.config.ts`","Limité à ESM, en évitant CommonJS pour des performances optimales"],"de":["Benötigt eine Vorliebe für TypeScript für `vite.config.ts`","Begrenzt auf ESM, wobei CommonJS zur Erzielung eines optimalen Leistungsverhaltens vermieden wird"],"pt":["Exige preferência por TypeScript para `vite.config.ts`","Limitado a ESM, evitando CommonJS para desempenho ótimo"],"ru":["Требует предпочтения TypeScript для `vite.config.ts`","Ограничен до ESM, избегая CommonJS для оптимальной производительности"],"ar":["يتطلب تفضيلًا لـ TypeScript من أجل `vite.config.ts`","محدود بـ ESM، وتجنب CommonJS من أجل أداء مثالي"]},"version":3},"contentHash":"3cb7a75336e338faa9be15dd8b97479721ac8ceac6f1ff4061c9b9eefccd9983","qualityScore":40}');
