INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ajiu9/skills/vite', 'vite', 'ajiu9', 'skills', 'community', 'vite ajiu9 skills community Vite 是一个快速且高效的前端构建工具，支持 TypeScript 和 ES 模块 Vite は高速で効率的なフロントエンドビルドツールで、TypeScript と ES モジュールをサポートしています Vite는 빠르고 효율적인 프론트엔드 빌드 도구로 TypeScript와 ES 모듈을 지원합니다 Vite es una herramienta de compilación frontend de próxima generación con servidor de desarrollo rápido y construcciones de producción optimizadas Vite est un outil de construction frontend de nouvelle génération avec serveur de développement rapide et constructions de production optimisées Vite ist ein Next-Generation-Frontend-Build-Tool mit schnellem Entwicklungsserver und optimierten Produktionsbuilds Vite é uma ferramenta de build frontend de próxima geração, com servidor de desenvolvimento rápido e compilação de produção otimizada. Ela suporta TypeScript e ESM. Vite - это инструмент построения frontend нового поколения, с быстрым сервером разработки и оптимизированным производством. Он поддерживает TypeScript и ESM. Vite هي أداة بناء واجهة المستخدم الأمامية من الجيل التالي، مع خادم تطوير سريع وترجمة إنتاج محسنة. تدعم TypeScript و ESM. Ajiu9''s curated collection of agent skills. Vite 前端构建工具 TypeScript ES 模块 快速开发服务器 优化的生产构建 Ajiu9''s curated collection of agent skills.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/worktree', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'worktree', 0, 0, 40, '2026-02-20T04:13:19.580Z', '2026-02-20T05:05:44.668Z', '023acb413e9a81cbdedcc3096f07569077afcf8a55f7d57ba5d961ad7c397f38', '{"id":"majiayu000/claude-skill-registry/worktree","name":"worktree","description":{"zh":"Worktree技能用于管理Git工作树中的任务，通过workmux启动任务，实现自动化","ja":"Worktreeスキルは、Gitワークツリー内のタスクを管理し、workmuxを使用してタスクを起動して自動化する","ko":"워크트리 스킬은 깃 작업 트리 내의 태스크를 관리하며 workmux를 사용하여 태스크를 시작하여 자동화를 구현합니다","es":"Worktree es una herramienta que permite lanzar una o más tareas en nuevos entornos Git utilizando workmux, mejorando la eficiencia en el desarrollo de software.","fr":"Worktree est un outil qui permet de lancer une ou plusieurs tâches dans de nouveaux environnements Git en utilisant workmux, améliorant ainsi l''efficacité dans le développement de logiciels.","de":"Worktree ist ein Tool, das es ermöglicht, eine oder mehrere Aufgaben in neuen Git-Arbeitsbereichen mit workmux zu starten, wodurch die Effizienz in der Softwareentwicklung verbessert wird.","pt":"O worktree é uma ferramenta que permite lançar tarefas em novos worktrees Git, melhorando a produtividade e a organização do desenvolvimento","ru":"Worktree — это инструмент, который позволяет запускать задачи в новых ветках Git, улучшая производительность и организацию разработки","ar":"Worktree هو أداة تسمح بإطلاق المهام في trabajoات Git الجديدة، مما يحسن الإنتاجية والتنظيم التطويري","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"Worktree技能：Git工作树任务管理","ja":"Worktreeスキル：Gitワークツリータスク管理","ko":"워크트리 스킬: 깃 작업 트리 태스크 관리","es":"Worktree: Lanzamiento de tareas en nuevos entornos Git","fr":"Worktree : Lancement de tâches dans de