INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/worktree', 'worktree', 'majiayu000', 'claude-skill-registry', 'community', 'worktree majiayu000 claude-skill-registry community Worktree技能用于管理Git工作树中的任务，通过workmux启动任务，实现自动化 Worktreeスキルは、Gitワークツリー内のタスクを管理し、workmuxを使用してタスクを起動して自動化する 워크트리 스킬은 깃 작업 트리 내의 태스크를 관리하며 workmux를 사용하여 태스크를 시작하여 자동화를 구현합니다 Worktree es una herramienta que permite lanzar una o más tareas en nuevos entornos Git utilizando workmux, mejorando la eficiencia en el desarrollo de software. Worktree est un outil qui permet de lancer une ou plusieurs tâches dans de nouveaux environnements Git en utilisant workmux, améliorant ainsi l''efficacité dans le développement de logiciels. Worktree ist ein Tool, das es ermöglicht, eine oder mehrere Aufgaben in neuen Git-Arbeitsbereichen mit workmux zu starten, wodurch die Effizienz in der Softwareentwicklung verbessert wird. O worktree é uma ferramenta que permite lançar tarefas em novos worktrees Git, melhorando a produtividade e a organização do desenvolvimento Worktree — это инструмент, который позволяет запускать задачи в новых ветках Git, улучшая производительность и организацию разработки Worktree هو أداة تسمح بإطلاق المهام في trabajoات Git الجديدة، مما يحسن الإنتاجية والتنظيم التطويري The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app Worktree Git工作树 任务管理 workmux 自动化 开发效率 Git技能 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
