INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('antfu/skills/vite', 'vite', 'antfu', 'skills', 'community', 'vite antfu skills community Vite AIエージェント提供了构建工具配置、插件API、SSR和Vite 8迁移等功能，帮助开发者提高开发效率 Vite AIエージェントは、ビルドツール設定、プラグインAPI、SSR、Vite 8ロールダウン移行などを提供し、開発者の開発効率を向上させます Vite AI 에이전트는 빌드 툴 구성, 플러그인 API, SSR 및 Vite 8 마이그레이션 등을 제공하여 개발자의 개발 효율성을 높여줍니다 Vite es una herramienta de construcción de proyectos web que ofrece una configuración flexible y una API de plugins para mejorar la productividad de los desarrolladores Vite est un outil de construction de projets web qui offre une configuration flexible et une API de plugins pour améliorer la productivité des développeurs Vite ist ein Tool zur Erstellung von Webprojekten, das eine flexible Konfiguration und eine Plugin-API zur Steigerung der Produktivität von Entwicklern bietet Vite é uma ferramenta de build para projetos JavaScript, permitindo configuração de plugins e SSR para melhorar a produtividade Vite - это билд тул для проектов JavaScript, позволяющий конфигурировать плагины и SSR для повышения производительности Vite هي أداة بناء لمشاريع JavaScript، تتيح تكوين الإضافات و SSR لتحسين الإنتاجية Vite build tool configuration, plugin API, SSR, and Vite 8 Rolldown migration. Use when working with Vite projects, vite.config.ts, Vite plugins, or building libraries/SSR apps with Vite. Vite AIエージェント Vite构建工具 插件API SSR Vite 8迁移 如何使用Vite Vite教程 Vite插件 Vite替代品 Vite build tool configuration, plugin API, SSR, and Vite 8 Rolldown migration. Use when working with Vite projects, vite.config.ts, Vite plugins, or building libraries/SSR apps with Vite.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HoangNguyen0403/agent-skills-standard/React Native State Management', 'community', 'HoangNguyen0403', 'agent-skills-standard', 'HoangNguyen0403/agent-skills-standard', 'React Native State Management', 0, 0, 40, '2026-02-20T04:13:19.578Z', '2026-03-01T07:22:56.403Z', '8938fd178b2fca43f23c18c8e64ffa9f3b8b26222debad908d84ccccdd52179a', '{"id":"HoangNguyen0403/agent-skills-standard/React Native State Management","name":"React Native State Management","description":{"zh":"React Native状态管理使用Context、Zustand和Redux Toolkit实现本地和全局状态模式","ja":"React Nativeステート管理は、Context、Zustand、Redux Toolkitを使用してローカルとグローバルステートパターンを実現します","ko":"리액트 네이티브 상태 관리는 Context, Zustand, Redux Toolkit을 사용하여 로컬 및 글로벌 상태 패턴을 구현합니다","es":"Aprende sobre patrones de estado local y global con Context, Zustand y Redux Toolkit para mejorar tus habilidades en React Native","fr":"Apprenez sur les modèles d''état local et global avec Context, Zustand et Redux Toolkit pour améliorer vos compétences en React Native","de":"Lernen Sie über lokale und globale Statusmuster mit Context, Zustand und Redux Toolkit, um Ihre Fähigkeiten in React Native zu verbessern","pt":"Desenvolva aplicativos React Native com gerenciamento de estado eficaz usando Context, Zustand e Redux Toolkit","ru":"Разрабатывайте приложения React Native с эффективным управлением состоянием с помощью Context, Zustand и Redux Toolkit","ar":"طور تطبيقات React Native مع إدارة حالة فعالة باستخدام Context وZustand وRedux Toolkit","en":"Local and global state patterns with Context, Zustand, and Redux Toolkit."},"seo":{"title":{"zh":"AIエージェント：React Native状态管理","ja":"AIエージェント：React Nativeステート管理","ko":"AI 에이전트: 리액트 네이티브 상태 관리","es":"Herramientas de Estado de React Native","fr":"Outils d''état React Native","de":"React Native State Management Tools","pt":"Ferramentas de Estado React Native - Gerenciamento de Estado","ru":"ИИ Агенты: Управление Состоянием в React Native","ar":"أدوات إدارة الحالة في React Native - Ferramentas de Estado","en":"React Native State Management"},"description":{"zh":"React Native状态管理使用Context、Zustand和Redux Toolkit实现本地和全局状态模式","ja":"React Nativeステート管理は、Context、Zustand、Redux Toolkitを使用してローカルとグローバルステートパターンを実現します","ko":"리액트 네이티브 상태 관리는 Context, Zustand, Redux Toolkit을 사용하여 로컬 및 글로벌 상태 패턴을 구현합니다","es":"Aprende sobre patrones de estado local y global con Context, Zustand y Redux Toolkit para mejorar tus habilidades en React Native","fr":"Apprenez sur les modèles d''état local et global avec Context, Zustand et Redux Toolkit pour améliorer vos compétences en React Native","de":"Lernen Sie über lokale und globale Statusmuster mit Context, Zustand und Redux Toolkit, um Ihre Fähigkeiten in React Native zu verbessern","pt":"Desenvolva aplicativos React Native com gerenciamento de estado eficaz usando Context, Zustand e Redux Toolkit","ru":"Разрабатывайте приложения React Native с эффективным управлением состоянием с помощью Context, Zustand и Redux Toolkit","ar":"طور تطبيقات React Native مع إدارة حالة فعالة باستخدام Context وZustand وRedux Toolkit","en":"Local and global state patterns with Context, Zustand, and Redux Toolkit."},"definition":{"en":"Local and global state patterns with Context, Zustand, and Redux Toolkit."},"features":{"zh":["使用Context实现本地状态管理","使用Zustand实现全局状态管理","使用Redux Toolkit实现复杂状态管理","支持React Native的状态管理","提供简单易用的API","提高开发效率"],"ja":["Contextを使用してローカルステート管理を実現","Zustandを使用してグローバルステート管理を実現","Redux Toolkitを使用して複雑なステート管理を実現","React Nativeのステート管理をサポート","シンプルで使いやすいAPIを提供","開発効率を向上させる"],"ko":["Context를 사용하여 로컬 상태 관리를 구현","Zustand를 사용하여 글로벌 상태 관리를 구현","Redux Toolkit을 사용하여 복잡한 상태 관리를 구현","리액트 네이티브의 상태 관리를 지원","간단하고 사용하기 쉬운 API를 제공","개발 효율성을 높입니다"],"es":["Patrones de estado local y global","Integración con Context","Uso de Zustand para la gestión de estado","Implementación de Redux Toolkit","Mejora de la escalabilidad de la aplicación","Optimización del rendimiento de la aplicación"],"fr":["Modèles d''état local et global","Intégration avec Context","Utilisation de Zustand pour la gestion d''état","Mise en œuvre de Redux Toolkit","Amélioration de la scalabilité de l''application","Optimisation des performances de l''application"],"de":["Lokale und globale Statusmuster","Integration mit Context","Verwendung von Zustand für die Statusverwaltung","Implementierung von Redux Toolkit","Verbesserung der Skalierbarkeit der Anwendung","Optimierung der Leistung der Anwendung"],"pt":["Padrões de estado local e global","Integração com Context","Uso de Zustand para gerenciamento de estado","Implementação de Redux Toolkit","Melhoria da performance do aplicativo","Simplificação do código"],"ru":["Шаблоны локального и глобального состояния","Интеграция с Context","Использование Zustand для управления состоянием","Реализация Redux Toolkit","Улучшение производительности приложения","Упрощение кода"],"ar":["أنماط الحالة المحلية والعالمية","التكامل مع Context","استخدام Zustand لإدارة الحالة","تنفيذ Redux Toolkit","تحسين أداء التطبيق","بسيطية الكود"]},"keywords":{"zh":["React Native状态管理","Context","Zustand","Redux Toolkit","如何使用React Native状态管理","React Native状态管理教程","React Native状态管理库","React Native状态管理工具","React Native状态管理示例"],"ja":["React Nativeステート管理","Context","Zustand","Redux Toolkit","React Nativeステート管理の使い方","React Nativeステート管理チュートリアル","React Nativeステート管理ライブラリ","React Nativeステート管理ツール","React Nativeステート管理サンプル"],"ko":["리액트 네이티브 상태 관리","Context","Zustand","Redux Toolkit","리액트 네이티브 상태 관리 사용법","리액트 네이티브 상태 관리 튜토리얼","리액트 네이티브 상태 관리 라이브러리","리액트 네이티브 상태 관리 도구","리액트 네이티브 상태 관리 예시"],"es":["cómo usar React Native","qué es la administración de estado","alternativas a Redux","React Native vs Flutter","instalación de Redux Toolkit","guía de configuración de Zustand","patrones de estado en React Native","mejora del rendimiento de React Native"],"fr":["comment utiliser React Native","qu''est-ce que la gestion d''état","alternatives à Redux","React Native vs Flutter","installation de Redux Toolkit","guide de configuration de Zustand","modèles d''état dans React Native","amélioration des performances de React Native"],"de":["wie man React Native verwendet","was ist die Statusverwaltung","Alternativen zu Redux","React Native vs Flutter","Installation von Redux Toolkit","Konfigurationshandbuch für Zustand","Statusmuster in React Native","Leistungsverbesserung von React Native"],"pt":["react native state management","context api","zustand","redux toolkit","como usar react native","o que é gerenciamento de estado","alternativas para react native","react native vs flutter","instalar react native","guia de configuração do react native"],"ru":["управление состоянием react native","context api","zustand","redux toolkit","как использовать react native","что такое управление состоянием","альтернативы для react native","react native vs flutter","установить react native","руководство по настройке react native"],"ar":["إدارة الحالة في react native","context api","zustand","redux toolkit","كيفية استخدام react native","ما هي إدارة الحالة","بديلات ل react native","react native مقابل flutter","تثبيت react native","دليل إعداد react native"]}},"owner":"HoangNguyen0403","repo":"agent-skills-standard","repoPath":"HoangNguyen0403/agent-skills-standard","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.578Z","topics":[],"category":"community","skillMd":{"name":"React Native State Management","description":"Local and global state patterns with Context, Zustand, and Redux Toolkit.","bodyPreview":"# React Native State Management\n\n## **Priority: P1 (OPERATIONAL)**\n\n## State Strategy\n\n- **Local State**: Use `useState` for component-scoped state (forms, UI toggles).\n- **Lifted State**: Share between siblings via parent component.\n- **Context**: Share across components without prop drilling (theme, auth).\n- **Zustand**: Lightweight global state for small-medium apps.\n- **Redux Toolkit**: Complex apps with time-travel debugging needs.\n- **Server State**: Use `@tanstack/react-query` for API dat","body":"# React Native State Management\n\n## **Priority: P1 (OPERATIONAL)**\n\n## State Strategy\n\n- **Local State**: Use `useState` for component-scoped state (forms, UI toggles).\n- **Lifted State**: Share between siblings via parent component.\n- **Context**: Share across components without prop drilling (theme, auth).\n- **Zustand**: Lightweight global state for small-medium apps.\n- **Redux Toolkit**: Complex apps with time-travel debugging needs.\n- **Server State**: Use `@tanstack/react-query` for API data (caching, refetching).\n\n```tsx\nconst ThemeContext = createContext<ThemeContextType | undefined>(undefined);\n\nexport function useTheme() {\n  const ctx = useContext(ThemeContext);\n  if (!ctx) throw new Error(''useTheme must be inside ThemeProvider'');\n  return ctx;\n}\n```\n\n## Zustand (Recommended for Most Apps)\n\n```tsx\nimport { create } from ''zustand'';\n\nconst useStore = create((set) => ({\n  count: 0,\n  increment: () => set((state) => ({ count: state.count + 1 })),\n}));\n\n// Usage\nconst count = useStore((state) => state.count);\n```\n\n## Anti-Patterns\n\n- **No Redux for Everything**: Start with Context/Zustand.\n- **No Prop Drilling**: Use Context for global state.\n- **No Derived State in State**: Compute in render.\n\n## Reference & Examples\n\nSee [references/REFERENCE.md](references/REFERENCE.md).\n\n## Related Topics\n\nreact/state-management | react/hooks\n"},"lastSynced":"2026-03-01T07:22:56.403Z","agentAnalysis":{"suitability":{"en":"Essential for React Native Development Agents handling complex application state across components.","zh":"对于处理跨组件复杂应用程序状态的React Native开发智能体至关重要。","ja":"コンポーネント間の複雑なアプリケーション状態を扱うReact Native開発エージェントにとって必須です。","ko":"컴포넌트 간의 복잡한 애플리케이션 상태를 처리하는 React Native 개발 에이전트에게 필수적입니다.","es":"Esencial para los Agents de desarrollo de React Native que manejan el estado complejo de la aplicación entre componentes.","fr":"Essentiel pour les Agents de développement React Native gérant l''état d''application complexe entre les composants.","de":"Essenziell für React Native Development Agents, die komplexen Anwendungszustand über Komponenten hinweg handhaben.","pt":"Essencial para Agentes de Desenvolvimento React Native que lidam com estados de aplicação complexos entre componentes.","ru":"Необходим для агентов разработки React Native, работающих со сложным состоянием приложения между компонентами.","ar":"أساسي لوكلاء تطوير React Native الذين يتعاملون مع حالة التطبيق المعقدة عبر المكونات."},"recommendation":{"en":"Enables precise state management strategy selection from local useState hooks to global Zustand or Redux Toolkit stores. Provides best practices for avoiding prop drilling with Context API and handling server state with @tanstack/react-query.","zh":"支持从本地useState钩子到全局Zustand或Redux Toolkit存储库的精确状态管理策略选择。提供使用Context API避免属性钻取以及使用@tanstack/react-query处理服务器状态的最佳实践。","ja":"ローカルのuseStateフックからグローバルなZustandまたはRedux Toolkitストアまで、精密な状態管理戦略の選択を可能にします。Context APIを使用したプロップドリリングの回避と、@tanstack/react-queryを使用したサーバー状態の処理に関するベストプラクティスを提供します。","ko":"로컬 useState 훅에서 전역 Zustand 또는 Redux Toolkit 스토어에 이르는 정밀한 상태 관리 전략 선택을 가능하게 합니다. Context API를 사용한 prop drilling 회피 및 @tanstack/react-query를 사용한 서버 상태 처리에 대한 모범 사례를 제공합니다.","es":"Permite una selección precisa de la estrategia de gestión de estado, desde los hooks locales de useState hasta las stores globales de Zustand o Redux Toolkit. Proporciona las mejores prácticas para evitar el prop drilling con la Context API y manejar el estado del servidor con @tanstack/react-query.","fr":"Permet une sélection précise de la stratégie de gestion d''état, des hooks locaux useState aux stores globaux de Zustand ou Redux Toolkit. Fournit les meilleures pratiques pour éviter le prop drilling avec la Context API et gérer l''état du serveur avec @tanstack/react-query.","de":"Ermöglicht eine präzise Auswahl der State-Management-Strategie, von lokalen useState-Hooks bis zu globalen Zustand- oder Redux Toolkit-Stores. Bietet Best Practices zur Vermeidung von Prop Drilling mit der Context API und zur Handhabung des Serverzustands mit @tanstack/react-query.","pt":"Permite a seleção precisa de estratégias de gerenciamento de estado, desde hooks useState locais até stores globais como Zustand ou Redux Toolkit. Fornece melhores práticas para evitar prop drilling com Context API e gerenciar estado do servidor com @tanstack/react-query.","ru":"Позволяет точно выбирать стратегии управления состоянием: от локальных хуков useState до глобальных хранилищ Zustand или Redux Toolkit. Предоставляет лучшие практики для избежания prop drilling с помощью Context API и управления состоянием сервера с @tanstack/react-query.","ar":"يُمكّن الاختيار الدقيق لاستراتيجية إدارة الحالة من hooks محلية مثل useState إلى مخازن عامة مثل Zustand أو Redux Toolkit. يقدم أفضل الممارسات لتجنب prop drilling باستخدام Context API والتعامل مع حالة الخادم باستخدام @tanstack/react-query."},"useCases":{"en":["Implementing form state management with useState","Setting up global authentication state with Context","Optimizing API data caching with react-query","Debugging state flows with Redux Toolkit devtools"],"zh":["使用useState实现表单状态管理","使用Context设置全局认证状态","使用react-query优化API数据缓存","使用Redux Toolkit开发工具调试状态流"],"ja":["useStateを使用したフォーム状態管理の実装","Contextを使用したグローバル認証状態の設定","react-queryを使用したAPIデータキャッシュの最適化","Redux Toolkit devtoolsを使用した状態フローのデバッグ"],"ko":["useState로 폼 상태 관리 구현","Context로 전역 인증 상태 설정","react-query로 API 데이터 캐싱 최적화","Redux Toolkit devtools로 상태 흐름 디버깅"],"es":["Implementar la gestión del estado de formularios con useState","Configurar el estado global de autenticación con Context","Optimizar el almacenamiento en caché de datos de API con react-query","Depurar flujos de estado con las devtools de Redux Toolkit"],"fr":["Mettre en œuvre la gestion d''état de formulaire avec useState","Configurer l''état global d''authentification avec Context","Optimiser la mise en cache des données d''API avec react-query","Déboguer les flux d''état avec les devtools de Redux Toolkit"],"de":["Implementierung der Formularzustandsverwaltung mit useState","Einrichten des globalen Authentifizierungszustands mit Context","Optimieren der API-Datencaching mit react-query","Debugging von Zustandsflüssen mit den Redux Toolkit Devtools"],"pt":["Implementação de gerenciamento de estado de formulários com useState","Configuração de estado global de autenticação com Context","Otimização de cache de dados de API com react-query","Depuração de fluxos de estado com Redux Toolkit devtools"],"ru":["Реализация управления состоянием форм с помощью useState","Настройка глобального состояния аутентификации с Context","Оптимизация кэширования данных API с react-query","Отладка потоков состояния с помощью Redux Toolkit devtools"],"ar":["تنفيذ إدارة حالة النماذج باستخدام useState","إعداد حالة المصادقة العامة باستخدام Context","تحسين تخزين بيانات API مؤقتًا باستخدام react-query","تصحيح تدفقات الحالة باستخدام أدوات تطوير Redux Toolkit"]},"limitations":{"en":["Requires React Native project context","Different strategies suit different app scales","Server state management depends on API integration"],"zh":["需要React Native项目上下文","不同的策略适用于不同规模的应用程序","服务器状态管理依赖于API集成"],"ja":["React Nativeプロジェクトのコンテキストが必要","異なる戦略は異なるアプリケーション規模に適する","サーバー状態管理はAPI統合に依存"],"ko":["React Native 프로젝트 컨텍스트 필요","다른 전략은 다른 앱 규모에 적합함","서버 상태 관리는 API 통합에 의존함"],"es":["Requiere el contexto de un proyecto React Native","Diferentes estrategias se adaptan a diferentes escalas de aplicación","La gestión del estado del servidor depende de la integración de la API"],"fr":["Nécessite le contexte d''un projet React Native","Différentes stratégies conviennent à différentes échelles d''application","La gestion de l''état du serveur dépend de l''intégration de l''API"],"de":["Erfordert den Kontext eines React Native-Projekts","Verschiedene Strategien eignen sich für unterschiedliche App-Größen","Die Serverzustandsverwaltung hängt von der API-Integration ab"],"pt":["Requer contexto de projeto React Native","Diferentes estratégias se adequam a diferentes escalas de aplicativo","O gerenciamento de estado do servidor depende da integração com API"],"ru":["Требует контекст проекта React Native","Разные стратегии подходят для приложений разного масштаба","Управление состоянием сервера зависит от интеграции с API"],"ar":["يتطلب سياق مشروع React Native","استراتيجيات مختلفة مناسبة لتطبيقات بمقاييس مختلفة","إدارة حالة الخادم تعتمد على تكامل API"]},"version":3},"contentHash":"8938fd178b2fca43f23c18c8e64ffa9f3b8b26222debad908d84ccccdd52179a","qualityScore":40}');
