INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sushichan044/dotfiles/prepare-issue-pr', 'prepare-issue-pr', 'sushichan044', 'dotfiles', 'community', 'prepare-issue-pr sushichan044 dotfiles community The prepare-issue-pr skill automates Issue and Pull Request preparation, adhering to repository templates and best practices, benefiting developers and repository maintainers prepare-issue-pr 是一个 Issue/PR 准备专家，自动创建全面的问题和拉取请求描述，严格遵循仓库模板和最佳实践 prepare-issue-pr は、Issue/PR 準備スペシャリストで、リポジトリ テンプレートとベスト プラクティスに厳密に従った、包括的で構造化された Issue/PR 説明を自動的に作成します prepare-issue-pr는 이슈/PR 준비 전문가로 저장소 템플릿 및 최선의 관행을 엄격히 따르는 포괄적이고 구조화된 이슈/PR 설명을 자동으로 생성합니다 Prepare-issue-pr es una herramienta especializada en la creación de descripciones de Issue y Pull Request estructuradas y personalizadas según las plantillas del repositorio Prepare-issue-pr est un outil spécialisé dans la création de descriptions de Issue et Pull Request structurées et personnalisées selon les modèles de référentiel Prepare-issue-pr ist ein spezialisiertes Tool für die Erstellung strukturierter und personalisierter Issue- und Pull-Request-Beschreibungen nach Repository-Vorlagen O prepare-issue-pr é uma ferramenta que ajuda a criar descrições de Issue e Pull Request bem estruturadas, utilizando tecnologias como detecção de tipo e indicadores de Issue e PR Prepare-issue-pr - это инструмент, который помогает создавать описания Issue и Pull Request, которые соответствуют шаблонам и лучшим практикам репозитория, используя технологии типа обнаружения и индикаторов Issue и PR prepare-issue-pr هو أداة تساعد في إنشاء وصفات مشكلة وطلب سحب متوافقة مع قوالب المستودع وأفضل الممارسات، مستخدمة تقنيات مثل الكشف عن النوع ومؤشرات المشكلة وطلب السحب how to use prepare-issue-pr prepare-issue-pr setup guide prepare-issue-pr alternative prepare-issue-pr vs GitHub templates automated issue and pr setup repository template best practices prepare-issue-pr install prepare-issue-pr for AI agents prepare-issue-pr 自动化问题和拉取请求 仓库模板 最佳实践 AIエージェント 自动化工具 Automatically determines whether to prepare an Issue or Pull Request based on context Detects Issue indicators such as ''issue'', ''bug report'', and ''feature request'' Detects PR indicators such as ''PR'', ''pull request'', and ''プルリク'' Generates descriptions that strictly adhere to repository templates and best practices Supports multiple languages, including English and Japanese prepare-issue-pr is a skill that automatically prepares comprehensive and well-structured Issue and Pull Request descriptions');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('brainqub3/brainqub3/crm-sync', 'community', 'brainqub3', 'brainqub3', 'brainqub3/brainqub3', 'crm-sync', 10, 11, 39, '2026-02-07T19:18:14Z', '2026-03-06T06:46:27.455Z', '7adca2a73636fdef2fbf6fb85ab6eb9c6b7ce1bc7f95eb2d90d5b72bddf76fba', '{"id":"brainqub3/brainqub3/crm-sync","name":"crm-sync","description":{"en":"crm-sync is a technical solution that synchronizes leads from Zoho CRM into a local SQLite database, ideal for businesses and individuals seeking data integration. It provides a structured database schema for efficient lead management.","zh":"crm-sync是一款将Zoho CRM leads同步到本地SQLite数据库的工具，支持leads和leads_history表的管理","ja":"crm-syncはZoho CRMのリードをローカルのSQLiteデータベースに同期するツールで、leadsとleads_historyテーブルの管理をサポートします","ko":"crm-sync는 Zoho CRM 리드를 로컬 SQLite 데이터베이스에 동기화하는 도구로, 리드 및 리드 기록 테이블 관리를 지원합니다","es":"crm-sync es una herramienta para sincronizar leads de Zoho CRM con una base de datos SQLite local","fr":"crm-sync est un outil pour synchroniser les leads de Zoho CRM avec une base de données SQLite locale","de":"crm-sync ist ein Tool zur Synchronisierung von Leads von Zoho CRM mit einer lokalen SQLite-Datenbank","pt":"O crm-sync é uma ferramenta que sincroniza leads do Zoho CRM com um banco de dados SQLite local, oferecendo uma segunda cérebro para negócios e necessidades pessoais","ru":"crm-sync - это инструмент, который синхронизирует лиды из Zoho CRM с локальной базой данных SQLite, предоставляя второй мозг для бизнеса и личных нужд","ar":"crm-sync هي أداة لتزامن الرصيد من Zoho CRM مع قاعدة بيانات SQLite المحلية، وتقدم دماغًا ثانيًا للأعمال والاحتياجات الشخصية"},"seo":{"title":{"en":"crm-sync: SQLite Database Setup Guide | AI Agent Skill","zh":"crm-sync同步指南：Zoho CRM_lead同步工具","ja":"crm-syncセットアップガイド：Zoho CRMとの連携","ko":"crm-sync 설정 가이드: Zoho CRM 리드 동기화 솔루션","es":"crm-sync: Guía de configuración para sincronización de leads","fr":"crm-sync: Guide de mise en œuvre pour la synchronisation ...","de":"crm-sync: Einrichtungsleitfaden für Lead-Synchronisation","pt":"crm-sync: Guia de Configuração para Sincronização de Leads","ru":"crm-sync: Руководство по настройке синхронизации лидов с ...","ar":"crm-sync: دليل إعداد التزامن للرصيد مع أدوات الذكاء الاصط..."},"description":{"en":"Discover how to sync Zoho CRM leads with a local SQLite database using crm-sync. Learn to set up and optimize your workflow now!","zh":"crm-sync是一款将Zoho CRM leads同步到本地SQLite数据库的工具，提供leads和leads_history表的管理","ja":"crm-syncはZoho CRMのリードをローカルのSQLiteデータベースに同期するツールで、leadsとleads_historyテーブルの管理を提供します","ko":"crm-sync는 Zoho CRM 리드를 로컬 SQLite 데이터베이스에 동기화하는 도구로, 리드 및 리드 기록 테이블 관리를 제공합니다","es":"Aprende a sincronizar leads de Zoho CRM con la base de datos SQLite local utilizando crm-sync","fr":"Découvrez comment synchroniser les leads de Zoho CRM avec la base de données SQLite locale à l''aide de crm-sync","de":"Erfahren Sie, wie Sie Leads von Zoho CRM mit der lokalen SQLite-Datenbank mithilfe von crm-sync synchronisieren","pt":"Aprenda a sincronizar leads do Zoho CRM com um banco de dados SQLite local usando o crm-sync, uma ferramenta de segunda cérebro para negócios e necessidades ...","ru":"Узнайте, как синхронизировать лиды из Zoho CRM с локальной базой данных SQLite с помощью crm-sync, второго мозга для бизнеса и личных нужд, от ИИ Агентов","ar":"تعرف على كيفية مزامنة الرصيد من Zoho CRM مع قاعدة بيانات SQLite المحلية باستخدام crm-sync، وهي أداة للدماغ الثاني للأعمال والاحتياجات الشخصية مع أدوات الذكاء..."},"definition":{"en":"crm-sync is a skill that enables synchronization of Zoho CRM leads with a local SQLite database, utilizing a predefined schema for organized data storage.","zh":"crm-sync是一款AI工具，用于同步Zoho CRM leads到本地数据库","ja":"crm-syncはAIエージェントの一種で、Zoho CRMのリードをローカルのデータベースに同期する","ko":"crm-sync는 AI 도구의 일종으로, Zoho CRM 리드를 로컬 데이터베이스에 동기화합니다","es":"crm-sync es una herramienta de sincronización de leads que utiliza Zoho CRM y SQLite","fr":"crm-sync est un outil de synchronisation de leads qui utilise Zoho CRM et SQLite","de":"crm-sync ist ein Tool zur Lead-Synchronisierung, das Zoho CRM und SQLite verwendet","pt":"crm-sync é uma ferramenta de sincronização de leads que utiliza um banco de dados SQLite local para armazenar informações de contatos","ru":"crm-sync - это инструмент синхронизации лидов, который использует локальную базу данных SQLite для хранения информации о контактах","ar":"crm-sync هي أداة لتزامن الرصيد التي تستخدم قاعدة بيانات SQLite المحلية لتخزين معلومات الاتصال"},"features":{"en":["Synchronizes leads from Zoho CRM into a local SQLite database","Utilizes a predefined database schema defined in scripts/crm/db_schema.sql","Stores lead data in the ''leads'' table with fields such as id, first_name, and email","Maintains an audit trail in the ''leads_history'' table with captured_at and chang fields","Supports local timestamps for created_at and updated_at fields","Retrieves Zoho record ID and Modified_Time for each lead"],"zh":["支持Zoho CRM leads同步到本地SQLite数据库","提供leads表的管理，包括id、first_name、last_name、company、email、phone、lead_source、description等字段","提供leads_history表的管理，包括所有leads字段及captured_at和chang等字段","支持本地timestamps和Zoho modified_time的管理","使用scripts/crm/db_schema.sql定义数据库schema"],"ja":["Zoho CRMのリードをローカルのSQLiteデータベースに同期する","leadsテーブルの管理を提供する，包括id、first_name、last_name、company、email、phone、lead_source、description等フィールド","leads_historyテーブルの管理を提供する，包括すべてのleadsフィールド及captured_atとchang等フィールド","ローカルのタイムスタンプとZoho modified_timeの管理をサポートする","scripts/crm/db_schema.sqlを使用してデータベースschemaを定義する"],"ko":["Zoho CRM 리드를 로컬 SQLite 데이터베이스에 동기화하는 기능","리드 테이블 관리 기능，包括 id、first_name、last_name、company、email、phone、lead_source、description 등 필드","리드 기록 테이블 관리 기능，包括 모든 리드 필드 및 captured_at과 chang 등 필드","로컬 타임스탬프와 Zoho modified_time 관리 기능","scripts/crm/db_schema.sql을 사용하여 데이터베이스 스키마를 정의하는 기능"],"es":["Sincronización de leads de Zoho CRM con base de datos SQLite local","Almacenamiento de leads en la tabla ''leads'' con campos como id, first_name, last_name, company, email, phone, lead_source, description","Registro de cambios en la tabla ''leads_history'' con campos como captured_at y chang","Uso de esquema de base de datos definido en scripts/crm/db_schema.sql","Soporte para timestamps locales y zoho_modified_time"],"fr":["Synchronisation des leads de Zoho CRM avec la base de données SQLite locale","Stockage des leads dans la table ''leads'' avec des champs tels que id, first_name, last_name, company, email, phone, lead_source, description","Enregistrement des modifications dans la table ''leads_history'' avec des champs tels que captured_at et chang","Utilisation d''un schéma de base de données défini dans scripts/crm/db_schema.sql","Prise en charge des timestamps locaux et zoho_modified_time"],"de":["Synchronisierung von Leads von Zoho CRM mit lokaler SQLite-Datenbank","Speicherung von Leads in der Tabelle ''leads'' mit Feldern wie id, first_name, last_name, company, email, phone, lead_source, description","Aufzeichnung von Änderungen in der Tabelle ''leads_history'' mit Feldern wie captured_at und chang","Verwendung eines Datenbankschemas, das in scripts/crm/db_schema.sql definiert ist","Unterstützung für lokale Timestamps und zoho_modified_time"],"pt":["Sincronização de leads do Zoho CRM com banco de dados SQLite local","Armazenamento de informações de contatos em tabelas ''leads'' e ''leads_history''","Utilização de esquema de banco de dados definido em ''scripts/crm/db_schema.sql''","Suporte a timestamps locais e Zoho modified time","Auditoria de alterações em leads com tabela ''leads_history''"],"ru":["Синхронизация лидов из Zoho CRM с локальной базой данных SQLite","Хранение информации о контактах в таблицах ''leads'' и ''leads_history''","Использование схемы базы данных, определенной в ''scripts/crm/db_schema.sql''","Поддержка локальных временных меток и времени модификации Zoho","Аудит изменений лидов с таблицей ''leads_history''"],"ar":["تزامن الرصيد من Zoho CRM مع قاعدة بيانات SQLite المحلية","تخزين معلومات الاتصال في جداول ''leads'' و ''leads_history''","استخدام مخطط قاعدة البيانات المحدد في ''scripts/crm/db_schema.sql''","دعم للتوقيتات المحلية ووقت التعديل Zoho","مراجعة التغييرات على الرصيد مع جدول ''leads_history''"]},"keywords":{"en":["how to use crm-sync","crm-sync setup guide","Zoho CRM lead sync","SQLite database integration","crm-sync alternative","crm-sync vs Zoho CRM","crm-sync install","what is crm-sync","crm-sync for AI Agents","crm-sync database schema"],"zh":["crm-sync","Zoho CRM同步","SQLite数据库","leads管理","AI工具","crm同步工具","Zoho CRM lead同步","数据同步","数据库管理"],"ja":["crm-sync","Zoho CRM同期","SQLiteデータベース","リード管理","AIエージェント","crm同期ツール","Zoho CRMリード同期","データ同期","データベース管理"],"ko":["crm-sync","Zoho CRM 동기화","SQLite 데이터베이스","리드 관리","AI 도구","crm 동기화 도구","Zoho CRM 리드 동기화","데이터 동기화","데이터베이스 관리"],"es":["crm-sync","sincronización de leads","Zoho CRM","SQLite","base de datos local","leads","tabla leads","tabla leads_history","esquema de base de datos","timestamps locales"],"fr":["crm-sync","synchronisation de leads","Zoho CRM","SQLite","base de données locale","leads","table leads","table leads_history","schéma de base de données","timestamps locaux"],"de":["crm-sync","Lead-Synchronisierung","Zoho CRM","SQLite","lokale Datenbank","Leads","Tabelle leads","Tabelle leads_history","Datenbankschema","lokale Timestamps"],"pt":["crm-sync","sincronização de leads","Zoho CRM","banco de dados SQLite","segunda cérebro para negócios","ferramenta de sincronização","armazenamento de contatos","esquema de banco de dados"],"ru":["crm-sync","синхронизация лидов","Zoho CRM","локальная база данных SQLite","второй мозг для бизнеса","инструмент синхронизации","хранение контактов","схема базы данных","ИИ Агенты"],"ar":["crm-sync","تزامن الرصيد","Zoho CRM","قاعدة بيانات SQLite المحلية","دماغ ثاني للأعمال","أداة التزامن","تخزين الاتصال","مخطط قاعدة البيانات","أدوات الذكاء الاصطناعي"]}},"owner":"brainqub3","repo":"brainqub3","repoPath":"brainqub3/brainqub3","stars":10,"forks":11,"updatedAt":"2026-02-07T19:18:14Z","topics":[],"category":"community","skillMd":{"name":"crm-sync","description":"Sync leads from Zoho CRM into the local SQLite database. Fetches all leads, performs upserts with change detection, and maintains full audit history.","bodyPreview":"# crm-sync (CRM Lead Sync)\n\nSynchronise leads from Zoho CRM into the local SQLite database.\n\n## Database\n\n- **Path**: `raw/crm/crm.db`\n- **Schema**: `scripts/crm/db_schema.sql`\n\n### Tables\n\n**leads** (current state):\n- id (TEXT PRIMARY KEY) - Zoho record ID\n- first_name, last_name, company, email, phone, lead_source, description\n- created_at, updated_at - local timestamps\n- zoho_modified_time - Modified_Time from Zoho\n\n**leads_history** (audit trail):\n- All lead fields plus captured_at and chang","body":"# crm-sync (CRM Lead Sync)\n\nSynchronise leads from Zoho CRM into the local SQLite database.\n\n## Database\n\n- **Path**: `raw/crm/crm.db`\n- **Schema**: `scripts/crm/db_schema.sql`\n\n### Tables\n\n**leads** (current state):\n- id (TEXT PRIMARY KEY) - Zoho record ID\n- first_name, last_name, company, email, phone, lead_source, description\n- created_at, updated_at - local timestamps\n- zoho_modified_time - Modified_Time from Zoho\n\n**leads_history** (audit trail):\n- All lead fields plus captured_at and change_type (''insert'', ''update'', ''delete'')\n\n**sync_log** (sync metadata):\n- started_at, completed_at, records_fetched, records_inserted, records_updated, status, error_message\n\n## Procedure\n\n### Step 1: Initialise Database\n\nEnsure the database exists with correct schema:\n\n```bash\nmkdir -p raw/crm\nsqlite3 raw/crm/crm.db < scripts/crm/db_schema.sql\n```\n\n### Step 2: Start Sync Log\n\n```bash\nsqlite3 raw/crm/crm.db \"INSERT INTO sync_log (started_at, status) VALUES (datetime(''now''), ''running''); SELECT last_insert_rowid();\"\n```\n\nSave the returned ID for later update.\n\n### Step 3: Fetch Leads from Zoho\n\nUse `mcp__zoho-crm__ZohoCRM_Get_Records`:\n- module: \"Leads\"\n- fields: \"id,First_Name,Last_Name,Company,Email,Phone,Lead_Source,Description,Modified_Time\"\n\nHandle pagination if more than one page of results.\n\n### Step 4: Upsert Each Lead\n\nFor each lead returned from Zoho:\n\n**4a. Check if exists:**\n```bash\nsqlite3 raw/crm/crm.db \"SELECT id, zoho_modified_time FROM leads WHERE id = ''{lead_id}'';\"\n```\n\n**4b. If new lead** (not in database):\n```bash\nsqlite3 raw/crm/crm.db \"\nINSERT INTO leads (id, first_name, last_name, company, email, phone, lead_source, description, created_at, updated_at, zoho_modified_time)\nVALUES (''{id}'', ''{first_name}'', ''{last_name}'', ''{company}'', ''{email}'', ''{phone}'', ''{lead_source}'', ''{description}'', datetime(''now''), datetime(''now''), ''{modified_time}'');\n\nINSERT INTO leads_history (lead_id, first_name, last_name, company, email, phone, lead_source, description, captured_at, change_type)\nVALUES (''{id}'', ''{first_name}'', ''{last_name}'', ''{company}'', ''{email}'', ''{phone}'', ''{lead_source}'', ''{description}'', datetime(''now''), ''insert'');\n\"\n```\n\n**4c. If existing and Zoho version is newer** (compare zoho_modified_time):\n```bash\nsqlite3 raw/crm/crm.db \"\n-- Capture old version to history\nINSERT INTO leads_history (lead_id, first_name, last_name, company, email, phone, lead_source, description, captured_at, change_type)\nSELECT id, first_name, last_name, company, email, phone, lead_source, description, datetime(''now''), ''update''\nFROM leads WHERE id = ''{id}'';\n\n-- Update the lead\nUPDATE leads SET\n  first_name = ''{first_name}'',\n  last_name = ''{last_name}'',\n  company = ''{company}'',\n  email = ''{email}'',\n  phone = ''{phone}'',\n  lead_source = ''{lead_source}'',\n  description = ''{description}'',\n  updated_at = datetime(''now''),\n  zoho_modified_time = ''{modified_time}''\nWHERE id = ''{id}'';\n\"\n```\n\n**4d. If unchanged** (same or older zoho_modified_time): Skip.\n\n### Step 5: Update Sync Log\n\nOn success:\n```bash\nsqlite3 raw/crm/crm.db \"\nUPDATE sync_log SET\n  completed_at = datetime(''now''),\n  records_fetched = {fetched},\n  records_inserted = {inserted},\n  records_updated = {updated},\n  status = ''completed''\nWHERE id = {sync_id};\n\"\n```\n\nOn failure:\n```bash\nsqlite3 raw/crm/crm.db \"\nUPDATE sync_log SET\n  completed_at = datetime(''now''),\n  status = ''failed'',\n  error_message = ''{error}''\nWHERE id = {sync_id};\n\"\n```\n\n### Step 6: Report Results\n\nOutput a summary:\n- Records fetched\n- New leads inserted\n- Existing leads updated\n- Unchanged (skipped)\n- Any errors\n\n## Field Mapping\n\n| Zoho Field     | Database Column      |\n|----------------|----------------------|\n| id             | id                   |\n| First_Name     | first_name           |\n| Last_Name      | last_name            |\n| Company        | company              |\n| Email          | email                |\n| Phone          | phone                |\n| Lead_Source    | lead_source          |\n| Description    | description          |\n| Modified_Time  | zoho_modified_time   |\n\n## Error Handling\n\n- If MCP credentials are missing: Report what''s needed\n- If API rate limits hit: Wait and retry, or report partial progress\n- If database errors occur: Log to sync_log with error_message\n- Always update sync_log status even on failure\n\n## Privacy\n\n- Do not display full email addresses or phone numbers in output\n- Show redacted summaries unless user explicitly requests full details\n"},"lastSynced":"2026-03-06T06:46:27.455Z","agentAnalysis":{"suitability":{"en":"Ideal for Data Integration Agents requiring seamless Zoho CRM and SQLite synchronization.","zh":"适用于需要无缝Zoho CRM和SQLite同步的数据集成代理。","ja":"Zoho CRMとSQLiteのシームレスな同期を必要とするデータ統合エージェントに最適です。","ko":"Zoho CRM과 SQLite의 무шов적 동기화를 필요로 하는 데이터 통합 에이전트에 적합합니다.","es":"Ideal para agentes de integración de datos que requieren una sincronización perfecta de Zoho CRM y SQLite.","fr":"Idéal pour les agents d''intégration de données nécessitant une synchronisation transparente de Zoho CRM et SQLite.","de":"Ideal für Data-Integration-Agents, die eine nahtlose Zoho CRM- und SQLite-Synchronisierung erfordern.","pt":"Ideal para Agentes de Integração de Dados que requerem sincronização sem interrupções do Zoho CRM e do SQLite.","ru":"Идеально для агентов интеграции данных, требующих бесшовной синхронизации Zoho CRM и SQLite.","ar":"مثالي للوكلاء المتعاونين مع البيانات الذين يحتاجون إلى تناسق بدون انقطاع بين Zoho CRM و SQLite."},"recommendation":{"en":"Empowers agents to synchronize leads from Zoho CRM into a local SQLite database, utilizing a structured database schema for efficient lead management with SQLite and Zoho API integration.","zh":"赋予代理同步Zoho CRM中的线索到本地SQLite数据库的能力，利用结构化数据库模式实现高效的线索管理，通过SQLite和Zoho API集成。","ja":"エージェントがZoho CRM内のリードをローカルのSQLiteデータベースに同期する機能を提供し、構造化されたデータベーススキーマを使用して効率的なリード管理と、SQLiteおよびZoho APIの統合を実現します。","ko":"에이전트가 Zoho CRM 내의 리드를 로컬 SQLite 데이터베이스로 동기화 할 수 있는 능력을 부여하여, 구조화된 데이터베이스 스키마를 사용하여 효율적인 리드 관리와 SQLite 및 Zoho API 통합을 제공합니다.","es":"Habilita a los agentes a sincronizar prospectos desde Zoho CRM en una base de datos SQLite local, utilizando un esquema de base de datos estructurado para una gestión de prospectos eficiente con integración de Zoho API y SQLite.","fr":"Permet aux agents de synchroniser les prospects depuis Zoho CRM vers une base de données SQLite locale, en utilisant un schéma de base de données structuré pour une gestion efficace des prospects avec l''intégration de l''API Zoho et SQLite.","de":"Ermächtigt Agenten, Leads von Zoho CRM in eine lokale SQLite-Datenbank zu synchronisieren, indem sie ein strukturiertes Datenbankschema für eine effiziente Leadverwaltung mit Zoho API- und SQLite-Integration nutzen.","pt":"Habilita os agentes a sincronizar os leads do Zoho CRM em um banco de dados SQLite local, utilizando um esquema de banco de dados estruturado para gerenciamento eficiente de leads com integração da API do Zoho e do SQLite.","ru":"Наделяет агентов возможностью синхронизировать лиды из Zoho CRM в локальную базу данных SQLite, используя структурированную схему базы данных для эффективного управления лидами с интеграцией API Zoho и SQLite.","ar":"يمنح الوكلاء القدرة على مزامنة المصادر من Zoho CRM إلى قاعدة بيانات SQLite محلية، باستخدام مخطط قاعدة بيانات منظم لادارة المصادر بكفاءة مع دمج واجهة برمجة التطبيقات Zoho و SQLite."},"useCases":{"en":["Synchronizing leads from Zoho CRM","Managing lead data in a local SQLite database","Auditing lead history with captured changes"],"zh":["从Zoho CRM同步线索","在本地SQLite数据库中管理线索数据","使用捕获的更改来审计线索历史"],"ja":["Zoho CRMからリードを同期する","ローカルのSQLiteデータベースでリードデータを管理する","キャプチャされた変更を使用してリード履歴を監査する"],"ko":["Zoho CRM에서 리드를 동기화하는 것","로컬 SQLite 데이터베이스에서 리드 데이터를 관리하는 것","캡처된 변경을 사용하여 리드 기록을 감사하는 것"],"es":["Sincronizar prospectos desde Zoho CRM","Gestionar datos de prospectos en una base de datos SQLite local","Auditar el historial de prospectos con cambios capturados"],"fr":["Synchroniser les prospects depuis Zoho CRM","Gérer les données de prospects dans une base de données SQLite locale","Auditer l''historique des prospects avec des changements capturés"],"de":["Leads von Zoho CRM synchronisieren","Lead-Daten in einer lokalen SQLite-Datenbank verwalten","Lead-Historie mit erfassten Änderungen überprüfen"],"pt":["Sincronizar os leads do Zoho CRM","Gerenciar dados de leads em um banco de dados SQLite local","Auditar o histórico de leads com alterações capturadas"],"ru":["Синхронизировать лиды из Zoho CRM","Управлять данными лидов в локальной базе данных SQLite","Проводить аудит истории лидов с захваченными изменениями"],"ar":["مزامنة المصادر من Zoho CRM","ادارة بيانات المصادر في قاعدة بيانات SQLite محلية","تدقيق تاريخ المصادر مع التغييرات المحتجزة"]},"limitations":{"en":["Requires Zoho CRM API access","SQLite database setup necessary","Limited to Zoho CRM lead data"],"zh":["需要Zoho CRM API访问","需要SQLite数据库设置","仅限Zoho CRM线索数据"],"ja":["Zoho CRM APIへのアクセスが必要","SQLiteデータベースの設定が必要","Zoho CRMのリードデータのみ"],"ko":["Zoho CRM API 액세스가 필요","SQLite 데이터베이스 설정이 필요","Zoho CRM의 리드 데이터만"],"es":["Requiere acceso a la API de Zoho CRM","Configuración de la base de datos SQLite necesaria","Limitado a los datos de prospectos de Zoho CRM"],"fr":["Nécessite un accès à l''API Zoho CRM","Configuration de la base de données SQLite nécessaire","Limité aux données de prospects de Zoho CRM"],"de":["Benötigt Zugriff auf die Zoho CRM-API","SQLite-Datenbank-Setup erforderlich","Begrenzt auf Zoho CRM-Lead-Daten"],"pt":["Requer acesso à API do Zoho CRM","Configuração do banco de dados SQLite necessária","Limitado a dados de leads do Zoho CRM"],"ru":["Требует доступа к API Zoho CRM","Необходима настройка базы данных SQLite","Ограничен данными лидов Zoho CRM"],"ar":["يتطلب الوصول إلى واجهة برمجة التطبيقات Zoho CRM","إعداد قاعدة بيانات SQLite ضروري","محدود بالبيانات الأساسية ل Zoho CRM"]},"version":4},"contentHash":"7adca2a73636fdef2fbf6fb85ab6eb9c6b7ce1bc7f95eb2d90d5b72bddf76fba","qualityScore":39}');
