INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('brainqub3/brainqub3/crm-sync', 'crm-sync', 'brainqub3', 'brainqub3', 'community', 'crm-sync brainqub3 brainqub3 community crm-sync is a technical solution that synchronizes leads from Zoho CRM into a local SQLite database, ideal for businesses and individuals seeking data integration. It provides a structured database schema for efficient lead management. crm-sync是一款将Zoho CRM leads同步到本地SQLite数据库的工具，支持leads和leads_history表的管理 crm-syncはZoho CRMのリードをローカルのSQLiteデータベースに同期するツールで、leadsとleads_historyテーブルの管理をサポートします crm-sync는 Zoho CRM 리드를 로컬 SQLite 데이터베이스에 동기화하는 도구로, 리드 및 리드 기록 테이블 관리를 지원합니다 crm-sync es una herramienta para sincronizar leads de Zoho CRM con una base de datos SQLite local crm-sync est un outil pour synchroniser les leads de Zoho CRM avec une base de données SQLite locale crm-sync ist ein Tool zur Synchronisierung von Leads von Zoho CRM mit einer lokalen SQLite-Datenbank O crm-sync é uma ferramenta que sincroniza leads do Zoho CRM com um banco de dados SQLite local, oferecendo uma segunda cérebro para negócios e necessidades pessoais crm-sync - это инструмент, который синхронизирует лиды из Zoho CRM с локальной базой данных SQLite, предоставляя второй мозг для бизнеса и личных нужд crm-sync هي أداة لتزامن الرصيد من Zoho CRM مع قاعدة بيانات SQLite المحلية، وتقدم دماغًا ثانيًا للأعمال والاحتياجات الشخصية how to use crm-sync crm-sync setup guide Zoho CRM lead sync SQLite database integration crm-sync alternative crm-sync vs Zoho CRM crm-sync install what is crm-sync crm-sync for AI Agents crm-sync database schema crm-sync Zoho CRM同步 SQLite数据库 leads管理 AI工具 crm同步工具 Zoho CRM lead同步 数据同步 数据库管理 Synchronizes leads from Zoho CRM into a local SQLite database Utilizes a predefined database schema defined in scripts/crm/db_schema.sql Stores lead data in the ''leads'' table with fields such as id, first_name, and email Maintains an audit trail in the ''leads_history'' table with captured_at and chang fields Supports local timestamps for created_at and updated_at fields Retrieves Zoho record ID and Modified_Time for each lead crm-sync is a skill that enables synchronization of Zoho CRM leads with a local SQLite database, utilizing a predefined schema for organized data storage.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zenbase-ai/code-voyager/session-brain', 'community', 'zenbase-ai', 'code-voyager', 'zenbase-ai/code-voyager', 'session-brain', 7, 1, 39, '2025-12-30T04:49:31Z', '2026-03-06T06:50:18.500Z', 'e296458daa5145d984f28081097086bfc1049c79f0a7f023172a0468df13715f', '{"id":"zenbase-ai/code-voyager/session-brain","name":"session-brain","description":{"en":"session-brain provides persistent per-repo working memory for AI agents, stored under `.claude/voyager/`. It benefits developers by maintaining a canonical structured state and human-readable summaries.","zh":"Session Brain 是一个持久化的工作内存，自动更新并存储在 .claude/voyager/ 目录下。它使用 brain.json 和 brain.md 文件来管理您的工作流程","ja":"Session Brain は、.claude/voyager/ ディレクトリに自動的に更新され、保存されるパーシステントワーキングメモリです。brain.json と brain.md ファイルを使用してワークフローを管理します","ko":"Session Brain은 영속적인 작업 메모리로, .claude/voyager/ 디렉토리에 자동으로 업데이트되고 저장됩니다. brain.json 및 brain.md 파일을 사용하여 워크플로우를 관리합니다","es":"Session Brain es una herramienta que almacena memoria de trabajo persistente en tu repositorio. Funciona automáticamente a través de hooks.","fr":"Session Brain est un outil qui stocke une mémoire de travail persistante dans votre référentiel. Il fonctionne automatiquement via des hooks.","de":"Session Brain ist ein Tool, das persistente Arbeitsgedächtnis in Ihrem Repository speichert. Es funktioniert automatisch über Hooks.","pt":"O Session Brain é uma memória de trabalho persistente que armazena estado em `.claude/voyager/` e atualiza automaticamente via hooks","ru":"Session Brain — это постоянная память для репозиториев, которая хранит состояние в `.claude/voyager/` и обновляется автоматически через хуки для ИИ Агентов","ar":"Session Brain هو ذاكرة عمل متواصلة التي تخزن الحالة في `.claude/voyager/` وتتحديث تلقائيًا عبر hooks للوكلاء الذكاء الاصطناعي"},"seo":{"title":{"en":"session-brain: Persistent Memory Setup Guide | AI Agent S...","zh":"Session Brain 设计指南 - 持久化工作内存","ja":"Session Brain セットアップガイド - AIエージェントのためのパーシステントワーキングメモリ","ko":"Session Brain 사용자 가이드 - 영속적인 작업 메모리","es":"Configuración de Session Brain: Guía de memoria de trabaj...","fr":"Configurer Session Brain: Guide de mémoire de travail per...","de":"Session Brain Einrichten: Leitfaden für persistente Arbei...","pt":"Guia de Configuração do Session Brain: Memória de Trabalh...","ru":"Настройка Session Brain: Постоянная память для репозитори...","ar":"دليل إعداد Session Brain: ذاكرة عمل متواصلة للوكلاء الذكا..."},"description":{"en":"Unlock efficient workflow management with session-brain. Discover how to leverage persistent per-repo memory for AI agents and boost productivity. Get starte...","zh":"了解 Session Brain 的工作原理，包括自动更新和持久化工作内存。发现如何使用 brain.json 和 brain.md 文件来管理您的工作流程","ja":"Session Brain の自動更新とパーシステントワーキングメモリについて学びます。brain.json と brain.md ファイルを使用してワークフローを管理する方法を発見しましょう","ko":"Session Brain의 자동 업데이트 및 영속적인 작업 메모리 기능에 대해 알아보세요. brain.json 및 brain.md 파일을 사용하여 워크플로우를 관리하는 방법을 발견하세요","es":"Aprende a utilizar Session Brain para almacenar memoria de trabajo persistente en tu repositorio. Descubre cómo funciona y sus beneficios.","fr":"Découvrez comment utiliser Session Brain pour stocker une mémoire de travail persistante dans votre référentiel. Comprenez son fonctionnement et ses avantages.","de":"Erfahren Sie, wie Sie Session Brain verwenden, um persistente Arbeitsgedächtnis in Ihrem Repository zu speichern. Erfahren Sie, wie es funktioniert und seine...","pt":"Aprenda a configurar o Session Brain, uma memória de trabalho persistente para repositorios, e melhore a eficiência do seu workflow de desenvolvimento","ru":"Узнайте, как настроить Session Brain, постоянную память для репозиториев, и повысьте эффективность вашего рабочего процесса разработки с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد Session Brain، ذاكرة عمل متواصلة للوكلاء الذكاء الاصطناعي، وطور كفاءة سير عملك التطويري"},"definition":{"en":"session-brain is a persistent memory mechanism that stores and updates AI agent state via hooks, utilizing files like `brain.json` and `brain.md` for efficient workflow management.","zh":"Session Brain 是一个用于管理工作内存的工具，使用 JSON 和 Markdown 文件来存储和更新工作状态","ja":"Session Brain は、ワークフローの状態を保存および更新するために JSON と Markdown ファイルを使用するワーキングメモリ管理ツールです","ko":"Session Brain은 작업 상태를 저장하고 업데이트하는 데 JSON 및 Markdown 파일을 사용하는 작업 메모리 관리 도구입니다","es":"Session Brain es una herramienta de memoria de trabajo persistente que almacena estado en archivos como brain.json y brain.md","fr":"Session Brain est un outil de mémoire de travail persistante qui stocke l''état dans des fichiers tels que brain.json et brain.md","de":"Session Brain ist ein Tool für persistente Arbeitsgedächtnis, das den Zustand in Dateien wie brain.json und brain.md speichert","pt":"O Session Brain é uma tecnologia de memória de trabalho que armazena estado em arquivos JSON e Markdown","ru":"Session Brain — это технология памяти работы, которая хранит состояние в файлах JSON и Markdown для ИИ Агентов","ar":"Session Brain هو تكنولوجيا ذاكرة عمل تخزن الحالة في ملفات JSON و Markdown للوكلاء الذكاء الاصطناعي"},"features":{"en":["Automatically updates via SessionStart and PreCompact/SessionEnd hooks","Utilizes `brain.json` for canonical structured state, validated against a schema","Generates human-readable summaries in `brain.md` for quick reference","Stores per-session summaries in the `episodes/` directory for history tracking","Persists current brain context and repo snapshot for efficient workflow management"],"zh":["自动更新工作内存","使用 brain.json 和 brain.md 文件存储工作状态","支持 per-repo 工作内存","具有 episodes/ 目录用于历史记录","使用 SessionStart 和 PreCompact/SessionEnd Hooks 进行自动更新"],"ja":["ワーキングメモリの自動更新","brain.json と brain.md ファイルを使用してワークフローの状態を保存","per-repo ワーキングメモリをサポート","episodes/ ディレクトリを使用して履歴を保存","SessionStart と PreCompact/SessionEnd Hooks を使用して自動更新"],"ko":["작업 메모리 자동 업데이트","brain.json 및 brain.md 파일을 사용하여 작업 상태 저장","per-repo 작업 메모리 지원","episodes/ 디렉토리를 사용하여 기록 저장","SessionStart 및 PreCompact/SessionEnd Hooks를 사용한 자동 업데이트"],"es":["Almacenamiento de estado en brain.json y brain.md","Resumen de sesiones en la carpeta episodes","Actualización automática a través de hooks","Compatibilidad con SessionStart y PreCompact/SessionEnd","Almacenamiento de memoria de trabajo persistente en el repositorio"],"fr":["Stockage de l''état dans brain.json et brain.md","Résumé de sessions dans le dossier episodes","Mise à jour automatique via des hooks","Compatibilité avec SessionStart et PreCompact/SessionEnd","Stockage de mémoire de travail persistante dans le référentiel"],"de":["Zustandsspeicherung in brain.json und brain.md","Sitzungszusammenfassung im Ordner episodes","Automatische Aktualisierung über Hooks","Kompatibilität mit SessionStart und PreCompact/SessionEnd","Speicherung von persistenter Arbeitsgedächtnis im Repository"],"pt":["Armazenamento de estado em `.claude/voyager/`","Atualização automática via hooks","Suporte a arquivos JSON e Markdown","Histórico de sessões em `episodes/`","Validação de esquema para `brain.json`"],"ru":["Хранение состояния в `.claude/voyager/`","Автоматическое обновление через хуки для ИИ Агентов","Поддержка файлов JSON и Markdown","История сессий в `episodes/`","Валидация схемы для `brain.json`"],"ar":["تخزين الحالة في `.claude/voyager/`","التحديث التلقائي عبر hooks للوكلاء الذكاء الاصطناعي","دعم ملفات JSON و Markdown","تاريخ الجلسات في `episodes/`","التحقق من مخطط لل `brain.json`"]},"keywords":{"en":["how to use session-brain","session-brain setup guide","session-brain alternative","session-brain vs claude","what is session-brain","session-brain install","persistent memory for AI agents","session-brain workflow management","session-brain hooks","session-brain state management"],"zh":["Session Brain","持久化工作内存","AI 工具","自动更新","brain.json","brain.md","per-repo 工作内存","episodes/ 目录"],"ja":["Session Brain","パーシステントワーキングメモリ","AIエージェント","自動更新","brain.json","brain.md","per-repo ワーキングメモリ","episodes/ ディレクトリ"],"ko":["Session Brain","영속적인 작업 메모리","AI 도구","자동 업데이트","brain.json","brain.md","per-repo 작업 메모리","episodes/ 디렉토리"],"es":["Session Brain","memoria de trabajo persistente","herramientas de AI","hooks de sesión","almacenamiento de estado","brain.json","brain.md","episodes","SessionStart","PreCompact/SessionEnd"],"fr":["Session Brain","mémoire de travail persistante","outils d''IA","hooks de session","stockage d''état","brain.json","brain.md","episodes","SessionStart","PreCompact/SessionEnd"],"de":["Session Brain","persistente Arbeitsgedächtnis","AI-Tools","Sitzungshooks","Zustandsspeicherung","brain.json","brain.md","episodes","SessionStart","PreCompact/SessionEnd"],"pt":["Session Brain","memória de trabalho persistente","desenvolvimento de software","hooks","JSON","Markdown","estado de sessão","validação de esquema"],"ru":["Session Brain","постоянная память работы","разработка программного обеспечения","хуки","JSON","Markdown","состояние сессии","валидация схемы","ИИ Агенты"],"ar":["Session Brain","ذاكرة عمل متواصلة","تطوير البرمجيات","hooks","JSON","Markdown","حالة الجلسة","التحقق من مخطط","الوكلاء الذكاء الاصطناعي"]}},"owner":"zenbase-ai","repo":"code-voyager","repoPath":"zenbase-ai/code-voyager","stars":7,"forks":1,"updatedAt":"2025-12-30T04:49:31Z","topics":[],"category":"community","skillMd":{"name":"session-brain","description":"|","bodyPreview":"# Session Brain\n\nPersistent per-repo working memory stored under `.claude/voyager/`.\n\n## State Files\n\n| File | Purpose |\n|------|---------|\n| `brain.json` | Canonical structured state (validated against schema) |\n| `brain.md` | Human-readable summary for quick reference |\n| `episodes/` | Per-session summaries for history |\n\n## How It Works\n\nSession Brain updates **automatically** via hooks:\n- **SessionStart**: Injects current brain context + repo snapshot\n- **PreCompact/SessionEnd**: Persists ch","body":"# Session Brain\n\nPersistent per-repo working memory stored under `.claude/voyager/`.\n\n## State Files\n\n| File | Purpose |\n|------|---------|\n| `brain.json` | Canonical structured state (validated against schema) |\n| `brain.md` | Human-readable summary for quick reference |\n| `episodes/` | Per-session summaries for history |\n\n## How It Works\n\nSession Brain updates **automatically** via hooks:\n- **SessionStart**: Injects current brain context + repo snapshot\n- **PreCompact/SessionEnd**: Persists changes to brain.json and creates episode\n\nYou don''t need to manually update the brain—just work normally and it tracks context.\n\n## Reading brain.json\n\nWhen exploring brain.json, use `jq` to query specific sections instead of reading the whole file:\n\n```bash\n# Current context (goal, plan, questions)\njq ''.working_set'' .claude/voyager/brain.json\n\n# Decision history\njq ''.decisions'' .claude/voyager/brain.json\n\n# Recent progress\njq ''.progress'' .claude/voyager/brain.json\n\n# Project overview\njq ''.project'' .claude/voyager/brain.json\n```\n\nFor a quick human-readable summary, read `.claude/voyager/brain.md` instead.\n\n## Answering User Questions\n\nWhen users ask about context, read and interpret the brain files:\n\n### \"Resume\" / \"What were we doing?\"\n\n1. Read `.claude/voyager/brain.md` for quick context\n2. Check `brain.json` → `working_set.current_goal` and `working_set.current_plan`\n3. Summarize: current goal, plan progress, any open questions\n\n### \"What''s next?\"\n\n1. Read `brain.json` → `working_set.current_plan`\n2. Check `progress.recent_changes` to see what''s done\n3. Suggest the next uncompleted step from the plan\n\n### \"Why did we decide X?\" / \"What was the rationale?\"\n\n1. Read `brain.json` → `decisions` array\n2. Find matching decision by keyword\n3. Return the `rationale` and `implications`\n\n### \"What are the open questions?\"\n\n1. Read `brain.json` → `working_set.open_questions`\n2. Also check `working_set.risks` for blockers\n\n## Recording Decisions\n\nWhen the user says \"remember this decision: ...\" or explicitly wants to record a decision:\n\n1. Read current `.claude/voyager/brain.json`\n2. Append to the `decisions` array:\n   ```json\n   {\n     \"when\": \"<ISO timestamp>\",\n     \"decision\": \"<what was decided>\",\n     \"rationale\": \"<why>\",\n     \"implications\": [\"<what this affects>\"]\n   }\n   ```\n3. Write updated `brain.json`\n\nNote: `brain.md` will be re-rendered automatically on the next session end or compaction.\n\n## Brain Schema Overview\n\nSee `schemas/brain.schema.json` for full schema. Key sections:\n\n- **project**: Stable project understanding (summary, stack, key commands)\n- **working_set**: Current context (goal, plan, open questions, risks)\n- **decisions**: Append-only decision log with rationale\n- **progress**: Recent changes and completed milestones\n- **signals**: Metadata (last session ID, timestamp)\n\n## Technical Details\n\nSee `reference.md` for:\n- Full file structure\n- Update flow details\n- Manual operations (reset, view history)\n- Graceful degradation behavior\n"},"lastSynced":"2026-03-06T06:50:18.500Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Claude, AutoGPT, and LangChain requiring persistent per-repo working memory for efficient session management.","zh":"适用于 Claude、AutoGPT 和 LangChain 等 AI Agents，需要持久的每个仓库的工作内存以实现高效的会话管理。","ja":"Claude、AutoGPT、LangChain などの AI エージェントに適しています。これらのエージェントでは、効率的なセッション管理のために、各リポジトリごとに永続的なワーキングメモリが必要です。","ko":"Claude, AutoGPT, LangChain 등의 AI 에이전트에 적합합니다. 이러한 에이전트에서는 효율적인 세션 관리를 위해 각 저장소당 영속적인 작업 메모리가 필요합니다.","es":"Ideal para agentes de IA como Claude, AutoGPT y LangChain que requieren una memoria de trabajo persistente por repositorio para una gestión de sesiones eficiente.","fr":"Idéal pour les agents IA comme Claude, AutoGPT et LangChain nécessitant une mémoire de travail persistante par référentiel pour une gestion de session efficace.","de":"Ideal für KI-Agents wie Claude, AutoGPT und LangChain, die eine persistente Arbeitsmemorie pro Repository für eine effiziente Sitzungsverwaltung benötigen.","pt":"Ideal para Agentes de IA como Claude, AutoGPT e LangChain que exigem memória de trabalho persistente por repositório para gerenciamento de sessão eficiente.","ru":"Идеально для агентов ИИ, таких как Claude, AutoGPT и LangChain, требующих постоянной рабочей памяти на репозиторий для эффективного управления сессиями.","ar":"مثالي لعمليات الوكلاء الذكية مثل Claude و AutoGPT و LangChain التي تتطلب ذاكرة عمل مستمرة لكل مستودع من أجل إدارة جلسات فعالة."},"recommendation":{"en":"Empowers agents to maintain a canonical structured state via brain.json and human-readable summaries in brain.md, utilizing automatic updates through hooks like SessionStart and PreCompact/SessionEnd, and storing session histories in episodes/","zh":"通过 brain.json 和 brain.md 中的人类可读摘要，实现代理维护规范的结构化状态，并通过 SessionStart 和 PreCompact/SessionEnd 等钩子进行自动更新，并将会话历史存储在 episodes/ 中。","ja":"brain.json と brain.md の人間が読みやすいサマリーを使用して、エージェントが規範の構造化された状態を維持できるようにし、SessionStart と PreCompact/SessionEnd などのフックを使用した自動更新を実施し、セッションの履歴を episodes/ に保存します。","ko":"brain.json 및 brain.md의 인간이 읽을 수 있는 요약을 통해 에이전트가 표준화된 구조화된 상태를 유지할 수 있도록 하며, SessionStart 및 PreCompact/SessionEnd 등의 후크를 사용한 자동 업데이트를 수행하며, 세션 기록을 episodes/에 저장합니다.","es":"Habilita a los agentes a mantener un estado estructurado canónico a través de brain.json y resúmenes legibles por humanos en brain.md, utilizando actualizaciones automáticas a través de ganchos como SessionStart y PreCompact/SessionEnd, y almacenando historias de sesiones en episodes/","fr":"Permet aux agents de maintenir un état structuré canonique via brain.json et des résumés lisibles par l''homme en brain.md, en utilisant des mises à jour automatiques via des crochets comme SessionStart et PreCompact/SessionEnd, et en stockant les historiques de sessions dans episodes/","de":"Ermächtigt Agents, einen kanonischen strukturierten Zustand über brain.json und menschenlesbare Zusammenfassungen in brain.md zu pflegen, indem automatische Updates durch Hooks wie SessionStart und PreCompact/SessionEnd genutzt werden und Sitzungsgeschichten in episodes/ gespeichert werden","pt":"Habilita os agentes a manter um estado estruturado canônico via brain.json e resumos legíveis por humanos em brain.md, utilizando atualizações automáticas por meio de ganchos como SessionStart e PreCompact/SessionEnd, e armazenando históricos de sessão em episodes/","ru":"Предоставляет агентам возможность поддерживать каноническое структурированное состояние через brain.json и сводки, понятные человеку, в brain.md, используя автоматическое обновление через крючки, такие как SessionStart и PreCompact/SessionEnd, и хранящие истории сессий в episodes/","ar":"تمكّن الوكلاء من الحفاظ على حالة منسقة قياسية عبر brain.json وملخصات قابلة للقراءة من قبل الإنسان في brain.md، واستخدام التحديثات التلقائية من خلال عناقيب مثل SessionStart و PreCompact/SessionEnd، وتخزين تاريخ الجلسات في episodes/"},"useCases":{"en":["Automating session state persistence","Generating human-readable summaries for quick reference","Debugging session history via episode summaries"],"zh":["自动化会话状态持久化","生成人类可读的摘要以便快速参考","通过剧集摘要调试会话历史"],"ja":["セッション状態の永続化を自動化する","人間が読みやすいサマリーを生成して迅速に参照する","エピソードのサマリーを使用してセッション履歴をデバッグする"],"ko":["세션 상태의 영속화를 자동화한다","인간이 읽을 수 있는 요약을 생성하여 빠르게 참조한다","에피소드 요약을 사용하여 세션 기록을 디버깅한다"],"es":["Automatizar la persistencia del estado de sesión","Generar resúmenes legibles por humanos para referencia rápida","Depurar el historial de sesiones a través de resúmenes de episodios"],"fr":["Automatiser la persistance de l''état de session","Générer des résumés lisibles par l''homme pour référence rapide","Déboguer l''historique des sessions via des résumés d''épisodes"],"de":["Automatisieren der Sitzungszustandspersistenz","Generieren menschenlesbarer Zusammenfassungen für schnellen Verweis","Debuggen der Sitzungsgeschichte über Episoden-Zusammenfassungen"],"pt":["Automatizar a persistência do estado da sessão","Gerar resumos legíveis por humanos para referência rápida","Depurar o histórico da sessão via resumos de episódios"],"ru":["Автоматизировать сохранение состояния сессии","Генерировать сводки, понятные человеку, для быстрого обращения","Отлаживать историю сессии через сводки эпизодов"],"ar":["أتمتة استمرار حالة الجلسة","توليد ملخصات قابلة للقراءة من قبل الإنسان للاستشارة السريعة","تصحيح أخطاء تاريخ الجلسة من خلال ملخصات الحلقات"]},"limitations":{"en":["Requires repository access to store .claude/voyager/ files","Compatibility with specific AI agent architectures may vary"],"zh":["需要仓库访问权限来存储 .claude/voyager/ 文件","特定 AI 代理架构的兼容性可能会有所不同"],"ja":[".claude/voyager/ ファイルを保存するためにリポジトリへのアクセスが必要","特定の AI エージェントアーキテクチャとの互換性は異なる場合があります"],"ko":[".claude/voyager/ 파일을 저장하기 위해 저장소 액세스가 필요합니다","특정 AI 에이전트 아키텍처와의 호환성이 다를 수 있습니다"],"es":["Requiere acceso al repositorio para almacenar archivos .claude/voyager/","La compatibilidad con arquitecturas de agentes de IA específicas puede variar"],"fr":["Nécessite un accès au référentiel pour stocker des fichiers .claude/voyager/","La compatibilité avec des architectures d''agents IA spécifiques peut varier"],"de":["Benötigt Zugriff auf das Repository, um .claude/voyager/-Dateien zu speichern","Die Kompatibilität mit bestimmten KI-Agent-Architekturen kann variieren"],"pt":["Exige acesso ao repositório para armazenar arquivos .claude/voyager/","A compatibilidade com arquiteturas de agentes de IA específicas pode variar"],"ru":["Требует доступа к репозиторию для хранения файлов .claude/voyager/","Совместимость с определенными архитектурами агентов ИИ может варьироваться"],"ar":["يتطلب الوصول إلى المستودع لتخزين الملفات .claude/voyager/","قد تختلف متوافقية عمليات الوكلاء الذكية المحددة"]},"version":4},"contentHash":"e296458daa5145d984f28081097086bfc1049c79f0a7f023172a0468df13715f","qualityScore":39}');
