INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zenbase-ai/code-voyager/session-brain', 'session-brain', 'zenbase-ai', 'code-voyager', 'community', 'session-brain zenbase-ai code-voyager community session-brain provides persistent per-repo working memory for AI agents, stored under `.claude/voyager/`. It benefits developers by maintaining a canonical structured state and human-readable summaries. Session Brain 是一个持久化的工作内存，自动更新并存储在 .claude/voyager/ 目录下。它使用 brain.json 和 brain.md 文件来管理您的工作流程 Session Brain は、.claude/voyager/ ディレクトリに自動的に更新され、保存されるパーシステントワーキングメモリです。brain.json と brain.md ファイルを使用してワークフローを管理します Session Brain은 영속적인 작업 메모리로, .claude/voyager/ 디렉토리에 자동으로 업데이트되고 저장됩니다. brain.json 및 brain.md 파일을 사용하여 워크플로우를 관리합니다 Session Brain es una herramienta que almacena memoria de trabajo persistente en tu repositorio. Funciona automáticamente a través de hooks. Session Brain est un outil qui stocke une mémoire de travail persistante dans votre référentiel. Il fonctionne automatiquement via des hooks. Session Brain ist ein Tool, das persistente Arbeitsgedächtnis in Ihrem Repository speichert. Es funktioniert automatisch über Hooks. O Session Brain é uma memória de trabalho persistente que armazena estado em `.claude/voyager/` e atualiza automaticamente via hooks Session Brain — это постоянная память для репозиториев, которая хранит состояние в `.claude/voyager/` и обновляется автоматически через хуки для ИИ Агентов Session Brain هو ذاكرة عمل متواصلة التي تخزن الحالة في `.claude/voyager/` وتتحديث تلقائيًا عبر hooks للوكلاء الذكاء الاصطناعي how to use session-brain session-brain setup guide session-brain alternative session-brain vs claude what is session-brain session-brain install persistent memory for AI agents session-brain workflow management session-brain hooks session-brain state management Session Brain 持久化工作内存 AI 工具 自动更新 brain.json brain.md per-repo 工作内存 episodes/ 目录 Automatically updates via SessionStart and PreCompact/SessionEnd hooks Utilizes `brain.json` for canonical structured state, validated against a schema Generates human-readable summaries in `brain.md` for quick reference Stores per-session summaries in the `episodes/` directory for history tracking Persists current brain context and repo snapshot for efficient workflow management session-brain is a persistent memory mechanism that stores and updates AI agent state via hooks, utilizing files like `brain.json` and `brain.md` for efficient workflow management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hirokazu-kobayashi-koba-hiro/idp-server/spec-json-schema', 'community', 'hirokazu-kobayashi-koba-hiro', 'idp-server', 'hirokazu-kobayashi-koba-hiro/idp-server', 'spec-json-schema', 7, 1, 39, '2026-02-27T00:30:38Z', '2026-03-06T06:50:20.179Z', 'c13be3d924591e02f5346029481b087c9e3ff3f918fbd54d600764f709f11278', '{"id":"hirokazu-kobayashi-koba-hiro/idp-server/spec-json-schema","name":"spec-json-schema","description":{"en":"The spec-json-schema skill provides JSON Schema Validation for AI agents, enabling robust data structure and type checking. It benefits developers by ensuring data integrity and security.","zh":"spec-json-schema 是一个 JSON Schema 验证工具，支持 JSON Schema Draft 2020-12 和用户注册验证、身份验证和外部 API 验证","ja":"spec-json-schema は JSON スキーマ検証ツールであり、JSON Schema Draft 2020-12 に準拠し、ユーザー登録検証、Identity Verification 検証、外部 API 検証をサポートする","ko":"spec-json-schema는 JSON 스키마를 검증하는 도구로, JSON Schema Draft 2020-12 및 사용자 등록 검증, 身份验证 및 외부 API 검증을 지원합니다","es":"Spec-json-schema es una capa de validación de estructuras de JSON que verifica la estructura, tipo y restricciones de los datos de entrada","fr":"Spec-json-schema est une couche de validation de structures JSON qui vérifie la structure, le type et les contraintes des données d''entrée","de":"Spec-json-schema ist eine Validierungsebene für JSON-Strukturen, die die Struktur, den Typ und die Einschränkungen der Eingabedaten überprüft","pt":"O spec-json-schema é uma camada de validação de dados JSON que verifica a estrutura, tipo e restrições de entrada","ru":"Spec-json-schema - это层 валидации данных JSON, проверяющая структуру, тип и ограничения ввода, основанная на ИИ Агентах","ar":"spec-json-schema هو طبقة للتحقق من صحة البيانات JSON التي تتحقق من البنية والنوع والقيود للمدخلات، مستندة إلى أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"spec-json-schema: JSON Schema Validation Setup Guide | AI...","zh":"JSON Schema 验证工具：spec-json-schema Setup Guide","ja":"JSONスキーマ検証開発ガイド：spec-json-schema ベストプラクティス","ko":"JSON 스키마 검증 도구: spec-json-schema 사용자 가이드","es":"Guía de configuración de spec-json-schema para validación...","fr":"Guide de mise en œuvre de spec-json-schema pour la valida...","de":"Einrichtungsanleitung für spec-json-schema zur JSON-Valid...","pt":"Guia de Configuração do spec-json-schema para Validação d...","ru":"Настройка spec-json-schema для валидации данных: лучшие п...","ar":"إعداد مرشد لتحقق من صحة البيانات باستخدام spec-json-schema"},"description":{"en":"Unlock robust JSON data validation with spec-json-schema. Discover how to implement JSON Schema Draft 2020-12 and ensure data integrity. Get started now!","zh":"了解如何使用 spec-json-schema 进行 JSON Schema 验证，包括用户注册验证、身份验证和外部 API 验证","ja":"spec-json-schema を使用した JSON スキーマ検証の方法を学び、ユーザー登録検証、Identity Verification 検証、外部 API 検証を実現する","ko":"spec-json-schema를 사용하여 JSON 스키마를 검증하고, 사용자 등록 검증, 身份验证 및 외부 API 검증을 수행하는 방법을 알아보세요","es":"Aprende a utilizar spec-json-schema para validar estructuras de JSON y asegurar la integridad de tus datos","fr":"Découvrez comment utiliser spec-json-schema pour valider les structures JSON et assurer l''intégrité de vos données","de":"Erfahren Sie, wie Sie spec-json-schema verwenden können, um JSON-Strukturen zu validieren und die Integrität Ihrer Daten sicherzustellen","pt":"Aprenda a configurar o spec-json-schema para validar dados JSON com eficiência, incluindo conceitos de segurança e extensões","ru":"Узнайте, как настроить spec-json-schema для эффективной валидации данных JSON, включая концепции безопасности и расширения ИИ Агентов","ar":"تعرف على كيفية ضبط spec-json-schema للتحقق من صحة البيانات JSON بفعالية، بما في ذلك مفاهيم الأمان وتوابع AI Tools"},"definition":{"en":"spec-json-schema is a JSON Schema Validation layer that checks input data structure, type, and constraints, supporting JSON Schema Draft 2020-12.","zh":"spec-json-schema 是一个用于验证 JSON 数据结构和类型的工具","ja":"spec-json-schema は JSON データの構造と型を検証するツールです","ko":"spec-json-schema는 JSON 데이터의 구조와 유형을 검증하는 도구입니다","es":"Spec-json-schema es una tecnología de validación de JSON que sigue el borrador de JSON Schema 2020-12","fr":"Spec-json-schema est une technologie de validation JSON qui suit le brouillon de JSON Schema 2020-12","de":"Spec-json-schema ist eine JSON-Validierungstechnologie, die dem JSON Schema 2020-12-Entwurf entspricht","pt":"O que é spec-json-schema? É uma especificação para validar dados JSON com base em esquemas personalizados","ru":"Что такое spec-json-schema? Это спецификация для валидации данных JSON на основеustom схем, используя ИИ Агенты","ar":"ما هو spec-json-schema؟ إنه مواصفة للتحقق من صحة البيانات JSON استناداً إلى سلاسل مخصصة، باستخدام أدوات الذكاء الاصطناعي"},"features":{"en":["Supports JSON Schema Draft 2020-12 for robust validation","Enables user registration validation with custom schemas per tenant","Performs identity verification validation for secure data processing","Validates external API requests and responses for data integrity","Provides detailed error messages for field-specific error handling"],"zh":["支持 JSON Schema Draft 2020-12","用户注册验证","身份验证","外部 API 验证","详细错误消息"],"ja":["JSON Schema Draft 2020-12 に準拠","ユーザー登録検証","Identity Verification 検証","外部 API 検証","詳細エラーメッセージ"],"ko":["JSON Schema Draft 2020-12 지원","사용자 등록 검증","身份验证","외부 API 검증","상세 오류 메시지"],"es":["Validación de estructuras de JSON según el borrador de JSON Schema 2020-12","Verificación de la estructura, tipo y restricciones de los datos de entrada","Soporte para la verificación de registros de usuario y verificación de identidad","Validación de API externas y respuestas","Mensajes de error detallados para cada campo"],"fr":["Validation des structures JSON selon le brouillon de JSON Schema 2020-12","Vérification de la structure, du type et des contraintes des données d''entrée","Prise en charge de la vérification des enregistrements utilisateur et de la vérification d''identité","Validation des API externes et des réponses","Messages d''erreur détaillés pour chaque champ"],"de":["Validierung von JSON-Strukturen gemäß dem JSON Schema 2020-12-Entwurf","Überprüfung der Struktur, des Typs und der Einschränkungen der Eingabedaten","Unterstützung für die Überprüfung von Benutzerregistrierungen und Identitätsprüfungen","Validierung von externen APIs und Antworten","Detaillierte Fehlermeldungen für jedes Feld"],"pt":["Suporte a JSON Schema Draft 2020-12","Validação de dados de usuário com esquemas personalizados","Verificação de identidade com validação de dados","Validação de APIs externas com solicitação e resposta","Mensagens de erro detalhadas por campo"],"ru":["Поддержка JSON Schema Draft 2020-12","Валидация пользовательских данных сustom схем","Проверка идентичности с валидацией данных, используя ИИ Агенты","Валидация внешних API с запросом и ответом","Подробные сообщения об ошибках по полям"],"ar":["دعم JSON Schema Draft 2020-12","التحقق من صحة بيانات المستخدم مع سلاسل مخصصة","التحقق من الهوية مع التحقق من صحة البيانات، باستخدام أدوات الذكاء الاصطناعي","التحقق من صحة واجهات برمجة التطبيقات الخارجية مع الطلب والاستجابة","رسائل خطأ مفصلة حسب الحقل"]},"keywords":{"en":["how to use spec-json-schema","spec-json-schema setup guide","JSON Schema Draft 2020-12 validation","spec-json-schema alternative","spec-json-schema vs jsonschema","spec-json-schema install","what is spec-json-schema","spec-json-schema documentation","JSON schema validation best practices"],"zh":["JSON Schema 验证","spec-json-schema","AIエージェント","JSON 数据验证","用户注册验证","身份验证","外部 API 验证"],"ja":["JSONスキーマ検証","spec-json-schema","AIエージェント","JSON データ検証","ユーザー登録検証","Identity Verification 検証","外部 API 検証"],"ko":["JSON 스키마 검증","spec-json-schema","AI 도구","JSON 데이터 검증","사용자 등록 검증","身份验证","외부 API 검증"],"es":["validación de JSON","JSON Schema 2020-12","verificación de estructuras de JSON","seguridad de datos","validación de API","Herramientas de AI","Agentes de IA","desarrollo de software"],"fr":["validation JSON","JSON Schema 2020-12","vérification des structures JSON","sécurité des données","validation des API","Outils d''IA","Agents d''IA","développement de logiciels"],"de":["JSON-Validierung","JSON Schema 2020-12","Überprüfung von JSON-Strukturen","Datensicherheit","API-Validierung","AI-Tools","KI-Agents","Softwareentwicklung"],"pt":["spec-json-schema","validação de dados JSON","esquemas personalizados","segurança de dados","API externas","erro de validação","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["spec-json-schema","валидация данных JSON","пользовательские схемы","безопасность данных","внешние API","ошибка валидации","разработка программного обеспечения","инструменты разработки ИИ Агентов"],"ar":["spec-json-schema","التحقق من صحة البيانات JSON","سلاسل مخصصة","أمان البيانات","واجهات برمجة التطبيقات الخارجية","خطأ التحقق","تطوير البرمجيات","أدوات تطوير أدوات الذكاء الاصطناعي"]}},"owner":"hirokazu-kobayashi-koba-hiro","repo":"idp-server","repoPath":"hirokazu-kobayashi-koba-hiro/idp-server","stars":7,"forks":1,"updatedAt":"2026-02-27T00:30:38Z","topics":[],"category":"community","skillMd":{"name":"spec-json-schema","description":"JSONスキーマ検証（JSON Schema Validation）機能の開発・修正を行う際に使用。ユーザー登録スキーマ、Identity Verificationスキーマ、外部API検証実装時に役立つ。","bodyPreview":"# JSONスキーマ検証（JSON Schema Validation）開発ガイド\n\n## ドキュメント\n\n- `documentation/docs/content_03_concepts/06-security-extensions/concept-03-schema-validation.md` - JSONスキーマ検証概念\n\n## 機能概要\n\nJSONスキーマ検証は、入力データの構造・型・制約を検証する層。\n- **JSON Schema Draft 2020-12準拠**\n- **ユーザー登録検証**: テナント別カスタムスキーマ\n- **Identity Verification検証**: 本人確認申請データ検証\n- **外部API検証**: リクエスト/レスポンス検証\n- **詳細エラーメッセージ**: フィールド別エラー\n\n## モジュール構成\n\n```\nlibs/\n└── idp-server-platform/                     # プラットフォーム基盤\n    └── .../platform/json/schema/\n        ├──","body":"# JSONスキーマ検証（JSON Schema Validation）開発ガイド\n\n## ドキュメント\n\n- `documentation/docs/content_03_concepts/06-security-extensions/concept-03-schema-validation.md` - JSONスキーマ検証概念\n\n## 機能概要\n\nJSONスキーマ検証は、入力データの構造・型・制約を検証する層。\n- **JSON Schema Draft 2020-12準拠**\n- **ユーザー登録検証**: テナント別カスタムスキーマ\n- **Identity Verification検証**: 本人確認申請データ検証\n- **外部API検証**: リクエスト/レスポンス検証\n- **詳細エラーメッセージ**: フィールド別エラー\n\n## モジュール構成\n\n```\nlibs/\n└── idp-server-platform/                     # プラットフォーム基盤\n    └── .../platform/json/schema/\n        ├── JsonSchemaDefinition.java       # スキーマ定義\n        ├── JsonSchemaValidator.java        # スキーマ検証\n        └── JsonSchemaValidationException.java\n```\n\n## ユーザー登録でのスキーマ検証\n\n`idp-server-core/openid/identity/IdPUserCreator.java` 内:\n\n```java\npublic class IdPUserCreator {\n\n    JsonSchemaDefinition definition;\n    AuthenticationInteractionRequest request;\n\n    public User create() {\n        User user = User.initialized();\n\n        // スキーマ定義に基づいてフィールドを設定\n        if (definition.hasProperty(\"name\") &&\n            request.containsKey(\"name\")) {\n            user.setName(request.getValueAsString(\"name\"));\n        }\n\n        if (definition.hasProperty(\"email\") &&\n            request.containsKey(\"email\")) {\n            user.setEmail(request.getValueAsString(\"email\"));\n        }\n\n        // その他のフィールドも同様に処理\n        // ...\n\n        return user;\n    }\n}\n```\n\n**注意**: JsonSchemaDefinitionが、許可されたフィールドを定義します。\n\n## スキーマ定義例\n\n### ユーザー登録スキーマ\n\n```json\n{\n  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\n  \"type\": \"object\",\n  \"properties\": {\n    \"email\": {\n      \"type\": \"string\",\n      \"format\": \"email\"\n    },\n    \"name\": {\n      \"type\": \"string\",\n      \"minLength\": 1,\n      \"maxLength\": 100\n    },\n    \"birthdate\": {\n      \"type\": \"string\",\n      \"pattern\": \"^[0-9]{4}-[0-9]{2}-[0-9]{2}$\"\n    }\n  },\n  \"required\": [\"email\", \"name\"]\n}\n```\n\n### Identity Verification申請スキーマ\n\n```json\n{\n  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\n  \"type\": \"object\",\n  \"properties\": {\n    \"document_type\": {\n      \"type\": \"string\",\n      \"enum\": [\"passport\", \"drivers_license\", \"national_id\"]\n    },\n    \"document_number\": {\n      \"type\": \"string\",\n      \"minLength\": 5\n    }\n  },\n  \"required\": [\"document_type\", \"document_number\"]\n}\n```\n\n## スキーマ検証エラー\n\n```java\npublic class JsonSchemaValidationException {\n    // フィールド別の詳細エラーメッセージ\n    // - 必須フィールド不足\n    // - 型不一致\n    // - フォーマット違反\n    // - 制約違反（minLength, maxLength, pattern等）\n}\n```\n\n## E2Eテスト\n\n```\ne2e/src/tests/\n└── integration/ida/\n    └── (Identity Verificationスキーマ検証テスト)\n```\n\n## コマンド\n\n```bash\n# ビルド\n./gradlew :libs:idp-server-platform:compileJava\n\n# テスト\ncd e2e && npm test -- integration/ida/\n```\n\n## トラブルシューティング\n\n### スキーマ検証失敗\n- スキーマ定義が正しいか確認（JSON Schema Draft 2020-12形式）\n- 必須フィールドが含まれているか確認\n\n### 型エラー\n- フィールドの型がスキーマと一致するか確認\n- string, number, boolean, object, arrayを正しく使用\n\n### フォーマット検証失敗\n- email, uri, date-time等のフォーマットが正しいか確認\n- カスタムpattern（正規表現）が正しいか確認\n\n### カスタムスキーマが反映されない\n- テナント別スキーマ設定が正しいか確認\n- JsonSchemaDefinitionが正しくロードされているか確認\n"},"lastSynced":"2026-03-06T06:50:20.179Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents requiring robust JSON data validation and security, such as Cursor, Windsurf, and AutoGPT.","zh":"适合需要强大的JSON数据验证和安全的AI代理，例如Cursor、Windsurf和AutoGPT。","ja":"Cursor、Windsurf、AutoGPTなどのロバストなJSONデータの検証とセキュリティが必要なAIエージェントに最適です。","ko":"Cursor, Windsurf, AutoGPT와 같은 강력한 JSON 데이터 검증 및 보안이 필요한 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA que requieren una validación y seguridad de datos JSON robustas, como Cursor, Windsurf y AutoGPT.","fr":"Idéal pour les agents IA nécessitant une validation et une sécurité des données JSON robustes, tels que Cursor, Windsurf et AutoGPT.","de":"Ideal für KI-Agents, die eine robuste JSON-Datenvalidierung und -sicherheit erfordern, wie z. B. Cursor, Windsurf und AutoGPT.","pt":"Ideal para Agentes de IA que necessitam de validação de dados JSON robusta e segurança, como Cursor, Windsurf e AutoGPT.","ru":"Идеально для агентов ИИ, требующих надежной валидации данных JSON и безопасности, таких как Cursor, Windsurf и AutoGPT.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يحتاجون إلى التحقق من صحة البيانات JSON القوي والأمن، مثل Cursor و Windsurf و AutoGPT."},"recommendation":{"en":"Empowers agents to enforce JSON Schema Draft 2020-12 standards, ensuring data integrity and security through features like user registration validation, identity verification, and external API request/response validation, utilizing detailed error messages for efficient debugging.","zh":"赋予代理人执行JSON Schema Draft 2020-12标准的能力，通过用户注册验证、身份验证和外部API请求/响应验证等功能，确保数据完整性和安全性，并利用详细的错误消息进行高效的调试。","ja":"JSON Schema Draft 2020-12標準を実施する能力をエージェントに与え、ユーザー登録の検証、アイデンティティーの検証、外部APIのリクエスト/レスポンスの検証などの機能を通じて、データの完全性とセキュリティを確保し、詳細なエラーメッセージを使用して効率的なデバッグを行う。","ko":"JSON Schema Draft 2020-12 표준을 시행할 수 있는 능력을 에이전트에게 부여하여, 사용자 등록 검증, 身分驗證, 외부 API 요청/응답 검증 등의 기능을 통해 데이터 무결성과 보안을 보장하며, 상세한 오류 메시지를 사용하여 효율적인 디버깅을 수행합니다.","es":"Habilita a los agentes a aplicar los estándares de JSON Schema Draft 2020-12, garantizando la integridad y seguridad de los datos a través de características como la validación de registro de usuarios, verificación de identidad y validación de solicitudes y respuestas de API externas, utilizando mensajes de error detallados para un depuración eficiente.","fr":"Permet aux agents d''appliquer les normes de JSON Schema Draft 2020-12, garantissant l''intégrité et la sécurité des données grâce à des fonctionnalités telles que la validation de l''inscription des utilisateurs, la vérification de l''identité et la validation des requêtes et réponses d''API externes, en utilisant des messages d''erreur détaillés pour un débogage efficace.","de":"Ermächtigt die Agents, die Standards von JSON Schema Draft 2020-12 durchzusetzen, die Integrität und Sicherheit der Daten durch Funktionen wie Benutzerregistrierungsvalidierung, Identitätsüberprüfung und Validierung von externen API-Anfragen und -Antworten sicherzustellen, wobei detaillierte Fehlermeldungen für eine effiziente Fehlersuche verwendet werden.","pt":"Habilita os agentes a impor os padrões do JSON Schema Draft 2020-12, garantindo a integridade e segurança dos dados por meio de recursos como validação de registro de usuário, verificação de identidade e validação de solicitação/resposta de API externa, utilizando mensagens de erro detalhadas para depuração eficiente.","ru":"Наделяет агентов возможностью обеспечить соблюдение стандартов JSON Schema Draft 2020-12, гарантируя целостность и безопасность данных за счет функций, таких как проверка регистрации пользователей, верификация личности и валидация внешних запросов и ответов API, используя подробные сообщения об ошибках для эффективной отладки.","ar":"تمكين الوكلاء من فرض معايير مشروع JSON Schema 2020-12، ضمانًا للسلامة والأمن البيانات من خلال ميزات مثل التحقق من تسجيل المستخدم والتحقق من الهوية والتحقق من طلب/استجابة API الخارجية، باستخدام رسائل الخطأ المفصلة للتصحيح الفعال."},"useCases":{"en":["Validating user input data against custom JSON schemas","Verifying identity verification requests for security compliance","Debugging external API integrations using detailed error messages"],"zh":["验证用户输入数据与自定义JSON模式","验证身份验证请求以确保安全合规性","使用详细的错误消息调试外部API集成"],"ja":["カスタムJSONスキーマに対するユーザー入力データの検証","セキュリティコンプライアンスを確保するためにアイデンティティ検証リクエストの検証","詳細なエラーメッセージを使用して外部API統合をデバッグする"],"ko":["사용자 입력 데이터를 사용자 정의 JSON 스키마와 비교하여 검증","보안 준수를 위해 身分驗證 요청을 검증","상세한 오류 메시지를 사용하여 외부 API 통합을 디버깅"],"es":["Validar datos de entrada de usuario contra esquemas JSON personalizados","Verificar solicitudes de verificación de identidad para el cumplimiento de la seguridad","Depurar integraciones de API externas mediante mensajes de error detallados"],"fr":["Valider les données de saisie utilisateur par rapport à des schémas JSON personnalisés","Vérifier les demandes de vérification d''identité pour la conformité à la sécurité","Déboguer les intégrations d''API externes à l''aide de messages d''erreur détaillés"],"de":["Validieren von Benutzereingabedaten gegen benutzerdefinierte JSON-Schemata","Überprüfen von Identitätsüberprüfungsanfragen auf Sicherheitskonformität","Fehlersuche bei externen API-Integrationen mithilfe detaillierter Fehlermeldungen"],"pt":["Validar dados de entrada do usuário contra esquemas JSON personalizados","Verificar solicitações de verificação de identidade para cumprimento da conformidade de segurança","Depurar integrações de API externas usando mensagens de erro detalhadas"],"ru":["Валидировать данные ввода пользователя против пользовательских схем JSON","Проверять запросы на верификацию личности для соблюдения требований безопасности","Отлаживать внешние интеграции API с помощью подробных сообщений об ошибках"],"ar":["التحقق من صحة بيانات nhập المستخدم ضد مخططات JSON المخصصة","التحقق من طلبات التحقق من الهوية للامتثال لمتطلبات الأمن","تصحيح أخطاء التكاملات الخارجية API باستخدام رسائل الخطأ المفصلة"]},"limitations":{"en":["Requires JSON Schema Draft 2020-12 compatibility","Limited to JSON data format"],"zh":["需要JSON Schema Draft 2020-12兼容性","仅限于JSON数据格式"],"ja":["JSON Schema Draft 2020-12の互換性が必要","JSONデータ形式のみに限定"],"ko":["JSON Schema Draft 2020-12 호환성이 필요","JSON 데이터 형식만 지원"],"es":["Requiere compatibilidad con JSON Schema Draft 2020-12","Limitado al formato de datos JSON"],"fr":["Nécessite la compatibilité avec JSON Schema Draft 2020-12","Limité au format de données JSON"],"de":["Benötigt Kompatibilität mit JSON Schema Draft 2020-12","Begrenzt auf JSON-Datenträger"],"pt":["Exige compatibilidade com o JSON Schema Draft 2020-12","Limitado ao formato de dados JSON"],"ru":["Требует совместимости со стандартом JSON Schema Draft 2020-12","Ограничен форматом данных JSON"],"ar":["يتطلب توافقًا مع مشروع JSON Schema 2020-12","محدود بتنسيق البيانات JSON"]},"version":4},"contentHash":"c13be3d924591e02f5346029481b087c9e3ff3f918fbd54d600764f709f11278","qualityScore":39}');
