INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hirokazu-kobayashi-koba-hiro/idp-server/spec-json-schema', 'spec-json-schema', 'hirokazu-kobayashi-koba-hiro', 'idp-server', 'community', 'spec-json-schema hirokazu-kobayashi-koba-hiro idp-server community The spec-json-schema skill provides JSON Schema Validation for AI agents, enabling robust data structure and type checking. It benefits developers by ensuring data integrity and security. spec-json-schema 是一个 JSON Schema 验证工具，支持 JSON Schema Draft 2020-12 和用户注册验证、身份验证和外部 API 验证 spec-json-schema は JSON スキーマ検証ツールであり、JSON Schema Draft 2020-12 に準拠し、ユーザー登録検証、Identity Verification 検証、外部 API 検証をサポートする spec-json-schema는 JSON 스키마를 검증하는 도구로, JSON Schema Draft 2020-12 및 사용자 등록 검증, 身份验证 및 외부 API 검증을 지원합니다 Spec-json-schema es una capa de validación de estructuras de JSON que verifica la estructura, tipo y restricciones de los datos de entrada Spec-json-schema est une couche de validation de structures JSON qui vérifie la structure, le type et les contraintes des données d''entrée Spec-json-schema ist eine Validierungsebene für JSON-Strukturen, die die Struktur, den Typ und die Einschränkungen der Eingabedaten überprüft O spec-json-schema é uma camada de validação de dados JSON que verifica a estrutura, tipo e restrições de entrada Spec-json-schema - это层 валидации данных JSON, проверяющая структуру, тип и ограничения ввода, основанная на ИИ Агентах spec-json-schema هو طبقة للتحقق من صحة البيانات JSON التي تتحقق من البنية والنوع والقيود للمدخلات، مستندة إلى أدوات الذكاء الاصطناعي how to use spec-json-schema spec-json-schema setup guide JSON Schema Draft 2020-12 validation spec-json-schema alternative spec-json-schema vs jsonschema spec-json-schema install what is spec-json-schema spec-json-schema documentation JSON schema validation best practices JSON Schema 验证 spec-json-schema AIエージェント JSON 数据验证 用户注册验证 身份验证 外部 API 验证 Supports JSON Schema Draft 2020-12 for robust validation Enables user registration validation with custom schemas per tenant Performs identity verification validation for secure data processing Validates external API requests and responses for data integrity Provides detailed error messages for field-specific error handling spec-json-schema is a JSON Schema Validation layer that checks input data structure, type, and constraints, supporting JSON Schema Draft 2020-12.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('planetaryescape/blah.chat/budget-tracker-patterns', 'community', 'planetaryescape', 'blah.chat', 'planetaryescape/blah.chat', 'budget-tracker-patterns', 7, 0, 39, '2026-02-28T20:36:58Z', '2026-03-06T06:51:17.221Z', 'd731101c652d0cdaec250dfca5be02e780da1765a561c8883c4b574539ea5559', '{"id":"planetaryescape/blah.chat/budget-tracker-patterns","name":"budget-tracker-patterns","description":{"en":"budget-tracker-patterns tracks context consumption and detects runaway patterns for AI generation tool calls, providing visibility and awareness. Ideal for developers using NextJS and TypeScript.","zh":"预算跟踪模式是一种用于跟踪AI工具调用上下文消费和检测异常模式的技术，基于AGPL-3.0和Typescript实现","ja":"予算トラッカー パターンは、AIエージェントの呼び出し上下文の消費を追跡し、異常パターンを検出する技術です。AGPL-3.0とTypeScriptを使用して実現しています","ko":"예산 추적 패턴은 AI 도구의 호출 컨텍스트 소비를 추적하고 이상 패턴을 감지하는 기술입니다. AGPL-3.0 및 Typescript를 사용하여 구현합니다","es":"El seguimiento de patrones de presupuesto permite la detección de patrones de generación y el control del consumo de contexto en herramientas de inteligencia artificial","fr":"Le suivi des modèles de budget permet la détection de modèles de génération et le contrôle de la consommation de contexte dans les outils d''intelligence artificielle","de":"Die Überwachung von Budgetmustern ermöglicht die Erkennung von Generierungsmustern und die Kontrolle des Kontextverbrauchs in künstlichen Intelligenzwerkzeugen","pt":"O budget-tracker-patterns é uma ferramenta de código aberto que ajuda a otimizar o uso de ferramentas de IA, rastreando o consumo de contexto e detectando padrões de gastos excessivos","ru":"Budget-tracker-patterns - это открытый инструмент, который помогает оптимизировать использование ИИ Агентов, отслеживая потребление контекста и обнаруживая чрезмерные расходы","ar":"budget-tracker-patterns هو أداة مفتوحة المصدر تساعد في تحسين استخدام أدوات الذكاء الاصطناعي، من خلال تتبع استهلاك السياق والكشف عن الأنماط المفرطة في الإنفاق"},"seo":{"title":{"en":"budget-tracker-patterns: Awareness-based Tracking Setup G...","zh":"预算跟踪模式设置指南 - 基于AGPL-3.0的AI工具","ja":"予算トラッカー パターン設定ガイド - AGPL-3.0ベースのAIエージェント","ko":"예산 추적 패턴 설정 가이드 - AGPL-3.0 기반 AI 도구","es":"Guía de configuración de budget-tracker-patterns para age...","fr":"Configurer les modèles de suivi de budget pour les agents...","de":"Einrichtungsanleitung für budget-tracker-patterns in küns...","pt":"Guia de Configuração do budget-tracker-patterns para Ferr...","ru":"Руководство по настройке budget-tracker-patterns для ИИ А...","ar":"دليل إعداد budget-tracker-patterns لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how budget-tracker-patterns provides visibility into AI generation tool calls, detect runaway patterns, and optimize context consumption - get start...","zh":"了解预算跟踪模式的技术细节，包括BudgetState接口和Typescript实现，用于优化AI工具的性能","ja":"予算トラッカー パターンの技術的詳細をみてみよう。BudgetStateインターフェイスやTypeScriptの実装などを学び、AIエージェントのパフォーマンスを最適化する","ko":"예산 추적 패턴의 기술적 세부 사항을 살펴보세요. BudgetState 인터페이스 및 Typescript 구현을 통해 AI 도구의 성능을 최적화하는 방법을 알아보세요","es":"Aprende a configurar y utilizar budget-tracker-patterns para controlar el consumo de contexto y detectar patrones de generación en herramientas de inteligenc...","fr":"Découvrez comment configurer et utiliser les modèles de suivi de budget pour contrôler la consommation de contexte et détecter les modèles de génération dans...","de":"Erfahren Sie, wie Sie budget-tracker-patterns konfigurieren und verwenden, um den Kontextverbrauch zu kontrollieren und Generierungsmuster in künstlichen Int...","pt":"Aprenda a configurar o budget-tracker-patterns para otimizar o uso de ferramentas de IA e evitar padrões de gastos excessivos","ru":"Узнайте, как настроить budget-tracker-patterns для оптимизации использования ИИ Агентов и предотвращения чрезмерных расходов","ar":"تعرف على كيفية إعداد budget-tracker-patterns لتحسين استخدام أدوات الذكاء الاصطناعي وتجنب النمط المفرط في الإنفاق"},"definition":{"en":"budget-tracker-patterns is an open-source, self-hostable alternative to ChatGPT, utilizing AGPL-3.0 license and offering a hosted cloud version.","zh":"预算跟踪模式是一种用于跟踪和管理AI工具资源消耗的技术","ja":"予算トラッカー パターンは、AIエージェントのリソース消費を追跡して管理する技術です","ko":"예산 추적 패턴은 AI 도구의 리소스 소비를 추적하고 관리하는 기술입니다","es":"Un patrón de seguimiento de presupuesto es un mecanismo que controla el consumo de contexto y detecta patrones de generación en herramientas de inteligencia artificial","fr":"Un modèle de suivi de budget est un mécanisme qui contrôle la consommation de contexte et détecte les modèles de génération dans les outils d''intelligence artificielle","de":"Ein Budget-Überwachungsmuster ist ein Mechanismus, der den Kontextverbrauch kontrolliert und Generierungsmuster in künstlichen Intelligenzwerkzeugen erkennt","pt":"O que é budget-tracker-patterns? É uma ferramenta de código aberto que rastreia o consumo de contexto e detecta padrões de gastos excessivos em ferramentas de IA","ru":"Что такое budget-tracker-patterns? Это открытый инструмент, который отслеживает потребление контекста и обнаруживает чрезмерные расходы в ИИ Агентах","ar":"ما هو budget-tracker-patterns؟ هو أداة مفتوحة المصدر تتبع استهلاك السياق والكشف عن الأنماط المفرطة في الإنفاق لأدوات الذكاء الاصطناعي"},"features":{"en":["Tracks context consumption using the BudgetState interface","Detects runaway patterns in AI generation tool calls","Provides visibility into tool call counts and search history","Utilizes TypeScript for core state tracking","Integrates with NextJS for seamless implementation","Offers a hosted cloud version for easy deployment"],"zh":["基于AGPL-3.0的开源实现","使用Typescript进行开发","BudgetState接口用于跟踪上下文消费","支持检测异常模式","与Nextjs和Convex集成"],"ja":["AGPL-3.0ベースのオープンソース実装","TypeScriptを使用した開発","BudgetStateインターフェイスを使用して上下文の消費を追跡","異常パターンの検出をサポート","NextjsとConvexとの統合"],"ko":["AGPL-3.0 기반의 오픈소스 구현","Typescript를 사용한 개발","BudgetState 인터페이스를 사용하여 컨텍스트 소비를 추적","이상 패턴 감지를 지원","Nextjs와 Convexとの 통합"],"es":["Detección de patrones de generación utilizando algoritmos de inteligencia artificial","Control del consumo de contexto para evitar el agotamiento de recursos","Integración con tecnologías como NextJS y TypeScript","Compatibilidad con licencia AGPL-3.0 para uso open source","Capacidad de seguimiento de herramientas de generación de inteligencia artificial","Visualización de datos de consumo de contexto y patrones de generación"],"fr":["Détection de modèles de génération à l''aide d''algorithmes d''intelligence artificielle","Contrôle de la consommation de contexte pour éviter l''épuisement des ressources","Intégration avec des technologies telles que NextJS et TypeScript","Compatibilité avec la licence AGPL-3.0 pour une utilisation open source","Capacité de suivi des outils de génération d''intelligence artificielle","Visualisation des données de consommation de contexte et de modèles de génération"],"de":["Erkennung von Generierungsmustern mithilfe von künstlicher Intelligenz-Algorithmen","Kontrolle des Kontextverbrauchs, um Ressourcenverbrauch zu vermeiden","Integration mit Technologien wie NextJS und TypeScript","Kompatibilität mit der AGPL-3.0-Lizenz für Open-Source-Verwendung","Fähigkeit zur Überwachung von künstlichen Intelligenz-Generierungstools","Visualisierung von Kontextverbrauchs- und Generierungsmustardaten"],"pt":["Rastreamento de consumo de contexto","Detecção de padrões de gastos excessivos","Interface BudgetState para acompanhamento de estado","Suporte a tecnologias como NextJS e TypeScript","Código aberto e auto-hospedado","Disponível em nuvem"],"ru":["Отслеживание потребления контекста","Обнаружение чрезмерных расходов","Интерфейс BudgetState для отслеживания состояния","Поддержка технологий như NextJS и TypeScript","Открытый исходный код и самохостинг","Доступно в облаке"],"ar":["تتبع استهلاك السياق","الكشف عن الأنماط المفرطة في الإنفاق","واجهة BudgetState لتتبع الحالة","دعم لتكنولوجيا مثل NextJS و TypeScript","كود مفتوح و自وست","متوفر في السحابة"]},"keywords":{"en":["how to use budget-tracker-patterns","budget-tracker-patterns alternative to ChatGPT","budget-tracker-patterns setup guide","what is budget-tracker-patterns","budget-tracker-patterns vs ChatGPT","install budget-tracker-patterns","budget-tracker-patterns AGPL-3.0 license","NextJS budget-tracker-patterns integration","TypeScript budget-tracker-patterns implementation"],"zh":["预算跟踪模式","AI工具","AGPL-3.0","Typescript","BudgetState接口","Nextjs","Convex","AIエージェント"],"ja":["予算トラッカー パターン","AIエージェント","AGPL-3.0","TypeScript","BudgetStateインターフェイス","Nextjs","Convex","AIツール"],"ko":["예산 추적 패턴","AI 도구","AGPL-3.0","Typescript","BudgetState 인터페이스","Nextjs","Convex","AI 에이전트"],"es":["agentes de inteligencia artificial","seguimiento de patrones de presupuesto","control de consumo de contexto","detección de patrones de generación","NextJS","TypeScript","AGPL-3.0","herramientas de inteligencia artificial","desarrollo de software de inteligencia artificial"],"fr":["agents d''intelligence artificielle","suivi des modèles de budget","contrôle de la consommation de contexte","détection de modèles de génération","NextJS","TypeScript","AGPL-3.0","outils d''intelligence artificielle","développement de logiciels d''intelligence artificielle"],"de":["künstliche Intelligenzagenten","Überwachung von Budgetmustern","Kontrolle des Kontextverbrauchs","Erkennung von Generierungsmustern","NextJS","TypeScript","AGPL-3.0","künstliche Intelligenzwerkzeuge","Entwicklung von künstlicher Intelligenz-Software"],"pt":["ferramentas de IA","otimização de custos","rastreamento de contexto","padrões de gastos excessivos","NextJS","TypeScript","código aberto","auto-hospedado","nuvem"],"ru":["ИИ Агенты","оптимизация затрат","отслеживание контекста","чрезмерные расходы","NextJS","TypeScript","открытый исходный код","самохостинг","облако"],"ar":["أدوات الذكاء الاصطناعي","تحسين التكاليف","تتبع السياق","الأنماط المفرطة في الإنفاق","NextJS","TypeScript","كود مفتوح","自وست","السحابة"]}},"owner":"planetaryescape","repo":"blah.chat","repoPath":"planetaryescape/blah.chat","stars":7,"forks":0,"updatedAt":"2026-02-28T20:36:58Z","topics":["agpl","ai","chat","convex","llm","nextjs","self-hosted","typescript"],"category":"community","skillMd":{"name":"budget-tracker-patterns","description":"Backend budget tracking patterns for AI generation. Awareness-based tracking (not blocking), tool timeouts, per-tool rate limits, token estimates, context window management, truncation strategies, search quality detection. Triggers on budget, tool timeout, rate limit, token estimate, truncation, context window, search quality, diminishing returns.","bodyPreview":"# Budget Tracker Patterns\n\nAwareness-based tracking for AI generation tool calls. Tracks context consumption, detects runaway patterns, provides visibility. Does NOT block tool calls - existing step limits handle that.\n\n## BudgetState Interface\n\nCore state tracked during generation:\n\n```typescript\n// From packages/backend/convex/lib/budgetTracker.ts\nexport interface BudgetState {\n  maxTokens: number;\n  usedTokens: number;\n  toolCallCount: number;\n  searchHistory: Array<{\n    query: string;\n    r","body":"# Budget Tracker Patterns\n\nAwareness-based tracking for AI generation tool calls. Tracks context consumption, detects runaway patterns, provides visibility. Does NOT block tool calls - existing step limits handle that.\n\n## BudgetState Interface\n\nCore state tracked during generation:\n\n```typescript\n// From packages/backend/convex/lib/budgetTracker.ts\nexport interface BudgetState {\n  maxTokens: number;\n  usedTokens: number;\n  toolCallCount: number;\n  searchHistory: Array<{\n    query: string;\n    resultCount: number;\n    topScore: number;\n  }>;\n  toolCallCounts: Record<string, number>; // Per-tool counts for rate limiting\n}\n```\n\nInitialize:\n```typescript\nconst budget = createBudgetState(maxTokens);\n```\n\nUpdate immutably:\n```typescript\nbudget = recordUsage(budget, tokens);\nbudget = recordToolCall(budget, toolName);\nbudget = recordSearch(budget, query, resultCount, topScore);\n```\n\n## Tool Timeout Pattern\n\nWall-clock timeout wrapper prevents stuck tools:\n\n```typescript\n// From packages/backend/convex/lib/budgetTracker.ts\nexport async function withTimeout<T>(\n  promise: Promise<T>,\n  timeoutMs: number,\n  operation: string,\n): Promise<T> {\n  let timeoutId: ReturnType<typeof setTimeout>;\n\n  const timeoutPromise = new Promise<never>((_, reject) => {\n    timeoutId = setTimeout(() => {\n      reject(new TimeoutError(operation, timeoutMs));\n    }, timeoutMs);\n  });\n\n  try {\n    const result = await Promise.race([promise, timeoutPromise]);\n    clearTimeout(timeoutId!);\n    return result;\n  } catch (error) {\n    clearTimeout(timeoutId!);\n    throw error;\n  }\n}\n```\n\n**Tool timeouts** (milliseconds):\n```typescript\nexport const TOOL_TIMEOUTS: Record<string, number> = {\n  searchAll: 30000,        // 30s - multiple parallel searches\n  searchFiles: 15000,\n  searchNotes: 15000,\n  searchTasks: 15000,\n  searchKnowledgeBank: 15000,\n  queryHistory: 15000,\n  urlReader: 120000,       // 2min - external fetch slow\n  codeExecution: 120000,   // 2min - code execution takes time\n  youtubeVideo: 300000,    // 5min - video processing slow\n  weather: 60000,          // 1min - external API\n  calculator: 5000,\n  datetime: 1000,\n  default: 30000,\n};\n```\n\nUsage:\n```typescript\nconst timeout = getToolTimeout(toolName);\nconst result = await withTimeout(toolPromise, timeout, `${toolName} call`);\n```\n\n## Per-Tool Rate Limits\n\nPrevent tool abuse while allowing reasonable usage:\n\n```typescript\n// From packages/backend/convex/lib/budgetTracker.ts\nconst TOOL_RATE_LIMITS: Record<string, number> = {\n  searchAll: 5,\n  searchFiles: 5,\n  searchNotes: 5,\n  searchTasks: 5,\n  searchKnowledgeBank: 5,\n  queryHistory: 5,\n  urlReader: 3,\n  codeExecution: 2,\n  weather: 3,\n  default: 10,\n};\n```\n\nCheck before calling:\n```typescript\nconst { limited, message } = isToolRateLimited(budget, toolName);\nif (limited) {\n  return { error: message };\n}\nbudget = recordToolCall(budget, toolName);\n```\n\nReturns:\n```typescript\n{\n  limited: true,\n  message: \"searchAll limit reached (5/5). Try a different approach.\"\n}\n```\n\n## Token Estimation\n\nRough estimates for context tracking (chars/4 approximation):\n\n```typescript\n// From packages/backend/convex/lib/budgetTracker.ts\nconst TOOL_TOKEN_ESTIMATES: Record<string, number> = {\n  searchAll: 800,\n  searchFiles: 400,\n  searchNotes: 300,\n  searchTasks: 300,\n  searchKnowledgeBank: 500,\n  queryHistory: 400,\n  urlReader: 1500,\n  codeExecution: 600,\n  calculator: 100,\n  datetime: 50,\n  weather: 200,\n  default: 300,\n};\n```\n\nGet estimate before tool execution:\n```typescript\nconst estimatedCost = estimateToolCost(toolName);\n```\n\nRecord actual usage after:\n```typescript\nconst actualTokens = countTokens(toolResult);\nbudget = recordUsage(budget, actualTokens);\n```\n\n## Context Getting Full Detection\n\nTiered warnings based on usage:\n\n```typescript\n// From packages/backend/convex/lib/budgetTracker.ts\nexport function formatStatus(state: BudgetState): string {\n  const percentUsed = getContextPercent(state);\n  const toolCount = state.toolCallCount;\n\n  if (percentUsed >= 70) {\n    return `[Budget Critical: ~${percentUsed}% context, ${toolCount} tools]\nAnswer now with current info or ask user for clarification.`;\n  }\n\n  if (percentUsed >= 50) {\n    return `[Budget: ~${percentUsed}% context, ${toolCount} tools]\nPrioritize essential searches only.`;\n  }\n\n  return `[Context: ${toolCount} tool calls, ~${percentUsed}% of context used]`;\n}\n```\n\nCheck programmatically:\n```typescript\nif (isContextGettingFull(budget)) {\n  // >= 50% used - inject warning into prompt\n}\n```\n\n## Truncation Strategy\n\nPreserve structure while managing context:\n\n```typescript\n// From packages/backend/convex/lib/budgetTracker.ts\nexport const MIN_TOOL_CALLS_FOR_TRUNCATION = 2; // Don''t truncate first tool call\n\nexport function truncateToolResult(\n  result: unknown,\n  maxChars: number = 500,\n): unknown {\n  const str = JSON.stringify(result);\n  if (str.length <= maxChars) return result;\n\n  // Arrays: keep first 3 items\n  if (Array.isArray(result)) {\n    return result\n      .slice(0, 3)\n      .map((item) => truncateToolResult(item, Math.floor(maxChars / 3)));\n  }\n\n  // Strings: truncate with marker\n  if (typeof result === \"string\") {\n    return `${result.slice(0, maxChars)}... [truncated]`;\n  }\n\n  // Objects: truncate string values\n  if (typeof result === \"object\" && result !== null) {\n    const truncated: Record<string, unknown> = {};\n    const keys = Object.keys(result);\n    if (keys.length === 0) return result;\n    const charPerKey = Math.floor(maxChars / keys.length);\n    for (const key of keys) {\n      truncated[key] = truncateToolResult(\n        (result as Record<string, unknown>)[key],\n        charPerKey,\n      );\n    }\n    return truncated;\n  }\n\n  return result;\n}\n```\n\nApply after MIN_TOOL_CALLS_FOR_TRUNCATION:\n```typescript\nif (budget.toolCallCount >= MIN_TOOL_CALLS_FOR_TRUNCATION) {\n  toolResult = truncateToolResult(toolResult);\n}\n```\n\n## Search Quality Detection\n\nDetect diminishing returns from repeated searches:\n\n```typescript\n// From packages/backend/convex/lib/budgetTracker.ts\nexport const LOW_QUALITY_SCORE_THRESHOLD = 0.7;\n\nexport function formatSearchWarning(state: BudgetState): string | null {\n  const { searchHistory } = state;\n  if (searchHistory.length === 0) return null;\n\n  const latest = searchHistory[searchHistory.length - 1];\n\n  // Repeated query\n  const isDuplicate = searchHistory\n    .slice(0, -1)\n    .some((h) => h.query.toLowerCase().trim() === latest.query.toLowerCase().trim());\n  if (isDuplicate) {\n    return `Already searched \"${latest.query}\". Try different terms or answer with current info.`;\n  }\n\n  // Decreasing quality (3+ searches)\n  if (searchHistory.length >= 3) {\n    const last3 = searchHistory.slice(-3).map((h) => h.topScore);\n    if (last3[0] > last3[1] && last3[1] > last3[2] && last3[2] < 0.5) {\n      return \"Search quality declining. Consider different approach or ask user.\";\n    }\n  }\n\n  // Many searches without good results\n  if (searchHistory.length >= 4) {\n    return \"Multiple searches performed. Consider answering with current info.\";\n  }\n\n  return null;\n}\n```\n\nCheck for stuck patterns:\n```typescript\nexport function shouldSuggestAskUser(state: BudgetState): boolean {\n  const { searchHistory } = state;\n\n  // 3+ searches with all low quality results\n  if (searchHistory.length >= 3) {\n    const recentScores = searchHistory.slice(-3).map((h) => h.topScore);\n    if (recentScores.every((s) => s < 0.7)) return true;\n  }\n\n  // Budget critical (>= 70%)\n  if (getContextPercent(state) >= 70) return true;\n\n  return false;\n}\n```\n\n## Key Files\n\n- `packages/backend/convex/lib/budgetTracker.ts` - Budget tracking, timeouts, truncation\n- `packages/backend/convex/generation/tools.ts` - Tool building with budget integration\n\n## BuildTools Integration\n\nPass budget state to tools for rate limiting:\n\n```typescript\n// From packages/backend/convex/generation/tools.ts\nexport interface BuildToolsConfig {\n  ctx: ActionCtx;\n  userId: Id<\"users\">;\n  conversationId: Id<\"conversations\">;\n  budgetState?: {\n    current: BudgetState;\n    update: (newState: BudgetState) => void;\n  };\n  // ... other config\n}\n\nexport function buildTools(config: BuildToolsConfig): Record<string, unknown> {\n  const { budgetState } = config;\n\n  // Pass budgetState to tools that need it (searchAll, etc.)\n  tools.searchAll = createSearchAllTool(\n    ctx,\n    userId,\n    conversationId,\n    searchCache,\n    budgetState, // Tool can check limits and update state\n  );\n}\n```\n\n## Avoid\n\n- Don''t block tool calls based on budget - use for awareness only\n- Don''t skip timeout wrapper - prevents generation hangs\n- Don''t ignore rate limits - prevents tool abuse\n- Don''t truncate first tool call - need full initial context\n- Don''t ignore search quality warnings - indicates stuck patterns\n"},"lastSynced":"2026-03-06T06:51:17.221Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing advanced budget tracking and runaway pattern detection for optimized tool call management in NextJS and TypeScript environments.","zh":"非常适合需要高级预算跟踪和运行模式检测以优化工具调用管理的AI代理，特别是在NextJS和TypeScript环境中。","ja":"NextJSおよびTypeScript環境でのツール呼び出しの最適化された管理のための高度な予算追跡とランアウェイパターン検出が必要なAIエージェントに最適です。","ko":"NextJS와 TypeScript 환경에서 최적화된 도구 호출 관리를 위한 고급 예산 추적 및 런어웨이 패턴 검색이 필요한 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA que necesitan un seguimiento avanzado de presupuesto y detección de patrones descontrolados para una gestión optimizada de llamadas de herramientas en entornos NextJS y TypeScript.","fr":"Parfait pour les agents IA ayant besoin d''un suivi avancé du budget et d''une détection de modèles déchaînés pour une gestion optimisée des appels d''outils dans les environnements NextJS et TypeScript.","de":"Perfekt für KI-Agents, die ein erweitertes Budget-Tracking und eine Ausreißermuster-Erkennung für eine optimierte Tool-Aufrufverwaltung in NextJS- und TypeScript-Umgebungen benötigen.","pt":"Perfeito para Agentes de IA que necessitam de acompanhamento orçamentário avançado e detecção de padrões descontrolados para gerenciamento otimizado de chamadas de ferramentas em ambientes NextJS e TypeScript.","ru":"Идеально подходит для агентов ИИ, которым требуется продвинутый учет бюджета и обнаружение неограниченных закономерностей для оптимизированного управления вызовами инструментов в средах NextJS и TypeScript.","ar":"مثالي لعمليات الوكلاء الذكية التي تحتاج إلى تتبع متقدم للميزانية واكتشاف أنماط هاربة لتنظيم أدوات متقنة في بيئات NextJS وTypeScript."},"recommendation":{"en":"Empowers agents to track context consumption, detect runaway patterns, and provide visibility into tool call counts and search history using the BudgetState interface, all while leveraging TypeScript and NextJS for seamless integration.","zh":"赋予代理跟踪上下文消费、检测运行模式并提供工具调用计数和搜索历史的可见性，使用BudgetState接口，同时利用TypeScript和NextJS实现无缝集成。","ja":"BudgetStateインターフェイスを使用して、コンテキストの消費を追跡し、ランアウェイパターンを検出し、ツール呼び出し回数と検索履歴の可視性を提供することで、エージェントを強化し、TypeScriptとNextJSを使用してシームレスな統合を実現します。","ko":"BudgetState 인터페이스를 사용하여 컨텍스트 소비를 추적하고 런어웨이 패턴을 검색하며 도구 호출 수와 검색 기록에 대한 가시성을 제공함으로써 에이전트를 강화하고 TypeScript와 NextJS를 사용하여 무缝한 통합을实现합니다.","es":"Habilita a los agentes a realizar un seguimiento del consumo de contexto, detectar patrones descontrolados y proporcionar visibilidad en los recuentos de llamadas de herramientas y el historial de búsqueda utilizando la interfaz BudgetState, todo mientras aprovecha TypeScript y NextJS para una integración sin problemas.","fr":"Autonomise les agents pour suivre la consommation de contexte, détecter les modèles déchaînés et fournir une visibilité sur les comptes d''appels d''outils et l''historique de recherche en utilisant l''interface BudgetState, le tout en exploitant TypeScript et NextJS pour une intégration transparente.","de":"Ermächtigt Agents, den Kontextverbrauch zu verfolgen, Ausreißermuster zu erkennen und Einblick in die Tool-Aufrufzahlen und die Suchhistorie mithilfe der BudgetState-Schnittstelle zu gewähren, und zwar unter Ausnutzung von TypeScript und NextJS für eine nahtlose Integration.","pt":"Habilita os agentes a acompanhar o consumo de contexto, detectar padrões descontrolados e fornecer visibilidade nos contadores de chamadas de ferramentas e histórico de pesquisa usando a interface BudgetState, tudo isso aproveitando o TypeScript e o NextJS para integração perfeita.","ru":"Наделяет агентов возможностью отслеживать потребление контекста, обнаруживать неограниченные закономерности и обеспечивать видимость счетчиков вызовов инструментов и истории поиска с помощью интерфейса BudgetState, все это при помощи TypeScript и NextJS для бесшовной интеграции.","ar":"يمنح الوكلاء القدرة على تتبع استهلاك السياق واكتشاف الأنماط الهاربة وتوفير الرؤية فيعدادات呼بة أدوات وسجل البحث باستخدام واجهة BudgetState، كل ذلك بالاستفادة من TypeScript وNextJS من أجل التكامل السلس."},"useCases":{"en":["Tracking context consumption for AI generation tool calls","Detecting runaway patterns to prevent excessive resource usage","Providing visibility into tool call counts and search history for optimized budget management"],"zh":["跟踪AI生成工具调用时的上下文消费","检测运行模式以防止过度资源使用","提供工具调用计数和搜索历史的可见性以优化预算管理"],"ja":["AI生成ツール呼び出しのコンテキスト消費を追跡する","過度のリソース使用を防ぐためにランアウェイパターンを検出する","ツール呼び出し回数と検索履歴の可視性を提供して予算管理を最適化する"],"ko":["AI 생성 도구 호출 시 컨텍스트 소비를 추적하는 것","과도한 리소스 사용을 방지하기 위해 런어웨이 패턴을 검색하는 것","도구 호출 수와 검색 기록에 대한 가시성을 제공하여 예산 관리를 최적화하는 것"],"es":["Seguimiento del consumo de contexto para llamadas de herramientas de generación de IA","Detección de patrones descontrolados para prevenir un uso excesivo de recursos","Proporcionar visibilidad en los recuentos de llamadas de herramientas y el historial de búsqueda para una gestión optimizada del presupuesto"],"fr":["Suivi de la consommation de contexte pour les appels d''outils de génération d''IA","Détection de modèles déchaînés pour prévenir une utilisation excessive de ressources","Fournir une visibilité sur les comptes d''appels d''outils et l''historique de recherche pour une gestion optimisée du budget"],"de":["Verfolgung des Kontextverbrauchs für KI-Generierungstool-Aufrufe","Erkennung von Ausreißermustern, um einen übermäßigen Ressourcenverbrauch zu verhindern","Bereitstellung von Einblicken in die Tool-Aufrufzahlen und die Suchhistorie für eine optimierte Budgetverwaltung"],"pt":["Acompanhamento do consumo de contexto para chamadas de ferramentas de geração de IA","Detecção de padrões descontrolados para prevenir uso excessivo de recursos","Fornecimento de visibilidade nos contadores de chamadas de ferramentas e histórico de pesquisa para gestão orçamentária otimizada"],"ru":["Отслеживание потребления контекста для вызовов инструментов генерации ИИ","Обнаружение неограниченных закономерностей для предотвращения чрезмерного использования ресурсов","Обеспечение видимости счетчиков вызовов инструментов и истории поиска для оптимизированного управления бюджетом"],"ar":["تتبع استهلاك السياق ل呼بة أدوات توليد الذكاء الاصطناعي","اكتشاف الأنماط الهاربة لمنع الاستخدام المفرط للموارد","توفير رؤية فيعدادات呼بة الأدوات وتسجيل البحث لأدارة الميزانية المتقنة"]},"limitations":{"en":["Does not block tool calls, relies on existing step limits for control","Specifically designed for NextJS and TypeScript environments"],"zh":["不阻止工具调用，依赖现有的步骤限制进行控制","专门为NextJS和TypeScript环境设计"],"ja":["ツール呼び出しをブロックしない、既存のステップ制限に依存して制御する","NextJSおよびTypeScript環境専用に設計"],"ko":["도구 호출을 차단하지 않음, 기존의 단계 제한에 의존하여 제어함","NextJS 및 TypeScript 환경専用로 설계됨"],"es":["No bloquea las llamadas de herramientas, depende de los límites de paso existentes para el control","Diseñado específicamente para entornos NextJS y TypeScript"],"fr":["Ne bloque pas les appels d''outils, s''appuie sur les limites de étapes existantes pour le contrôle","Conçu spécifiquement pour les environnements NextJS et TypeScript"],"de":["Blockiert keine Tool-Aufrufe, verlässt sich auf bestehende Schrittlimits für die Kontrolle","Speziell für NextJS- und TypeScript-Umgebungen konzipiert"],"pt":["Não bloqueia chamadas de ferramentas, confia nos limites de etapas existentes para controle","Especificamente projetado para ambientes NextJS e TypeScript"],"ru":["Не блокирует вызовы инструментов, полагается на существующие ограничения шагов для контроля","Специально разработан для сред NextJS и TypeScript"],"ar":["لا يمنع呼بة الأدوات، يعتمد على حدود الخطوات الحالية للسيطرة","صمّم خصيصاً لبيئات NextJS وTypeScript"]},"version":4},"contentHash":"d731101c652d0cdaec250dfca5be02e780da1765a561c8883c4b574539ea5559","qualityScore":39}');
