INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('planetaryescape/blah.chat/budget-tracker-patterns', 'budget-tracker-patterns', 'planetaryescape', 'blah.chat', 'community', 'budget-tracker-patterns planetaryescape blah.chat community agpl ai chat convex llm nextjs self-hosted typescript budget-tracker-patterns tracks context consumption and detects runaway patterns for AI generation tool calls, providing visibility and awareness. Ideal for developers using NextJS and TypeScript. 预算跟踪模式是一种用于跟踪AI工具调用上下文消费和检测异常模式的技术，基于AGPL-3.0和Typescript实现 予算トラッカー パターンは、AIエージェントの呼び出し上下文の消費を追跡し、異常パターンを検出する技術です。AGPL-3.0とTypeScriptを使用して実現しています 예산 추적 패턴은 AI 도구의 호출 컨텍스트 소비를 추적하고 이상 패턴을 감지하는 기술입니다. AGPL-3.0 및 Typescript를 사용하여 구현합니다 El seguimiento de patrones de presupuesto permite la detección de patrones de generación y el control del consumo de contexto en herramientas de inteligencia artificial Le suivi des modèles de budget permet la détection de modèles de génération et le contrôle de la consommation de contexte dans les outils d''intelligence artificielle Die Überwachung von Budgetmustern ermöglicht die Erkennung von Generierungsmustern und die Kontrolle des Kontextverbrauchs in künstlichen Intelligenzwerkzeugen O budget-tracker-patterns é uma ferramenta de código aberto que ajuda a otimizar o uso de ferramentas de IA, rastreando o consumo de contexto e detectando padrões de gastos excessivos Budget-tracker-patterns - это открытый инструмент, который помогает оптимизировать использование ИИ Агентов, отслеживая потребление контекста и обнаруживая чрезмерные расходы budget-tracker-patterns هو أداة مفتوحة المصدر تساعد في تحسين استخدام أدوات الذكاء الاصطناعي، من خلال تتبع استهلاك السياق والكشف عن الأنماط المفرطة في الإنفاق how to use budget-tracker-patterns budget-tracker-patterns alternative to ChatGPT budget-tracker-patterns setup guide what is budget-tracker-patterns budget-tracker-patterns vs ChatGPT install budget-tracker-patterns budget-tracker-patterns AGPL-3.0 license NextJS budget-tracker-patterns integration TypeScript budget-tracker-patterns implementation 预算跟踪模式 AI工具 AGPL-3.0 Typescript BudgetState接口 Nextjs Convex AIエージェント Tracks context consumption using the BudgetState interface Detects runaway patterns in AI generation tool calls Provides visibility into tool call counts and search history Utilizes TypeScript for core state tracking Integrates with NextJS for seamless implementation Offers a hosted cloud version for easy deployment budget-tracker-patterns is an open-source, self-hostable alternative to ChatGPT, utilizing AGPL-3.0 license and offering a hosted cloud version.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MidnightV1/Claude-Code-Feishu/feishu-drive', 'community', 'MidnightV1', 'Claude-Code-Feishu', 'MidnightV1/Claude-Code-Feishu', 'feishu-drive', 7, 0, 39, '2026-03-06T12:02:18Z', '2026-03-07T01:52:20.074Z', 'a0fd7d831b035883afa544358494ca5acd9e8a2f0f13c8e3950b1e3b78ccdd1b', '{"id":"MidnightV1/Claude-Code-Feishu/feishu-drive","name":"feishu-drive","description":{"en":"The feishu-drive skill enables AI agents to manage files and folders in Feishu Drive, benefiting developers and teams. It provides a messaging interface with calendar, documents, and tasks.","zh":"Feishu Drive Skill 提供文件管理和自动化功能，包括文件浏览、组织和管理","ja":"Feishu Drive Skill はファイル管理と自動化機能を提供し、ファイルの閲覧、整理、管理を行う","ko":"Feishu Drive 스킬은 파일 관리 및 자동화 기능을 제공하며 파일을 브라우징, 조직 및 관리","es":"Feishu Drive es una herramienta de gestión de archivos y carpetas que se integra con la interfaz de mensajería Feishu/Lark. Ofrece funciones como la organización de archivos, la creación de carpetas y la gestión de metadatos.","fr":"Feishu Drive est un outil de gestion de fichiers et de dossiers qui s''intègre à l''interface de messagerie Feishu/Lark. Il propose des fonctionnalités telles que l''organisation de fichiers, la création de dossiers et la gestion de métadonnées.","de":"Feishu Drive ist ein Tool zur Verwaltung von Dateien und Ordnern, das in die Feishu/Lark-Messaging-Oberfläche integriert ist. Es bietet Funktionen wie Dateiorganisation, Ordnererstellung und Metadatenverwaltung.","pt":"O Feishu Drive é uma habilidade que permite gerenciar arquivos e pastas com comandos Python. Ele oferece recursos como listagem de arquivos, obtenção de metadados e criação de pastas.","ru":"Feishu Drive — это навык, который позволяет управлять файлами и папками с помощью команд Python. Он предлагает такие возможности, как список файлов, получение метаданных и создание папок.","ar":"Feishu Drive هو مهارة يسمح بإدارة الملفات والمجلدات باستخدام أوامر Python. يقدم ميزات مثل قائمة الملفات، الحصول على البيانات الوصفية وإنشاء المجلدات."},"seo":{"title":{"en":"feishu-drive: File Management Setup Guide | AI Agent Skill","zh":"Feishu Drive 集成指南：文件管理和自动化","ja":"Feishu Drive Setup Guide: AIエージェントによるファイル管理","ko":"Feishu Drive 설치 가이드: 파일 관리 및 자동화","es":"Guía de configuración de Feishu Drive para desarrolladores","fr":"Guide de mise en route de Feishu Drive pour les développeurs","de":"Einrichtungsleitfaden für Feishu Drive-Entwickler","pt":"Guia de Configuração do Feishu Drive: Integração de Arqui...","ru":"Настройка Feishu Drive: Интеграция Файлов и Папок для ИИ ...","ar":"دليل إعداد Feishu Drive: دمج الملفات والمجلدات للوكلاء ال..."},"description":{"en":"Unlock Feishu Drive''s full potential with our expert guide. Learn how to browse, organize, and manage files with drive_ctl.py commands and more!","zh":"使用 Feishu Drive Skill 实现文件浏览、组织和管理，包括日历、文档、任务、Wiki 和自动健康监测","ja":"Feishu Drive Skill を使用してファイルの閲覧、整理、管理を行い、カレンダー、ドキュメント、タスク、Wiki、自動ヘルスモニタリングを実現","ko":"Feishu Drive 스킬을 사용하여 파일을 브라우징, 조직 및 관리하고 달력, 문서, 작업, Wiki 및 자동 건강 모니터링을 구현","es":"Aprende a integrar Feishu Drive en tus proyectos con nuestra guía de configuración y mejores prácticas para desarrolladores","fr":"Découvrez comment intégrer Feishu Drive dans vos projets avec notre guide de configuration et les meilleures pratiques pour les développeurs","de":"Erfahren Sie, wie Sie Feishu Drive in Ihre Projekte integrieren können, mit unserer Einrichtungsanleitung und Best Practices für Entwickler","pt":"Aprenda a configurar o Feishu Drive para gerenciar arquivos e pastas com facilidade. Descubra como utilizar comandos Python para otimizar sua produtividade.","ru":"Узнайте, как настроить Feishu Drive для управления файлами и папками. Откройте для себя возможности команд Python для повышения производительности.","ar":"تعرف على كيفية إعداد Feishu Drive لإدارة الملفات والمجلدات بسهولة. اكتشف كيفية استخدام أوامر Python لتحسين الإنتاجية."},"definition":{"en":"feishu-drive is a skill that allows AI agents to interact with Feishu Drive, enabling file management and organization using commands like drive_ctl.py","zh":"Feishu Drive 是一个提供文件管理和自动化功能的 AI Skill","ja":"Feishu Drive はファイル管理と自動化機能を提供する AIエージェント","ko":"Feishu Drive는 파일 관리 및 자동화 기능을 제공하는 AI 스킬","es":"Feishu Drive es una herramienta de gestión de archivos y carpetas para desarrolladores","fr":"Feishu Drive est un outil de gestion de fichiers et de dossiers pour les développeurs","de":"Feishu Drive ist ein Tool zur Verwaltung von Dateien und Ordnern für Entwickler","pt":"O que é Feishu Drive? É uma habilidade que fornece uma interface de gerenciamento de arquivos e pastas para o Feishu/Lark.","ru":"Что такое Feishu Drive? Это навык, который предоставляет интерфейс для управления файлами и папками для Feishu/Lark.","ar":"ما هو Feishu Drive؟ إنه مهارة يوفر واجهة لإدارة الملفات والمجلدات لـ Feishu/Lark."},"features":{"en":["List files in root or a folder using drive_ctl.py list command","Get file/folder metadata with drive_ctl.py info command","Create folders using drive_ctl.py mkdir command","Move files using drive_ctl.py move command","Supports file types like docx, sheet, and bitable"],"zh":["文件浏览和管理","文件夹创建和管理","文件元数据获取","自动健康监测","日历、文档、任务、Wiki 集成"],"ja":["ファイルの閲覧と管理","フォルダの作成と管理","ファイルのメタデータ取得","自動ヘルスモニタリング","カレンダー、ドキュメント、タスク、Wiki の統合"],"ko":["파일 브라우징과 관리","폴더 생성과 관리","파일 메타데이터 获取","자동 건강 모니터링","달력, 문서, 작업, Wiki 통합"],"es":["Organización de archivos y carpetas","Creación de carpetas y subcarpetas","Gestión de metadatos de archivos y carpetas","Integración con la interfaz de mensajería Feishu/Lark","Soporte para la línea de comandos (CLI) con Python"],"fr":["Organisation de fichiers et de dossiers","Création de dossiers et de sous-dossiers","Gestion de métadonnées de fichiers et de dossiers","Intégration à l''interface de messagerie Feishu/Lark","Prise en charge de la ligne de commande (CLI) avec Python"],"de":["Verwaltung von Dateien und Ordnern","Erstellung von Ordnern und Unterordnern","Verwaltung von Metadaten von Dateien und Ordnern","Integration in die Feishu/Lark-Messaging-Oberfläche","Unterstützung für die Kommandozeile (CLI) mit Python"],"pt":["Listagem de arquivos em pastas específicas","Obtenção de metadados de arquivos e pastas","Criação de pastas com comandos Python","Gerenciamento de arquivos e pastas com o Feishu/Lark","Integração com calendário, documentos e tarefas"],"ru":["Список файлов в конкретных папках","Получение метаданных файлов и папок","Создание папок с помощью команд Python","Управление файлами и папками с помощью Feishu/Lark","Интеграция с календарем, документами и задачами"],"ar":["قائمة الملفات في المجلدات المحددة","الحصول على البيانات الوصفية للملفات والمجلدات","إنشاء المجلدات باستخدام أوامر Python","إدارة الملفات والمجلدات مع Feishu/Lark","التكامل مع التقويم والوثائق والمهام"]},"keywords":{"en":["how to use feishu-drive","feishu-drive setup guide","feishu-drive alternative","feishu-drive vs lark","feishu-drive install","feishu-drive file management","drive_ctl.py commands","feishu drive integration"],"zh":["Feishu Drive","AI Skill","文件管理","自动化","日历集成","文档管理","任务管理","Wiki 集成","自动健康监测"],"ja":["Feishu Drive","AIエージェント","ファイル管理","自動化","カレンダー統合","ドキュメント管理","タスク管理","Wiki 統合","自動ヘルスモニタリング"],"ko":["Feishu Drive","AI 스킬","파일 관리","자동화","달력 통합","문서 관리","작업 관리","Wiki 통합","자동 건강 모니터링"],"es":["Feishu Drive","herramienta de gestión de archivos","integración con Feishu/Lark","desarrollo de software","Python","CLI","gestión de metadatos","organización de archivos"],"fr":["Feishu Drive","outils de gestion de fichiers","intégration à Feishu/Lark","développement de logiciels","Python","CLI","gestion de métadonnées","organisation de fichiers"],"de":["Feishu Drive","Tool zur Verwaltung von Dateien","Integration in Feishu/Lark","Softwareentwicklung","Python","CLI","Verwaltung von Metadaten","Verwaltung von Dateien"],"pt":["Feishu Drive","gerenciamento de arquivos","pastas Feishu","comandos Python","integração Feishu/Lark","produtividade","automatização"],"ru":["Feishu Drive","управление файлами","папки Feishu","команды Python","интеграция Feishu/Lark","производительность","автоматизация"],"ar":["Feishu Drive","إدارة الملفات","مجلدات Feishu","أوامر Python","التكامل Feishu/Lark","الإنتاجية","الآليّة"]}},"owner":"MidnightV1","repo":"Claude-Code-Feishu","repoPath":"MidnightV1/Claude-Code-Feishu","stars":7,"forks":0,"updatedAt":"2026-03-06T12:02:18Z","topics":[],"category":"community","skillMd":{"name":"feishu-drive","description":"Manage Feishu Drive / cloud storage (云盘/云空间) — list files/folders, create folders, move/delete files, search, get file info. Use when the user mentions cloud drive (云盘/云空间), file management (文件管理), folders (文件夹), or wants to organize/find files in Feishu Drive.","bodyPreview":"# Feishu Drive\r\n\r\nBrowse, organize, and manage files and folders in Feishu Drive.\r\n\r\n## Tool\r\n\r\n```\r\npython3 .claude/skills/feishu-drive/scripts/drive_ctl.py <command> [args]\r\n```\r\n\r\n## Commands\r\n\r\n```bash\r\n# List files in root or a folder\r\ndrive_ctl.py list [--folder <folder_token>] [--type docx|sheet|bitable|folder|...] [--limit 20]\r\n\r\n# Get file/folder metadata\r\ndrive_ctl.py info <token_or_url>\r\n\r\n# Create a folder\r\ndrive_ctl.py mkdir \"Folder Name\" [--parent <folder_token>]\r\n\r\n# Move a file/f","body":"# Feishu Drive\r\n\r\nBrowse, organize, and manage files and folders in Feishu Drive.\r\n\r\n## Tool\r\n\r\n```\r\npython3 .claude/skills/feishu-drive/scripts/drive_ctl.py <command> [args]\r\n```\r\n\r\n## Commands\r\n\r\n```bash\r\n# List files in root or a folder\r\ndrive_ctl.py list [--folder <folder_token>] [--type docx|sheet|bitable|folder|...] [--limit 20]\r\n\r\n# Get file/folder metadata\r\ndrive_ctl.py info <token_or_url>\r\n\r\n# Create a folder\r\ndrive_ctl.py mkdir \"Folder Name\" [--parent <folder_token>]\r\n\r\n# Move a file/folder\r\ndrive_ctl.py move <file_token> <dest_folder_token> --type <file_type>\r\n\r\n# Delete a file/folder (moves to trash)\r\ndrive_ctl.py delete <file_token> --type <file_type>\r\n\r\n# Search files by name\r\ndrive_ctl.py search \"query\" [--type docx|sheet|...] [--limit 20]\r\n```\r\n\r\n## File Types\r\n\r\n| Type | Description |\r\n|------|-------------|\r\n| `docx` | Document |\r\n| `sheet` | Spreadsheet |\r\n| `bitable` | Multidimensional table |\r\n| `folder` | Folder |\r\n| `file` | Uploaded file |\r\n| `mindnote` | Mind map |\r\n| `slides` | Presentation |\r\n\r\n## URL Handling\r\n\r\nDrive URLs are automatically parsed — pass full Feishu URLs directly to `info`.\r\n\r\n## Behavior Notes\r\n\r\n- `list` with no `--folder` shows root folder contents.\r\n- `delete` moves to trash (recoverable), not permanent deletion.\r\n- `search` uses the Drive file search API with keyword matching.\r\n- Bot needs `drive:drive` and `drive:file` permission scopes.\r\n"},"lastSynced":"2026-03-07T01:52:20.074Z","agentAnalysis":{"suitability":{"en":"Ideal for Cloud Storage Agents needing seamless Feishu Drive integration for file management and collaboration.","zh":"适用于需要与飞书网盘进行无缝集成的云存储代理，用于文件管理和协作。","ja":"ファイル管理およびコラボレーションのためのFeishu Driveとのシームレスな統合が必要なクラウドストレージエージェントに最適。","ko":"파일 관리 및 협업을 위한 Feishu Drive와의無斷な 통합이 필요한 클라우드 스토리지 에이전트에 적합합니다.","es":"Ideal para agentes de almacenamiento en la nube que necesitan una integración sin problemas con Feishu Drive para la administración de archivos y la colaboración.","fr":"Idéal pour les agents de stockage cloud ayant besoin d''une intégration transparente de Feishu Drive pour la gestion de fichiers et la collaboration.","de":"Ideal für Cloud-Speicher-Agents, die eine nahtlose Integration mit Feishu Drive für Dateiverwaltung und Zusammenarbeit benötigen.","pt":"Ideal para Agentes de Armazenamento em Nuvem que necessitam de integração perfeita com o Feishu Drive para gerenciamento de arquivos e colaboração.","ru":"Идеально для агентов облачного хранилища, которым необходима бесперебойная интеграция с Feishu Drive для управления файлами и сотрудничества.","ar":"مثالي لعميل تخزين السحابي الذي يحتاج إلى دمج سلس مع Feishu Drive لإدارة الملفات والتعاون."},"recommendation":{"en":"Empowers agents to browse, organize, and manage files and folders in Feishu Drive using Python scripts, facilitating tasks such as listing files, getting file metadata, and creating folders, all through a messaging interface with calendar, documents, and tasks support.","zh":"赋予代理人使用Python脚本浏览、组织和管理飞书网盘中的文件和文件夹的能力，实现文件列表、获取文件元数据、创建文件夹等任务，所有这些都可以通过支持日历、文档和任务的消息接口来实现。","ja":"エージェントがPythonスクリプトを使用してFeishu Driveのファイルとフォルダを参照、組織、管理できるようにし、ファイルのリスト表示、ファイルメタデータの取得、フォルダの作成などのタスクを、カレンダー、ドキュメント、タスクをサポートしたメッセージインターフェイスを通じて実行できる。","ko":"에이전트가 Python 스크립트를 사용하여 Feishu Drive의 파일과 폴더를 브라우징하고, 조직하고, 관리할 수 있는 능력을 부여하여, 파일 목록, 파일 메타데이터 가져오기, 폴더 생성 등과 같은 작업을 달력, 문서, 작업을 지원하는 메시지 인터페이스를 통해 수행할 수 있습니다.","es":"Habilita a los agentes para navegar, organizar y gestionar archivos y carpetas en Feishu Drive mediante scripts de Python, facilitando tareas como la lista de archivos, la obtención de metadatos de archivo y la creación de carpetas, todo a través de una interfaz de mensajería con soporte de calendario, documentos y tareas.","fr":"Permet aux agents de parcourir, d''organiser et de gérer des fichiers et des dossiers dans Feishu Drive à l''aide de scripts Python, facilitant des tâches telles que la liste de fichiers, l''obtention de métadonnées de fichier et la création de dossiers, le tout via une interface de messagerie avec prise en charge de calendrier, de documents et de tâches.","de":"Ermächtigt Agenten, Dateien und Ordner in Feishu Drive mithilfe von Python-Skripten zu durchsuchen, zu organisieren und zu verwalten, wodurch Aufgaben wie die Auflistung von Dateien, das Abrufen von Dateimetadaten und das Erstellen von Ordnern erleichtert werden, all dies über eine Messaging-Oberfläche mit Kalender-, Dokumenten- und Aufgabenunterstützung.","pt":"Habilita os agentes a navegar, organizar e gerenciar arquivos e pastas no Feishu Drive usando scripts Python, facilitando tarefas como listar arquivos, obter metadados de arquivos e criar pastas, tudo por meio de uma interface de mensagens com suporte a calendário, documentos e tarefas.","ru":"Наделяет агентов возможностью просматривать, организовывать и управлять файлами и папками в Feishu Drive с помощью скриптов Python, облегчая задачи, такие как перечисление файлов, получение метаданных файлов и создание папок, все через интерфейс сообщений с поддержкой календаря, документов и задач.","ar":"يتمكّن الوكيل من استعراض وتنظيم وإدارة الملفات والمجلدات في Feishu Drive باستخدام سكريبتات Python، مما يسهل المهام مثل قائمة الملفات و الحصول على بيانات وصف الملفات و إنشاء المجلدات، و كل ذلك من خلال واجهة رسائل مع دعم التقويم والوثائق والمهام."},"useCases":{"en":["Automating file organization in Feishu Drive","Generating folder structures for team collaborations","Retrieving file metadata for document management"],"zh":["在飞书网盘中自动化文件组织","为团队协作生成文件夹结构","检索文件元数据以进行文档管理"],"ja":["Feishu Driveでのファイルの自動化された整理","チームコラボレーションのためのフォルダ構造の生成","文書管理のためのファイルメタデータの取得"],"ko":["Feishu Drive에서 파일 자동화 조직","팀 협업을 위한 폴더 구조 생성","문서 관리를 위한 파일 메타데이터 가져오기"],"es":["Automatización de la organización de archivos en Feishu Drive","Generación de estructuras de carpetas para colaboraciones de equipo","Recuperación de metadatos de archivo para la administración de documentos"],"fr":["Automatisation de l''organisation de fichiers dans Feishu Drive","Génération de structures de dossiers pour des collaborations d''équipe","Récupération de métadonnées de fichier pour la gestion de documents"],"de":["Automatisierung der Dateiorganisation in Feishu Drive","Erstellung von Ordnerstrukturen für Teamzusammenarbeiten","Abrufen von Dateimetadaten für die Dokumentenverwaltung"],"pt":["Automatizar a organização de arquivos no Feishu Drive","Gerar estruturas de pastas para colaborações em equipe","Recuperar metadados de arquivos para gerenciamento de documentos"],"ru":["Автоматизировать организацию файлов в Feishu Drive","Генерировать структуры папок для командного сотрудничества","Извлекать метаданные файлов для управления документами"],"ar":["توفير آلي لتنظيم الملفات في Feishu Drive","توليد هيكل المجلدات للتعاون الفريق","استرجاع بيانات وصف الملفات لإدارة الوثائق"]},"limitations":{"en":["Requires Feishu Drive access","Python 3.x compatibility needed for drive_ctl.py script execution"],"zh":["需要飞书网盘访问权限","需要Python 3.x兼容性以执行drive_ctl.py脚本"],"ja":["Feishu Driveへのアクセスが必要","drive_ctl.pyスクリプトの実行にはPython 3.xの互換性が必要"],"ko":["Feishu Drive 액세스 필요","drive_ctl.py 스크립트 실행을 위한 Python 3.x 호환성 필요"],"es":["Requiere acceso a Feishu Drive","Compatibilidad con Python 3.x necesaria para la ejecución del script drive_ctl.py"],"fr":["Nécessite un accès à Feishu Drive","Compatibilité Python 3.x requise pour l''exécution du script drive_ctl.py"],"de":["Benötigt Zugriff auf Feishu Drive","Python 3.x-Kompatibilität erforderlich für die Ausführung des Skripts drive_ctl.py"],"pt":["Requer acesso ao Feishu Drive","Compatibilidade com Python 3.x necessária para execução do script drive_ctl.py"],"ru":["Требуется доступ к Feishu Drive","Необходима совместимость с Python 3.x для выполнения скрипта drive_ctl.py"],"ar":["يتطلب الوصول إلى Feishu Drive","مطلوبة توافق مع Python 3.x لتنفيذ سكريبت drive_ctl.py"]},"version":4},"contentHash":"a0fd7d831b035883afa544358494ca5acd9e8a2f0f13c8e3950b1e3b78ccdd1b","qualityScore":39}');
DELETE FROM skills_fts WHERE id = 'MidnightV1/Claude-Code-Feishu/feishu-drive';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MidnightV1/Claude-Code-Feishu/feishu-drive', 'feishu-drive', 'MidnightV1', 'Claude-Code-Feishu', 'community', 'feishu-drive MidnightV1 Claude-Code-Feishu community The feishu-drive skill enables AI agents to manage files and folders in Feishu Drive, benefiting developers and teams. It provides a messaging interface with calendar, documents, and tasks. Feishu Drive Skill 提供文件管理和自动化功能，包括文件浏览、组织和管理 Feishu Drive Skill はファイル管理と自動化機能を提供し、ファイルの閲覧、整理、管理を行う Feishu Drive 스킬은 파일 관리 및 자동화 기능을 제공하며 파일을 브라우징, 조직 및 관리 Feishu Drive es una herramienta de gestión de archivos y carpetas que se integra con la interfaz de mensajería Feishu/Lark. Ofrece funciones como la organización de archivos, la creación de carpetas y la gestión de metadatos. Feishu Drive est un outil de gestion de fichiers et de dossiers qui s''intègre à l''interface de messagerie Feishu/Lark. Il propose des fonctionnalités telles que l''organisation de fichiers, la création de dossiers et la gestion de métadonnées. Feishu Drive ist ein Tool zur Verwaltung von Dateien und Ordnern, das in die Feishu/Lark-Messaging-Oberfläche integriert ist. Es bietet Funktionen wie Dateiorganisation, Ordnererstellung und Metadatenverwaltung. O Feishu Drive é uma habilidade que permite gerenciar arquivos e pastas com comandos Python. Ele oferece recursos como listagem de arquivos, obtenção de metadados e criação de pastas. Feishu Drive — это навык, который позволяет управлять файлами и папками с помощью команд Python. Он предлагает такие возможности, как список файлов, получение метаданных и создание папок. Feishu Drive هو مهارة يسمح بإدارة الملفات والمجلدات باستخدام أوامر Python. يقدم ميزات مثل قائمة الملفات، الحصول على البيانات الوصفية وإنشاء المجلدات. how to use feishu-drive feishu-drive setup guide feishu-drive alternative feishu-drive vs lark feishu-drive install feishu-drive file management drive_ctl.py commands feishu drive integration Feishu Drive AI Skill 文件管理 自动化 日历集成 文档管理 任务管理 Wiki 集成 自动健康监测 List files in root or a folder using drive_ctl.py list command Get file/folder metadata with drive_ctl.py info command Create folders using drive_ctl.py mkdir command Move files using drive_ctl.py move command Supports file types like docx, sheet, and bitable feishu-drive is a skill that allows AI agents to interact with Feishu Drive, enabling file management and organization using commands like drive_ctl.py');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cjprybol/Mycelia/coverage-expansion', 'community', 'cjprybol', 'Mycelia', 'cjprybol/Mycelia', 'coverage-expansion', 6, 3, 39, '2026-02-27T13:43:34Z', '2026-03-06T06:53:25.769Z', '81271b74ad678c3d491bcfab320d4b7f602889a82311741bb0103a77ece99077', '{"id":"cjprybol/Mycelia/coverage-expansion","name":"coverage-expansion","description":{"en":"coverage-expansion is a skill designed for linux-based HPC and cloud systems, enabling multiomic analysis and data integration for biological characterization, prediction, and design. It benefits developers working with the Mycelia Julia package.","zh":"coverage-expansion 技术用于生物特征分析和数据集成，支持 Linux 基础的 HPC 和云系统，实现多组学分析和预测","ja":"coverage-expansion は、生物学的特性分析とデータ統合を実現するテクノロジーです。Linux ベースの HPC およびクラウドシステムで動作し、多オミクス分析と予測を可能にします","ko":"coverage-expansion 기술은 생물학적 특성 분석 및 데이터 통합을 위한 솔루션으로, 리눅스 기반의 HPC 및 클라우드 시스템에서 동작하며 다중 오믹스 분석 및 예측을 가능하게 합니다","es":"coverage-expansion es una herramienta para expandir la cobertura de pruebas del paquete Mycelia de Julia, diseñada para sistemas HPC y cloud basados en Linux","fr":"coverage-expansion est un outil pour étendre la couverture de tests du package Mycelia de Julia, conçu pour les systèmes HPC et cloud basés sur Linux","de":"coverage-expansion ist ein Werkzeug zur Erweiterung der Testabdeckung des Mycelia-Pakets von Julia, entwickelt für Linux-basierte HPC- und Cloud-Systeme","pt":"A expansão de cobertura é uma ferramenta para análise multiômica e integração de dados em sistemas Linux-based HPC e cloud.","ru":"Расширение покрытия - это инструмент для мультиомной аналитики и интеграции данных в системах Linux-based HPC и cloud.","ar":"توسيع الغطاء هو أداة لتحليل متعدد الأوجه وتكامل البيانات في أنظمة Linux-based HPC و السحابية"},"seo":{"title":{"en":"coverage-expansion: Systematic Test Coverage Setup Guide ...","zh":"coverage-expansion 设置指南：生物特征分析和数据集成","ja":"coverage-expansion のセットアップガイド：AIエージェントによる生物学的特性分析とデータ統合","ko":"coverage-expansion 설정 가이드: 생물학적 특성 분석 및 데이터 통합","es":"Guía de Configuración de coverage-expansion para Análisis...","fr":"Guide d''Installation de coverage-expansion pour l''Analyse...","de":"Einrichtungsleitfaden für coverage-expansion zur Multiomi...","pt":"Guia de Configuração de Expansão de Cobertura para Anális...","ru":"Руководство по настройке расширения покрытия для мультиом...","ar":"دليل إعداد توسيع الغطاء لتحليل متعدد الأوجه"},"description":{"en":"Unlock comprehensive test coverage with coverage-expansion. Learn how to systematically expand test coverage for the Mycelia Julia package and improve your d...","zh":"了解 coverage-expansion 技术，实现生物特征分析、预测和设计的数据集成，适用于 Linux 基础的 HPC 和云系统","ja":"coverage-expansion を使用して、生物学的特性分析、予測、設計のためのデータ統合を実現します。Linux ベースの HPC およびクラウドシステム対応","ko":"coverage-expansion 기술을 사용하여 생물학적 특성 분석, 예측 및 설계를 위한 데이터 통합을 실현하세요. 리눅스 기반의 HPC 및 클라우드 시스템을 지원합니다","es":"Aprende a expandir la cobertura de pruebas para el paquete Mycelia de Julia con coverage-expansion y mejora la caracterización biológica","fr":"Découvrez comment étendre la couverture de tests pour le package Mycelia de Julia avec coverage-expansion et améliorez la caractérisation biologique","de":"Erfahren Sie, wie Sie die Testabdeckung für das Mycelia-Paket von Julia mit coverage-expansion erweitern und die biologische Charakterisierung verbessern","pt":"Aprenda a configurar a expansão de cobertura para análise multiômica e integração de dados em sistemas Linux-based HPC e cloud","ru":"Узнайте, как настроить расширение покрытия для мультиомной аналитики и интеграции данных в системах Linux-based HPC и cloud - ИИ Агенты","ar":"تعلم كيفية إعداد توسيع الغطاء لتحليل متعدد الأوجه وتكامل البيانات في أنظمة Linux-based HPC و السحابية"},"definition":{"en":"coverage-expansion is a systematic approach to expanding test coverage for the Mycelia Julia package, utilizing environment flags and coverage files to identify gaps and improve accuracy.","zh":"coverage-expansion 是一种用于生物特征分析和数据集成的技术，支持多组学分析和预测","ja":"coverage-expansion は、生物学的特性分析とデータ統合を実現する AI エージェントのテクノロジーです","ko":"coverage-expansion은 생물학적 특성 분석 및 데이터 통합을 위한 기술로, 다중 오믹스 분석 및 예측을 지원합니다","es":"coverage-expansion es una técnica de análisis multiómico para la caracterización y predicción biológica","fr":"coverage-expansion est une technique d''analyse multiomique pour la caractérisation et la prédiction biologique","de":"coverage-expansion ist eine Technik der Multiomikanalyse für die biologische Charakterisierung und Vorhersage","pt":"O que é expansão de cobertura? É uma técnica para expandir a cobertura de testes para o pacote Mycelia Julia.","ru":"Что такое расширение покрытия? Это техника для расширения покрытия тестов для пакета Mycelia Julia - ИИ Агенты","ar":"ما هو توسيع الغطاء؟ إنه تقنية لتوسيع تغطية الاختبارات لحزمة Mycelia Julia"},"features":{"en":["Utilizes bash commands to check for existing coverage files","Employs environment flags such as MYCELIA_RUN_ALL and MYCELIA_RUN_EXTERNAL for accurate coverage","Identifies gaps in coverage using recent .cov files","Designed for linux-based HPC and cloud systems","Integrates with the Mycelia Julia package for comprehensive test coverage","Supports systematic expansion of test coverage for improved accuracy"],"zh":["支持 Linux 基础的 HPC 和云系统","实现多组学分析和预测","使用 find 命令检查现有的 coverage 文件","环境标志设置，实现准确的 coverage 分析","支持 Mycelia Julia 包的测试覆盖扩展","使用 export 命令设置环境标志"],"ja":["Linux ベースの HPC およびクラウドシステムをサポート","多オミクス分析と予測を実現","find コマンドを使用して既存の coverage ファイルを確認","環境フラグを設定して正確な coverage 分析を実現","Mycelia Julia パッケージのテストカバー範囲の拡張をサポート","export コマンドを使用して環境フラグを設定"],"ko":["리눅스 기반의 HPC 및 클라우드 시스템을 지원","다중 오믹스 분석 및 예측을 실현","find 명령을 사용하여 기존의 coverage 파일을 확인","환경 플래그를 설정하여 정확한 coverage 분석을 실현","Mycelia Julia 패키지의 테스트 커버리지 확장을 지원","export 명령을 사용하여 환경 플래그를 설정"],"es":["Análisis multiómico para la caracterización biológica","Integración de datos para la predicción y el diseño","Diseñado para sistemas HPC y cloud basados en Linux","Compatibilidad con el paquete Mycelia de Julia","Expansión sistemática de la cobertura de pruebas","Soporte para la identificación de brechas en la cobertura"],"fr":["Analyse multiomique pour la caractérisation biologique","Intégration de données pour la prédiction et la conception","Conçu pour les systèmes HPC et cloud basés sur Linux","Compatibilité avec le package Mycelia de Julia","Étendue systématique de la couverture de tests","Support pour l''identification des lacunes dans la couverture"],"de":["Multiomikanalyse für die biologische Charakterisierung","Datenintegration für die Vorhersage und das Design","Entwickelt für Linux-basierte HPC- und Cloud-Systeme","Kompatibilität mit dem Mycelia-Paket von Julia","Systematische Erweiterung der Testabdeckung","Unterstützung für die Identifizierung von Lücken in der Abdeckung"],"pt":["Análise multiômica e integração de dados","Suporte a sistemas Linux-based HPC e cloud","Utiliza flags de ambiente para garantir cobertura precisa","Identificação de lacunas de cobertura com arquivos .cov","Execução de testes com código não pré-compilado"],"ru":["Мультиомная аналитика и интеграция данных","Поддержка систем Linux-based HPC и cloud - ИИ Агенты","Использование флагов среды для обеспечения точного покрытия","Обнаружение пробелов в покрытии с помощью файлов .cov","Выполнение тестов с не pré-скомпилированным кодом"],"ar":["تحليل متعدد الأوجه وتكامل البيانات","دعم أنظمة Linux-based HPC و السحابية","استخدام أعلام البيئة لضمان تغطية دقيقة","تحديد فجوات التغطية باستخدام ملفات .cov","تشغيل الاختبارات مع код غير مجمع مسبقًا"]},"keywords":{"en":["how to use coverage-expansion","coverage-expansion alternative","coverage-expansion setup guide","what is coverage-expansion","coverage-expansion vs Mycelia","coverage-expansion install","systematic test coverage","Mycelia Julia package","linux-based HPC","cloud systems"],"zh":["coverage-expansion","生物特征分析","数据集成","多组学分析","预测","Linux","HPC","云系统","Mycelia Julia","测试覆盖扩展"],"ja":["coverage-expansion","生物学的特性分析","データ統合","多オミクス分析","予測","Linux","HPC","クラウドシステム","Mycelia Julia","テストカバー範囲の拡張","AIエージェント"],"ko":["coverage-expansion","생물학적 특성 분석","데이터 통합","다중 오믹스 분석","예측","리눅스","HPC","클라우드 시스템","Mycelia Julia","테스트 커버리지 확장","AI 에이전트"],"es":["análisis multiómico","caracterización biológica","predicción biológica","diseño biológico","herramientas de AI","agentes de AI","Julia","Mycelia","HPC","cloud","Linux"],"fr":["analyse multiomique","caractérisation biologique","prédiction biologique","conception biologique","outils d''IA","agents d''IA","Julia","Mycelia","HPC","cloud","Linux"],"de":["Multiomikanalyse","biologische Charakterisierung","biologische Vorhersage","biologisches Design","KI-Werkzeuge","KI-Agents","Julia","Mycelia","HPC","Cloud","Linux"],"pt":["expansão de cobertura","análise multiômica","integração de dados","sistemas Linux-based HPC","cloud computing","testes de software","cobertura de testes","Mycelia Julia"],"ru":["расширение покрытия","мультиомная аналитика","интеграция данных","системы Linux-based HPC","облачные вычисления - ИИ Агенты","тестирование программного обеспечения","покрытие тестов","Mycelia Julia"],"ar":["توسيع الغطاء","تحليل متعدد الأوجه","تكامل البيانات","أنظمة Linux-based HPC","حوسبة سحابية","اختبارات البرمجيات","تغطية الاختبارات","Mycelia Julia"]}},"owner":"cjprybol","repo":"Mycelia","repoPath":"cjprybol/Mycelia","stars":6,"forks":3,"updatedAt":"2026-02-27T13:43:34Z","topics":[],"category":"community","skillMd":{"name":"coverage-expansion","description":"Mycelia-specific test coverage expansion workflow","bodyPreview":"# Mycelia Test Coverage Expansion\n\nSystematically expand test coverage for the Mycelia Julia package.\n\n## Prerequisites\n\n1. Check for existing coverage files:\n   ```bash\n   find . -name \"*.cov\" -mtime -1 2>/dev/null\n   ```\n   If recent .cov files exist, use them to identify gaps without re-running.\n\n2. Environment flags - ALWAYS enable these for accurate coverage:\n   ```bash\n   export MYCELIA_RUN_ALL=true\n   export MYCELIA_RUN_EXTERNAL=true\n   ```\n   Coverage needs non-precompiled code for accur","body":"# Mycelia Test Coverage Expansion\n\nSystematically expand test coverage for the Mycelia Julia package.\n\n## Prerequisites\n\n1. Check for existing coverage files:\n   ```bash\n   find . -name \"*.cov\" -mtime -1 2>/dev/null\n   ```\n   If recent .cov files exist, use them to identify gaps without re-running.\n\n2. Environment flags - ALWAYS enable these for accurate coverage:\n   ```bash\n   export MYCELIA_RUN_ALL=true\n   export MYCELIA_RUN_EXTERNAL=true\n   ```\n   Coverage needs non-precompiled code for accurate line hits. Use `--compiled-modules=no`\n   (matches `ci/hpc/run_hpc_ci.sh`).\n\n## Running Coverage Analysis\n\n```bash\n# Full coverage with all tests enabled (matches HPC CI flags)\nMYCELIA_RUN_ALL=true MYCELIA_RUN_EXTERNAL=true \\\n  julia --project=. --compiled-modules=no \\\n  -e \"import Pkg; Pkg.test(coverage=true)\"\n\n# Coverage files will be generated as src/*.jl.cov\n```\n\nOptional parity with HPC CI (skips Codecov upload):\n```bash\nci/hpc/run_hpc_ci.sh --tests-only --no-codecov\n```\n\n## Analyzing Coverage\n\nCoverage files are generated alongside source files (e.g., `src/utility-functions.jl.cov`).\n\nFormat: Each line shows execution count, then source line:\n```\n    1  function foo(x)\n    0      if x < 0      # uncovered branch\n    -          return -x\n    1      end\n    1      return x\n    -  end\n```\n\n- Number = times executed\n- `0` = never executed (needs test)\n- `-` = non-executable line\n\n## Test Placement\n\nMatch source file to test stage:\n\n| Source File | Test Stage |\n|-------------|------------|\n| `reference-databases.jl` | `test/1_data_acquisition/` |\n| `fastx.jl`, `preprocessing.jl` | `test/2_preprocessing_qc/` |\n| `kmer-analysis.jl` | `test/3_feature_extraction_kmer/` |\n| `src/rhizomorph/` | `test/4_assembly/` |\n| `quality-control-and-benchmarking.jl` | `test/5_validation/` |\n| `annotation.jl`, `genome-features.jl` | `test/6_annotation/` |\n| `taxonomy-and-trees.jl`, `pangenome.jl` | `test/7_comparative_pangenomics/` |\n| `bioconda.jl`, `sentencepiece.jl` | `test/8_tool_integration/` |\n\n## Test Template\n\n```julia\nimport Test\nimport StableRNGs\nimport Mycelia\n\nTest.@testset \"FunctionName - description\" begin\n    rng = StableRNGs.StableRNG(42)\n\n    Test.@testset \"normal case\" begin\n        result = Mycelia.function_name(input)\n        Test.@test result == expected\n    end\n\n    Test.@testset \"edge case - empty input\" begin\n        result = Mycelia.function_name([])\n        Test.@test isempty(result)\n    end\n\n    Test.@testset \"error case\" begin\n        Test.@test_throws ArgumentError Mycelia.function_name(invalid)\n    end\nend\n```\n\n## Priority Order\n\n1. **Core utilities** - `utility-functions.jl` (used everywhere)\n2. **Data I/O** - `fastx.jl`, `reference-databases.jl`\n3. **Assembly core** - `src/rhizomorph/` modules\n4. **Analysis** - `kmer-analysis.jl`, `taxonomy-and-trees.jl`\n5. **External tools** - `bioconda.jl`, `sentencepiece.jl` (require MYCELIA_RUN_EXTERNAL)\n\n## Rules\n\n- **NEVER disable tests** because functionality is broken - fix the implementation\n- Use `Test.@test_skip` ONLY for explicitly planned but unimplemented features\n- Always use fully qualified names: `Mycelia.function_name()`, not imported functions\n- Use `StableRNGs.StableRNG(seed)` for any randomness\n- Use small synthetic data, not large external files\n- Commit after each file''s tests pass\n\n## Commit Format\n\n```\nadd: tests for utility-functions.jl coverage\n\n- Add tests for memory_estimate() normal and edge cases\n- Add tests for safe_mkdir() error handling\n- Coverage: 45% -> 72% for utility-functions.jl\n```\n\n## Verifying Progress\n\nAfter adding tests, re-run coverage and compare:\n\n```bash\n# Quick check of specific file coverage\nMYCELIA_RUN_ALL=true MYCELIA_RUN_EXTERNAL=true \\\n  julia --project=. --compiled-modules=no -e ''\n    import Pkg; Pkg.test()\n'' && grep -c \"^    0\" src/utility-functions.jl.cov\n```\n"},"lastSynced":"2026-03-06T06:53:25.769Z","agentAnalysis":{"suitability":{"en":"Perfect for Linux-based HPC and Cloud Agents needing advanced multiomic analysis and data integration for biological characterization.","zh":"非常适合需要高级多组学分析和数据集成的生物特性分析的基于Linux的HPC和云代理。","ja":"LinuxベースのHPCおよびクラウドエージェントが、生物学的特性分析のための高度なマルチオミクス分析およびデータ統合を必要とする場合に最適です。","ko":"생물학적 특성 분석을 위한 고급 멀티오믹스 분석 및 데이터 통합이 필요한 리눅스 기반 HPC 및 클라우드 에이전트에 적합합니다.","es":"Perfecto para agentes HPC y Cloud basados en Linux que necesitan análisis avanzado de multiómica y integración de datos para caracterización biológica.","fr":"Parfait pour les agents HPC et Cloud basés sur Linux nécessitant une analyse multiomique avancée et une intégration de données pour la caractérisation biologique.","de":"Perfekt für Linux-basierte HPC- und Cloud-Agents, die eine fortschrittliche Multiomikanalyse und Datenintegration für biologische Charakterisierung benötigen.","pt":"Perfeito para agentes HPC e Cloud baseados em Linux que necessitam de análise multiômica avançada e integração de dados para caracterização biológica.","ru":"Идеально подходит для агентов HPC и Cloud на основе Linux, которым требуется расширенный мультиомный анализ и интеграция данных для биологической характеристики.","ar":"مثالي لعميل الهيكل المفتوح وال سحابي المستند إلى لينكس الذي يحتاج إلى تحليل متقدم متعدد الأوجه وتكامل البيانات لتحديد الخصائص البيولوجية."},"recommendation":{"en":"Empowers agents to systematically expand test coverage for the Mycelia Julia package, utilizing environment flags like MYCELIA_RUN_ALL and MYCELIA_RUN_EXTERNAL for accurate coverage, and integrating with Linux-based systems and cloud environments for comprehensive data analysis and prediction.","zh":"赋予代理在Linux系统和云环境中扩展Mycelia Julia包的测试覆盖范围的能力，利用环境标志如MYCELIA_RUN_ALL和MYCELIA_RUN_EXTERNAL实现准确的覆盖率，并进行全面数据分析和预测。","ja":"エージェントに、Linuxシステムおよびクラウド環境におけるMycelia Juliaパッケージのテストカバレッジを方法的に拡張する能力を付与し、MYCELIA_RUN_ALLおよびMYCELIA_RUN_EXTERNALなどの環境フラグを使用して正確なカバレッジを実現し、包括的なデータ分析および予測を実行する。","ko":"에이전트가 Linux 시스템 및 클라우드 환경에서 Mycelia Julia 패키지의 테스트 범위를 체계적으로 확장할 수 있도록 하며, MYCELIA_RUN_ALL 및 MYCELIA_RUN_EXTERNAL와 같은 환경 플래그를 사용하여 정확한 범위를 달성하고, 포괄적인 데이터 분석 및 예측을 수행합니다.","es":"Habilita a los agentes a ampliar sistemáticamente la cobertura de pruebas para el paquete Mycelia Julia, utilizando indicadores de entorno como MYCELIA_RUN_ALL y MYCELIA_RUN_EXTERNAL para una cobertura precisa, e integrándose con sistemas y entornos de nube basados en Linux para un análisis y predicción de datos integrales.","fr":"Permet aux agents d''étendre systématiquement la couverture des tests pour le package Mycelia Julia, en utilisant des indicateurs d''environnement tels que MYCELIA_RUN_ALL et MYCELIA_RUN_EXTERNAL pour une couverture précise, et en s''intégrant avec des systèmes et des environnements de cloud basés sur Linux pour une analyse et une prédiction de données complètes.","de":"Ermöglicht es Agenten, die Testabdeckung für das Mycelia Julia-Paket systematisch zu erweitern, indem sie Umgebungsflags wie MYCELIA_RUN_ALL und MYCELIA_RUN_EXTERNAL für eine genaue Abdeckung verwenden und sich in Linux-basierte Systeme und Cloud-Umgebungen für eine umfassende Datenanalyse und -vorhersage integrieren.","pt":"Habilita os agentes a expandir sistematicamente a cobertura de testes para o pacote Mycelia Julia, utilizando flags de ambiente como MYCELIA_RUN_ALL e MYCELIA_RUN_EXTERNAL para cobertura precisa, e integrando com sistemas baseados em Linux e ambientes de nuvem para análise e previsão de dados abrangentes.","ru":"Наделяет агентов возможностью систематически расширять тестовое покрытие для пакета Mycelia Julia, используя флаги окружения, такие как MYCELIA_RUN_ALL и MYCELIA_RUN_EXTERNAL, для точного покрытия, и интегрируя с системами на основе Linux и облачными средами для всестороннего анализа и прогнозирования данных.","ar":"يُمنح الوكيل القدرة على توسيع نطاق تغطية الاختبار بشكل منهجي لصفقة Mycelia Julia، باستخدام علامات بيئة مثل MYCELIA_RUN_ALL و MYCELIA_RUN_EXTERNAL للحصول على تغطية دقيقة، وتكامل مع أنظمة لينكس وسحابة لتحليل بيانات شاملة وتوقعات."},"useCases":{"en":["Automating test coverage expansion for the Mycelia Julia package","Generating comprehensive coverage files for biological characterization and prediction","Debugging gaps in test coverage using recent .cov files and environment flags"],"zh":["自动扩展Mycelia Julia包的测试覆盖范围","生成用于生物特性分析和预测的全面覆盖率文件","使用最近的.cov文件和环境标志调试测试覆盖率中的间隙"],"ja":["Mycelia Juliaパッケージのテストカバレッジを自動的に拡張する","生物学的特性分析および予測のための包括的なカバレッジファイルを生成する","最近の.covファイルおよび環境フラグを使用してテストカバレッジのギャップをデバッグする"],"ko":["Mycelia Julia 패키지의 테스트 범위를 자동으로 확장하는 것","생물학적 특성 분석 및 예측을 위한 포괄적인 범위 파일을 생성하는 것","최근의 .cov 파일 및 환경 플래그를 사용하여 테스트 범위의 간격을 디버깅하는 것"],"es":["Automatizar la ampliación de la cobertura de pruebas para el paquete Mycelia Julia","Generar archivos de cobertura integrales para la caracterización y predicción biológicas","Depurar lagunas en la cobertura de pruebas utilizando archivos .cov recientes y indicadores de entorno"],"fr":["Automatiser l''extension de la couverture des tests pour le package Mycelia Julia","Générer des fichiers de couverture complets pour la caractérisation et la prédiction biologiques","Déboguer les lacunes dans la couverture des tests en utilisant des fichiers .cov récents et des indicateurs d''environnement"],"de":["Automatisieren der Erweiterung der Testabdeckung für das Mycelia Julia-Paket","Erstellen umfassender Abdeckungsdateien für biologische Charakterisierung und Vorhersage","Fehler in der Testabdeckung mithilfe aktueller .cov-Dateien und Umgebungsflags beheben"],"pt":["Automatizar a expansão da cobertura de testes para o pacote Mycelia Julia","Gerar arquivos de cobertura abrangentes para caracterização biológica e previsão","Depurar lacunas na cobertura de testes usando arquivos .cov recentes e flags de ambiente"],"ru":["Автоматизировать расширение тестового покрытия для п