INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cjprybol/Mycelia/coverage-expansion', 'coverage-expansion', 'cjprybol', 'Mycelia', 'community', 'coverage-expansion cjprybol Mycelia community coverage-expansion is a skill designed for linux-based HPC and cloud systems, enabling multiomic analysis and data integration for biological characterization, prediction, and design. It benefits developers working with the Mycelia Julia package. coverage-expansion 技术用于生物特征分析和数据集成，支持 Linux 基础的 HPC 和云系统，实现多组学分析和预测 coverage-expansion は、生物学的特性分析とデータ統合を実現するテクノロジーです。Linux ベースの HPC およびクラウドシステムで動作し、多オミクス分析と予測を可能にします coverage-expansion 기술은 생물학적 특성 분석 및 데이터 통합을 위한 솔루션으로, 리눅스 기반의 HPC 및 클라우드 시스템에서 동작하며 다중 오믹스 분석 및 예측을 가능하게 합니다 coverage-expansion es una herramienta para expandir la cobertura de pruebas del paquete Mycelia de Julia, diseñada para sistemas HPC y cloud basados en Linux coverage-expansion est un outil pour étendre la couverture de tests du package Mycelia de Julia, conçu pour les systèmes HPC et cloud basés sur Linux coverage-expansion ist ein Werkzeug zur Erweiterung der Testabdeckung des Mycelia-Pakets von Julia, entwickelt für Linux-basierte HPC- und Cloud-Systeme A expansão de cobertura é uma ferramenta para análise multiômica e integração de dados em sistemas Linux-based HPC e cloud. Расширение покрытия - это инструмент для мультиомной аналитики и интеграции данных в системах Linux-based HPC и cloud. توسيع الغطاء هو أداة لتحليل متعدد الأوجه وتكامل البيانات في أنظمة Linux-based HPC و السحابية how to use coverage-expansion coverage-expansion alternative coverage-expansion setup guide what is coverage-expansion coverage-expansion vs Mycelia coverage-expansion install systematic test coverage Mycelia Julia package linux-based HPC cloud systems coverage-expansion 生物特征分析 数据集成 多组学分析 预测 Linux HPC 云系统 Mycelia Julia 测试覆盖扩展 Utilizes bash commands to check for existing coverage files Employs environment flags such as MYCELIA_RUN_ALL and MYCELIA_RUN_EXTERNAL for accurate coverage Identifies gaps in coverage using recent .cov files Designed for linux-based HPC and cloud systems Integrates with the Mycelia Julia package for comprehensive test coverage Supports systematic expansion of test coverage for improved accuracy coverage-expansion is a systematic approach to expanding test coverage for the Mycelia Julia package, utilizing environment flags and coverage files to identify gaps and improve accuracy.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('robertguss/web-app-starter-kit/components-guide', 'community', 'robertguss', 'web-app-starter-kit', 'robertguss/web-app-starter-kit', 'components-guide', 5, 1, 39, '2026-03-01T20:49:59Z', '2026-03-06T06:55:26.977Z', '7721be98908a4d17c1455e90f01c357c018e1e1bbbde2bdeb0c6810a8de8971b', '{"id":"robertguss/web-app-starter-kit/components-guide","name":"components-guide","description":{"en":"The components-guide skill helps developers build maintainable, reusable backends by encapsulating features into self-contained mini-backends. It benefits developers who want to ship ideas quickly with AI.","zh":"Convex 组件指南提供了一个开箱即用的解决方案，用于快速构建可维护的后端。它允许您将功能封装在自包含的组件中","ja":"Convex コンポーネントガイドは、AI エージェントを使用して高速にアイデアを実現するためのオピニオンATED スターター キットです。コンポーネントを使用して機能をカプセル化し、維持可能なバックエンドを構築します","ko":"Convex 컴포넌트 가이드는 유지 보수 가능한 백엔드를 빠르게 구축하는 데 도움이 되는 오피니어티드 스타터 키트입니다. 컴포넌트를 사용하여 기능을 캡슐화하고 데이터베이스 스키마, 함수 및 데이터를 분리합니다","es":"Utilice componentes para encapsular características y construir backends mantenibles y reutilizables con nuestra guía de componentes","fr":"Utilisez des composants pour encapsuler des fonctionnalités et créer des backends maintenables et réutilisables avec notre guide des composants","de":"Verwenden Sie Komponenten, um Funktionen zu kapseln und wartbare, wiederverwendbare Backends mit unserem Komponenten-Leitfaden zu erstellen","pt":"O Convex Components Guide é um kit de início opinativo para enviar suas ideias rapidamente com AI, usando componentes para encapsular recursos e criar backends mantidos e reutilizáveis.","ru":"ИИ Агенты: Руководство по Компонентам - opinativo стартовый набор для быстрой отправки ваших идей с помощью ИИ, используя компоненты для инкапсуляции функций и создания поддерживаемых и многократно используемых бэкендов.","ar":"دليل المكونات Convex - هو مجموعة بدء تشغيل موضعية لطرح أفكارك بسرعة مع AI، باستخدام المكونات لتغليف الميزات وإنشاء خلفيات قابلة للصيانة وإعادة الاستخدام."},"seo":{"title":{"en":"components-guide: Setup Guide for AI Agents | AI Agent Skill","zh":"Convex 组件指南：快速构建可维护的后端","ja":"Convex コンポーネントガイド：AI エージェントを使用した高速開発","ko":"Convex 컴포넌트 가이드: 유지 보수 가능한 백엔드 구축","es":"Guía de Componentes para Agentes de IA: Implementación Rá...","fr":"Guide des Composants pour Outils d''IA: Mise en Place Rapide","de":"Komponenten-Leitfaden für KI-Agenten: Schnellstart","pt":"Guia de Configuração de Componentes para Desenvolvedores ...","ru":"ИИ Агенты: Руководство по Настройке Компонентов","ar":"دليل تركيب المكونات لل AI Agents"},"description":{"en":"Discover how to ship ideas fast with the components-guide skill. Learn to build maintainable backends with self-contained mini-backends and clear API boundar...","zh":"Convex 组件指南提供了一个开箱即用的解决方案，用于快速构建可维护的后端，具有自己的数据库模式、函数和数据","ja":"Convex コンポーネントガイドは、AI エージェントを使用して高速にアイデアを実現するためのオピニオンATED スターター キットです","ko":"Convex 컴포넌트 가이드는 유지 보수 가능한 백엔드를 빠르게 구축하는 데 도움이 되는 오피니어티드 스타터 키트입니다","es":"Aprende a utilizar componentes para desarrollar backends mantenibles y reutilizables con nuestra guía de componentes para agentes de IA","fr":"Découvrez comment utiliser des composants pour créer des backends maintenables et réutilisables avec notre guide des composants pour outils d''IA","de":"Erfahren Sie, wie Sie Komponenten verwenden können, um wartbare und wiederverwendbare Backends mit unserem Komponenten-Leitfaden für KI-Agenten zu erstellen","pt":"Aprenda a usar componentes para criar backends mantidos e reutilizáveis com o Convex Components Guide","ru":"Исользуйте компоненты для создания поддерживаемых и многократно используемых бэкендов с ИИ Агентами","ar":"استخدم المكونات لإنشاء خلفيات قابلة للصيانة وإعادة الاستخدام مع دليل المكونات Convex"},"definition":{"en":"components-guide is a starter kit for shipping ideas fast with AI, using self-contained mini-backends that bundle database schema, functions, and data.","zh":"Convex 组件是一种自包含的微型后端，具有自己的数据库模式、函数和数据","ja":"Convex コンポーネントは、自包含のミニバックエンドであり、独自のデータベース スキーマ、関数、およびデータを保持します","ko":"Convex 컴포넌트는 자체적으로 포함된 미니 백엔드로, 자신의 데이터베이스 스키마, 함수 및 데이터를 가집니다","es":"Un componente es un mini-backend autónomo que incluye su propia base de datos, funciones y datos aislados","fr":"Un composant est un mini-backend autonome qui inclut sa propre base de données, fonctions et données isolées","de":"Ein Komponente ist ein eigenständiges Mini-Backend, das über eigene Datenbank, Funktionen und isolierte Daten verfügt","pt":"Componentes são mini-backends autossuficientes que agrupam esquema de banco de dados, funções e dados isolados.","ru":"Компоненты - это самодостаточные мини-бэкенды, которые объединяют схему базы данных, функции и изолированные данные.","ar":"المكونات هي خلفيات صغيرة ذاتية الكفاية التي تجمع بين مخطط قاعدة البيانات والوظائف والبيانات المزيلة."},"features":{"en":["Bundles own database schema for isolated data management","Includes own functions for queries, mutations, and actions","Provides clear API boundaries for microservices-like architecture","Enables building maintainable, reusable backends with self-contained mini-backends","Supports isolated tables for data management","Acts like npm packages for backend development"],"zh":["自包含的微型后端","自己的数据库模式","自己的函数（查询、变异、操作）","自己的数据（隔离表）","清晰的 API 边界"],"ja":["自包含のミニバックエンド","独自のデータベース スキーマ","独自の関数（クエリ、ミューテーション、操作）","独自のデータ（隔離されたテーブル）","明確な API の境界"],"ko":["자체적으로 포함된 미니 백엔드","자신의 데이터베이스 스키마","자신의 함수（쿼리, 뮤테이션, 액션）","자신의 데이터（분리된 테이블）","명확한 API 경계"],"es":["Base de datos propia para cada componente","Funciones y consultas personalizadas","Datos aislados para cada componente","Límites de API claros","Desarrollo de backends mantenibles y reutilizables"],"fr":["Base de données propre pour chaque composant","Fonctions et requêtes personnalisées","Données isolées pour chaque composant","Limites d''API claires","Développement de backends maintenables et réutilisables"],"de":["Eigene Datenbank für jeden Komponenten","Benutzerdefinierte Funktionen und Abfragen","Isolierte Daten für jeden Komponenten","Klare API-Grenzen","Entwicklung von wartbaren und wiederverwendbaren Backends"],"pt":["Encapsula recursos em componentes autossuficientes","Cria backends mantidos e reutilizáveis","Fornece esquema de banco de dados isolado","Permite funções e ações personalizadas","Oferece API de fronteira clara"],"ru":["Инкапсулирует функции в самодостаточные компоненты","Создает поддерживаемые и многократно используемые бэкенды","Предоставляет изолированную схему базы данных","Позволяет использовать пользовательские функции и действия","Предлагает четкую границу API"],"ar":["يغلف الميزات في مكونات ذاتية الكفاية","ينشئ خلفيات قابلة للصيانة وإعادة الاستخدام","يوفر مخطط قاعدة بيانات معزول","يسمح بالوظائف والعمليات المخصصة","يقدم واجهة برمجة تطبيقات واضحة"]},"keywords":{"en":["how to use components-guide","components-guide setup guide","what is components-guide","components-guide alternative","components-guide vs microservices","components-guide install","building maintainable backends with components-guide","components-guide for AI agents","self-contained mini-backends with components-guide"],"zh":["Convex 组件","AI 工具","后端开发","微型后端","数据库模式","函数","数据","API 边界","Convex 组件指南"],"ja":["Convex コンポーネント","AI エージェント","バックエンド開発","ミニバックエンド","データベース スキーマ","関数","データ","API の境界","Convex コンポーネントガイド"],"ko":["Convex 컴포넌트","AI 툴","백엔드 개발","미니 백엔드","데이터베이스 스키마","함수","데이터","API 경계","Convex 컴포넌트 가이드"],"es":["agentes de ia","desarrollo de backends","componentes para ia","guias de componentes","implementación rápida de ia","desarrollo de aplicaciones con ia"],"fr":["outils d''ia","développement de backends","composants pour ia","guides de composants","mise en place rapide d''ia","développement d''applications avec ia"],"de":["ki-agenten","entwicklung von backends","komponenten für ki","komponenten-leitfäden","schnellstart für ki","entwicklung von anwendungen mit ki"],"pt":["componentes AI","desenvolvimento de backend","Convex Components Guide","guias de configuração de componentes","ferramentas de AI para desenvolvedores","componentes reutilizáveis"],"ru":["ИИ Агенты","разработка бэкенда","Руководство по Компонентам","настройка компонентов","инструменты ИИ для разработчиков","повторно используемые компоненты"],"ar":["مكونات AI","تطوير الخلفية","دليل المكونات Convex","إعدادات المكونات","أدوات AI لل مطورين","مكونات قابلة لإعادة الاستخدام"]}},"owner":"robertguss","repo":"web-app-starter-kit","repoPath":"robertguss/web-app-starter-kit","stars":5,"forks":1,"updatedAt":"2026-03-01T20:49:59Z","topics":[],"category":"community","skillMd":{"name":"components-guide","description":"Guide to using Convex components for feature encapsulation. Learn about sibling components, creating your own, and when to use components vs monolithic code.","bodyPreview":"# Convex Components Guide\n\nUse components to encapsulate features and build maintainable, reusable backends.\n\n## What Are Convex Components?\n\n**Components are self-contained mini-backends** that bundle:\n- Their own database schema\n- Their own functions (queries, mutations, actions)\n- Their own data (isolated tables)\n- Clear API boundaries\n\n**Think of them as:** npm packages for your backend, or microservices without the deployment complexity.\n\n## Why Use Components?\n\n### Traditional Approach (Mo","body":"# Convex Components Guide\n\nUse components to encapsulate features and build maintainable, reusable backends.\n\n## What Are Convex Components?\n\n**Components are self-contained mini-backends** that bundle:\n- Their own database schema\n- Their own functions (queries, mutations, actions)\n- Their own data (isolated tables)\n- Clear API boundaries\n\n**Think of them as:** npm packages for your backend, or microservices without the deployment complexity.\n\n## Why Use Components?\n\n### Traditional Approach (Monolithic)\n```\nconvex/\n├── users.ts           (500 lines)\n├── files.ts           (600 lines - upload, storage, permissions, rate limiting)\n├── payments.ts        (400 lines - Stripe, webhooks, billing)\n├── notifications.ts   (300 lines)\n└── analytics.ts       (200 lines)\n\nTotal: One big codebase, everything mixed together\n```\n\n### Component Approach (Encapsulated)\n```\nconvex/\n├── components/\n│   ├── storage/      (File uploads - reusable)\n│   ├── billing/      (Payments - reusable)\n│   ├── notifications/ (Alerts - reusable)\n│   └── analytics/    (Tracking - reusable)\n├── convex.config.ts  (Wire components together)\n└── domain/           (Your actual business logic)\n    ├── users.ts      (50 lines - uses components)\n    └── projects.ts   (75 lines - uses components)\n\nTotal: Clean, focused, reusable\n```\n\n## Quick Start\n\n### 1. Install a Component\n\n```bash\n# Official components from npm\nnpm install @convex-dev/ratelimiter\n```\n\n### 2. Configure in convex.config.ts\n\n```typescript\nimport { defineApp } from \"convex/server\";\nimport ratelimiter from \"@convex-dev/ratelimiter/convex.config\";\n\nexport default defineApp({\n  components: {\n    ratelimiter,\n  },\n});\n```\n\n### 3. Use in Your Code\n\n```typescript\nimport { components } from \"./_generated/api\";\n\nexport const createPost = mutation({\n  handler: async (ctx, args) => {\n    // Use the component\n    await components.ratelimiter.check(ctx, {\n      key: `user:${ctx.user._id}`,\n      limit: 10,\n      period: 60000, // 10 requests per minute\n    });\n\n    return await ctx.db.insert(\"posts\", args);\n  },\n});\n```\n\n## Sibling Components Pattern\n\nMultiple components working together at the same level:\n\n```typescript\n// convex.config.ts\nexport default defineApp({\n  components: {\n    // Sibling components - each handles one concern\n    auth: authComponent,\n    storage: storageComponent,\n    payments: paymentsComponent,\n    emails: emailComponent,\n    analytics: analyticsComponent,\n  },\n});\n```\n\n### Example: Complete Feature Using Siblings\n\n```typescript\n// convex/subscriptions.ts\nimport { components } from \"./_generated/api\";\n\nexport const subscribe = mutation({\n  args: { plan: v.string() },\n  handler: async (ctx, args) => {\n    // 1. Verify authentication (auth component)\n    const user = await components.auth.getCurrentUser(ctx);\n\n    // 2. Create payment (payments component)\n    const subscription = await components.payments.createSubscription(ctx, {\n      userId: user._id,\n      plan: args.plan,\n      amount: getPlanAmount(args.plan),\n    });\n\n    // 3. Track conversion (analytics component)\n    await components.analytics.track(ctx, {\n      event: \"subscription_created\",\n      userId: user._id,\n      plan: args.plan,\n    });\n\n    // 4. Send confirmation (emails component)\n    await components.emails.send(ctx, {\n      to: user.email,\n      template: \"subscription_welcome\",\n      data: { plan: args.plan },\n    });\n\n    // 5. Store subscription in main app\n    await ctx.db.insert(\"subscriptions\", {\n      userId: user._id,\n      paymentId: subscription.id,\n      plan: args.plan,\n      status: \"active\",\n    });\n\n    return subscription;\n  },\n});\n```\n\n**What this achieves:**\n- ✅ Each component is single-purpose\n- ✅ Components are reusable across features\n- ✅ Easy to swap implementations (change email provider)\n- ✅ Can update components independently\n- ✅ Clear separation of concerns\n\n## Official Components\n\nBrowse [Component Directory](https://www.convex.dev/components):\n\n### Authentication\n- **@convex-dev/better-auth** - Better Auth integration\n\n### Storage\n- **@convex-dev/r2** - Cloudflare R2 file storage\n- **@convex-dev/storage** - File upload/download\n\n### Payments\n- **@convex-dev/polar** - Polar billing & subscriptions\n\n### AI\n- **@convex-dev/agent** - AI agent workflows\n- **@convex-dev/embeddings** - Vector storage & search\n\n### Backend Utilities\n- **@convex-dev/ratelimiter** - Rate limiting\n- **@convex-dev/aggregate** - Data aggregations\n- **@convex-dev/action-cache** - Cache action results\n- **@convex-dev/sharded-counter** - Distributed counters\n- **@convex-dev/migrations** - Schema migrations\n- **@convex-dev/workflow** - Workflow orchestration\n\n## Creating Your Own Component\n\n### When to Create a Component\n\n**Good reasons:**\n- Feature is self-contained\n- You''ll reuse it across projects\n- Want to share with team/community\n- Complex feature with its own data model\n- Third-party integration wrapper\n\n**Not good reasons:**\n- One-off business logic\n- Tightly coupled to main app\n- Simple utility functions\n\n### Structure\n\n```bash\nmkdir -p convex/components/notifications\n```\n\n```typescript\n// convex/components/notifications/convex.config.ts\nimport { defineComponent } from \"convex/server\";\n\nexport default defineComponent(\"notifications\");\n```\n\n```typescript\n// convex/components/notifications/schema.ts\nimport { defineSchema, defineTable } from \"convex/server\";\nimport { v } from \"convex/values\";\n\nexport default defineSchema({\n  notifications: defineTable({\n    userId: v.id(\"users\"),\n    message: v.string(),\n    read: v.boolean(),\n    createdAt: v.number(),\n  })\n    .index(\"by_user\", [\"userId\"])\n    .index(\"by_user_and_read\", [\"userId\", \"read\"]),\n});\n```\n\n```typescript\n// convex/components/notifications/send.ts\nimport { mutation } from \"./_generated/server\";\nimport { v } from \"convex/values\";\n\nexport const send = mutation({\n  args: {\n    userId: v.id(\"users\"),\n    message: v.string(),\n  },\n  handler: async (ctx, args) => {\n    await ctx.db.insert(\"notifications\", {\n      userId: args.userId,\n      message: args.message,\n      read: false,\n      createdAt: Date.now(),\n    });\n  },\n});\n\nexport const markRead = mutation({\n  args: { notificationId: v.id(\"notifications\") },\n  handler: async (ctx, args) => {\n    await ctx.db.patch(args.notificationId, { read: true });\n  },\n});\n```\n\n```typescript\n// convex/components/notifications/read.ts\nimport { query } from \"./_generated/server\";\nimport { v } from \"convex/values\";\n\nexport const list = query({\n  args: { userId: v.id(\"users\") },\n  handler: async (ctx, args) => {\n    return await ctx.db\n      .query(\"notifications\")\n      .withIndex(\"by_user\", q => q.eq(\"userId\", args.userId))\n      .order(\"desc\")\n      .collect();\n  },\n});\n\nexport const unreadCount = query({\n  args: { userId: v.id(\"users\") },\n  handler: async (ctx, args) => {\n    const unread = await ctx.db\n      .query(\"notifications\")\n      .withIndex(\"by_user_and_read\", q =>\n        q.eq(\"userId\", args.userId).eq(\"read\", false)\n      )\n      .collect();\n\n    return unread.length;\n  },\n});\n```\n\n### Use Your Component\n\n```typescript\n// convex.config.ts\nimport { defineApp } from \"convex/server\";\nimport notifications from \"./components/notifications/convex.config\";\n\nexport default defineApp({\n  components: {\n    notifications, // Your local component\n  },\n});\n```\n\n```typescript\n// convex/tasks.ts - main app code\nimport { components } from \"./_generated/api\";\n\nexport const completeTask = mutation({\n  args: { taskId: v.id(\"tasks\") },\n  handler: async (ctx, args) => {\n    const task = await ctx.db.get(args.taskId);\n\n    await ctx.db.patch(args.taskId, { completed: true });\n\n    // Use your component\n    await components.notifications.send(ctx, {\n      userId: task.userId,\n      message: `Task \"${task.title}\" completed!`,\n    });\n  },\n});\n```\n\n## Component Communication Patterns\n\n### ✅ Parent → Component (Good)\n\n```typescript\n// Main app calls component\nawait components.storage.upload(ctx, file);\nawait components.analytics.track(ctx, event);\n```\n\n### ✅ Parent → Multiple Siblings (Good)\n\n```typescript\n// Main app orchestrates multiple components\nawait components.auth.verify(ctx);\nconst file = await components.storage.upload(ctx, data);\nawait components.notifications.send(ctx, message);\n```\n\n### ✅ Component Receives Parent Data (Good)\n\n```typescript\n// Pass IDs from parent''s tables to component\nawait components.audit.log(ctx, {\n  userId: user._id,        // From parent''s users table\n  action: \"delete\",\n  resourceId: task._id,    // From parent''s tasks table\n});\n\n// Component stores these as strings/IDs\n// but doesn''t access parent tables directly\n```\n\n### ❌ Component → Parent Tables (Bad)\n\n```typescript\n// Inside component code - DON''T DO THIS\nconst user = await ctx.db.get(userId); // Error! Can''t access parent tables\n```\n\n### ❌ Sibling → Sibling (Bad)\n\nComponents can''t call each other directly. If you need this, they should be in the main app or refactor the design.\n\n## Real-World Examples\n\n### Multi-Tenant SaaS\n\n```typescript\n// convex.config.ts\nexport default defineApp({\n  components: {\n    auth: \"@convex-dev/better-auth\",\n    organizations: \"./components/organizations\",\n    billing: \"./components/billing\",\n    storage: \"@convex-dev/r2\",\n    analytics: \"./components/analytics\",\n    emails: \"./components/emails\",\n  },\n});\n```\n\nEach component:\n- `auth` - User authentication & sessions\n- `organizations` - Tenant isolation & permissions\n- `billing` - Stripe integration & subscriptions\n- `storage` - File uploads to R2\n- `analytics` - Event tracking & metrics\n- `emails` - Email sending via SendGrid\n\n### E-Commerce Platform\n\n```typescript\nexport default defineApp({\n  components: {\n    cart: \"./components/cart\",\n    inventory: \"./components/inventory\",\n    orders: \"./components/orders\",\n    payments: \"@convex-dev/polar\",\n    shipping: \"./components/shipping\",\n    recommendations: \"./components/recommendations\",\n  },\n});\n```\n\n### AI Application\n\n```typescript\nexport default defineApp({\n  components: {\n    agent: \"@convex-dev/agent\",\n    embeddings: \"./components/embeddings\",\n    documents: \"./components/documents\",\n    chat: \"./components/chat\",\n    workflow: \"@convex-dev/workflow\",\n  },\n});\n```\n\n## Migration from Monolithic\n\n**Step 1: Identify Features**\n```\nCurrent monolith:\n- File uploads (mixed with main app)\n- Rate limiting (scattered everywhere)\n- Analytics (embedded in functions)\n```\n\n**Step 2: Extract One Feature**\n```bash\n# Create component\nmkdir -p convex/components/storage\n\n# Move storage code to component\n# Update imports in main app\n```\n\n**Step 3: Test Independently**\n```bash\n# Component has its own tests\n# No coupling to main app\n```\n\n**Step 4: Repeat**\nExtract other features incrementally.\n\n## Best Practices\n\n### 1. Single Responsibility\nEach component does ONE thing well:\n- ✅ storage component handles files\n- ✅ auth component handles authentication\n- ❌ Don''t create \"utils\" component with everything\n\n### 2. Clear API Surface\n```typescript\n// Export only what''s needed\nexport { upload, download, delete } from \"./storage\";\n\n// Keep internals private\n// (Don''t export helper functions)\n```\n\n### 3. Minimal Coupling\n```typescript\n// ✅ Good: Pass data as arguments\nawait components.audit.log(ctx, {\n  userId: user._id,\n  action: \"delete\"\n});\n\n// ❌ Bad: Component accesses parent tables\n// (Not even possible, but shows the principle)\n```\n\n### 4. Version Your Components\n```json\n{\n  \"name\": \"@yourteam/notifications-component\",\n  \"version\": \"1.0.0\"\n}\n```\n\n### 5. Document Your Components\nInclude README with:\n- What the component does\n- How to install\n- How to use\n- API reference\n- Examples\n\n## Troubleshooting\n\n### Component not found\n```bash\n# Make sure component is in convex.config.ts\n# Run: npx convex dev\n```\n\n### Can''t access parent tables\n```\nThis is by design! Components are sandboxed.\nPass data as arguments instead.\n```\n\n### Component conflicts\n```\nEach component has isolated tables.\nComponents can''t see each other''s data.\n```\n\n## Learn More\n\n- [Components Documentation](https://docs.convex.dev/components)\n- [Component Directory](https://www.convex.dev/components)\n- [Using Components](https://docs.convex.dev/components/using)\n- [Authoring Components](https://docs.convex.dev/components/authoring)\n- [Stack: Backend Components](https://stack.convex.dev/backend-components)\n\n## Checklist\n\n- [ ] Browse [Component Directory](https://www.convex.dev/components) for existing solutions\n- [ ] Install components via npm: `npm install @convex-dev/component-name`\n- [ ] Configure in `convex.config.ts`\n- [ ] Use sibling components for feature encapsulation\n- [ ] Create your own components for reusable features\n- [ ] Keep components focused (single responsibility)\n- [ ] Test components in isolation\n- [ ] Document component APIs\n- [ ] Version your components properly\n\n**Remember:** Components are about encapsulation and reusability. When in doubt, prefer components over monolithic code!\n"},"lastSynced":"2026-03-06T06:55:26.977Z","agentAnalysis":{"suitability":{"en":"Perfect for Backend Agents needing to build maintainable, reusable backends with self-contained mini-backends","zh":"适用于后端代理，需要构建可维护、可重用的后端，并具有自包含的迷你后端","ja":"バックエンドエージェントがメンテナンス可能で再利用可能なバックエンドを構築する必要がある場合に最適です。セルフコンテナされたミニバックエンドを備えたバックエンド","ko":"백엔드 에이전트가 유지 보수 및 재사용이 가능한 백엔드를 구축해야 하는 경우에 적합합니다. 자체 포함된 미니 백엔드와 함께","es":"Perfecto para agentes de Backend que necesitan crear backends mantenibles y reutilizables con mini-backends autocontenidos","fr":"Parfait pour les agents Backend ayant besoin de créer des backends maintenables et réutilisables avec des mini-backends autocontenus","de":"Perfekt für Backend-Agents, die wartbare und wiederverwendbare Backends mit selbstenthaltenen Mini-Backends erstellen müssen","pt":"Perfeito para Agentes de Backend que precisam criar backends mantenedores e reutilizáveis com mini-backends autocontidos","ru":"Идеально для агентов бэкенда, которым необходимо создавать поддерживаемые и повторно используемые бэкенды с самодостаточными мини-бэкендами","ar":"مثالي للوكلاء الخلفية الذين يحتاجون إلى بناء خلفيات متوافقة وقابلة لإعادة الاستخدام مع خلفيات صغيرة مدمجة"},"recommendation":{"en":"Empowers agents to encapsulate features into components with their own database schema, functions, and data, using clear API boundaries and microservices-like architecture without deployment complexity","zh":"赋予代理将功能封装到具有自己的数据库模式、函数和数据的组件中，使用清晰的API边界和微服务样架构，而无需部署复杂性","ja":"エージェントに機能を明確なAPIの境界とマイクロサービスのようなアーキテクチャを使用して、独自のデータベーススキーマ、関数、データを備えたコンポーネントにカプセル化する能力を付与します。デプロイの複雑さなし","ko":"에이전트에게 기능을 明確한 API 경계 및 마이크로서비스와 같은 아키텍처를 사용하여 자체 데이터베이스 스키마, 함수 및 데이터를 갖춘 구성 요소에 캡슐화하는 능력을 부여합니다. 배포의 복잡성なし","es":"Habilita a los agentes a encapsular características en componentes con su propia base de datos, funciones y datos, utilizando límites de API claros y arquitectura similar a microservicios sin complejidad de implementación","fr":"Permet aux agents d''encapsuler des fonctionnalités dans des composants avec leur propre schéma de base de données, fonctions et données, en utilisant des limites d''API claires et une architecture similaire à des microservices sans complexité de déploiement","de":"Ermächtigt Agenten, Funktionen in Komponenten mit eigener Datenbank, Funktionen und Daten zu kapseln, indem sie klare API-Grenzen und eine microservices-ähnliche Architektur ohne Deploy-Komplexität verwenden","pt":"Habilita os agentes a encapsular recursos em componentes com seu próprio esquema de banco de dados, funções e dados, usando limites de API claros e arquitetura semelhante a microsserviços sem complexidade de implantação","ru":"Предоставляет агентам возможность инкапсулировать функции в компоненты со своей собственной схемой базы данных, функциями и данными, используя четкие границы API и архитектуру, подобную микросервисам, без сложности развертывания","ar":"تمكين الوكلاء من تجزئة الميزات في المكونات مع مخطط قاعدة بياناتها الخاص ووظائفها وبياناتها، باستخدام حدود واجهة برمجة التطبيقات الواضحة وهندسة تشبه هندسة الخدمات الصغيرة دون تعقيد النشر"},"useCases":{"en":["Building modular backends with isolated tables","Creating reusable components for rapid idea shipping","Encapsulating features into self-contained mini-backends"],"zh":["构建具有隔离表的模块化后端","创建可重用的组件以实现快速想法交付","将功能封装到自包含的迷你后端"],"ja":["分離されたテーブルを持つモジュラーバックエンドの構築","迅速なアイデアの出荷のための再利用可能なコンポーネントの作成","機能をセルフコンテナされたミニバックエンドにカプセル化"],"ko":["분리된 표를 갖춘 모듈화 된 백엔드를 구축하는 것","신속한 아이디어 출하를 위한 재사용 가능한 구성 요소 만들기","기능을 자체 포함된 미니 백엔드에 캡슐화"],"es":["Creación de backends modulares con tablas aisladas","Creación de componentes reutilizables para un envío rápido de ideas","Encapsulación de características en mini-backends autocontenidos"],"fr":["Création de backends modulaires avec des tables isolées","Création de composants réutilisables pour un envoi rapide d''idées","Encapsulation de fonctionnalités dans des mini-backends autocontenus"],"de":["Erstellung von modularen Backends mit isolierten Tabellen","Erstellung von wiederverwendbaren Komponenten für einen schnellen Ideenversand","Kapselung von Funktionen in selbstenthaltenen Mini-Backends"],"pt":["Construir backends modulares com tabelas isoladas","Criar componentes reutilizáveis para envio rápido de ideias","Encapsular recursos em mini-backends autocontidos"],"ru":["Создание модульных бэкендов с изолированными таблицами","Создание повторно используемых компонентов для быстрой доставки идей","Инкапсуляция функций в самодостаточные мини-бэкенды"],"ar":["بناء خلفيات موديلر مع جداول معزولة","إنشاء مكونات قابلة لإعادة الاستخدام لنقل الأفكار السريع","تجزئة الميزات في خلفيات صغيرة مدمجة"]},"limitations":{"en":["Requires understanding of database schema and API design","Components must be designed with clear boundaries and interfaces"],"zh":["需要了解数据库模式和API设计","组件必须设计为具有明确的边界和接口"],"ja":["データベーススキーマとAPIデザインの理解が必要","コンポーネントは明確な境界とインターフェイスで設計する必要がある"],"ko":["데이터베이스 스키마 및 API 설계에 대한 이해가 필요","구성 요소는 명확한 경계 및 인터페이스로 설계되어야 함"],"es":["Requiere comprensión del esquema de base de datos y diseño de API","Los componentes deben diseñarse con límites y interfaces claros"],"fr":["Nécessite une compréhension du schéma de base de données et de la conception d''API","Les composants doivent être conçus avec des limites et des interfaces claires"],"de":["Benötigt Verständnis des Datenbankschemas und API-Designs","Komponenten müssen mit klaren Grenzen und Schnittstellen entworfen werden"],"pt":["Exige compreensão do esquema de banco de dados e design de API","Os componentes devem ser projetados com limites e interfaces claros"],"ru":["Требует понимания схемы базы данных и дизайна API","Компоненты должны быть спроектированы с четкими границами и интерфейсами"],"ar":["يتطلب فهم مخطط قاعدة البيانات وتصميم واجهة برمجة التطبيقات","يجب تصميم المكونات مع حدود وواجهات واضحة"]},"version":4},"contentHash":"7721be98908a4d17c1455e90f01c357c018e1e1bbbde2bdeb0c6810a8de8971b","qualityScore":39}');
