INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('robertguss/web-app-starter-kit/components-guide', 'components-guide', 'robertguss', 'web-app-starter-kit', 'community', 'components-guide robertguss web-app-starter-kit community The components-guide skill helps developers build maintainable, reusable backends by encapsulating features into self-contained mini-backends. It benefits developers who want to ship ideas quickly with AI. Convex 组件指南提供了一个开箱即用的解决方案，用于快速构建可维护的后端。它允许您将功能封装在自包含的组件中 Convex コンポーネントガイドは、AI エージェントを使用して高速にアイデアを実現するためのオピニオンATED スターター キットです。コンポーネントを使用して機能をカプセル化し、維持可能なバックエンドを構築します Convex 컴포넌트 가이드는 유지 보수 가능한 백엔드를 빠르게 구축하는 데 도움이 되는 오피니어티드 스타터 키트입니다. 컴포넌트를 사용하여 기능을 캡슐화하고 데이터베이스 스키마, 함수 및 데이터를 분리합니다 Utilice componentes para encapsular características y construir backends mantenibles y reutilizables con nuestra guía de componentes Utilisez des composants pour encapsuler des fonctionnalités et créer des backends maintenables et réutilisables avec notre guide des composants Verwenden Sie Komponenten, um Funktionen zu kapseln und wartbare, wiederverwendbare Backends mit unserem Komponenten-Leitfaden zu erstellen O Convex Components Guide é um kit de início opinativo para enviar suas ideias rapidamente com AI, usando componentes para encapsular recursos e criar backends mantidos e reutilizáveis. ИИ Агенты: Руководство по Компонентам - opinativo стартовый набор для быстрой отправки ваших идей с помощью ИИ, используя компоненты для инкапсуляции функций и создания поддерживаемых и многократно используемых бэкендов. دليل المكونات Convex - هو مجموعة بدء تشغيل موضعية لطرح أفكارك بسرعة مع AI، باستخدام المكونات لتغليف الميزات وإنشاء خلفيات قابلة للصيانة وإعادة الاستخدام. how to use components-guide components-guide setup guide what is components-guide components-guide alternative components-guide vs microservices components-guide install building maintainable backends with components-guide components-guide for AI agents self-contained mini-backends with components-guide Convex 组件 AI 工具 后端开发 微型后端 数据库模式 函数 数据 API 边界 Convex 组件指南 Bundles own database schema for isolated data management Includes own functions for queries, mutations, and actions Provides clear API boundaries for microservices-like architecture Enables building maintainable, reusable backends with self-contained mini-backends Supports isolated tables for data management Acts like npm packages for backend development components-guide is a starter kit for shipping ideas fast with AI, using self-contained mini-backends that bundle database schema, functions, and data.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('chronista-club/unison/zed-editor', 'community', 'chronista-club', 'unison', 'chronista-club/unison', 'zed-editor', 4, 1, 39, '2026-02-23T08:15:53Z', '2026-03-06T06:57:00.735Z', '6d7205571fccca8505724728995233a0a4f99eb1904f98345d90339f3de5f639', '{"id":"chronista-club/unison/zed-editor","name":"zed-editor","description":{"en":"The zed-editor skill provides comprehensive knowledge on the Zed Editor and its innovative Agent Client Protocol (ACP), benefiting developers with advanced code editing capabilities.","zh":"Zed Editor 是一个基于 Rust 的下一代代码编辑器，具有高速性能、内存安全性和开源特性","ja":"Zed Editor は、Rust で書かれた次世代のコードエディタです。高速パフォーマンス、メモリ安全性、オープンソースを特徴とします","ko":"Zed Editor는 러스트 기반의 차세대 코드 편집기로서高速 성능, 메모리 안전성, 오픈소스를 특징으로 합니다","es":"Zed Editor es un editor de código de próxima generación escrito en Rust, con capacidades de inteligencia artificial y un rendimiento rápido","fr":"Zed Editor est un éditeur de code de nouvelle génération écrit en Rust, avec des capacités d''intelligence artificielle et des performances rapides","de":"Zed Editor ist ein Code-Editor der nächsten Generation, geschrieben in Rust, mit künstlicher Intelligenz und schneller Leistung","pt":"O Zed Editor é uma ferramenta de edição de código de próxima geração, construída em Rust, com recursos como desempenho rápido e integração de IA","ru":"Zed Editor - это инструмент для редактирования кода нового поколения, построенный на Rust, с функциями, такими как быстрое выполнение и интеграция ИИ","ar":"محرر Zed هو أداة تحرير كود من الجيل التالي، مبني على Rust، مع ميزات مثل الأداء السريع وتكامل الذكاء الاصطناعي"},"seo":{"title":{"en":"zed-editor: AI-Powered Code Editing Setup Guide | AI Agen...","zh":"Zed Editor.setup 指南：基于 Rust 的下一代代码编辑器","ja":"Zed Editor セットアップガイド：次世代のコードエディタ","ko":"Zed Editor 설정 가이드: 러스트 기반의 차세대 코드 편집기","es":"Guía de configuración de Zed Editor para Agentes de Intel...","fr":"Guide de mise en place de Zed Editor pour les Agents d''In...","de":"Einrichtungsleitfaden für Zed Editor mit künstlicher Inte...","pt":"Guia de Configuração do Zed Editor: Ferramenta de Edição ...","ru":"Настройка Zed Editor: Инструмент для Продвинутого Редакти...","ar":"دليل إعداد محرر Zed: أداة تحرير كود متقدمة"},"description":{"en":"Unlock efficient coding with zed-editor''s Agentic Editing and Edit Prediction. Learn how to integrate AI into your workflow and revolutionize your developmen...","zh":"了解 Zed Editor 的功能和特点，包括 Agentic Editing、Edit Prediction 和 Inline Assistant 等","ja":"Zed Editor の機能と特徴について学びます。Agentic Editing、Edit Prediction、Inline Assistant など","ko":"Zed Editor의 기능과 특징에 대해 알아보세요. Agentic Editing, Edit Prediction, Inline Assistant 등","es":"Aprende a configurar Zed Editor con capacidades de inteligencia artificial para mejorar tu productividad como desarrollador","fr":"Découvrez comment configurer Zed Editor avec des capacités d''intelligence artificielle pour améliorer votre productivité en tant que développeur","de":"Erfahren Sie, wie Sie Zed Editor mit künstlicher Intelligenz konfigurieren, um Ihre Produktivität als Entwickler zu steigern","pt":"Aprenda a configurar o Zed Editor, uma ferramenta de edição de código de próxima geração, com recursos como desempenho rápido e integração de IA","ru":"Узнайте, как настроить Zed Editor, инструмент для редактирования кода нового поколения, с функциями, такими как быстрое выполнение и интеграция ИИ","ar":"تعرف على كيفية 설정 محرر Zed، أداة تحرير كود من الجيل التالي، مع ميزات مثل الأداء السريع وتكامل الذكاء الاصطناعي"},"definition":{"en":"zed-editor is a next-generation code editor written entirely in Rust, offering high-performance, memory safety, and open-source flexibility.","zh":"Zed Editor 是一个基于 Rust 的代码编辑器，具有 AI 统合、高速性能和内存安全性等特点","ja":"Zed Editor は、Rust で書かれたコードエディタです。AI 統合、高速パフォーマンス、メモリ安全性を特徴とします","ko":"Zed Editor는 러스트 기반의 코드 편집기로서 AI 통합,高速 성능, 메모리 안전성을 특징으로 합니다","es":"Zed Editor es un editor de código que utiliza inteligencia artificial para mejorar la productividad del desarrollador","fr":"Zed Editor est un éditeur de code qui utilise l''intelligence artificielle pour améliorer la productivité du développeur","de":"Zed Editor ist ein Code-Editor, der künstliche Intelligenz nutzt, um die Produktivität des Entwicklers zu steigern","pt":"O Zed Editor é uma ferramenta de edição de código de código aberto, construída em Rust, que oferece desempenho rápido e integração de IA","ru":"Zed Editor - это открытый инструмент для редактирования кода, построенный на Rust, который предлагает быстрое выполнение и интеграцию ИИ","ar":"محرر Zed هو أداة تحرير كود مفتوحة المصدر، مبني على Rust، يقدم أداء سريع وتكامل الذكاء الاصطناعي"},"features":{"en":["Utilizes Rust for memory safety and performance","Employs Agentic Editing for real-time progress tracking","Features Edit Prediction with open-source language models","Supports Inline Assistant for code transformation with LLMs","Leverages multiple CPU cores and GPU for efficient performance"],"zh":["基于 Rust 的下一代代码编辑器","Agentic Editing：委托工作给代理并实时跟踪进度","Edit Prediction：使用开源语言模型预测下一次输入","Inline Assistant：将选中的代码发送给 LLM 进行转换","高速性能：利用多个 CPU 核和 GPU"],"ja":["Rust で書かれた次世代のコードエディタ","Agentic Editing：エージェントに作業を委託し、進捗をリアルタイムで追跡","Edit Prediction：オープンソース言語モデルを使用して次の入力を予測","Inline Assistant：選択したコードを LLM に送信して変換","高速パフォーマンス：複数の CPU コアと GPU を効率的に活用"],"ko":["러스트 기반의 차세대 코드 편집기","Agentic Editing：에이전트에 작업을 위임하고 진행 상황을 실시간으로 추적","Edit Prediction：오픈소스 언어 모델을 사용하여 다음 입력을 예측","Inline Assistant：선택한 코드를 LLM에 전송하여 변환","高速 성능：複数의 CPU 코어와 GPU를 효율적으로 활용"],"es":["Edición asistida por agente con seguimiento en tiempo real","Predicción de edición con modelos de lenguaje abiertos","Asistente en línea para convertir código con LLM","Rendimiento rápido con utilización eficiente de CPU y GPU","Seguridad de memoria y rendimiento con Rust","Código abierto bajo licencia Apache 2.0"],"fr":["Édition assistée par agent avec suivi en temps réel","Prédiction d''édition avec des modèles de langage ouverts","Assistant en ligne pour convertir du code avec LLM","Performances rapides avec utilisation efficace de CPU et GPU","Sécurité de la mémoire et performances avec Rust","Code ouvert sous licence Apache 2.0"],"de":["Agentenunterstützte Bearbeitung mit Echtzeit-Verfolgung","Bearbeitungsvorhersage mit offenen Sprachmodellen","Online-Assistent für Code-Konvertierung mit LLM","Schnelle Leistung mit effizienter Nutzung von CPU und GPU","Sicherheit und Leistung mit Rust","Open-Source-Code unter Apache-2.0-Lizenz"],"pt":["Desempenho rápido com utilização eficiente de múltiplos CPU e GPU","Integração de IA com recursos como Agentic Editing e Edit Prediction","Construído em Rust para garantir segurança de memória e desempenho","Código aberto sob a licença Apache License 2.0","Recursos de edição avançados, como Inline Assistant e Text Transformation"],"ru":["Быстрое выполнение с эффективным использованием нескольких CPU и GPU","Интеграция ИИ с функциями, такими как Agentic Editing и Edit Prediction","Построен на Rust для обеспечения безопасности памяти и производительности","Открытый код под лицензией Apache License 2.0","Продвинутые функции редактирования, такие как Inline Assistant и Text Transformation"],"ar":["أداء سريع باستخدام كفاءة متعددة من CPU و GPU","تكامل الذكاء الاصطناعي مع ميزات مثل تحرير الوكيل و تنبؤ التحرير","مبني على Rust لضمان أمان الذاكرة والأداء","كود مفتوح تحت ترخيص Apache License 2.0","ميزات تحرير متقدمة، مثل مساعد الإدراج وتحويل النص"]},"keywords":{"en":["how to use zed-editor","zed-editor alternative","zed-editor setup guide","what is zed-editor","zed-editor vs vscode","zed-editor install rust","zed-editor Agentic Editing","zed-editor performance optimization","zed-editor open-source community"],"zh":["Zed Editor","Rust 编辑器","AI 编辑器","Agentic Editing","Edit Prediction","Inline Assistant","代码编辑器","下一代编辑器"],"ja":["Zed Editor","Rust エディタ","AI エディタ","Agentic Editing","Edit Prediction","Inline Assistant","コードエディタ","次世代エディタ"],"ko":["Zed Editor","러스트 편집기","AI 편집기","Agentic Editing","Edit Prediction","Inline Assistant","코드 편집기","차세대 편집기"],"es":["Zed Editor","Inteligencia artificial para desarrolladores","Agentes de inteligencia artificial","Edición asistida por agente","Predicción de edición","Rust","Desarrollo de software","Herramientas de desarrollo","Productividad del desarrollador"],"fr":["Zed Editor","Intelligence artificielle pour les développeurs","Agents d''intelligence artificielle","Édition assistée par agent","Prédiction d''édition","Rust","Développement de logiciels","Outils de développement","Productivité du développeur"],"de":["Zed Editor","Künstliche Intelligenz für Entwickler","Künstliche Intelligenz-Agenten","Agentenunterstützte Bearbeitung","Bearbeitungsvorhersage","Rust","Software-Entwicklung","Entwicklertools","Entwickler-Produktivität"],"pt":["zed editor","ferramenta de edição de código","desempenho rápido","integração de ia","rust","código aberto","agentic editing","edit prediction","inline assistant","text transformation"],"ru":["zed editor","инструмент для редактирования кода","быстрое выполнение","интеграция ии","rust","открытый код","agentic editing","edit prediction","inline assistant","text transformation"],"ar":["محرر zed","أداة تحرير كود","أداء سريع","تكامل الذكاء الاصطناعي","rust","كود مفتوح","تحرير الوكيل","تنبؤ التحرير","مساعد الإدراج","تحويل النص"]}},"owner":"chronista-club","repo":"unison","repoPath":"chronista-club/unison","stars":4,"forks":1,"updatedAt":"2026-02-23T08:15:53Z","topics":[],"category":"community","skillMd":{"name":"zed-editor","description":"Zed Editorの特徴、ACP（Agent Client Protocol）の仕様、AI統合、パフォーマンス特性、設定方法について包括的な知識を提供します。Zed Editorに関する質問、ACP対応エージェントの統合、設定のカスタマイズが必要な場合に使用してください。","bodyPreview":"# Zed Editor Skill\n\nこのスキルは、Zed Editorとその革新的なAgent Client Protocol (ACP)について包括的な知識を提供します。\n\n## Zed Editorとは\n\nZed は、**Rustで完全に書き直された次世代のコードエディタ**です。以下の特徴を持ちます：\n\n### コア特性\n- **高速パフォーマンス**: 複数のCPUコアとGPUを効率的に活用\n  - 起動時間が極めて高速\n  - UIインタラクションの遅延がほぼゼロ\n  - タイピング遅延が最小限\n- **Rust製**: メモリ安全性とパフォーマンスを両立\n- **オープンソース**: Apache License 2.0の下で公開\n\n### 主要機能\n\n#### 1. AI統合\n- **Agentic Editing**: エージェントに作業を委譲し、進捗をリアルタイムで追跡\n- **Edit Prediction**: 次の入力を予測するオープンソース言語モデル\n- **Inline Assistant**: 選択したコードをLLMに送信して変換\n- **Text T","body":"# Zed Editor Skill\n\nこのスキルは、Zed Editorとその革新的なAgent Client Protocol (ACP)について包括的な知識を提供します。\n\n## Zed Editorとは\n\nZed は、**Rustで完全に書き直された次世代のコードエディタ**です。以下の特徴を持ちます：\n\n### コア特性\n- **高速パフォーマンス**: 複数のCPUコアとGPUを効率的に活用\n  - 起動時間が極めて高速\n  - UIインタラクションの遅延がほぼゼロ\n  - タイピング遅延が最小限\n- **Rust製**: メモリ安全性とパフォーマンスを両立\n- **オープンソース**: Apache License 2.0の下で公開\n\n### 主要機能\n\n#### 1. AI統合\n- **Agentic Editing**: エージェントに作業を委譲し、進捗をリアルタイムで追跡\n- **Edit Prediction**: 次の入力を予測するオープンソース言語モデル\n- **Inline Assistant**: 選択したコードをLLMに送信して変換\n- **Text Threads**: プレーンテキストインターフェースでLLMと対話\n\n#### 2. コラボレーション機能\n- チームメンバーとのチャット\n- 共同でのノート作成\n- スクリーンとプロジェクトの共有\n- すべてデフォルトで利用可能\n\n#### 3. 開発者機能\n- Language Server Protocol対応\n- アウトラインビュー\n- リモート開発\n- マルチバッファ編集\n- Vimバインディング\n- デバッガ\n- Git統合\n\n## Agent Client Protocol (ACP)\n\n### ACPの概念\n\nACPは、**コードエディタとAIコーディングエージェント間の通信を標準化するプロトコル**です。Language Server Protocol (LSP)がIDEから言語インテリジェンスを切り離したように、ACPはエディタからAIエージェントを切り離します。\n\n```\n┌─────────────┐         ACP         ┌──────────────┐\n│   Editor    │◄──────────────────►│    Agent     │\n│  (Client)   │   JSON-RPC/stdio   │   (Server)   │\n└─────────────┘                     └──────────────┘\n```\n\n### ACPの設計原理\n\n1. **エディタ非依存**: どのエディタでも同じエージェントが動作\n2. **標準化された通信**: JSON-RPCを使用したstdio通信\n3. **MCPとの統合**: Model Context Protocol (MCP)の仕様を可能な限り再利用\n4. **セキュリティ**: エディタがファイル、ターミナル、ツールへのアクセスを仲介\n\n### 技術仕様\n\n#### 通信方式\n- **プロトコル**: JSON-RPC over stdio\n- **起動**: エージェントプロセスはコードエディタによって起動\n- **スキーマ**: `schema/schema.json`で標準化\n\n#### 公式SDK\n\n| 言語 | パッケージ名 | 配布場所 |\n|------|-------------|---------|\n| TypeScript | `@agentclientprotocol/sdk` | NPM |\n| Rust | `agent-client-protocol` | crates.io |\n| Kotlin | `acp-kotlin` | JVM（他ターゲット開発中） |\n\n### エコシステム\n\n#### サポートされているエディタ\n- **Zed**: ネイティブサポート\n- **Neovim**: CodeCompanion、avante.nvim\n- **Emacs**: agent-shell plugin\n- **JetBrains IDEs**: 開発中（公式連携）\n- **Eclipse**: プロトタイプ実装\n- **marimo**: Python notebook環境\n\n#### サポートされているエージェント\n1. **Claude Code**: Anthropic製（パブリックベータ）\n2. **Gemini CLI**: Google製（デフォルト）\n3. **Codex CLI**: OpenAI製\n4. カスタムACP対応エージェント\n\n## Zed EditorでのACP使用方法\n\n### デフォルトエージェントの使用\n\n#### Gemini CLI\n```json\n{\n  \"bindings\": {\n    \"cmd-alt-g\": [\"agent::NewExternalAgentThread\", { \"agent\": \"gemini\" }]\n  }\n}\n```\n\n認証方法：\n- Googleログイン\n- Gemini APIキー\n- Vertex AI\n\n#### Claude Code\n\n1. 初回起動時に自動インストール\n2. `/login`コマンドで認証（APIキーまたはClaude Pro）\n3. カスタム実行ファイルの設定（オプション）：\n\n```json\n{\n  \"agent_servers\": {\n    \"claude\": {\n      \"env\": {\n        \"CLAUDE_CODE_EXECUTABLE\": \"/path/to/executable\"\n      }\n    }\n  }\n}\n```\n\n#### Codex CLI\n\n認証方法（3種類）：\n- ChatGPTアカウント\n- `CODEX_API_KEY`環境変数\n- `OPENAI_API_KEY`環境変数\n\n### カスタムエージェントの追加\n\n任意のACP対応エージェントを追加できます：\n\n```json\n{\n  \"agent_servers\": {\n    \"Custom Agent\": {\n      \"command\": \"node\",\n      \"args\": [\"~/projects/agent/index.js\", \"--acp\"],\n      \"env\": {\n        \"CUSTOM_ENV_VAR\": \"value\"\n      }\n    }\n  }\n}\n```\n\n### デバッグ\n\nコマンドパレット → \"dev: open acp logs\" でエージェント間の通信メッセージを確認できます。\n\n## Claude Code in Zed\n\n### 統合の特徴\n\nZedは、Claude Codeを**ネイティブに統合**しています：\n\n1. **リアルタイムトラッキング**: 複数ファイルにわたる変更を構文ハイライトと共に追跡\n2. **細かいコードレビュー**: マルチバッファ形式で個別の変更を承認/却下\n3. **タスクリストの可視化**: サイドバーに永続的に表示\n4. **カスタムワークフロー**: スラッシュコマンド対応\n\n### 技術アーキテクチャ\n\nZedは**アダプター方式**を採用：\n- Claude Code SDKの操作をACPのJSON RPC形式に変換\n- Claude Codeは独立して動作\n- ZedがUIレイヤーを提供\n\nアダプターはApacheライセンスで[オープンソース化](https://github.com/zed-industries/claude-code-adapter)されており、他のACP対応エディタでも利用可能です。\n\n### 現在の制限事項\n\nベータ版では以下の機能が未サポート：\n- Plan mode\n- 組み込みスラッシュコマンド\n\nこれらはAnthropicによるSDK拡張待ちです。\n\n## MCP (Model Context Protocol) との関係\n\n### MCPサポート状況\n\n| エージェント | MCPサポート |\n|-------------|-----------|\n| Claude Code | ✅ 対応 |\n| Codex CLI | ✅ 対応 |\n| Gemini CLI | ❌ 未対応 |\n\n### MCPとACPの違い\n\n- **MCP**: モデル（AI）がコンテキスト（データ）にアクセスするためのプロトコル\n- **ACP**: エディタとエージェント間の通信プロトコル\n- **関係**: ACPはMCPの仕様を可能な限り再利用しつつ、独自の型も追加\n\n## パートナーシップとエコシステム\n\n### JetBrains連携\n\nJetBrainsとZedは、ACP駆動の体験をJetBrains IDEでネイティブに実装する取り組みを進めています：\n- JetBrains IDEでのネイティブな統合\n- エコシステム全体での互換性維持\n- オープンで移植可能な実装\n\n### コミュニティの広がり\n\nACPは、複数のエディタコミュニティで採用されています：\n- Neovim: 2つのプラグインで実装\n- Emacs: agent-shellプラグイン\n- marimo: Pythonノートブック環境\n- Eclipse: プロトタイプ実装\n\n## 設定ファイルの場所\n\n### Zed設定ファイル\n\n| 設定タイプ | ファイルパス |\n|----------|------------|\n| ユーザー設定 | `~/.config/zed/settings.json` |\n| キーバインド | `~/.config/zed/keymap.json` |\n| エージェント設定 | settings.jsonの`agent_servers`セクション |\n\n### 設定例\n\n```json\n{\n  // 基本設定\n  \"theme\": \"One Dark\",\n  \"vim_mode\": true,\n  \n  // エージェント設定\n  \"agent_servers\": {\n    \"claude\": {\n      \"env\": {}\n    },\n    \"gemini\": {\n      \"env\": {}\n    }\n  },\n  \n  // キーバインド\n  \"bindings\": {\n    \"cmd-alt-c\": [\"agent::NewExternalAgentThread\", { \"agent\": \"claude\" }],\n    \"cmd-alt-g\": [\"agent::NewExternalAgentThread\", { \"agent\": \"gemini\" }]\n  }\n}\n```\n\n## ベストプラクティス\n\n### エージェント選択の指針\n\n1. **Claude Code**: 複雑なコード編集、リファクタリング、アーキテクチャ設計\n2. **Gemini CLI**: Google Cloud連携、Vertex AI利用\n3. **Codex CLI**: OpenAI APIとの統合\n\n### パフォーマンス最適化\n\n- 不要なエージェントは無効化\n- デバッグログは必要時のみ有効化\n- 大規模プロジェクトでは言語サーバーの設定を調整\n\n### セキュリティ考慮事項\n\n1. **信頼できるソースのみ**: エージェントは信頼できるソースからのみインストール\n2. **環境変数の管理**: APIキーは環境変数で管理\n3. **アクセス制御**: エージェントのファイルアクセスを適切に制限\n\n## トラブルシューティング\n\n### エージェントが起動しない\n\n1. ACPログを確認: `dev: open acp logs`\n2. 実行ファイルのパスを確認\n3. 環境変数が正しく設定されているか確認\n\n### 認証エラー\n\n1. APIキーの有効期限を確認\n2. 環境変数の設定を確認\n3. エージェントの再認証を試行\n\n### パフォーマンス問題\n\n1. 不要なエージェントを無効化\n2. Zedのバージョンを最新に更新\n3. システムリソースの使用状況を確認\n\n## 参考リンク\n\n### 公式ドキュメント\n- [Zed Editor公式サイト](https://zed.dev/)\n- [ACP GitHub Repository](https://github.com/zed-industries/agent-client-protocol)\n- [Zed AI Documentation](https://zed.dev/docs/ai/external-agents)\n\n### ブログ記事\n- [Claude Code via ACP](https://zed.dev/blog/claude-code-via-acp)\n- [ACP Progress Report](https://zed.dev/blog/acp-progress-report)\n- [JetBrains × Zed Partnership](https://blog.jetbrains.com/ai/2025/10/jetbrains-zed-open-interoperability-for-ai-coding-agents-in-your-ide/)\n\n### コミュニティリソース\n- Zed Discord\n- GitHub Discussions\n- ACP Ecosystem Projects\n\n## まとめ\n\nZed Editorは、高速なRust製エディタとして、Agent Client Protocolを通じて真にオープンなAIエージェント統合を実現しています。ACPは、LSPが言語ツールに対して行ったことをAIエージェントに対して実現し、開発者に選択肢と柔軟性を提供します。\n\nこのスキルを使用することで、Zed Editorの設定、ACPエージェントの統合、トラブルシューティング、最適化を効率的に行うことができます。\n"},"lastSynced":"2026-03-06T06:57:00.735Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Analysis Agents seeking advanced editing capabilities with Rust-based performance and AI-driven features like Agentic Editing and Edit Prediction.","zh":"适合于寻求具有Rust性能和AI驱动功能（如Agentic Editing和Edit Prediction）高级编辑功能的代码分析代理。","ja":"RustベースのパフォーマンスとAI駆動の機能（例：Agentic EditingおよびEdit Prediction）を備えた高度なエディティング機能を求めるコード分析エージェントに適しています。","ko":"Rust 기반의 성능과 AI 구동 기능(Agentic Editing 및 Edit Prediction 등)을 갖춘 고급 편집 기능을 찾는 코드 분석 에이전트에 적합합니다.","es":"Ideal para Agentes de Análisis de Código que buscan capacidades de edición avanzadas con rendimiento basado en Rust y características impulsadas por IA como Edición Agente y Predicción de Edición.","fr":"Idéal pour les Agents d''Analyse de Code qui recherchent des capacités de modification avancées avec des performances basées sur Rust et des fonctionnalités pilotées par l''IA comme l''Édition Agente et la Prédiction d''Édition.","de":"Ideal für Code-Analyse-Agenten, die erweiterte Bearbeitungsfunktionen mit Rust-basierten Leistungen und künstlicher Intelligenz-getriebenen Funktionen wie Agentic Editing und Edit Prediction suchen.","pt":"Ideal para Agentes de Análise de Código que buscam capacidades de edição avançadas com desempenho baseado em Rust e recursos impulsionados por IA, como Edição Agente e Previsão de Edição.","ru":"Идеально для агентов анализа кода, которые ищут расширенные возможности редактирования с производительностью на основе Rust и функциями, управляемыми ИИ, такими как редактирование агентов и прогнозирование редактирования.","ar":"مثالية للوكلاء قائمين على تحليل الشفرة الذين يبحثون عن إمكانيات تحرير متقدمة مع أداء مُستند إلى رست وسمات مدفوعة بالذكاء الاصطناعي مثل تحرير الوكيل وتحديد التحرير."},"recommendation":{"en":"Empowers agents to leverage the Zed Editor''s Agent Client Protocol (ACP) for seamless integration with AI models, utilizing features like Inline Assistant for real-time code transformation and analysis, all while benefiting from the editor''s core characteristics such as high-performance rendering and memory safety.","zh":"赋予代理利用Zed编辑器的Agent Client Protocol（ACP）与AI模型实现无缝集成，利用内联助手进行实时代码转换和分析，同时受益于编辑器的核心特征，如高性能渲染和内存安全。","ja":"エージェントがZedエディターのエージェントクライアントプロトコル（ACP）を利用してAIモデルとシームレスに統合し、インラインアシスタントを使用したリアルタイムコード変換と分析を行うことができ、またエディターのコア特性である高パフォーマンスレンダリングとメモリセーフティの利点も享受できます。","ko":"에이전트가 Zed 편집기의 에이전트 클라이언트 프로토콜(ACP)을 사용하여 AI 모델과 무결점으로 통합하고, 인라인 어시스턴트를 통해 실시간 코드 변환 및 분석을 수행할 수 있으며, 또한 편집기의 핵심 특성인 고성능 렌더링 및 메모리 안전성의 이점도 누릴 수 있습니다.","es":"Habilita a los agentes a aprovechar el Protocolo de Cliente de Agente de Zed (ACP) para una integración perfecta con los modelos de IA, utilizando características como Asistente en Línea para la transformación y el análisis de código en tiempo real, y beneficiándose de las características básicas del editor como la representación de alto rendimiento y la seguridad de la memoria.","fr":"Permet aux agents d''exploiter le Protocole Client Agent Zed (ACP) pour une intégration transparente avec les modèles d''IA, en utilisant des fonctionnalités comme l''Assistant en Ligne pour la transformation et l''analyse de code en temps réel, tout en bénéficiant des caractéristiques de base de l''éditeur telles que le rendu haute performance et la sécurité de la mémoire.","de":"Ermächtigt die Agenten, das Agent Client Protocol (ACP) von Zed Editor zu nutzen, um eine nahtlose Integration mit KI-Modellen zu ermöglichen, die Funktionen wie Inline-Assistent für Echtzeit-Code-Transformation und -Analyse nutzen und gleichzeitig von den Kernmerkmalen des Editors wie hochleistungsfähiger Darstellung und Speichersicherheit profitieren.","pt":"Habilita os agentes a aproveitarem o Protocolo de Cliente de Agente do Zed Editor (ACP) para integração sem problemas com modelos de IA, utilizando recursos como Assistente Inline para transformação e análise de código em tempo real, aproveitando as características principais do editor, como renderização de alto desempenho e segurança de memória.","ru":"Наделяет агентов возможностью использовать протокол клиента агента редактора Zed (ACP) для бесшовной интеграции с моделями ИИ, используя функции, такие как помощник Inline для реального времени преобразования и анализа кода, при этом пользуясь основными характеристиками редактора, такими как высокопроизводительный рендеринг и безопасность памяти.","ar":"تمكّن الوكلاء من الاستفادة من بروتوكول عميل الوكيل الخاص بمحرر زد (ACP) من أجل التكامل السلس مع نماذج الذكاء الاصطناعي، باستخدام ميزات مثل مساعد الإدراج للتحويل والتحليل الفوري للشفرة، مع الاستفادة من الخصائص الأساسية للمحرر مثل العرض العالي للأداء وأمان الذاكرة."},"useCases":{"en":["Automating code reviews with AI-driven edit predictions","Generating and transforming code snippets using the Inline Assistant","Debugging complex codebases with the Zed Editor''s high-performance capabilities"],"zh":["使用AI驱动的编辑预测自动化代码审查","使用内联助手生成和转换代码片段","使用Zed编辑器的高性能功能调试复杂的代码库"],"ja":["AI駆動の編集予測を使用したコードレビューの自動化","インラインアシスタントを使用したコードスニペットの生成と変換","Zedエディターの高パフォーマンス機能を使用した複雑なコードベースのデバッグ"],"ko":["AI 구동 편집 예측을 사용한 코드 리뷰 자동화","인라인 어시스턴트를 사용한 코드 조각 생성 및 변환","Zed 편집기의 고성능 기능을 사용한 복잡한 코드베이스 디버깅"],"es":["Automatizar las revisiones de código con predicciones de edición impulsadas por IA","Generar y transformar fragmentos de código utilizando el Asistente en Línea","Depurar código complejo con las capacidades de alto rendimiento del Zed Editor"],"fr":["Automatiser les examens de code avec des prédictions d''édition pilotées par l''IA","Générer et transformer des extraits de code à l''aide de l''Assistant en Ligne","Déboguer des bases de code complexes avec les capacités de haute performance de l''éditeur Zed"],"de":["Automatisieren von Code-Reviews mit künstlicher Intelligenz-getriebenen Bearbeitungsvorhersagen","Generieren und Umwandeln von Code-Snippets unter Verwendung des Inline-Assistenten","Fehlersuche in komplexen Codebasen mit den Hochleistungs-Funktionen des Zed Editors"],"pt":["Automatizar análises de código com previsões de edição impulsionadas por IA","Gerar e transformar trechos de código usando o Assistente Inline","Depurar bases de código complexas com as capacidades de alto desempenho do Zed Editor"],"ru":["Автоматизировать анализ кода с прогнозами редактирования, управляемыми ИИ","Генерировать и преобразовывать фрагменты кода с помощью помощника Inline","Отлаживать сложные кодовые базы с помощью высокопроизводительных возможностей редактора Zed"],"ar":["تأتمتة مراجعة الشفرة مع تنبؤات التحرير مدفوعة بالذكاء الاصطناعي","توليد وتحويل مقاطع الشفرة باستخدام مساعد الإدراج","تصحيح الأخطاء في قواعد الشفرة المعقدة باستخدام إمكانيات محرر زد عالية الأداء"]},"limitations":{"en":["Requires Rust compatibility for full feature utilization","Dependent on Apache License 2.0 for open-source contributions and usage"],"zh":["需要Rust兼容性才能完全利用功能","依赖Apache License 2.0进行开源贡献和使用"],"ja":["機能を完全に利用するにはRustの互換性が必要","オープンソースの貢献と使用にはApache License 2.0に依存"],"ko":["기능을 완전히 활용하기 위해서는 Rust 호환성이 필요합니다","오픈소스 기여 및 사용에는 Apache License 2.0에 의존"],"es":["Requiere compatibilidad con Rust para la utilización completa de las características","Dependiente de la Licencia Apache 2.0 para contribuciones y uso de código abierto"],"fr":["Nécessite une compatibilité avec Rust pour une utilisation complète des fonctionnalités","Dépend de la Licence Apache 2.0 pour les contributions et l''utilisation de code ouvert"],"de":["Benötigt Rust-Kompatibilität für die vollständige Nutzung der Funktionen","Abhängig von der Apache-Lizenz 2.0 für Open-Source-Beiträge und -Nutzung"],"pt":["Exige compatibilidade com Rust para utilização completa de recursos","Dependente da Licença Apache 2.0 para contribuições e utilização de código aberto"],"ru":["Требует совместимости с Rust для полного использования функций","Зависит от лицензии Apache 2.0 для вклада и использования открытого кода"],"ar":["يتطلب توافقًا مع رست للاستفادة الكاملة من الميزات","يعتمد على رخصة أباتشي 2.0 لمساهمات واستخدام الشفرة المفتوحة"]},"version":4},"contentHash":"6d7205571fccca8505724728995233a0a4f99eb1904f98345d90339f3de5f639","qualityScore":39}');
