INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('chronista-club/unison/zed-editor', 'zed-editor', 'chronista-club', 'unison', 'community', 'zed-editor chronista-club unison community The zed-editor skill provides comprehensive knowledge on the Zed Editor and its innovative Agent Client Protocol (ACP), benefiting developers with advanced code editing capabilities. Zed Editor 是一个基于 Rust 的下一代代码编辑器，具有高速性能、内存安全性和开源特性 Zed Editor は、Rust で書かれた次世代のコードエディタです。高速パフォーマンス、メモリ安全性、オープンソースを特徴とします Zed Editor는 러스트 기반의 차세대 코드 편집기로서高速 성능, 메모리 안전성, 오픈소스를 특징으로 합니다 Zed Editor es un editor de código de próxima generación escrito en Rust, con capacidades de inteligencia artificial y un rendimiento rápido Zed Editor est un éditeur de code de nouvelle génération écrit en Rust, avec des capacités d''intelligence artificielle et des performances rapides Zed Editor ist ein Code-Editor der nächsten Generation, geschrieben in Rust, mit künstlicher Intelligenz und schneller Leistung O Zed Editor é uma ferramenta de edição de código de próxima geração, construída em Rust, com recursos como desempenho rápido e integração de IA Zed Editor - это инструмент для редактирования кода нового поколения, построенный на Rust, с функциями, такими как быстрое выполнение и интеграция ИИ محرر Zed هو أداة تحرير كود من الجيل التالي، مبني على Rust، مع ميزات مثل الأداء السريع وتكامل الذكاء الاصطناعي how to use zed-editor zed-editor alternative zed-editor setup guide what is zed-editor zed-editor vs vscode zed-editor install rust zed-editor Agentic Editing zed-editor performance optimization zed-editor open-source community Zed Editor Rust 编辑器 AI 编辑器 Agentic Editing Edit Prediction Inline Assistant 代码编辑器 下一代编辑器 Utilizes Rust for memory safety and performance Employs Agentic Editing for real-time progress tracking Features Edit Prediction with open-source language models Supports Inline Assistant for code transformation with LLMs Leverages multiple CPU cores and GPU for efficient performance zed-editor is a next-generation code editor written entirely in Rust, offering high-performance, memory safety, and open-source flexibility.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zot/frictionless/ui', 'community', 'zot', 'frictionless', 'zot/frictionless', 'ui', 4, 2, 39, '2026-02-25T22:58:57Z', '2026-03-06T06:57:16.733Z', '182b0049834589f72bb98ddf4554c3b351885fe9361de0471ac92c67f5d8e6a2', '{"id":"zot/frictionless/ui","name":"ui","description":{"en":"The ui skill enables developers to build and run UIs with Lua apps connected to widgets. It supports features like showing app-console and starting event loops.","zh":"UI 技术提供 Lua 应用和 Playwright 集成，实现动态 UI 更新和事件循环","ja":"UI 技術は Lua アプリケーションと Playwright 統合を提供し、ダイナミック UI 更新とイベントループを実現","ko":"UI 기술은 Lua 애플리케이션과 Playwright 통합을 제공하여 동적 UI 업데이트와 이벤트 루프를 구현","es":"La habilidad UI permite la construcción y ejecución de aplicaciones con Lua y Playwright. Evoluciona tus aplicaciones mientras se ejecutan y comparte tus creaciones.","fr":"La compétence UI permet la création et l''exécution d''applications avec Lua et Playwright. Faites évoluer vos applications pendant leur exécution et partagez vos créations.","de":"Die UI-Fähigkeit ermöglicht die Erstellung und Ausführung von Anwendungen mit Lua und Playwright. Entwickeln Sie Ihre Anwendungen während der Ausführung und teilen Sie Ihre Kreationen.","pt":"A UI é uma fundação para construir e executar ui-engine UIs com aplicativos Lua conectados a widgets. Aprenda a utilizar o Playwright e o Quick Start.","ru":"UI - это основа для построения и запуска ui-engine UI с подключенными к виджетам приложениями Lua. Узнайте, как использовать Playwright и Quick Start.","ar":"واجهة المستخدم هي أساس لبناء وتشغيل ui-engine UI مع تطبيقات Lua متصلة بWidgets. تعلم كيفية استخدام Playwright و Quick Start."},"seo":{"title":{"en":"ui: Setup Guide for AI Agents | AI Agent Skill","zh":"UI 技术集成指南 - AIエージェント UI 引擎","ja":"UI Setup Guide - AIエージェント UI エンジン","ko":"UI 설정 가이드 - AI 에이전트 UI 엔진","es":"Guía de Configuración de UI: Construcción de Aplicaciones...","fr":"Guide de Configuration UI : Création d''Applications avec ...","de":"UI-Konfigurationsleitfaden: Erstellung von Anwendungen mi...","pt":"Guia de Configuração UI: Desenvolvimento de Aplicativos c...","ru":"ИИ Агенты: Настройка UI для построения и запуска ui-engine","ar":"دليل إعداد واجهة المستخدم: تطوير التطبيقات مع Lua"},"description":{"en":"Unlock the full potential of UI with our expert guide. Learn how to use Lua apps, widgets, and Playwright for seamless UI development. Get started now!","zh":"了解 UI 技术的最新进展，包括 Lua 应用、Playwright 集成和事件循环","ja":"UI 技術の最新情報をご紹介します。Lua アプリケーション、Playwright 統合、イベントループなど","ko":"UI 기술의 최신 동향을 확인하세요. Lua 애플리케이션, Playwright 통합, 이벤트 루프 등","es":"Descubre cómo configurar y utilizar la habilidad UI para construir aplicaciones con Lua y Playwright, y mejora tu experiencia de desarrollo","fr":"Découvrez comment configurer et utiliser la compétence UI pour créer des applications avec Lua et Playwright, et améliorez votre expérience de développement","de":"Erfahren Sie, wie Sie die UI-Fähigkeit konfigurieren und verwenden können, um Anwendungen mit Lua und Playwright zu erstellen und Ihre Entwicklungserfahrung ...","pt":"Aprenda a configurar a UI para desenvolver aplicativos com Lua e ui-engine. Descubra como utilizar o Playwright e o Quick Start.","ru":"Узнайте, как настроить UI для построения и запуска ui-engine с помощью Lua и Playwright. Прочитайте нашу документацию.","ar":"تعلم كيفية إعداد واجهة المستخدم لتطوير التطبيقات مع Lua و ui-engine. اكتشف كيفية استخدام Playwright و Quick Start."},"definition":{"en":"ui is a foundation for building and running ui-engine UIs with Lua apps connected to widgets, utilizing technologies like Playwright.","zh":"UI 技术是指使用 Lua 应用和 Playwright 集成的 UI 引擎","ja":"UI 技術とは、Lua アプリケーションと Playwright 統合を使用する UI エンジン","ko":"UI 기술은 Lua 애플리케이션과 Playwright 통합을 사용하는 UI 엔진","es":"La habilidad UI es un conjunto de herramientas para la creación y ejecución de aplicaciones con Lua y Playwright","fr":"La compétence UI est un ensemble d''outils pour la création et l''exécution d''applications avec Lua et Playwright","de":"Die UI-Fähigkeit ist ein Satz von Tools für die Erstellung und Ausführung von Anwendungen mit Lua und Playwright","pt":"UI é uma fundação para construir e executar interfaces de usuário com aplicativos Lua","ru":"UI - это основа для построения и запуска интерфейсов пользователя с приложениями Lua","ar":"واجهة المستخدم هي أساس لبناء واجهات المستخدم مع تطبيقات Lua"},"features":{"en":["Shows app-console as in Quick Start using `/ui` command","Preferably uses Playwright if the user has been using it","Starts event loop when the user says `events`","Supports showing specific apps with `show APP` command","Utilizes Lua apps connected to widgets for UI development","Allows evolving apps while they run"],"zh":["Lua 应用集成","Playwright 支持","事件循环","动态 UI 更新","Quick Start 集成","UI 引擎"],"ja":["Lua アプリケーション統合","Playwright サポート","イベントループ","ダイナミック UI 更新","Quick Start 統合","UI エンジン"],"ko":["Lua 애플리케이션 통합","Playwright 지원","이벤트 루프","동적 UI 업데이트","Quick Start 통합","UI 엔진"],"es":["Construcción de aplicaciones con Lua","Integración con Playwright","Ejecución de aplicaciones mientras se desarrollan","Compartir aplicaciones y widgets","Uso de la consola de aplicaciones","Incorporación de eventos en la aplicación"],"fr":["Création d''applications avec Lua","Intégration avec Playwright","Exécution d''applications pendant leur développement","Partage d''applications et de widgets","Utilisation de la console d''applications","Intégration d''événements dans l''application"],"de":["Erstellung von Anwendungen mit Lua","Integration mit Playwright","Ausführung von Anwendungen während der Entwicklung","Teilen von Anwendungen und Widgets","Verwendung der Anwendungs-Konsole","Einbindung von Ereignissen in die Anwendung"],"pt":["Desenvolvimento de aplicativos com Lua","Conexão a widgets com ui-engine","Utilização do Playwright","Integração com Quick Start","Suporte a eventos com event loop"],"ru":["Построение приложений с помощью Lua","Подключение к виджетам с ui-engine","Использование Playwright","Интеграция с Quick Start","Поддержка событий с помощью event loop"],"ar":["تطوير التطبيقات مع Lua","الارتباط بWidgets مع ui-engine","استخدام Playwright","التكامل مع Quick Start","دعم الأحداث مع حلقة الأحداث"]},"keywords":{"en":["how to use ui","ui setup guide","ui alternative","ui vs Playwright","ui install","what is ui","ui lua apps","ui widgets","ui event loop","ui development"],"zh":["UI 技术","Lua 应用","Playwright","事件循环","动态 UI 更新","AIエージェント","UI 引擎","Quick Start"],"ja":["UI 技術","Lua アプリケーション","Playwright","イベントループ","ダイナミック UI 更新","AIエージェント","UI エンジン","Quick Start"],"ko":["UI 기술","Lua 애플리케이션","Playwright","이벤트 루프","동적 UI 업데이트","AI 에이전트","UI 엔진","Quick Start"],"es":["herramientas de desarrollo UI","aplicaciones con Lua","Playwright","construcción de aplicaciones","desarrollo de aplicaciones","UI AI","Herramientas de UI","Desarrollo de aplicaciones con Lua y Playwright","UI para desarrolladores"],"fr":["outils de développement UI","applications avec Lua","Playwright","création d''applications","développement d''applications","UI IA","Outils de UI","Développement d''applications avec Lua et Playwright","UI pour les développeurs"],"de":["Entwicklungstools UI","Anwendungen mit Lua","Playwright","Erstellung von Anwendungen","Entwicklung von Anwendungen","UI KI","UI-Tools","Entwicklung von Anwendungen mit Lua und Playwright","UI für Entwickler"],"pt":["ui","lua","ui-engine","playwright","quick start","desenvolvimento de aplicativos","construção de interfaces de usuário","tecnologias de desenvolvimento web"],"ru":["ИИ Агенты","ui","lua","ui-engine","playwright","quick start","построение приложений","построение интерфейсов пользователя","технологии веб-разработки"],"ar":["واجهة المستخدم","lua","ui-engine","playwright","quick start","تطوير التطبيقات","بناء واجهات المستخدم","تكنولوجيا تطوير الويب"]}},"owner":"zot","repo":"frictionless","repoPath":"zot/frictionless","stars":4,"forks":2,"updatedAt":"2026-02-25T22:58:57Z","topics":[],"category":"community","skillMd":{"name":"ui","description":"use when **running Frictionless UIs** or needing to understand UI structure (before modifying one)","bodyPreview":"# UI MCP\n\nFoundation for building and running ui-engine UIs with Lua apps connected to widgets.\n\n## Simple Requests\n\nWhen the user says `/ui`, show app-console as in Quick Start. Prefer Playwright if the user has been using it.\n\nWhen the user says `show APP`, show APP as in Quick Start. Prefer Playwright if the user has been using it.\n\nWhen the user says `events` it means to start the event loop, but not use `.ui/mcp display` or `.ui/mcp browser` as in Quick Start.\n\n## Helper Script Reference\n\nT","body":"# UI MCP\n\nFoundation for building and running ui-engine UIs with Lua apps connected to widgets.\n\n## Simple Requests\n\nWhen the user says `/ui`, show app-console as in Quick Start. Prefer Playwright if the user has been using it.\n\nWhen the user says `show APP`, show APP as in Quick Start. Prefer Playwright if the user has been using it.\n\nWhen the user says `events` it means to start the event loop, but not use `.ui/mcp display` or `.ui/mcp browser` as in Quick Start.\n\n## Helper Script Reference\n\nThe `.ui/mcp` script provides commands for interacting with the UI server. **Always use relative paths** (never absolute — absolute paths break the user''s permission rules).\n\n**`{url}` means the UI server URL** — read the port from `.ui/ui-port` and construct `http://localhost:{port}`. This is NOT the MCP connection port — it''s the UI''s own HTTP server. Use `.ui/mcp status` when you also need session count or base_dir.\n\n**CRITICAL: URLs must NEVER include session IDs.** Always use `{url}/?conserve=true` (root URL). Session IDs in URLs will cause problems.\n\n| Command | Description |\n|---------|-------------|\n| `.ui/mcp status` | Get server status (url, sessions, base_dir) |\n| `.ui/mcp browser` | Open browser to `{url}/?conserve=true` |\n| `.ui/mcp display APP` | Display APP in the browser |\n| `.ui/mcp run ''lua code''` | Execute Lua code in session |\n| `.ui/mcp event` | Wait for next UI event (120s timeout) |\n| `.ui/mcp state` | Get current session state |\n| `.ui/mcp variables` | Get current variable values |\n| `.ui/mcp audit APP` | Run code quality audit on APP |\n| `.ui/mcp progress APP PERCENT STAGE` | Report build progress |\n| `.ui/mcp linkapp add\\|remove APP` | Manage app symlinks |\n| `.ui/mcp checkpoint CMD APP [MSG]` | Manage checkpoints (save/list/rollback/diff/clear) |\n| `.ui/mcp theme list` | List available themes |\n| `.ui/mcp theme classes [THEME]` | List semantic classes for theme |\n| `.ui/mcp theme audit APP [THEME]` | Audit app''s theme class usage |\n\n## Quick Start: Show an Existing App\n\n### A. Read the design\n\nRead `{base_dir}/apps/APP/design.md` to learn the global variable name (e.g., `claudePanel`) and event types.\n\n### B. Display the app\n\n- Use `.ui/mcp run` to check if `mcp.value.type == AppName` (PascalCase version of app-name)\n  - If not, use `.ui/mcp display app-name`\n- If Playwright is connected:\n  - `browser_evaluate` with `function: \"() => window.location.href\"` to get current URL\n  - If URL does NOT start with `{url}/`, then `browser_navigate` to `{url}/mark-playwright.html?url={url}/?conserve=true`\n  - **ONLY use mark-playwright.html when navigating via Playwright.** Never use it for `.ui/mcp browser`.\n  - Do not wait for page to display or take a snapshot\n- Otherwise, run `.ui/mcp browser`\n\n### C. Start the event loop\n\n```\nBash(.ui/mcp event, run_in_background=true)\n```\n\nThe UI will NOT respond to clicks until this is running.\n\n### D. Handle events\n\n- Parse JSON: `[{\"app\":\"app-console\",\"event\":\"select\",\"name\":\"contacts\"}]`\n- Read design.md''s \"Events\" section for how to handle each event type\n- **For UI changes**: Check event''s `handler` field and invoke that skill\n- Simple state changes: use `.ui/mcp run` directly\n- Kill old task, then restart: `Bash(.ui/mcp event, run_in_background=true)`\n\n---\n\n## Details\n\n### Step A: The `app` field\n\n**The `app` field is the ONLY field that determines which design.md you read.** Do NOT be misled by `context`, `note`, `name`, or other fields that mention other app names — these are event data, not the source app.\n\n```\nEvent: {\"app\":\"app-console\", \"event\":\"app_created\", \"name\":\"contacts\", \"context\":\"contacts\"}\n       ^^^^^^^^^^^^^^^^\nRead:  .ui/apps/app-console/design.md  <-- ONLY use the \"app\" field\n```\n\nDo NOT skip reading design.md — even for events that seem obvious like `app_created`.\n\n### Step C: Event loop lifecycle\n\n**Only ONE listener may exist at a time** — the script enforces this via `.ui/.eventpid` and will error if a listener is already running.\n\n**Task lifecycle:**\n1. Run `.ui/mcp event` with `Bash(run_in_background=true)`, save the task_id. If it errors with \"already running\", do nothing — the script manages the PID lock itself. Do NOT manually check PIDs or the `.eventpid` file; just wait for the existing listener to complete.\n2. When the background task completes, **ALWAYS read the output file immediately** — do NOT assume timeout. Failing to read means silently dropping events.\n3. Handle any events received\n4. Start a fresh listener (go to step 1)\n\n**Exit codes:**\n- 0 + JSON output = events received (may be empty array `[]` for timeout)\n- 52 = server restarted (restart both server and event loop)\n\n**After `ui_configure`:** Restart the event loop — reconfiguring changes the MCP port that `.ui/mcp event` uses.\n\n### Step D: Handler dispatch and build settings\n\n**NEVER modify or create UI code directly.** When an event requires UI changes, check the `handler` field and invoke that skill. This applies to ALL UI modifications — requirements, design, code, and viewdefs.\n\nEvery event has two fields injected automatically based on the status bar toggles:\n\n| Toggle | Field | Values |\n|--------|-------|--------|\n| Build mode (rocket/diamond) | `handler` | `\"/ui-fast\"` or `\"/ui-thorough\"` |\n| Execution (hourglass/arrows) | `background` | `false` or `true` |\n\nThese reflect the user''s explicit choices. For background execution:\n```\nTask(subagent_type=\"ui-builder\", run_in_background=true, prompt=\"invoke {handler} skill...\")\n```\n\n---\n\n## App Variable Convention\n\nEach app defines a **global variable** for interacting with it via `.ui/mcp run`:\n\n| App Name       | Global Variable | Example Call                        |\n|----------------|-----------------|-------------------------------------|\n| `claude-panel` | `claudePanel`   | `claudePanel:addAgentMessage(\"Hi\")` |\n| `contacts`     | `contacts`      | `contacts:addContact(name, email)`  |\n| `ma-luba`      | `maLuba`        | `maLuba:someMethod()`               |\n\n**Convention:** kebab-case app name → camelCase variable. The global variable is exactly the camelCase conversion of the app directory name (no \"App\" suffix).\n\nFind the variable by looking at the bottom of `app.lua` for the instance creation:\n```lua\nif not session.reloading then\n    claudePanel = ClaudePanel:new()  -- <-- this is the global variable\nend\n```\n\n## Chat Messages\n\nAll chat messages render markdown. Use it via `.ui/mcp run`:\n```\n.ui/mcp run ''mcp:addAgentMessage(\"Found **salary data**: $150k-$180k\")''\n```\n\n### Pointing at UI elements\n\nWhen the user asks \"where is X?\" or \"show me the Y\", **both highlight the element AND include a clickable link** in your response so the user can re-trigger the highlight later:\n\n1. Find the element''s DOM id (from variables, viewdefs, or Playwright)\n2. Highlight it immediately: `mcp.code = [=[window.uiApp.highlight(\"ui-42\")// ]=] .. os.time()`\n3. Reply with a rich message containing a highlight link:\n\n```lua\nmcp:addRichMessage(\n    \"The search box is \"\n    .. mcp:highlightLink(\"ui-42\", \"right here\")\n    .. \". Type to filter the list.\"\n)\n```\n\nThe link stays in the chat history — the user can click it anytime to re-highlight the element.\n\n### Message methods\n\n| Method | Description |\n|--------|-------------|\n| `mcp:addAgentMessage(text)` | Agent message with markdown rendering |\n| `mcp:addRichMessage(html)` | Agent message with raw HTML (for highlight links, custom content) |\n| `mcp:highlightLink(elementId, label)` | Returns anchor HTML that highlights an element on click |\n| `mcp:addAgentThinking(text)` | Thinking/progress message (italic, updates status bar) |\n| `mcp:renderMarkdown(text)` | Convert markdown to HTML fragment (for custom use) |\n\n## Building or Modifying UIs\n\nWhen the user asks for changes outside an event loop, ask which mode they prefer or default to `/ui-fast` for small changes.\n\n**Before building a new app:**\n1. Create the app directory: `mkdir -p {base_dir}/apps/<app>`\n2. Write requirements to `{base_dir}/apps/<app>/requirements.md`\n\n### Requirements Format\n\n```markdown\n# Descriptive Title\n\nA short paragraph describing what the app does.\n\n## Section 1\n...\n```\n\nThe first line is a descriptive title (e.g., \"# Contact Manager\"), followed by prose describing the app. See `.claude/skills/ui-builder/examples/requirements.md` for a reference.\n\n## Directory Structure\n\n```\n{base_dir}/\n├── apps/<app>/           # App source files\n│   ├── requirements.md   # What to build (you write this)\n│   ├── design.md         # How it works (generated)\n│   ├── app.lua           # Lua code (generated)\n│   └── viewdefs/         # HTML templates (generated)\n├── lua/                  # Symlinks to app lua files\n├── viewdefs/             # Symlinks to app viewdefs\n├── html/<app>            # Symlink to app dir (serves static files at /<app>/)\n├── html/<app>-storage    # Symlink to storage dir (serves at /<app>-storage/)\n├── storage/<app>/        # Optional local storage (isolated from app updates)\n├── patterns/             # Reusable pattern documentation\n├── themes/               # Theme definitions and CSS variables\n├── event                 # Event wait script\n└── log/                  # Runtime logs\n```\n\n## File Ownership\n\n- `requirements.md` — you write/update this\n- `design.md`, `app.lua`, `viewdefs/` — **MUST load `/ui-basics` first**, then use `/ui-fast` or `/ui-thorough`. This is a non-standard system; standard web patterns will lead you astray.\n\n## Debugging\n\n- **Lua logs:** `{base_dir}/log/lua.log` for Lua errors\n- **MCP server stderr:** `.ui/log/mcp.log`\n- **Variable inspector:** `http://localhost:{mcp-port}/variables` (read port from `.ui/mcp-port`) — curl for JSON, browser for interactive inspector\n- **MCP resources:** `ui://variables` (full variable tree), `ui://state` (live state JSON)\n- **JS diagnostics:** `window.uiApp.getStore()` (variable state) and `window.uiApp.getBinding()` (widget bindings) in browser console\n- **Remote JS execution:** Set `mcp.code` from Lua — bound to `ui-code` in the MCP shell, enabling JS execution in the browser. Critical when using a system browser instead of Playwright. Re-assigning the same value is a no-op (change detection); append a nonce to re-execute (e.g., `code .. \"\\n// \" .. nonce`)\n- `.ui/mcp run` returns error messages\n"},"lastSynced":"2026-03-06T06:57:16.733Z","agentAnalysis":{"suitability":{"en":"Perfect for Lua-based AI Agents needing interactive UI capabilities with widget integration.","zh":"非常适合需要交互式 UI 功能和小部件集成的 Lua 基础 AI 代理。","ja":"Lua ベースの AI エージェントがインタラクティブな UI 機能とウィジェット統合を必要とする場合に最適です。","ko":"Lua 기반 AI 에이전트가 인터랙티브 UI 기능 및 위젯 통합을 필요로 할 때 완벽합니다.","es":"Perfecto para agentes de inteligencia artificial basados en Lua que necesitan capacidades de interfaz de usuario interactiva con integración de widgets.","fr":"Parfait pour les agents d''intelligence artificielle basés sur Lua nécessitant des capacités d''interface utilisateur interactive avec intégration de widgets.","de":"Perfekt für Lua-basierte KI-Agents, die interaktive Benutzeroberflächen mit Widget-Integration benötigen.","pt":"Perfeito para agentes de IA baseados em Lua que precisam de capacidades de UI interativas com integração de widgets.","ru":"Идеально подходит для агентов ИИ на основе Lua, которым необходимы интерактивные возможности UI с интеграцией виджетов.","ar":"مثالي لعمليات وكيل الذكاء الاصطناعي التي تعتمد على لوا وتحتاج إلى قدرات واجهة المستخدم التفاعلية مع دمج Widgets."},"recommendation":{"en":"Empowers agents to build and run UIs with Lua apps connected to widgets, supporting features like showing app-console and starting event loops with Playwright preference.","zh":"赋予代理构建和运行 UI 的能力，连接 Lua 应用程序到小部件，支持显示应用程序控制台和使用 Playwright 首选项启动事件循环等功能。","ja":"エージェントが Lua アプリケーションをウィジェットに接続して UI を構築および実行する機能を提供し、Playwright を使用したアプリケーション コンソールの表示やイベント ループの開始などの機能をサポートします。","ko":"에이전트가 Lua 애플리케이션을 위젯에 연결하여 UI를 구축하고 실행할 수 있는 기능을 제공하며, Playwright를 사용한 애플리케이션 콘솔 표시 및 이벤트 루프 시작 등과 같은 기능을 지원합니다.","es":"Permite a los agentes crear y ejecutar interfaces de usuario con aplicaciones Lua conectadas a widgets, que admiten funciones como mostrar la consola de la aplicación y iniciar bucles de eventos con preferencia de Playwright.","fr":"Permet aux agents de créer et d''exécuter des interfaces utilisateur avec des applications Lua connectées à des widgets, qui prennent en charge des fonctionnalités comme l''affichage de la console d''application et le démarrage de boucles d''événements avec la préférence Playwright.","de":"Ermöglicht es Agents, Benutzeroberflächen mit Lua-Anwendungen zu erstellen und auszuführen, die mit Widgets verbunden sind und Funktionen wie die Anzeige der Anwendungs-Konsole und das Starten von Ereignisschleifen mit Playwright-Präferenz unterstützen.","pt":"Habilita os agentes a construir e executar UIs com aplicativos Lua conectados a widgets, suportando recursos como exibir app-console e iniciar loops de eventos com preferência do Playwright.","ru":"Наделяет агентов возможностью создавать и запускать UI с приложениями Lua, подключенными к виджетам, поддерживая функции, такие как отображение app-console и запуск циклов событий с предпочтением Playwright.","ar":"يمنح الوكيل القدرة على بناء واجهات المستخدم وتشغيلها مع تطبيقات لوا متصلة بالويدجتس، مع دعم ميزات مثل عرض console التطبيق وبدء دورات الأحداث مع تفضيل Playwright."},"useCases":{"en":["Showing app-console with Quick Start","Starting event loops without display or browser","Building UI-engine UIs with Lua apps and widget integration"],"zh":["使用快速启动显示应用程序控制台","不显示或浏览器启动事件循环","使用 Lua 应用程序和小部件集成构建 UI 引擎 UI"],"ja":["Quick Start を使用してアプリケーション コンソールを表示する","表示またはブラウザなしでイベント ループを起動する","Lua アプリケーションとウィジェット統合を使用して UI エンジン UI を構築する"],"ko":["Quick Start를 사용하여 애플리케이션 콘솔 표시","표시 또는 브라우저 없이 이벤트 루프 시작","Lua 애플리케이션 및 위젯 통합을 사용하여 UI 엔진 UI 구축"],"es":["Mostrar la consola de la aplicación con Quick Start","Iniciar bucles de eventos sin pantalla o navegador","Crear interfaces de usuario de motor de interfaz de usuario con aplicaciones Lua y widget integration"],"fr":["Afficher la console d''application avec Quick Start","Démarrer des boucles d''événements sans affichage ou navigateur","Créer des interfaces utilisateur de moteur d''interface utilisateur avec des applications Lua et intégration de widgets"],"de":["Anzeigen der Anwendungs-Konsole mit Quick Start","Starten von Ereignisschleifen ohne Anzeige oder Browser","Erstellen von Benutzeroberflächen-Motoren mit Lua-Anwendungen und Widget-Integration"],"pt":["Exibir app-console com Início Rápido","Iniciar loops de eventos sem exibir ou navegador","Construir UIs do mecanismo UI com aplicativos Lua e integração de widgets"],"ru":["Отображать app-console с Быстрым Началом","Запускать циклы событий без отображения или браузера","Создавать UI-инженерию UI с приложениями Lua и интеграцией виджетов"],"ar":["عرض console التطبيق مع التشغيل السريع","بدء دورات الأحداث بدون عرض أو متصفح","بناء محركات واجهة المستخدم مع تطبيقات لوا ودمج الويدجتس"]},"limitations":{"en":["Requires Lua apps and widget integration","Preferentially uses Playwright if previously used"],"zh":["需要 Lua 应用程序和小部件集成","如果之前使用过则更喜欢使用 Playwright"],"ja":["Lua アプリケーションとウィジェット統合が必要","以前使用した場合は Playwright を優先的に使用"],"ko":["Lua 애플리케이션 및 위젯 통합 필요","이전에 사용한 경우 Playwright를 우선적으로 사용"],"es":["Requiere aplicaciones Lua y widget integration","Preferentemente utiliza Playwright si se ha utilizado anteriormente"],"fr":["Nécessite des applications Lua et une intégration de widgets","Utilise de préférence Playwright si elle a été utilisée précédemment"],"de":["Erfordert Lua-Anwendungen und Widget-Integration","Nutzt Playwright bevorzugt, wenn es zuvor verwendet wurde"],"pt":["Requer aplicativos Lua e integração de widgets","Preferencialmente usa Playwright se usado anteriormente"],"ru":["Требует приложений Lua и интеграции виджетов","Предпочтительно использует Playwright, если ранее использовался"],"ar":["يتطلب تطبيقات لوا ودمج الويدجتس","يفضل استخدام Playwright إذا تم استخدامه من قبل"]},"version":4},"contentHash":"182b0049834589f72bb98ddf4554c3b351885fe9361de0471ac92c67f5d8e6a2","qualityScore":39}');
