INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zot/frictionless/ui', 'ui', 'zot', 'frictionless', 'community', 'ui zot frictionless community The ui skill enables developers to build and run UIs with Lua apps connected to widgets. It supports features like showing app-console and starting event loops. UI 技术提供 Lua 应用和 Playwright 集成，实现动态 UI 更新和事件循环 UI 技術は Lua アプリケーションと Playwright 統合を提供し、ダイナミック UI 更新とイベントループを実現 UI 기술은 Lua 애플리케이션과 Playwright 통합을 제공하여 동적 UI 업데이트와 이벤트 루프를 구현 La habilidad UI permite la construcción y ejecución de aplicaciones con Lua y Playwright. Evoluciona tus aplicaciones mientras se ejecutan y comparte tus creaciones. La compétence UI permet la création et l''exécution d''applications avec Lua et Playwright. Faites évoluer vos applications pendant leur exécution et partagez vos créations. Die UI-Fähigkeit ermöglicht die Erstellung und Ausführung von Anwendungen mit Lua und Playwright. Entwickeln Sie Ihre Anwendungen während der Ausführung und teilen Sie Ihre Kreationen. A UI é uma fundação para construir e executar ui-engine UIs com aplicativos Lua conectados a widgets. Aprenda a utilizar o Playwright e o Quick Start. UI - это основа для построения и запуска ui-engine UI с подключенными к виджетам приложениями Lua. Узнайте, как использовать Playwright и Quick Start. واجهة المستخدم هي أساس لبناء وتشغيل ui-engine UI مع تطبيقات Lua متصلة بWidgets. تعلم كيفية استخدام Playwright و Quick Start. how to use ui ui setup guide ui alternative ui vs Playwright ui install what is ui ui lua apps ui widgets ui event loop ui development UI 技术 Lua 应用 Playwright 事件循环 动态 UI 更新 AIエージェント UI 引擎 Quick Start Shows app-console as in Quick Start using `/ui` command Preferably uses Playwright if the user has been using it Starts event loop when the user says `events` Supports showing specific apps with `show APP` command Utilizes Lua apps connected to widgets for UI development Allows evolving apps while they run ui is a foundation for building and running ui-engine UIs with Lua apps connected to widgets, utilizing technologies like Playwright.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('DNUM-SocialGouv/sirena/hono-js', 'community', 'DNUM-SocialGouv', 'sirena', 'DNUM-SocialGouv/sirena', 'hono-js', 4, 1, 39, '2026-03-04T16:43:59Z', '2026-03-06T06:59:16.509Z', '5fd8780d52b16b88ff957a8a624add72eadd710d1b4724ca1a10e402356d4d49', '{"id":"DNUM-SocialGouv/sirena/hono-js","name":"hono-js","description":{"en":"hono-js is a skill for adding or changing backend endpoints built with Hono, benefiting developers working with TypeScript and OpenAPI.","zh":"Hono.js 是一个后端开发框架，支持 OpenAPI 元数据声明和路由管理。它的项目结构包括特性、路由、控制器、服务、模式和类型等","ja":"Hono.js は、OpenAPI メタデータの宣言とルーティング管理をサポートするバックエンド開発フレームワークです。プロジェクト構造には、特性、ルーティング、コントローラ、サービス、スキーマ、タイプなどがあります","ko":"Hono.js는 OpenAPI 메타데이터 선언 및 라우팅 관리를 지원하는 백엔드 개발 프레임워크입니다. 프로젝트 구조에는 특성, 라우팅, 컨트롤러, 서비스, 스키마, 유형 등이 포함됩니다","es":"Hono.js es un framework para crear endpoints de backend con OpenAPI. Ofrece una estructura de proyecto y rutas predefinidas","fr":"Hono.js est un framework pour créer des points de terminaison de backend avec OpenAPI. Il propose une structure de projet et des routes prédéfinies","de":"Hono.js ist ein Framework zum Erstellen von Backend-Endpunkten mit OpenAPI. Es bietet eine Projektstruktur und vordefinierte Routen","pt":"O Hono.js é uma ferramenta para desenvolvedores que visa simplificar a criação de endpoints de backend. Com ele, você pode criar rotas, controladores e serviços de forma eficiente.","ru":"Hono.js - это инструмент для разработчиков, который упрощает создание бэкенд-конечных точек. С его помощью вы можете создавать маршруты, контроллеры и сервисы эффективно с помощью ИИ Агентов.","ar":"Hono.js هو أداة لمطوري البرامج التي تهدف إلى تبسيط إنشاء نهايات الخلفية. معها، يمكنك إنشاء مسارات ومراقبة والخدمات بفعالية على منصة الإي أجنٹ"},"seo":{"title":{"en":"hono-js: Setup Guide for AI Agents","zh":"Hono.js 后端开发最佳实践","ja":"Hono.js を使用したバックエンド開発ガイド","ko":"Hono.js 백엔드 개발 설정 가이드","es":"Guía de configuración de Hono.js para desarrolladores","fr":"Guide de mise en route de Hono.js pour les développeurs","de":"Einrichtungsleitfaden für Hono.js-Entwickler","pt":"Guia de Configuração do Hono.js para Desenvolvedores","ru":"Настройка Hono.js: Руководство для Разработчиков ИИ Агентов","ar":"دليل إعداد Hono.js لمنصة الإي أجنٹ"},"description":{"en":"Discover how to leverage hono-js for building backend endpoints with OpenAPI metadata and TypeScript, get started now!","zh":"了解 Hono.js 的项目结构、路由和 OpenAPI 元数据声明，提高您的后端开发效率","ja":"Hono.js のプロジェクト構造、ルーティング、OpenAPI メタデータの宣言について学び、バックエンド開発の効率を上げましょう","ko":"Hono.js 프로젝트 구조, 라우팅, OpenAPI 메타데이터 선언에 대해 알아보고 백엔드 개발 효율을 높이세요","es":"Aprende a utilizar Hono.js para crear endpoints de backend escalables y seguros con OpenAPI","fr":"Découvrez comment utiliser Hono.js pour créer des points de terminaison de backend évolutifs et sécurisés avec OpenAPI","de":"Erfahren Sie, wie Sie Hono.js verwenden, um skalierbare und sichere Backend-Endpunkte mit OpenAPI zu erstellen","pt":"Aprenda a configurar o Hono.js para desenvolver endpoints de backend com eficiência. Descubra as melhores práticas e recursos para otimizar seu workflow.","ru":"Узнайте, как настроить Hono.js для разработки бэкенд-конечных точек с помощью ИИ Агентов. Откройте для себя лучшие практики и инструменты для оптимизации ваш...","ar":"تعلم كيفية إعداد Hono.js لتطوير نهايات الخلفية بفعالية. اكتشف أفضل الممارسات والموارد لتحسين تدفق العمل الخاص بك على منصة الإي أجنٹ"},"definition":{"en":"hono-js is a JavaScript framework for building backend endpoints with a structured project layout and OpenAPI support.","zh":"Hono.js 是一个用于构建后端 API 的 JavaScript 框架","ja":"Hono.js は、バックエンド API を構築するための JavaScript フレームワークです","ko":"Hono.js는 백엔드 API를 구축하기 위한 JavaScript 프레임워크입니다","es":"Hono.js es un framework de JavaScript para crear endpoints de backend con OpenAPI","fr":"Hono.js est un framework JavaScript pour créer des points de terminaison de backend avec OpenAPI","de":"Hono.js ist ein JavaScript-Framework zum Erstellen von Backend-Endpunkten mit OpenAPI","pt":"Hono.js é uma biblioteca JavaScript para criar endpoints de backend com OpenAPI.","ru":"Hono.js - это библиотека JavaScript для создания бэкенд-конечных точек с OpenAPI и ИИ Агентами.","ar":"Hono.js هو مكتبة جافاسكريبت لإنشاء نهايات الخلفية مع OpenAPI على منصة الإي أجنٹ"},"features":{"en":["Declares OpenAPI metadata in route files using TypeScript","Utilizes helpers from @sirena/backend-utils/helpers for efficient development","Follows a structured project layout with feature-based organization","Supports common file types such as route, controller, service, schema, type, and test","Integrates with OpenAPI for standardized API documentation"],"zh":["支持 OpenAPI 元数据声明","路由管理和声明","特性、控制器、服务、模式和类型等项目结构","使用 @sirena/backend-utils/helpers 中的帮助函数","支持 TypeScript 语言"],"ja":["OpenAPI メタデータの宣言をサポート","ルーティング管理と宣言","特性、コントローラ、サービス、スキーマ、タイプなどプロジェクト構造","@sirena/backend-utils/helpers 内のヘルパー関数を使用","TypeScript 言語をサポート"],"ko":["OpenAPI 메타데이터 선언 지원","라우팅 관리 및 선언","특성, 컨트롤러, 서비스, 스키마, 유형 등 프로젝트 구조","@sirena/backend-utils/helpers 내의 헬퍼 함수 사용","TypeScript 언어 지원"],"es":["Estructura de proyecto predefinida con carpetas y archivos de características","Declaración de metadatos de OpenAPI en archivos de rutas","Uso de helpers de @sirena/backend-utils/helpers para simplificar el código","Soporte para tipos de archivos como route, controller, service, schema, type y test","Integración con OpenAPI para documentación y validación de APIs"],"fr":["Structure de projet prédéfinie avec des dossiers et des fichiers de fonctionnalités","Déclaration de métadonnées OpenAPI dans les fichiers de routes","Utilisation d''helpers de @sirena/backend-utils/helpers pour simplifier le code","Prise en charge de types de fichiers tels que route, controller, service, schema, type et test","Intégration avec OpenAPI pour la documentation et la validation des API"],"de":["Vordefinierte Projektstruktur mit Ordnern und Dateien für Funktionen","Deklaration von OpenAPI-Metadaten in Routendateien","Verwendung von Helpers von @sirena/backend-utils/helpers zur Vereinfachung des Codes","Unterstützung für Dateitypen wie Route, Controller, Service, Schema, Type und Test","Integration mit OpenAPI für Dokumentation und Validierung von APIs"],"pt":["Criação de rotas com OpenAPI","Declaração de metadados de resposta","Uso de helpers do @sirena/backend-utils/helpers","Organização de arquivos em pastas de recursos","Suporte a tipos de arquivos como route, controller, service e schema"],"ru":["Создание маршрутов с OpenAPI и ИИ Агентами","Декларация метаданных ответа","Использование хелперов из @sirena/backend-utils/helpers","Организация файлов в папках ресурсов","Поддержка типов файлов, таких как route, controller, service и schema"],"ar":["إنشاء مسارات مع OpenAPI على منصة الإي أجنٹ","إعلان بيانات وصف الرد","استخدام مساعدين من @sirena/backend-utils/helpers","تنظيم الملفات في مجلدات الموارد","دعم أنواع الملفات مثل route و controller و service و schema"]},"keywords":{"en":["how to use hono-js","hono-js setup guide","hono-js alternative","hono-js vs express","hono-js install","what is hono-js","hono-js OpenAPI support","hono-js TypeScript integration"],"zh":["Hono.js","后端开发","OpenAPI","路由管理","TypeScript","JavaScript 框架","API 构建","后端 API"],"ja":["Hono.js","バックエンド開発","OpenAPI","ルーティング管理","TypeScript","JavaScript フレームワーク","API 構築","バックエンド API"],"ko":["Hono.js","백엔드 개발","OpenAPI","라우팅 관리","TypeScript","JavaScript 프레임워크","API 구축","백엔드 API"],"es":["Hono.js","OpenAPI","endpoints de backend","desarrollo de backend","framework de JavaScript","estructura de proyecto","rutas de API","documentación de API","validación de API"],"fr":["Hono.js","OpenAPI","points de terminaison de backend","développement de backend","framework JavaScript","structure de projet","routes d''API","documentation d''API","validation d''API"],"de":["Hono.js","OpenAPI","Backend-Endpunkte","Backend-Entwicklung","JavaScript-Framework","Projektstruktur","API-Routen","API-Dokumentation","API-Validierung"],"pt":["hono js","desenvolvimento de backend","openapi","rotas de api","bibliotecas javascript","desenvolvedores de software","ferramentas de desenvolvimento","otimização de workflow"],"ru":["hono js","разработка бэкенда","openapi","маршруты api","библиотеки javascript","разработчики программного обеспечения","инструменты разработки","оптимизация рабочего процесса","ИИ Агенты"],"ar":["hono js","تطوير الخلفية","openapi","مسارات api","مكتبات جافاسكريبت","مطورو البرامج","أدوات التطوير","تحسين تدفق العمل","منصة الإي أجنٹ"]}},"owner":"DNUM-SocialGouv","repo":"sirena","repoPath":"DNUM-SocialGouv/sirena","stars":4,"forks":1,"updatedAt":"2026-03-04T16:43:59Z","topics":[],"category":"community","skillMd":{"name":"hono-js","description":"Hono API patterns for DNUM-SocialGouv (routes/controllers/services/schemas/types/tests, openapi helpers, zValidator, prisma). Trigger on hono, route, controller, service, schema, openapi.","bodyPreview":"# Hono.js (DNUM-SocialGouv)\n\nUse this skill when adding or changing backend endpoints built with Hono in this repo.\n\n## Project Structure\n\n- Features live in `apps/backend/src/features/<feature-name>/`\n- Files are named `<feature-name>.<file-type>.ts`\n- Common file types: `route`, `controller`, `service`, `schema`, `type`, `test`\n\n## Routes (OpenAPI)\n\n- Route files only declare OpenAPI metadata (responses), not params.\n- Use helpers from `@sirena/backend-utils/helpers`.\n\nExample:\n\n```ts\nexport c","body":"# Hono.js (DNUM-SocialGouv)\n\nUse this skill when adding or changing backend endpoints built with Hono in this repo.\n\n## Project Structure\n\n- Features live in `apps/backend/src/features/<feature-name>/`\n- Files are named `<feature-name>.<file-type>.ts`\n- Common file types: `route`, `controller`, `service`, `schema`, `type`, `test`\n\n## Routes (OpenAPI)\n\n- Route files only declare OpenAPI metadata (responses), not params.\n- Use helpers from `@sirena/backend-utils/helpers`.\n\nExample:\n\n```ts\nexport const getUserRoute = openApiProtectedRoute({\n  description: ''Get user by id'',\n  responses: {\n    ...openApiResponse(GetUserResponseSchema),\n    ...openApi404NotFound(''User not found''),\n  },\n});\n```\n\n## Schemas\n\n- Define request/response schemas (params, query, body, response).\n- Use `paginationQueryParamsSchema` for `search/limit/offset/order`.\n\nExample:\n\n```ts\nexport const UserSchema = z.object({\n  id: z.cuid(),\n  email: z.email({ message: ''Invalid email address'' }),\n  prenom: z.string(),\n  nom: z.string(),\n  uid: z.string(),\n  sub: z.string(),\n  pcData: z.record(z.string(), z.string()),\n  roleId: z.string(),\n  statutId: z.string(),\n  entiteId: z.string().nullable(),\n  createdAt: z.coerce.date(),\n  updatedAt: z.coerce.date(),\n});\n\nconst columns = [\n  Prisma.UserScalarFieldEnum.email,\n  Prisma.UserScalarFieldEnum.prenom,\n  Prisma.UserScalarFieldEnum.nom,\n] as const;\n\nexport const GetUsersQuerySchema = paginationQueryParamsSchema(columns).extend({\n  roleId: z\n    .string()\n    .transform((val) => val.split('','').map((id) => id.trim()))\n    .optional(),\n  statutId: z\n    .string()\n    .transform((val) => val.split('','').map((id) => id.trim()))\n    .optional(),\n});\n```\n\n## Types\n\n- Prefer `z.infer` from schemas.\n\nExample:\n\n```ts\nexport type GetUsersQuery = z.infer<typeof GetUsersQuerySchema>;\n```\n\n## Controllers\n\n- Build controllers from `factoryWithLogs.createApp()` for typed context.\n- Chain middleware and routes in order.\n- Use `zValidator` for query/body validation.\n- Return `c.json({ data: ... }, status)`.\n\n### Common Middleware\n\n- `authMiddleware` (auth cookie/session)\n- `userStatusMiddleware` (active user checks)\n- `roleMiddleware([ROLES...])` (RBAC guard)\n- `entitesMiddleware` (entite context)\n- `pino.middleware` (logging)\n- `sentry.middleware` (error context)\n- `upload.middleware` (multipart handling)\n- `logout.middleware`\n- `changelog/*` (entity change tracking)\n\nExample:\n\n```ts\nconst app = factoryWithLogs\n  .createApp()\n  .use(authMiddleware)\n  .use(userStatusMiddleware)\n  .use(roleMiddleware([ROLES.SUPER_ADMIN, ROLES.ENTITY_ADMIN]))\n  .use(entitesMiddleware)\n  .get(''/:id'', getUsersRoute, zValidator(''query'', GetUsersQuerySchema), async (c) => {\n    // ...\n    return c.json({ data: users }, 200);\n  })\n  .get(''/:id'', getUserRoute, async (c) => {\n    // ...\n    return c.json({ data: user }, 200);\n  });\n```\n\n## Services\n\n- Prisma calls live in `service` files.\n- Keep logic small and composable.\n\nExample:\n\n```ts\nexport const getUsers = async (entiteIds: string[] | null, query: GetUsersQuery = {}) => {\n  const { offset = 0, limit, sort = ''nom'', order = ''asc'', roleId, statutId, search } = query;\n\n  const entiteFilter = filterByEntities(entiteIds);\n  const roleFilter = filterByRoles(roleId ?? null);\n\n  const searchConditions: Prisma.UserWhereInput[] | undefined = search?.trim()\n    ? [\n        { prenom: { contains: search, mode: ''insensitive'' } },\n        { nom: { contains: search, mode: ''insensitive'' } },\n        { email: { contains: search, mode: ''insensitive'' } },\n      ]\n    : undefined;\n\n  const where: Prisma.UserWhereInput = {\n    ...(entiteFilter ?? {}),\n    ...(roleFilter ?? {}),\n    ...(statutId !== undefined ? { statutId: { in: statutId } } : {}),\n    ...(searchConditions ? { OR: searchConditions } : {}),\n  };\n\n  const [data, total] = await Promise.all([\n    prisma.user.findMany({\n      where,\n      skip: offset,\n      ...(typeof limit === ''number'' ? { take: limit } : {}),\n      orderBy: { [sort]: order },\n      include: { role: true },\n    }),\n    prisma.user.count({ where }),\n  ]);\n\n  return { data, total };\n};\n```\n\n## Tests\n\n### Controller Tests (Hono)\n\n- Prefer controller tests for endpoint behavior.\n- Use `testClient` from `hono/testing`.\n- Build app with `appWithLogs.createApp().use(pinoLogger()).route(''/'', Controller).onError(errorHandler)`.\n- Use `client.index.$get()` or `client['':id''].$get()` with `query`/`param`/`json`.\n- Keep test data minimal and focus on response status + body.\n- Always cover success payload + at least one error case, with services mocked.\n\nExample:\n\n```ts\ndescribe(''Users endpoints: /users'', () => {\n  const app = appWithLogs.createApp().use(pinoLogger()).route(''/'', UsersController).onError(errorHandler);\n  const client = testClient(app);\n\n  describe(''GET /'', () => {\n    it(''returns filtered users'', async () => {\n      const res = await client.index.$get({\n        query: { roleId: ROLES.NATIONAL_STEERING, statutId: ''ACTIF'' },\n      });\n      // assert status + payload\n    });\n    it(''returns 404 when user not found'', async () => {\n      // mock service to return null, assert 404 payload\n    });\n  });\n});\n```\n\nReference: `apps/backend/src/features/users/users.controller.test.ts`.\n"},"lastSynced":"2026-03-06T06:59:16.509Z","agentAnalysis":{"suitability":{"en":"Perfect for TypeScript Agents needing streamlined backend endpoint management with Hono and OpenAPI","zh":"适合需要使用 Hono 和 OpenAPI 进行流线化后端端点管理的 TypeScript Agents","ja":"Hono と OpenAPI を使用した後端エンドポイント管理を簡素化する必要がある TypeScript エージェントに最適","ko":"Hono와 OpenAPI를 사용하여 백엔드 엔드ポイント 관리를 간소화해야 하는 TypeScript 에이전트에 적합","es":"Perfecto para agentes de TypeScript que necesitan una gestión de puntos de conexión de backend optimizada con Hono y OpenAPI","fr":"Parfait pour les agents TypeScript nécessitant une gestion de points de terminaison de backend rationalisée avec Hono et OpenAPI","de":"Perfekt für TypeScript-Agents, die eine optimierte Verwaltung von Backend-Endpunkten mit Hono und OpenAPI benötigen","pt":"Perfeito para Agentes TypeScript que necessitam de gerenciamento de endpoint de backend simplificado com Hono e OpenAPI","ru":"Идеально подходит для агентов TypeScript, которым необходим упрощенный менеджмент конечных точек бэкенда с помощью Hono и OpenAPI","ar":"مثالي لعميل TypeScript الذي يحتاج إلى إدارة نهاية بيك اند تيستريمة مع Hono و OpenAPI"},"recommendation":{"en":"Empowers agents to declaratively define OpenAPI metadata and implement robust endpoint logic using Hono, leveraging TypeScript for scalable and maintainable backend development with libraries like @sirena/backend-utils/helpers","zh":"赋予代理声明性地定义 OpenAPI 元数据，并使用 Hono 实现强大的端点逻辑，利用 TypeScript 进行可扩展和可维护的后端开发，借助类似 @sirena/backend-utils/helpers 的库","ja":"エージェントに OpenAPI メタデータを宣言的に定義し、Hono を使用して強力なエンドポイント ロジックを実装することを可能にし、TypeScript を使用してスケーラブルでメンテナンス可能なバックエンド開発を実現する、@sirena/backend-utils/helpers などのライブラリを利用","ko":"에이전트가 OpenAPI 메타데이터를 선언적으로 정의하고 Hono를 사용하여 강력한 엔드ポイント 로직을 구현할 수 있도록 하며, TypeScript를 사용하여 확장 가능하고 유지 보수 가능한 백엔드 개발을 가능하게 함, @sirena/backend-utils/helpers와 같은 라이브러리를 활용","es":"Habilita a los agentes a definir declarativamente metadatos de OpenAPI e implementar una lógica de punto de conexión robusta utilizando Hono, aprovechando TypeScript para un desarrollo de backend escalable y mantenible con bibliotecas como @sirena/backend-utils/helpers","fr":"Permet aux agents de définir déclarativement des métadonnées OpenAPI et de mettre en œuvre une logique de point de terminaison robuste en utilisant Hono, en exploitant TypeScript pour un développement de backend évolutif et maintenable avec des bibliothèques comme @sirena/backend-utils/helpers","de":"Ermöglicht es den Agents, OpenAPI-Metadaten deklarativ zu definieren und eine robuste Endpunklogik mit Hono umzusetzen, indem TypeScript für eine skalierbare und wartbare Backend-Entwicklung mit Bibliotheken wie @sirena/backend-utils/helpers genutzt wird","pt":"Habilita os agentes a definir declarativamente metadados OpenAPI e implementar lógica de endpoint robusta usando Hono, aproveitando o TypeScript para desenvolvimento de backend escalável e mantenedor com bibliotecas como @sirena/backend-utils/helpers","ru":"Позволяет агентам декларативно определять метаданные OpenAPI и реализовывать прочную логику конечных точек с помощью Hono, используя TypeScript для масштабируемого и поддерживаемого разработки бэкенда с библиотеками như @sirena/backend-utils/helpers","ar":"تمكن العملاء من تعريف البيانات الوصفية OpenAPI اعلانًا وتنفيذ منطق نهاية نقطة متين باستخدام Hono، مستفيدًا من TypeScript لتطوير الخلفية القابل للتمديد والصيانة باستخدام المكتبات مثل @sirena/backend-utils/helpers"},"useCases":{"en":["Automating backend endpoint generation with OpenAPI definitions","Implementing feature-specific routing and controller logic with Hono","Streamlining backend development with TypeScript and OpenAPI-based schema validation"],"zh":["使用 OpenAPI 定义自动化后端端点生成","使用 Hono 实现特性特定的路由和控制器逻辑","使用 TypeScript 和 OpenAPI 基础的 schema 验证简化后端开发"],"ja":["OpenAPI 定義を使用したバックエンドエンドポイントの自動生成","Hono を使用した特性特有的ルーティングとコントローラーロジックの実装","TypeScript と OpenAPI ベースのスキーマ検証を使用したバックエンド開発の簡素化"],"ko":["OpenAPI 정의를 사용하여 백엔드 엔드ポイント 자동 생성","Hono를 사용하여 특성별 라우팅 및 컨트롤러 논리를 구현","TypeScript 및 OpenAPI 기반 스키마 검증을 사용하여 백엔드 개발 간소화"],"es":["Automatizar la generación de puntos de conexión de backend con definiciones de OpenAPI","Implementar lógica de enrutamiento y controlador específica de características con Hono","Optimizar el desarrollo de backend con TypeScript y validación de esquemas basada en OpenAPI"],"fr":["Automatiser la génération de points de terminaison de backend avec des définitions OpenAPI","Mettre en œuvre une logique de routage et de contrôleur spécifique aux fonctionnalités avec Hono","Rationaliser le développement de backend avec TypeScript et une validation de schémas basée sur OpenAPI"],"de":["Automatisieren der Generierung von Backend-Endpunkten mit OpenAPI-Definitionen","Implementieren von featurespezifischer Routing- und Controller-Logik mit Hono","Optimieren der Backend-Entwicklung mit TypeScript und OpenAPI-basierter Schema-Validierung"],"pt":["Automatizar a geração de endpoint de backend com definições OpenAPI","Implementar lógica de roteamento e controlador específica de recurso com Hono","Simplificar o desenvolvimento de backend com TypeScript e validação de esquema baseada em OpenAPI"],"ru":["Автоматизировать генерацию конечных точек бэкенда с помощью определений OpenAPI","Реализовать логико маршрутизации и контроллера, специфичную для функции, с помощью Hono","Упростить разработку бэкенда с помощью TypeScript и валидации схемы на основе OpenAPI"],"ar":["توفير автомة توليد نهاية بيك اند مع تعريفات OpenAPI","تنفيذ منطق التوجيه والمراقبة المحدد للموارد مع Hono","تسهيل تطوير الخلفية مع TypeScript وتصديق مخطط قائم على OpenAPI"]},"limitations":{"en":["Requires Hono and OpenAPI setup","TypeScript environment necessary","Specific project structure required (e.g., apps/backend/src/features/<feature-name>/)"],"zh":["需要 Hono 和 OpenAPI 设置","需要 TypeScript 环境","需要特定的项目结构（例如，apps/backend/src/features/<feature-name>/）"],"ja":["Hono と OpenAPI の設定が必要","TypeScript 環境が必要","特定のプロジェクト構造（例：apps/backend/src/features/<feature-name>/）が必要"],"ko":["Hono 및 OpenAPI 설정 필요","TypeScript 환경 필요","특정 프로젝트 구조 필요(예: apps/backend/src/features/<feature-name>/)"],"es":["Requiere configuración de Hono y OpenAPI","Entorno de TypeScript necesario","Estructura de proyecto específica requerida (por ejemplo, apps/backend/src/features/<nombre_de_característica>/)"],"fr":["Nécessite une configuration de Hono et OpenAPI","Environnement TypeScript nécessaire","Structure de projet spécifique requise (par exemple, apps/backend/src/features/<nom_de_fonctionnalité>/)"],"de":["Benötigt Hono- und OpenAPI-Setup","TypeScript-Umgebung erforderlich","Spezifische Projektstruktur erforderlich (z. B. apps/backend/src/features/<funktionsname>/)"],"pt":["Requer configuração do Hono e OpenAPI","Ambiente TypeScript necessário","Estrutura de projeto específica necessária (por exemplo, apps/backend/src/features/<nome-da-funcionalidade>/)"],"ru":["Требуется настройка Hono и OpenAPI","Необходимо окружение TypeScript","Требуется определенная структура проекта (например, apps/backend/src/features/<имя-функции>/)"],"ar":["يتطلب إعداد Hono و OpenAPI","بيئة TypeScript ضرورية","هيكل مشروع محدد مطلوب (على سبيل المثال، apps/backend/src/features/<اسم-الوظيفة>/)"]},"version":4},"contentHash":"5fd8780d52b16b88ff957a8a624add72eadd710d1b4724ca1a10e402356d4d49","qualityScore":39}');
