INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('DNUM-SocialGouv/sirena/hono-js', 'hono-js', 'DNUM-SocialGouv', 'sirena', 'community', 'hono-js DNUM-SocialGouv sirena community hono-js is a skill for adding or changing backend endpoints built with Hono, benefiting developers working with TypeScript and OpenAPI. Hono.js 是一个后端开发框架，支持 OpenAPI 元数据声明和路由管理。它的项目结构包括特性、路由、控制器、服务、模式和类型等 Hono.js は、OpenAPI メタデータの宣言とルーティング管理をサポートするバックエンド開発フレームワークです。プロジェクト構造には、特性、ルーティング、コントローラ、サービス、スキーマ、タイプなどがあります Hono.js는 OpenAPI 메타데이터 선언 및 라우팅 관리를 지원하는 백엔드 개발 프레임워크입니다. 프로젝트 구조에는 특성, 라우팅, 컨트롤러, 서비스, 스키마, 유형 등이 포함됩니다 Hono.js es un framework para crear endpoints de backend con OpenAPI. Ofrece una estructura de proyecto y rutas predefinidas Hono.js est un framework pour créer des points de terminaison de backend avec OpenAPI. Il propose une structure de projet et des routes prédéfinies Hono.js ist ein Framework zum Erstellen von Backend-Endpunkten mit OpenAPI. Es bietet eine Projektstruktur und vordefinierte Routen O Hono.js é uma ferramenta para desenvolvedores que visa simplificar a criação de endpoints de backend. Com ele, você pode criar rotas, controladores e serviços de forma eficiente. Hono.js - это инструмент для разработчиков, который упрощает создание бэкенд-конечных точек. С его помощью вы можете создавать маршруты, контроллеры и сервисы эффективно с помощью ИИ Агентов. Hono.js هو أداة لمطوري البرامج التي تهدف إلى تبسيط إنشاء نهايات الخلفية. معها، يمكنك إنشاء مسارات ومراقبة والخدمات بفعالية على منصة الإي أجنٹ how to use hono-js hono-js setup guide hono-js alternative hono-js vs express hono-js install what is hono-js hono-js OpenAPI support hono-js TypeScript integration Hono.js 后端开发 OpenAPI 路由管理 TypeScript JavaScript 框架 API 构建 后端 API Declares OpenAPI metadata in route files using TypeScript Utilizes helpers from @sirena/backend-utils/helpers for efficient development Follows a structured project layout with feature-based organization Supports common file types such as route, controller, service, schema, type, and test Integrates with OpenAPI for standardized API documentation hono-js is a JavaScript framework for building backend endpoints with a structured project layout and OpenAPI support.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('plaenen/webx/migrate-component', 'community', 'plaenen', 'webx', 'plaenen/webx', 'migrate-component', 2, 0, 39, '2026-02-24T18:38:48Z', '2026-03-06T07:05:06.227Z', 'c6e7bbf82a74d1a7a6e84d34f3c767dcc8c4004a5565f8e0c9de1435f691ab77', '{"id":"plaenen/webx/migrate-component","name":"migrate-component","description":{"en":"The migrate-component skill migrates DaisyUI components into WebX templ components, following a detailed migration guide. It benefits developers working with WebX and DaisyUI.","zh":"migrate-component技能可以帮助您将DaisyUI组件迁移到WebX，支持CSS-only和交互式组件","ja":"migrate-componentスキルは、DaisyUIコンポーネントをWebXへ移行するのに役立ちます","ko":"migrate-component 기능은 DaisyUI 컴포넌트를 WebX로 마이그레이션하는 데 도움이 됩니다","es":"Migra componentes de DaisyUI a WebX con nuestra guía. Aprende a adaptar la estructura HTML, CSS y la interactividad.","fr":"Migrez des composants DaisyUI vers WebX avec notre guide. Apprenez à adapter la structure HTML, CSS et l''interactivité.","de":"Migrieren Sie DaisyUI-Komponenten zu WebX mit unserem Leitfaden. Erfahren Sie, wie Sie die HTML-Struktur, CSS und Interaktivität anpassen.","pt":"Migre componentes DaisyUI para WebX templ seguindo nosso guia de migração","ru":"Мигрируйте компоненты DaisyUI в WebX templ, следуя нашему руководству","ar":"انقل مكونات DaisyUI إلى WebX templ باتباع دليلنا"},"seo":{"title":{"en":"migrate-component: WebX Templating Setup Guide | AI Agent...","zh":"migrate-component Setup Guide: 将DaisyUI组件迁移到WebX","ja":"migrate-component セットアップガイド: DaisyUIコンポーネントをWebXへ移行","ko":"migrate-component 설정 가이드: DaisyUI 컴포넌트를 WebX로 마이그레이션","es":"Guía de migración de componentes de DaisyUI a WebX","fr":"Guide de migration de composants DaisyUI vers WebX","de":"Leitfaden zur Migration von DaisyUI-Komponenten zu WebX","pt":"Guia de Migração de Componentes para WebX","ru":"ИИ Агенты: Миграция Компонентов в WebX","ar":"أداة الذكاء الاصطناعي: إرشادات移植 المكونات إلى WebX"},"description":{"en":"Discover how to seamlessly migrate DaisyUI components to WebX templ components with our expert guide. Learn the steps and best practices now!","zh":"了解如何使用migrate-component技能将DaisyUI组件迁移到WebX，包括迁移步骤和最佳实践","ja":"migrate-componentスキルを使用してDaisyUIコンポーネントをWebXへ移行する方法を学びます","ko":"migrate-component 기능을 사용하여 DaisyUI 컴포넌트를 WebX로 마이그레이션하는 방법을 알아보세요","es":"Aprende a migrar componentes de DaisyUI a WebX con nuestra guía paso a paso. Descubre cómo adaptar tus componentes a la nueva plataforma.","fr":"Découvrez comment migrer les composants DaisyUI vers WebX avec notre guide étape par étape. Apprenez à adapter vos composants à la nouvelle plateforme.","de":"Erfahren Sie, wie Sie DaisyUI-Komponenten zu WebX migrieren, mit unserem Schritt-für-Schritt-Leitfaden. Entdecken Sie, wie Sie Ihre Komponenten an die neue P...","pt":"Aprenda a migrar componentes DaisyUI para WebX templ com nosso guia passo a passo","ru":"Мигрируйте компоненты DaisyUI в WebX templ с помощью нашего пошагового руководства","ar":"تعلم كيفية نقل مكونات DaisyUI إلى WebX templ باستخدام دليلنا المتواصل"},"definition":{"en":"migrate-component is a skill that enables the migration of DaisyUI components into WebX templ components, utilizing a step-by-step guide.","zh":"migrate-component是将DaisyUI组件迁移到WebX的技能","ja":"migrate-componentは、DaisyUIコンポーネントをWebXへ移行するスキルです","ko":"migrate-component는 DaisyUI 컴포넌트를 WebX로 마이그레이션하는 기능입니다","es":"La migración de componentes es el proceso de adaptar elementos de DaisyUI a WebX","fr":"La migration de composants est le processus d''adaptation d''éléments DaisyUI à WebX","de":"Die Migration von Komponenten ist der Prozess der Anpassung von DaisyUI-Elementen an WebX","pt":"Migração de componente é o processo de transferir componentes DaisyUI para WebX templ","ru":"Миграция компонентов - это процесс передачи компонентов DaisyUI в WebX templ","ar":"نقل المكونات هو عملية نقل مكونات DaisyUI إلى WebX templ"},"features":{"en":["Migrates DaisyUI components to WebX templ components","Follows a detailed migration guide at docs/component-migration-guide.md","Determines component tier based on CSS usage and interactivity","Supports lookup of component HTML structure and CSS classes on https://daisyui.com/components/","Handles hidden input and details elements for interactivity"],"zh":["支持DaisyUI组件到WebX的迁移","包括CSS-only和交互式组件的支持","遵循docs/component-migration-guide.md指南","自动识别组件的HTML结构和CSS类","支持Tier 1（CSS-only）和Tier 2（交互式）组件"],"ja":["DaisyUIコンポーネントをWebXへ移行するサポート","CSS-onlyとインタラクティブコンポーネントのサポート","docs/component-migration-guide.mdガイドに従う","コンポーネントのHTML構造とCSSクラスを自動で識別","Tier 1（CSS-only）とTier 2（インタラクティブ）コンポーネントのサポート"],"ko":["DaisyUI 컴포넌트를 WebX로 마이그레이션하는 지원","CSS-only와 인터랙티브 컴포넌트의 지원","docs/component-migration-guide.md 가이드에 따름","컴포넌트의 HTML 구조와 CSS 클래스를 자동으로 식별","Tier 1（CSS-only）와 Tier 2（인터랙티브）컴포넌트의 지원"],"es":["Migración de estructura HTML de componentes DaisyUI","Adaptación de CSS y clases de componentes","Implementación de interactividad con hidden input o detalles","Determinación del nivel de complejidad del componente (Tier 1 o superior)","Seguimiento de la guía de migración de componentes en docs/component-migration-guide.md"],"fr":["Migration de la structure HTML des composants DaisyUI","Adaptation du CSS et des classes de composants","Implémentation de l''interactivité avec hidden input ou détails","Détermination du niveau de complexité du composant (Tier 1 ou supérieur)","Suivi de la guide de migration de composants dans docs/component-migration-guide.md"],"de":["Migration der HTML-Struktur von DaisyUI-Komponenten","Anpassung von CSS und Klassen von Komponenten","Implementierung von Interaktivität mit hidden input oder Details","Bestimmung des Komplexitätsgrades des Komponenten (Tier 1 oder höher)","Befolgen der Migration-Anleitung in docs/component-migration-guide.md"],"pt":["Suporte à migração de componentes DaisyUI para WebX templ","Seguimento do guia de migração em docs/component-migration-guide.md","Análise da estrutura HTML e CSS dos componentes","Determinação do tier de migração (Tier 1 - CSS-only)","Suporte à interatividade com hidden input (checkbox/radio) ou <details>","Integração com a documentação oficial de DaisyUI"],"ru":["Поддержка миграции компонентов DaisyUI в WebX templ","Следование руководству по миграции в docs/component-migration-guide.md","Анализ структуры HTML и CSS компонентов","Определение уровня миграции (Tier 1 - CSS-only)","Поддержка интерактивности с hidden input (checkbox/radio) или <details>","Интеграция с официальной документацией DaisyUI"],"ar":["دعم نقل مكونات DaisyUI إلى WebX templ","اتباع دليل النقل في docs/component-migration-guide.md","تحليل هيكل HTML و CSS للمكونات","تحديد مستوى النقل (Tier 1 - CSS-only)","دعم التفاعل مع الإدخال المخفي (checkbox/radio) أو <details>","التكامل مع الوثائق الرسمية ل DaisyUI"]},"keywords":{"en":["how to use migrate-component","migrate-component setup guide","migrate-component vs WebX","DaisyUI to WebX migration","migrate-component install","WebX templating best practices"],"zh":["migrate-component","DaisyUI组件迁移","WebX","CSS-only","交互式组件","AIエージェント","组件迁移指南"],"ja":["migrate-component","DaisyUIコンポーネント移行","WebX","CSS-only","インタラクティブコンポーネント","AIエージェント","コンポーネント移行ガイド"],"ko":["migrate-component","DaisyUI 컴포넌트 마이그레이션","WebX","CSS-only","인터랙티브 컴포넌트","AI 에이전트","컴포넌트 마이그레이션 가이드"],"es":["migración de componentes","DaisyUI a WebX","guía de migración","estructura HTML","CSS","interactividad","hidden input","detalles","Tier 1"],"fr":["migration de composants","DaisyUI vers WebX","guide de migration","structure HTML","CSS","interactivité","hidden input","détails","Tier 1"],"de":["Migration von Komponenten","DaisyUI zu WebX","Migration-Anleitung","HTML-Struktur","CSS","Interaktivität","hidden input","Details","Tier 1"],"pt":["migração de componentes","DaisyUI","WebX templ","guia de migração","componentes React","desenvolvimento web","migração de código","otimização de componente","desenvolvedores web"],"ru":["миграция компонентов","DaisyUI","WebX templ","руководство по миграции","компоненты React","веб-разработка","миграция кода","оптимизация компонентов","веб-разработчики"],"ar":["نقل المكونات","DaisyUI","WebX templ","دليل النقل","مكونات React","تطوير الويب","نقل الكود","تحسين المكونات","مطورو الويب"]}},"owner":"plaenen","repo":"webx","repoPath":"plaenen/webx","stars":2,"forks":0,"updatedAt":"2026-02-24T18:38:48Z","topics":[],"category":"community","skillMd":{"name":"migrate-component","description":"Migrate a DaisyUI component into a WebX templ component following the migration guide","bodyPreview":"Migrate the DaisyUI component **$ARGUMENTS** into a WebX templ component.\n\nFollow the migration guide at `docs/component-migration-guide.md` exactly. Read it first before writing any code.\n\nSteps:\n\n1. Look up the component on https://daisyui.com/components/$ARGUMENTS/ to understand its HTML structure, CSS classes, modifiers, and whether it uses a hidden input (checkbox/radio) or `<details>` for interactivity.\n\n2. Determine the tier:\n   - **Tier 1 (CSS-only)** if purely visual/structural\n   - **T","body":"Migrate the DaisyUI component **$ARGUMENTS** into a WebX templ component.\n\nFollow the migration guide at `docs/component-migration-guide.md` exactly. Read it first before writing any code.\n\nSteps:\n\n1. Look up the component on https://daisyui.com/components/$ARGUMENTS/ to understand its HTML structure, CSS classes, modifiers, and whether it uses a hidden input (checkbox/radio) or `<details>` for interactivity.\n\n2. Determine the tier:\n   - **Tier 1 (CSS-only)** if purely visual/structural\n   - **Tier 2 (Interactive)** if it toggles, shows/hides, or changes state\n\n3. Create the package at `ui/$ARGUMENTS/$ARGUMENTS.templ` following the tier template from the migration guide.\n\n4. Map all DaisyUI modifiers to typed Go consts (Variant, Size, Position, etc.).\n\n5. For Tier 2 components: define a signals struct, use `utils.Signals()`, and use `ds.*` helpers for ALL Datastar attributes. Never write raw `data-on-click` or similar — always use `ds.OnClick()`, `ds.Attr()`, etc.\n\n6. Generate and build:\n   ```sh\n   go tool templ generate\n   go build ./cmd/showcase\n   ```\n\n7. If the component introduces new DaisyUI classes not yet in the codebase, rebuild CSS:\n   ```sh\n   go tool gotailwind -i static/css/input.css -o static/css/output.css\n   ```\n\n8. Create a showcase page at `cmd/showcase/internal/pages/$ARGUMENTS.templ` demonstrating the component with multiple variants/sizes. Register the route in `cmd/showcase/main.go` and add a sidebar link in `layouts/showcase.templ`.\n\n9. Write an E2E test at `tests/e2e/$ARGUMENTS_test.go`. For CSS-only components, verify elements render with expected classes. For interactive components, verify toggle/state behavior using Playwright.\n\n10. Run E2E tests to verify:\n    ```sh\n    go test ./tests/e2e/... -run $ARGUMENTS -v\n    ```\n"},"lastSynced":"2026-03-06T07:05:06.227Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing seamless DaisyUI to WebX templ component migration capabilities.","zh":"非常适合需要无缝迁移DaisyUI到WebX模板组件的前端代理。","ja":"フロントエンドエージェントがDaisyUIをWebXテンプレートコンポーネントにシームレスに移行する必要がある場合に最適です。","ko":"프론트엔드 에이전트가 DaisyUI를 WebX 템플릿 컴포�ント로 무중단으로 마이그레이션해야 하는 경우에 적합합니다.","es":"Perfecto para agentes Frontend que necesitan capacidades de migración de componentes de DaisyUI a WebX templ de forma fluida.","fr":"Parfait pour les agents Frontend qui ont besoin de capacités de migration de composants DaisyUI à WebX templ sans interruption.","de":"Perfekt für Frontend-Agents, die eine nahtlose Migration von DaisyUI- zu WebX-templ-Komponenten benötigen.","pt":"Perfeito para Agentes Frontend que precisam de capacidades de migração de componentes DaisyUI para WebX templ sem interrupções.","ru":"Идеально подходит для Фронтенд-агентов, которым необходимы возможности бесшовной миграции компонентов DaisyUI в компоненты WebX templ.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى قدرات هجرة مكونات DaisyUI إلى مكونات WebX templ دون انقطاع."},"recommendation":{"en":"Empowers agents to migrate DaisyUI components into WebX templ components following a detailed migration guide, utilizing HTML structure analysis, CSS class mapping, and modifier handling, all while adhering to the protocol outlined in the component-migration-guide.md.","zh":"赋予代理迁移DaisyUI组件到WebX模板组件的能力，遵循详细的迁移指南，利用HTML结构分析、CSS类映射和修饰符处理，所有这些都按照component-migration-guide.md中概述的协议进行。","ja":"エージェントにDaisyUIコンポーネントをWebXテンプレートコンポーネントに移行する能力を付与します。詳細な移行ガイドに従って、HTML構造分析、CSSクラスマッピング、および修飾子処理を使用し、component-migration-guide.mdに概説されているプロトコルに従います。","ko":"에이전트가 DaisyUI 컴포�ント를 WebX 템플릿 컴포�ντ로 마이그레이션 할 수 있는 기능을 제공합니다. 자세한 마이그레이션 가이드를 따르며, HTML 구조 분석, CSS 클래스 매핑 및 수정자 처리를 사용하여 component-migration-guide.md에 정의된 프로토콜을 준수합니다.","es":"Habilita a los agentes a migrar componentes de DaisyUI a componentes de WebX templ siguiendo una guía de migración detallada, utilizando análisis de estructura HTML, asignación de clases CSS y control de modificadores, todo mientras se adhiere al protocolo descrito en el component-migration-guide.md.","fr":"Permet aux agents de migrer des composants DaisyUI vers des composants WebX templ en suivant un guide de migration détaillé, en utilisant l''analyse de la structure HTML, le mappage des classes CSS et la gestion des modificateurs, le tout en respectant le protocole décrit dans le component-migration-guide.md.","de":"Ermächtigt Agenten, DaisyUI-Komponenten in WebX-templ-Komponenten zu migrieren, indem sie einem detaillierten Migrationsleitfaden folgen, der HTML-Strukturanalyse, CSS-Klassen-Zuordnung und Modifikator-Handling umfasst, all dies unter Einhaltung des im component-migration-guide.md beschriebenen Protokolls.","pt":"Habilita os agentes a migrar componentes DaisyUI para componentes WebX templ seguindo um guia de migração detalhado, utilizando análise de estrutura HTML, mapeamento de classes CSS e tratamento de modificador, tudo enquanto adere ao protocolo delineado no component-migration-guide.md.","ru":"Наделяет агентов возможностью мигрировать компоненты DaisyUI в компоненты WebX templ, следуя подробному руководству по миграции, используя анализ структуры HTML, сопоставление классов CSS и обработку модификаторов, все это при соблюдении протокола, изложенного в component-migration-guide.md.","ar":"يتمكّن الوكلاء من هجرة مكونات DaisyUI إلى مكونات WebX templ اتباعًا لدليل هجرة مفصل، مستخدمين تحليل هيكل HTML وتصويب فئات CSS ومعالجة المعدل، مع الالتزام بالبروتوكول المحدد في component-migration-guide.md."},"useCases":{"en":["Migrating DaisyUI components to WebX templ for enhanced compatibility","Automating the analysis of component HTML structures and CSS classes","Debugging migration issues based on the component''s tier and interactivity"],"zh":["将DaisyUI组件迁移到WebX模板以提高兼容性","自动分析组件HTML结构和CSS类","根据组件的层级和交互性调试迁移问题"],"ja":["DaisyUIコンポーネントをWebXテンプレートに移行して互換性を向上させる","コンポーネントのHTML構造とCSSクラスを自動分析する","コンポーネントの階層とインタラクティビティに基づいて移行の問題をデバッグする"],"ko":["DaisyUI 컴포넌트를 WebX 템플릿으로 마이그레이션하여 호환성을 향상시키는 것","컴포넌트의 HTML 구조와 CSS 클래스를 자동으로 분석하는 것","컴포넌트의 계층과 상호 작용성에 따라 마이그레이션 문제를 디버깅하는 것"],"es":["Migrar componentes de DaisyUI a WebX templ para una mayor compatibilidad","Automatizar el análisis de estructuras HTML de componentes y clases CSS","Depurar problemas de migración en función del nivel y la interactividad del componente"],"fr":["Migrer des composants DaisyUI vers WebX templ pour une compatibilité améliorée","Automatiser l''analyse des structures HTML et des classes CSS des composants","Déboguer les problèmes de migration en fonction du niveau et de l''interactivité du composant"],"de":["Migrieren von DaisyUI-Komponenten zu WebX-templ-Komponenten für eine verbesserte Kompatibilität","Automatisieren der Analyse von HTML-Strukturen und CSS-Klassen von Komponenten","Fehlerbehebung bei der Migration basierend auf der Ebene und Interaktivität des Komponenten"],"pt":["Migrar componentes DaisyUI para WebX templ para melhorar a compatibilidade","Automatizar a análise de estruturas HTML de componentes e classes CSS","Depurar problemas de migração com base na camada e interatividade do componente"],"ru":["Мигрировать компоненты DaisyUI в компоненты WebX templ для улучшения совместимости","Автоматизировать анализ структур HTML компонентов и классов CSS","Отлаживать проблемы миграции на основе уровня и интерактивности компонента"],"ar":["هجرة مكونات DaisyUI إلى مكونات WebX templ لتحسين التوافق","تأتمتة تحليل هياكل HTML للمكونات وفئات CSS","تصحيح مشاكل الهجرة بناءً على طبقة وتفاعلية المكون"]},"limitations":{"en":["Requires access to the component-migration-guide.md","Limited to DaisyUI and WebX templ components","Needs internet connection for looking up components on https://daisyui.com/"],"zh":["需要访问component-migration-guide.md","仅限DaisyUI和WebX模板组件","需要互联网连接以在https://daisyui.com/上查找组件"],"ja":["component-migration-guide.mdにアクセスする必要がある","DaisyUIとWebXテンプレートコンポーネントのみに限定される","コンポーネントをhttps://daisyui.com/で検索するためにインターネット接続が必要"],"ko":["component-migration-guide.md에 접근할 수 있어야 함","DaisyUI와 WebX 템플릿 컴포넌트에만 제한됨","컴포넌트를 https://daisyui.com/에서 검색하기 위해 인터넷 연결이 필요함"],"es":["Requiere acceso al component-migration-guide.md","Limitado a componentes de DaisyUI y WebX templ","Necesita conexión a Internet para buscar componentes en https://daisyui.com/"],"fr":["Nécessite un accès au component-migration-guide.md","Limité aux composants DaisyUI et WebX templ","Nécessite une connexion Internet pour rechercher des composants sur https://daisyui.com/"],"de":["Benötigt Zugriff auf das component-migration-guide.md","Begrenzt auf DaisyUI- und WebX-templ-Komponenten","Benötigt Internetverbindung zum Abrufen von Komponenten auf https://daisyui.com/"],"pt":["Requer acesso ao component-migration-guide.md","Limitado a componentes DaisyUI e WebX templ","Necessita de conexão com a internet para procurar componentes em https://daisyui.com/"],"ru":["Требует доступа к component-migration-guide.md","Ограничен компонентами DaisyUI и WebX templ","Требует подключения к интернету для поиска компонентов на https://daisyui.com/"],"ar":["يتطلب الوصول إلى component-migration-guide.md","محدود بمكونات DaisyUI ومكونات WebX templ","يحتاج إلى اتصال بالإنترنت للبحث عن المكونات على https://daisyui.com/"]},"version":4},"contentHash":"c6e7bbf82a74d1a7a6e84d34f3c767dcc8c4004a5565f8e0c9de1435f691ab77","qualityScore":39}');
