INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('plaenen/webx/migrate-component', 'migrate-component', 'plaenen', 'webx', 'community', 'migrate-component plaenen webx community The migrate-component skill migrates DaisyUI components into WebX templ components, following a detailed migration guide. It benefits developers working with WebX and DaisyUI. migrate-component技能可以帮助您将DaisyUI组件迁移到WebX，支持CSS-only和交互式组件 migrate-componentスキルは、DaisyUIコンポーネントをWebXへ移行するのに役立ちます migrate-component 기능은 DaisyUI 컴포넌트를 WebX로 마이그레이션하는 데 도움이 됩니다 Migra componentes de DaisyUI a WebX con nuestra guía. Aprende a adaptar la estructura HTML, CSS y la interactividad. Migrez des composants DaisyUI vers WebX avec notre guide. Apprenez à adapter la structure HTML, CSS et l''interactivité. Migrieren Sie DaisyUI-Komponenten zu WebX mit unserem Leitfaden. Erfahren Sie, wie Sie die HTML-Struktur, CSS und Interaktivität anpassen. Migre componentes DaisyUI para WebX templ seguindo nosso guia de migração Мигрируйте компоненты DaisyUI в WebX templ, следуя нашему руководству انقل مكونات DaisyUI إلى WebX templ باتباع دليلنا how to use migrate-component migrate-component setup guide migrate-component vs WebX DaisyUI to WebX migration migrate-component install WebX templating best practices migrate-component DaisyUI组件迁移 WebX CSS-only 交互式组件 AIエージェント 组件迁移指南 Migrates DaisyUI components to WebX templ components Follows a detailed migration guide at docs/component-migration-guide.md Determines component tier based on CSS usage and interactivity Supports lookup of component HTML structure and CSS classes on https://daisyui.com/components/ Handles hidden input and details elements for interactivity migrate-component is a skill that enables the migration of DaisyUI components into WebX templ components, utilizing a step-by-step guide.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('NobleDarkGames/thesparklingfarce/sns', 'community', 'NobleDarkGames', 'thesparklingfarce', 'NobleDarkGames/thesparklingfarce', 'sns', 2, 0, 39, '2026-02-21T17:00:38Z', '2026-03-06T07:06:16.528Z', 'ad424a2a1b7c16ab04b429f7acf516c00eb382592d0632d049bb614178f418d3', '{"id":"NobleDarkGames/thesparklingfarce/sns","name":"sns","description":{"en":"The SNS skill is a Godot-based tactical RPG creation platform that allows users to share and view screenshots using commands like SNS, SNS2, and SNS3. It benefits developers and gamers alike by streamlining the screenshot sharing process.","zh":"SNS是一个基于Godot的战术RPG创建平台，提供命令行工具和Screenshot Navigation System","ja":"SNSはGodotベースの戦術RPG作成プラットフォームで、コマンドラインツールとスクリーンショットナビゲーションシステムを提供する","ko":"SNS는 Godot 기반의 전술 RPG 생성 플랫폼으로, 명령줄 도구 및 스크린샷 탐색 시스템을 제공합니다","es":"SNS es un sistema de navegación de capturas de pantalla para plataformas de RPG tácticas basadas en Godot. Permite a los usuarios compartir capturas de pantalla.","fr":"SNS est un système de navigation d''écran pour les plateformes de RPG tactiques basées sur Godot. Il permet aux utilisateurs de partager des captures d''écran.","de":"SNS ist ein Screenshot-Navigations-System für Godot-basierte Tactical-RPG-Plattformen. Es ermöglicht Benutzern, Screenshots zu teilen.","pt":"O SNS é uma plataforma de RPG tático baseada em Godot que permite criar experiências de jogo personalizadas. Utilize comandos como SNS, SNS2 e SNS3 para visualizar capturas de tela.","ru":"SNS - это платформа для создания тактических RPG на базе Godot, которая позволяет создавать персонализированные игровые trải nghiệm. Используйте команды SNS, SNS2 и SNS3 для просмотра скриншотов.","ar":"SNS هي منصة إنشاء ألعاب RPG الإستراتيجية مبنية على Godot التي تمكن من إنشاء تجارب لعب شخصیة. استخدم أوامر مثل SNS و SNS2 و SNS3 لعرض لقطات الشاشة."},"seo":{"title":{"en":"SNS: Tactical RPG Creation Setup Guide | AI Agent Skill","zh":"SNS Setup Guide: Godot-based AI工具","ja":"SNS セットアップガイド: GodotベースのAIエージェント","ko":"SNS 설정 가이드: Godot 기반 AI 에이전트","es":"Guía de configuración de SNS para plataformas de RPG táct...","fr":"Guide de mise en place de SNS pour les plateformes de RPG...","de":"Einrichtungsleitfaden für SNS bei der Erstellung von Tact...","pt":"Guia de Configuração do SNS: Plataforma de RPG Tático bas...","ru":"Настройка SNS: Платформа для создания тактических RPG на ...","ar":"دليل إعداد SNS: منصة إنشاء ألعاب RPG الإستراتيجية مبنية ع..."},"description":{"en":"Unlock the power of Godot-based tactical RPG creation with SNS. Learn how to use SNS commands and navigate screenshots with ease. Get started now!","zh":"了解SNS的技术细节，包括命令、功能和Godot集成。使用SNS创建策略性RPG游戏","ja":"SNSの技術的詳細、コマンド、機能、Godotとの統合について学ぶ。SNSを使用して戦術性RPGゲームを作成する","ko":"SNS의 기술적 세부 정보, 명령, 기능 및 Godot 통합에 대해 알아보세요. SNS를 사용하여 전술 RPG 게임을 생성합니다","es":"Aprende a utilizar SNS, un sistema de navegación de capturas de pantalla para plataformas de RPG tácticas basadas en Godot","fr":"Découvrez comment utiliser SNS, un système de navigation d''écran pour les plateformes de RPG tactiques basées sur Godot","de":"Erfahren Sie, wie Sie SNS, ein Screenshot-Navigations-System für Godot-basierte Tactical-RPG-Plattformen, verwenden können","pt":"Aprenda a configurar e utilizar o SNS, uma plataforma de RPG tático baseada em Godot, para criar experiências de jogo personalizadas","ru":"Узнайте, как настроить и использовать SNS, платформу для создания тактических RPG на базе Godot, для создания персонализированных игровых trải nghiệm - ИИ Аг...","ar":"تعلم كيفية إعداد واستخدام SNS، منصة إنشاء ألعاب RPG الإستراتيجية مبنية على Godot، لإنشاء تجارب لعب شخصیة - أدوات الذكاء الاصطناعي"},"definition":{"en":"SNS is a Godot-based tactical RPG creation platform that utilizes the Screenshot Navigation System to share and view screenshots","zh":"SNS是基于Godot的战术RPG创建平台，提供命令行工具和Screenshot Navigation System","ja":"SNSはGodotベースの戦術RPG作成プラットフォームで、コマンドラインツールとスクリーンショットナビゲーションシステムを提供する","ko":"SNS는 Godot 기반의 전술 RPG 생성 플랫폼으로, 명령줄 도구 및 스크린샷 탐색 시스템을 제공합니다","es":"SNS es un sistema de navegación de capturas de pantalla para plataformas de RPG tácticas","fr":"SNS est un système de navigation d''écran pour les plateformes de RPG tactiques","de":"SNS ist ein Screenshot-Navigations-System für Tactical-RPG-Plattformen","pt":"O SNS é uma plataforma de RPG tático baseada em Godot que permite criar e compartilhar capturas de tela de jogos","ru":"SNS - это платформа для создания тактических RPG на базе Godot, которая позволяет создавать и делиться скриншотами игр - ИИ Агенты","ar":"SNS هي منصة إنشاء ألعاب RPG الإستراتيجية مبنية على Godot التي تمكن من إنشاء ومشاركة لقطات الشاشة للألعاب - أدوات الذكاء الاصطناعي"},"features":{"en":["Utilizes the Screenshot Navigation System (SNS) to share screenshots","Supports commands like SNS, SNS2, and SNS3 to view newest screenshots","Navigates to the ~/Pictures/Screenshots/ directory to find image files","Uses the Read tool to view image files in PNG format","Executes bash commands like ls -t to find the newest screenshot(s)","Integrates with Godot for tactical RPG creation"],"zh":["基于Godot的战术RPG创建","命令行工具：SNS、SNS2、SNS3","Screenshot Navigation System","支持图片文件查看","使用Read工具查看图片文件"],"ja":["Godotベースの戦術RPG作成","コマンドラインツール：SNS、SNS2、SNS3","スクリーンショットナビゲーションシステム","画像ファイルの表示をサポート","Readツールを使用して画像ファイルを表示"],"ko":["Godot 기반의 전술 RPG 생성","명령줄 도구: SNS, SNS2, SNS3","스크린샷 탐색 시스템","이미지 파일查看 지원","Read 도구를 사용하여 이미지 파일查看"],"es":["Comando SNS para ver la captura de pantalla más reciente","Comando SNS2 para ver las 2 capturas de pantalla más recientes","Comando SNS3 para ver las 3 capturas de pantalla más recientes","Integración con Godot","Uso de la herramienta Read para ver archivos de imagen","Compatibilidad con la carpeta ~/Pictures/Screenshots/"],"fr":["Commande SNS pour afficher la capture d''écran la plus récente","Commande SNS2 pour afficher les 2 captures d''écran les plus récentes","Commande SNS3 pour afficher les 3 captures d''écran les plus récentes","Intégration avec Godot","Utilisation de l''outil Read pour afficher les fichiers d''image","Compatibilité avec le dossier ~/Pictures/Screenshots/"],"de":["Befehl SNS zum Anzeigen des neuesten Screenshots","Befehl SNS2 zum Anzeigen der 2 neuesten Screenshots","Befehl SNS3 zum Anzeigen der 3 neuesten Screenshots","Integration mit Godot","Verwendung des Read-Tools zum Anzeigen von Bilddateien","Kompatibilität mit dem Verzeichnis ~/Pictures/Screenshots/"],"pt":["Comandos personalizados como SNS, SNS2 e SNS3 para visualizar capturas de tela","Integração com o Godot para criar experiências de jogo personalizadas","Capacidade de compartilhar capturas de tela de jogos","Utilização do Read tool para visualizar arquivos de imagem","Compatibilidade com o sistema de arquivos para encontrar as capturas de tela mais recentes"],"ru":["Пользовательские команды SNS, SNS2 и SNS3 для просмотра скриншотов","Интеграция с Godot для создания персонализированных игровых trải nghiệm","Возможность делиться скриншотами игр","Использование инструмента Read для просмотра файлов изображений","Совместимость с файловой системой для поиска наиболее свежих скриншотов - ИИ Агенты"],"ar":["أوامر مخصصة مثل SNS و SNS2 و SNS3 لعرض لقطات الشاشة","التكامل مع Godot لإنشاء تجارب لعب شخصیة","القدرة على مشاركة لقطات الشاشة للألعاب","استخدام أداة القراءة لعرض ملفات الصور","التوافق مع نظام الملفات لإيجاد لقطات الشاشة الأحدث - أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use sns","sns setup guide","godot tactical rpg creation","screenshot navigation system","sns vs godot","sns install","what is sns","sns alternative","sns tutorial","godot-based rpg development"],"zh":["SNS","Godot","战术RPG","AI工具","命令行工具","Screenshot Navigation System","Godot游戏开发","战术RPG游戏创建","AI游戏开发"],"ja":["SNS","Godot","戦術RPG","AIエージェント","コマンドラインツール","スクリーンショットナビゲーションシステム","Godotゲーム開発","戦術RPGゲーム作成","AIゲーム開発"],"ko":["SNS","Godot","전술RPG","AI에이전트","명령줄도구","스크린샷탐색시스템","Godot게임개발","전술RPG게임생성","AI게임개발"],"es":["SNS","Godot","RPG tácticas","sistema de navegación de capturas de pantalla","comando SNS","herramienta Read","capturas de pantalla","desarrollo de juegos","plataformas de juego"],"fr":["SNS","Godot","RPG tactiques","système de navigation d''écran","commande SNS","outil Read","captures d''écran","développement de jeux","plateformes de jeu"],"de":["SNS","Godot","Tactical-RPG","Screenshot-Navigations-System","Befehl SNS","Read-Tool","Screenshots","Spieleentwicklung","Spieleplattformen"],"pt":["SNS","Godot","RPG tático","capturas de tela","comandos personalizados","integração com Godot","criação de jogos","desenvolvimento de jogos"],"ru":["SNS","Godot","Тактические RPG","скриншоты","пользовательские команды","интеграция с Godot","создание игр","разработка игр","ИИ Агенты"],"ar":["SNS","Godot","RPG الإستراتيجية","لقطات الشاشة","أوامر مخصصة","التكامل مع Godot","إنشاء ألعاب","تطوير ألعاب","أدوات الذكاء الاصطناعي"]}},"owner":"NobleDarkGames","repo":"thesparklingfarce","repoPath":"NobleDarkGames/thesparklingfarce","stars":2,"forks":0,"updatedAt":"2026-02-21T17:00:38Z","topics":[],"category":"community","skillMd":{"name":"sns","description":"View the newest screenshot(s) from the users Screenshots folder. Use when user says SNS, SNS2, SNS3, or asks to see a screenshot.","bodyPreview":"## Screenshot Viewer Commands\n\nThe user uses `SNS` (Screenshot Navigation System) to share screenshots with you.\n\n### Commands\n\n| Command | Action |\n|---------|--------|\n| `SNS` | View the 1 newest screenshot |\n| `SNS2` | View the 2 newest screenshots |\n| `SNS3` | View the 3 newest screenshots |\n\n### How to Execute\n\n1. Find the newest screenshot(s) in `~/Pictures/Screenshots/`\n2. Use the Read tool to view the image file(s)\n\n```bash\n# Find newest screenshot\nls -t ~/Pictures/Screenshots/*.png | he","body":"## Screenshot Viewer Commands\n\nThe user uses `SNS` (Screenshot Navigation System) to share screenshots with you.\n\n### Commands\n\n| Command | Action |\n|---------|--------|\n| `SNS` | View the 1 newest screenshot |\n| `SNS2` | View the 2 newest screenshots |\n| `SNS3` | View the 3 newest screenshots |\n\n### How to Execute\n\n1. Find the newest screenshot(s) in `~/Pictures/Screenshots/`\n2. Use the Read tool to view the image file(s)\n\n```bash\n# Find newest screenshot\nls -t ~/Pictures/Screenshots/*.png | head -1\n\n# Find 2 newest\nls -t ~/Pictures/Screenshots/*.png | head -2\n\n# Find 3 newest  \nls -t ~/Pictures/Screenshots/*.png | head -3\n```\n\n### Notes\n\n- Screenshots are typically PNG files\n- Sort by modification time (`-t`) to get newest first\n- The user is showing you what they see on screen - analyze the image content\n- Common uses: showing UI state, error dialogs, visual bugs, design references\n"},"lastSynced":"2026-03-06T07:06:16.528Z","agentAnalysis":{"suitability":{"en":"Ideal for Visual Inspection Agents requiring streamlined screenshot analysis using SNS commands.","zh":"适合需要使用SNS命令进行简化的截图分析的视觉检查代理。","ja":"SNSコマンドを使用したスクリーンショット分析をストリームライン化する必要があるビジュアルインスペクションエージェントに適しています。","ko":"SNS 명령을 사용하여 스크린샷 분석을 간소화해야 하는 시각적 검사 에이전트에 적합합니다.","es":"Ideal para Agentes de Inspección Visual que requieren un análisis de capturas de pantalla optimizado utilizando comandos SNS.","fr":"Idéal pour les Agents d''Inspection Visuelle nécessitant une analyse de captures d''écran simplifiée à l''aide de commandes SNS.","de":"Ideal für visuelle Inspektionsagenten, die eine optimierte Screenshot-Analyse mit SNS-Befehlen erfordern.","pt":"Ideal para Agentes de Inspeção Visual que exigem análise de capturas de tela otimizadas usando comandos SNS.","ru":"Идеально для агентов визуального осмотра, требующих оптимизированного анализа скриншотов с помощью команд SNS.","ar":"مثالي لعميل التفتيش المرئي الذي يتطلب تحليلًا لقطات الشاشة المُبسّط باستخدام أوامر SNS."},"recommendation":{"en":"Empowers agents to efficiently view and navigate screenshots using commands like SNS, SNS2, and SNS3, leveraging the Read tool and ls -t protocol to retrieve the newest image files from ~/Pictures/Screenshots/","zh":"赋予代理能够使用SNS、SNS2和SNS3等命令高效地查看和导航截图，利用Read工具和ls -t协议从~/Pictures/Screenshots/中检索最新的图像文件。","ja":"SNS、SNS2、SNS3などのコマンドを使用して、スクリーンショットを効率的に表示およびナビゲートできるようにエージェントを Empowerします。Readツールとls -tプロトコルを使用して、~/Pictures/Screenshots/から最新の画像ファイルを取得します。","ko":"에이전트가 SNS, SNS2, SNS3などの 명령을 사용하여 스크린샷을 효율적으로查看하고 탐색할 수 있도록 합니다. Read 툴과 ls -t 프로토콜을 사용하여 ~/Pictures/Screenshots/에서 최신 이미지 파일을 가져옵니다.","es":"Permite a los agentes ver y navegar por capturas de pantalla de forma eficiente utilizando comandos como SNS, SNS2 y SNS3, aprovechando la herramienta Read y el protocolo ls -t para recuperar los archivos de imagen más nuevos de ~/Pictures/Screenshots/","fr":"Permet aux agents de visualiser et de naviguer dans les captures d''écran de manière efficace en utilisant des commandes comme SNS, SNS2 et SNS3, en exploitant l''outil Read et le protocole ls -t pour récupérer les fichiers image les plus récents de ~/Pictures/Screenshots/","de":"Ermöglicht es Agenten, Screenshots effizient anzuzeigen und zu navigieren, indem Befehle wie SNS, SNS2 und SNS3 verwendet werden, die Read-Tool und das ls -t-Protokoll nutzend, um die neuesten Bilddateien aus ~/Pictures/Screenshots/ abzurufen.","pt":"Habilita os agentes a visualizar e navegar por capturas de tela de forma eficiente usando comandos como SNS, SNS2 e SNS3, aproveitando a ferramenta Read e o protocolo ls -t para recuperar os arquivos de imagem mais recentes de ~/Pictures/Screenshots/","ru":"Наделяет агентов возможностью эффективно просматривать и навигировать по скриншотам, используя команды SNS, SNS2 и SNS3, используя инструмент Read и протокол ls -t для получения наиболее новых файлов изображений из ~/Pictures/Screenshots/","ar":"يُمكّن الوكيل من عرض لقطات الشاشة وتحريكها بفعالية باستخدام أوامر مثل SNS و SNS2 و SNS3، مستفيدًا من أداة القراءة وبروتوكول ls -t لاسترجاع أحدث ملفات الصور من ~/Pictures/Screenshots/"},"useCases":{"en":["Automating screenshot sharing with SNS commands","Debugging game development issues using SNS2 and SNS3","Generating reports with the 3 newest screenshots using SNS3"],"zh":["使用SNS命令自动共享截图","使用SNS2和SNS3调试游戏开发问题","使用SNS3生成3个最新截图的报告"],"ja":["SNSコマンドを使用してスクリーンショットを自動共有する","SNS2とSNS3を使用してゲーム開発の問題をデバッグする","SNS3を使用して3つの最新スクリーンショットのレポートを生成する"],"ko":["SNS 명령을 사용하여 스크린샷을 자동으로 공유하는 것","SNS2와 SNS3를 사용하여 게임 개발 문제를 디버깅하는 것","SNS3를 사용하여 3개의 최신 스크린샷의 보고서를 생성하는 것"],"es":["Automatizar el intercambio de capturas de pantalla con comandos SNS","Depurar problemas de desarrollo de juegos utilizando SNS2 y SNS3","Generar informes con las 3 capturas de pantalla más nuevas utilizando SNS3"],"fr":["Automatiser le partage de captures d''écran avec des commandes SNS","Déboguer les problèmes de développement de jeux en utilisant SNS2 et SNS3","Générer des rapports avec les 3 captures d''écran les plus récentes en utilisant SNS3"],"de":["Automatisieren des Screenshot-Teilens mit SNS-Befehlen","Debuggen von Spielentwicklungsproblemen mit SNS2 und SNS3","Erstellen von Berichten mit den 3 neuesten Screenshots unter Verwendung von SNS3"],"pt":["Automatizar o compartilhamento de capturas de tela com comandos SNS","Depurar problemas de desenvolvimento de jogos usando SNS2 e SNS3","Gerar relatórios com as 3 capturas de tela mais recentes usando SNS3"],"ru":["Автоматизировать обмен скриншотами с помощью команд SNS","Отладить проблемы разработки игр, используя SNS2 и SNS3","Генерировать отчеты с 3 последними скриншотами, используя SNS3"],"ar":["تأتمتية مشاركة لقطات الشاشة باستخدام أوامر SNS","تصحيح أخطاء تطوير الألعاب باستخدام SNS2 و SNS3","генерировать تقارير مع 3 لقطات الشاشة الأخيرة باستخدام SNS3"]},"limitations":{"en":["Requires access to ~/Pictures/Screenshots/ directory","Limited to .png file format","Godot-based platform only"],"zh":["需要访问~/Pictures/Screenshots/目录","仅限.png文件格式","仅限Godot平台"],"ja":["~/Pictures/Screenshots/ディレクトリへのアクセスが必要",".pngファイル形式のみ","Godotプラットフォームのみ"],"ko":["~/Pictures/Screenshots/ 디렉토리에 액세스해야 함",".png 파일 형식만","Godot 플랫폼만"],"es":["Requiere acceso al directorio ~/Pictures/Screenshots/","Limitado al formato de archivo .png","Plataforma basada en Godot solo"],"fr":["Nécessite un accès au répertoire ~/Pictures/Screenshots/","Limité au format de fichier .png","Plate-forme basée sur Godot uniquement"],"de":["Erfordert Zugriff auf das Verzeichnis ~/Pictures/Screenshots/","Begrenzt auf .png-Dateiformat","Nur Godot-basierte Plattform"],"pt":["Exige acesso ao diretório ~/Pictures/Screenshots/","Limitado ao formato de arquivo .png","Plataforma baseada em Godot apenas"],"ru":["Требует доступа к каталогу ~/Pictures/Screenshots/","Ограничен форматом файла .png","Платформа только на основе Godot"],"ar":["يتطلب الوصول إلى الدليل ~/Pictures/Screenshots/","محدود بتنسيق الملف .png","منصة مبنية على Godot فقط"]},"version":4},"contentHash":"ad424a2a1b7c16ab04b429f7acf516c00eb382592d0632d049bb614178f418d3","qualityScore":39}');
