INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('NobleDarkGames/thesparklingfarce/sns', 'sns', 'NobleDarkGames', 'thesparklingfarce', 'community', 'sns NobleDarkGames thesparklingfarce community The SNS skill is a Godot-based tactical RPG creation platform that allows users to share and view screenshots using commands like SNS, SNS2, and SNS3. It benefits developers and gamers alike by streamlining the screenshot sharing process. SNS是一个基于Godot的战术RPG创建平台，提供命令行工具和Screenshot Navigation System SNSはGodotベースの戦術RPG作成プラットフォームで、コマンドラインツールとスクリーンショットナビゲーションシステムを提供する SNS는 Godot 기반의 전술 RPG 생성 플랫폼으로, 명령줄 도구 및 스크린샷 탐색 시스템을 제공합니다 SNS es un sistema de navegación de capturas de pantalla para plataformas de RPG tácticas basadas en Godot. Permite a los usuarios compartir capturas de pantalla. SNS est un système de navigation d''écran pour les plateformes de RPG tactiques basées sur Godot. Il permet aux utilisateurs de partager des captures d''écran. SNS ist ein Screenshot-Navigations-System für Godot-basierte Tactical-RPG-Plattformen. Es ermöglicht Benutzern, Screenshots zu teilen. O SNS é uma plataforma de RPG tático baseada em Godot que permite criar experiências de jogo personalizadas. Utilize comandos como SNS, SNS2 e SNS3 para visualizar capturas de tela. SNS - это платформа для создания тактических RPG на базе Godot, которая позволяет создавать персонализированные игровые trải nghiệm. Используйте команды SNS, SNS2 и SNS3 для просмотра скриншотов. SNS هي منصة إنشاء ألعاب RPG الإستراتيجية مبنية على Godot التي تمكن من إنشاء تجارب لعب شخصیة. استخدم أوامر مثل SNS و SNS2 و SNS3 لعرض لقطات الشاشة. how to use sns sns setup guide godot tactical rpg creation screenshot navigation system sns vs godot sns install what is sns sns alternative sns tutorial godot-based rpg development SNS Godot 战术RPG AI工具 命令行工具 Screenshot Navigation System Godot游戏开发 战术RPG游戏创建 AI游戏开发 Utilizes the Screenshot Navigation System (SNS) to share screenshots Supports commands like SNS, SNS2, and SNS3 to view newest screenshots Navigates to the ~/Pictures/Screenshots/ directory to find image files Uses the Read tool to view image files in PNG format Executes bash commands like ls -t to find the newest screenshot(s) Integrates with Godot for tactical RPG creation SNS is a Godot-based tactical RPG creation platform that utilizes the Screenshot Navigation System to share and view screenshots');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Dynokostya/just-works/tailwind-css-coding', 'community', 'Dynokostya', 'just-works', 'Dynokostya/just-works', 'tailwind-css-coding', 2, 1, 39, '2026-03-02T10:19:57Z', '2026-03-06T07:09:45.159Z', '016c5b9aa42c13f5ad252f03be235ae7398c0ab4c1b5afc181de5c4ac6ecafaf', '{"id":"Dynokostya/just-works/tailwind-css-coding","name":"tailwind-css-coding","description":{"en":"The tailwind-css-coding skill provides instructions for integrating Tailwind CSS into any project, helping developers match existing conventions and infer local styles. This skill benefits developers working with Tailwind CSS versions 3 and 4.","zh":"Tailwind CSS 编码设置指南，帮助您在项目中集成 Tailwind CSS","ja":"Tailwind CSS コーディングセットアップガイド - プロジェクトに Tailwind CSS を統合する","ko":"Tailwind CSS 코딩 설정 가이드 - 프로젝트에 Tailwind CSS를 통합하는","es":"Tailwind CSS Coding es un conjunto de instrucciones para integrar Tailwind CSS en cualquier proyecto, siguiendo las convenciones existentes","fr":"Tailwind CSS Coding est un ensemble d''instructions pour intégrer Tailwind CSS dans n''importe quel projet, en suivant les conventions existantes","de":"Tailwind CSS Coding ist ein Satz von Anweisungen, um Tailwind CSS in jedes Projekt zu integrieren, unter Berücksichtigung der bestehenden Konventionen","pt":"O Tailwind CSS Coding é um conjunto de instruções para instalar a base de código Claude em qualquer projeto, seguindo as convenções existentes.","ru":"Tailwind CSS Coding — это набор инструкций для установки базы кода Claude в любом проекте, соответствующий существующим соглашениям.","ar":"Tailwind CSS Coding هو مجموعة من الإرشادات لتثبيت قاعدة كود كلود في أي مشروع، متوافق مع الاتفاقيات الحالية."},"seo":{"title":{"en":"tailwind-css-coding: Setup Guide for AI Agents | AI Agent...","zh":"Tailwind CSS 编码设置指南 - AI智能工具","ja":"Tailwind CSS コーディングセットアップガイド - AIエージェント","ko":"Tailwind CSS 코딩 설정 가이드 - AI 에이전트","es":"Guía de configuración de Tailwind CSS Coding","fr":"Guide d''installation de Tailwind CSS Coding","de":"Einrichtungsleitfaden für Tailwind CSS Coding","pt":"Guia de Configuração do Tailwind CSS Coding","ru":"ИИ Агенты: Руководство по Настройке Tailwind CSS Coding","ar":"دليل إعداد Tailwind CSS Coding للوكلاء الذكيين"},"description":{"en":"Unlock seamless integration with our tailwind-css-coding setup guide. Discover how to match project conventions and infer local styles for efficient development","zh":"了解如何在项目中集成Tailwind CSS，包括版本检测和样式兼容性","ja":"Tailwind CSSをプロジェクトに統合する方法を学び、バージョン検出とスタイルの互換性について","ko":"Tailwind CSS를 프로젝트에 통합하는 방법을 배우고 버전 감지 및 스타일 호환성에 대해","es":"Aprende a integrar Tailwind CSS en tus proyectos con nuestra guía de configuración paso a paso","fr":"Découvrez comment intégrer Tailwind CSS dans vos projets avec notre guide d''installation étape par étape","de":"Erfahren Sie, wie Sie Tailwind CSS in Ihre Projekte integrieren können, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a integrar o Tailwind CSS Coding em seus projetos com essa guia passo a passo","ru":"ИИ Агенты: узнайте, как настроить Tailwind CSS Coding в ваших проектах с помощью этого руководства","ar":"تعلم كيفية تثبيت Tailwind CSS Coding في مشاريعك باستخدام هذا الدليل المتقدم"},"definition":{"en":"tailwind-css-coding is a set of instructions for installing and integrating Tailwind CSS into a project, following existing conventions and styles","zh":"Tailwind CSS 编码是指在项目中集成 Tailwind CSS 的一组指令","ja":"Tailwind CSS コーディングとは、プロジェクトに Tailwind CSS を統合する一連の指示","ko":"Tailwind CSS 코딩은 프로젝트에 Tailwind CSS를 통합하는 일련의 지침","es":"Tailwind CSS Coding es una herramienta de código que facilita la integración de Tailwind CSS en proyectos","fr":"Tailwind CSS Coding est un outil de code qui facilite l''intégration de Tailwind CSS dans les projets","de":"Tailwind CSS Coding ist ein Code-Tool, das die Integration von Tailwind CSS in Projekte erleichtert","pt":"O que é Tailwind CSS Coding? É um conjunto de instruções para integrar a base de código Claude em projetos.","ru":"Что такое Tailwind CSS Coding? Это набор инструкций для интеграции базы кода Claude в проекты.","ar":"ما هو Tailwind CSS Coding؟ هو مجموعة من الإرشادات لتثبيت قاعدة كود كلود في المشاريع."},"features":{"en":["Checks package.json for tailwindcss version","Identifies v4 signals via @tailwindcss/postcss or @tailwindcss/vite dependencies","Detects v3 signals through tailwind.config.js and autoprefixer","Matches project''s existing conventions","Infers local style by reading existing components","Supports Tailwind CSS versions 3 and 4"],"zh":["检测 Tailwind CSS 版本","检查 package.json 中的依赖","识别样式兼容性","支持 v3 和 v4 版本","集成到现有项目中"],"ja":["Tailwind CSS バージョンの検出","package.json の依存関係の確認","スタイルの互換性の識別","v3 と v4 バージョンのサポート","既存のプロジェクトへの統合"],"ko":["Tailwind CSS 버전 감지","package.json 의 종속성 확인","스타일 호환성 식별","v3 및 v4 버전 지원","기존 프로젝트에 통합"],"es":["Integración con proyectos existentes","Compatibilidad con versiones de Tailwind CSS v3 y v4","Detección automática de la configuración de Tailwind CSS","Uso de @tailwindcss/postcss y @tailwindcss/vite","Compatibilidad con @import \"tailwindcss\" y @theme {}"],"fr":["Intégration avec des projets existants","Compatibilité avec les versions de Tailwind CSS v3 et v4","Détection automatique de la configuration de Tailwind CSS","Utilisation de @tailwindcss/postcss et @tailwindcss/vite","Compatibilité avec @import \"tailwindcss\" et @theme {}"],"de":["Integration in bestehende Projekte","Kompatibilität mit Tailwind CSS-Versionen v3 und v4","Automatische Erkennung der Tailwind CSS-Konfiguration","Verwendung von @tailwindcss/postcss und @tailwindcss/vite","Kompatibilität mit @import \"tailwindcss\" und @theme {}"],"pt":["Integração com o projeto existente","Compatibilidade com versões do Tailwind CSS","Detecção automática de convenções de codificação","Suporte a `@tailwindcss/postcss` e `@tailwindcss/vite`","Compatibilidade com `autoprefixer`"],"ru":["Интеграция с существующим проектом","Совместимость с версиями Tailwind CSS","Автоматическое обнаружение соглашений кодирования","Поддержка `@tailwindcss/postcss` и `@tailwindcss/vite`","Совместимость с `autoprefixer`"],"ar":["التكامل مع المشروع الحالي","توافق مع إصدارات Tailwind CSS","كشف تلقائي عن اتفاقيات الترميز","دعم `@tailwindcss/postcss` و `@tailwindcss/vite`","توافق مع `autoprefixer`"]},"keywords":{"en":["how to use tailwind-css-coding","tailwind-css-coding setup guide","tailwind-css-coding vs bootstrap","tailwind-css-coding install","what is tailwind-css-coding","tailwind-css-coding alternative","tailwindcss version 4","tailwindcss version 3","tailwind css coding tutorial"],"zh":["Tailwind CSS","AI智能工具","编码设置","项目集成","版本检测","样式兼容性","前端开发","CSS 框架"],"ja":["Tailwind CSS","AIエージェント","コーディングセットアップ","プロジェクト統合","バージョン検出","スタイルの互換性","フロントエンド開発","CSS フレームワーク"],"ko":["Tailwind CSS","AI 에이전트","코딩 설정","프로젝트 통합","버전 감지","스타일 호환성","프론트엔드 개발","CSS 프레임워크"],"es":["Tailwind CSS","integración de Tailwind CSS","configuración de Tailwind CSS","Tailwind CSS v3","Tailwind CSS v4","desarrollo web","herramientas de desarrollo","Tailwind CSS Coding"],"fr":["Tailwind CSS","intégration de Tailwind CSS","configuration de Tailwind CSS","Tailwind CSS v3","Tailwind CSS v4","développement web","outils de développement","Tailwind CSS Coding"],"de":["Tailwind CSS","Integration von Tailwind CSS","Konfiguration von Tailwind CSS","Tailwind CSS v3","Tailwind CSS v4","Webentwicklung","Entwicklungstools","Tailwind CSS Coding"],"pt":["Tailwind CSS Coding","Guia de configuração","Instalação de base de código","Integração com projetos","Convenções de codificação","Versões do Tailwind CSS","Desenvolvimento web"],"ru":["ИИ Агенты","Tailwind CSS Coding","Руководство по настройке","Установка базы кода","Интеграция с проектами","Соглашения кодирования","Версии Tailwind CSS","Веб-разработка"],"ar":["وكلاء ذكيين","Tailwind CSS Coding","دليل الإعداد","تثبيت قاعدة الكود","التكامل مع المشاريع","اتفاقيات الترميز","إصدارات Tailwind CSS","تطوير الويب"]}},"owner":"Dynokostya","repo":"just-works","repoPath":"Dynokostya/just-works","stars":2,"forks":1,"updatedAt":"2026-03-02T10:19:57Z","topics":[],"category":"community","skillMd":{"name":"tailwind-css-coding","description":"Apply when writing or editing Tailwind CSS classes in any template or component file. Behavioral corrections for dynamic styling, class composition, responsive design, dark mode, interaction states, accessibility, and common antipatterns. Project conventions always override these defaults.","bodyPreview":"# Tailwind CSS Coding\n\nMatch the project''s existing conventions. When uncertain, read 2-3 existing components to infer the local style. Check `package.json` for the `tailwindcss` version. v4 signals: `@tailwindcss/postcss` or `@tailwindcss/vite` in deps, `@import \"tailwindcss\"` in CSS, `@theme {}` blocks. v3 signals: `tailwind.config.js` with `module.exports`, `@tailwind base;` directives, `autoprefixer` as separate dep. These defaults apply only when the project has no established convention.","body":"# Tailwind CSS Coding\n\nMatch the project''s existing conventions. When uncertain, read 2-3 existing components to infer the local style. Check `package.json` for the `tailwindcss` version. v4 signals: `@tailwindcss/postcss` or `@tailwindcss/vite` in deps, `@import \"tailwindcss\"` in CSS, `@theme {}` blocks. v3 signals: `tailwind.config.js` with `module.exports`, `@tailwind base;` directives, `autoprefixer` as separate dep. These defaults apply only when the project has no established convention.\n\n## Never rules\n\nThese are unconditional. They prevent broken builds, invisible bugs, and inaccessible UI regardless of project style.\n\n- **Never construct class names dynamically** -- Tailwind''s compiler scans source files as plain text with regex. It never executes code. Template literals, string concatenation, and interpolation produce classes the compiler cannot find. Use lookup maps of complete static strings.\n\n```tsx\n// Wrong: compiler cannot extract \"bg-red-500\" from this\nconst cls = `bg-${color}-500`;\n\n// Correct: every class is a complete static string\nconst bgMap = {\n  red: \"bg-red-500\",\n  blue: \"bg-blue-500\",\n} as const;\nconst cls = bgMap[color];\n```\n\n- **Never use template literal concatenation for class composition** -- CSS source order determines which class wins when two utilities target the same property, not HTML attribute order. `p-4 p-6` is unpredictable. Use `cn()` (clsx + tailwind-merge) to merge classes safely.\n\n```tsx\n// Wrong: conflicting padding, last-in-source wins (not last-in-string)\nclassName={`p-4 ${isLarge ? \"p-6\" : \"\"}`}\n\n// Correct: tailwind-merge resolves conflicts deterministically\nimport { cn } from \"@/lib/utils\";\nclassName={cn(\"p-4\", isLarge && \"p-6\")}\n```\n\n- **Never use arbitrary values when a design token exists** -- `p-[16px]` is `p-4`. `bg-[#3b82f6]` is `bg-blue-500`. `w-[100%]` is `w-full`. `text-[14px]` is `text-sm`. Arbitrary values bypass the design system and create inconsistency.\n\n- **Never omit interaction states on interactive elements** -- every button and link needs `hover:`, `focus-visible:`, and `disabled:` states. Add `transition-colors` for smooth feedback. In v4: add `cursor-pointer` explicitly -- Preflight no longer sets it on buttons.\n\n```tsx\n// Wrong: no interaction feedback\n<button className=\"bg-blue-500 text-white px-4 py-2 rounded\">Save</button>\n\n// Correct: full interaction states (v4: include cursor-pointer)\n<button className=\"bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-blue-500 disabled:opacity-50 disabled:cursor-not-allowed transition-colors cursor-pointer\">\n  Save\n</button>\n```\n\n- **Never use `@apply` for patterns extractable to components** -- extract a React/Vue/Svelte component instead. `@apply` is only for third-party library overrides, CMS/Markdown HTML, and non-component template languages.\n\n- **Never forget dark mode counterparts** -- every `bg-`, `text-`, and `border-` color needs a `dark:` variant, or use CSS variable theming to handle both modes in one declaration.\n\n- **Never use `sm:` thinking it means \"small screens\"** -- `sm:` means 640px AND ABOVE. Unprefixed utilities apply to all screens (mobile-first). Write base styles for mobile, then layer breakpoints upward.\n\n```html\n<!-- Wrong mental model: \"sm means small phones\" -->\n<div class=\"hidden sm:block\">Only on small screens</div>\n\n<!-- Correct: sm:block means \"show at 640px and above\" -->\n<div class=\"block sm:hidden\">Mobile only</div>\n<div class=\"hidden sm:block\">Desktop only</div>\n```\n\n- **Never hallucinate class names** -- common fakes: `flex-center` (use `flex items-center justify-center`), `text-bold` (use `font-bold`), `bg-grey-500` (American spelling: `bg-gray-500`), `d-flex` (Bootstrap, not Tailwind).\n\n- **Never output conflicting utilities** -- `p-4 p-6` is unpredictable. One value per CSS property. Don''t redundantly set defaults (`flex flex-row`, `flex flex-nowrap`).\n\n- **Never forget accessibility** -- use `sr-only` for icon-only button labels, `focus:not-sr-only` for skip links. Every interactive element needs visible focus indication via `focus-visible:`.\n\n## Dynamic styling\n\nFor conditional classes, use `cn()` (clsx + tailwind-merge). For truly dynamic values that cannot be enumerated (user-set colors, computed positions), use inline `style` props -- these bypass the compiler entirely and always work.\n\n```tsx\n// Conditional classes: cn()\n<div className={cn(\"rounded p-4\", isActive && \"ring-2 ring-blue-500\")} />\n\n// Truly dynamic: inline style\n<div className=\"rounded p-4\" style={{ backgroundColor: user.brandColor }} />\n```\n\nFor variant-driven styling, use a lookup map with complete static strings:\n\n```tsx\nconst sizeClasses = {\n  sm: \"px-2 py-1 text-sm\",\n  md: \"px-4 py-2 text-base\",\n  lg: \"px-6 py-3 text-lg\",\n} as const;\n\nfunction Button({ size = \"md\", className, ...props }: ButtonProps) {\n  return <button className={cn(sizeClasses[size], className)} {...props} />;\n}\n```\n\nFor components with 2+ variant dimensions, consider `cva` from class-variance-authority.\n\nWhen the compiler must see classes that only appear in dynamic data (CMS content, database values), safelist them. In v4: `@source inline(\"bg-red-500 bg-blue-500\")`. In v3: `safelist` array in `tailwind.config.js`.\n\n## Class composition\n\nThe `cn()` helper combines `clsx` (conditional joining) with `tailwind-merge` (conflict resolution). Standard setup:\n\n```ts\nimport { clsx, type ClassValue } from \"clsx\";\nimport { twMerge } from \"tailwind-merge\";\n\nexport function cn(...inputs: ClassValue[]) {\n  return twMerge(clsx(inputs));\n}\n```\n\nUse `cn()` whenever merging external `className` props with internal defaults -- raw concatenation silently breaks when both sides set the same property.\n\n```tsx\n// Wrong: parent''s p-6 may or may not override internal p-4\nfunction Card({ className }: { className?: string }) {\n  return <div className={`rounded bg-white p-4 ${className}`} />;\n}\n\n// Correct: tailwind-merge ensures parent overrides win\nfunction Card({ className }: { className?: string }) {\n  return <div className={cn(\"rounded bg-white p-4\", className)} />;\n}\n```\n\n## Responsive design\n\nMobile-first: write base styles for the smallest screen, then add breakpoints upward. Always order breakpoints `sm:` -> `md:` -> `lg:` -> `xl:` -> `2xl:`. Never skip to `lg:` without considering the gap.\n\n```html\n<!-- Single column on mobile, two on tablet, three on desktop -->\n<div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4\">\n```\n\nIn v4: container queries are built-in (no plugin). Use `@container` for component-scoped responsive design:\n\n```tsx\n// Parent declares a container\n<div className=\"@container\">\n  {/* Child responds to container width, not viewport */}\n  <div className=\"flex flex-col @md:flex-row @lg:grid @lg:grid-cols-3 gap-4\">\n    {children}\n  </div>\n</div>\n```\n\n## Dark mode\n\nCover every visible color. A component with `bg-white text-gray-900` needs `dark:bg-gray-900 dark:text-white`. Missing a single `dark:` variant causes unreadable text or invisible elements.\n\nBetter approach -- CSS variable theming. Define colors once, switch palettes:\n\n```css\n/* v4: @theme block */\n@theme {\n  --color-surface: #ffffff;\n  --color-on-surface: #111827;\n}\n\n@custom-variant dark (&:where(.dark, .dark *));\n\n.dark {\n  --color-surface: #111827;\n  --color-on-surface: #f9fafb;\n}\n```\n\nThen use `bg-surface text-on-surface` everywhere -- no `dark:` variants needed per component.\n\n## Interaction states\n\nMinimum states for buttons: `hover:`, `focus-visible:`, `disabled:`, `transition-colors`. Minimum for inputs: `focus:`, `disabled:`, `placeholder:`. Minimum for links: `hover:`, `focus-visible:`.\n\n```tsx\n// Complete button pattern\n<button className={cn(\n  \"px-4 py-2 rounded font-medium transition-colors\",\n  \"bg-blue-600 text-white\",\n  \"hover:bg-blue-700\",\n  \"focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-blue-600\",\n  \"disabled:opacity-50 disabled:cursor-not-allowed\",\n  \"cursor-pointer\" // v4: Preflight no longer sets cursor:pointer on buttons\n)}>\n```\n\nComplete input pattern:\n\n```tsx\n<input className={cn(\n  \"w-full rounded border px-3 py-2 transition-colors\",\n  \"border-gray-300 bg-white text-gray-900\",\n  \"dark:border-gray-600 dark:bg-gray-800 dark:text-white\",\n  \"placeholder:text-gray-400 dark:placeholder:text-gray-500\",\n  \"focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500\",\n  \"disabled:cursor-not-allowed disabled:bg-gray-100 disabled:opacity-50\",\n)} />\n```\n\nIn v4: `hover:` only fires on hover-capable devices (`@media (hover: hover)`). Touch-only devices skip hover styles entirely -- don''t rely on hover for critical information.\n\n## Accessibility\n\nIcon-only buttons need screen reader text:\n\n```tsx\n<button className=\"p-2 rounded hover:bg-gray-100\">\n  <SearchIcon className=\"h-5 w-5\" aria-hidden=\"true\" />\n  <span className=\"sr-only\">Search</span>\n</button>\n```\n\nSkip links use `sr-only` that becomes visible on focus:\n\n```tsx\n<a href=\"#main\" className=\"sr-only focus:not-sr-only focus:absolute focus:top-4 focus:left-4 focus:z-50 focus:px-4 focus:py-2 focus:bg-white focus:text-black focus:rounded\">\n  Skip to main content\n</a>\n```\n\nEvery focusable element needs a visible focus indicator. `focus-visible:` is preferred over `focus:` -- it only shows for keyboard navigation, not mouse clicks.\n\nEnsure sufficient color contrast on interactive states. A `hover:bg-blue-700` on `bg-blue-600` is barely visible -- test both light and dark modes.\n\n## v4 configuration\n\nIn v4, configuration lives in CSS, not JavaScript. Entry point is `@import \"tailwindcss\"`. Autoprefixer is built-in (don''t add it separately).\n\n```css\n@import \"tailwindcss\";\n\n@theme {\n  --font-display: \"Inter\", sans-serif;\n  --color-brand: #4f46e5;\n  --breakpoint-3xl: 1920px;\n}\n\n@utility card {\n  background: var(--color-surface);\n  border-radius: var(--radius-lg);\n  padding: var(--spacing-6);\n}\n```\n\nKey v4 renames (old names still work via compat but generate warnings):\n\n```\nv3                    v4\nshadow            ->  shadow-sm       ring              ->  ring-3\nshadow-sm         ->  shadow-xs       outline-none      ->  outline-hidden\nrounded           ->  rounded-sm      bg-gradient-to-r  ->  bg-linear-to-r\nrounded-sm        ->  rounded-xs      blur              ->  blur-sm\n```\n\nOther v4 changes inline:\n\n```tsx\n// v3: bg-opacity-50       -> v4: bg-black/50 (opacity modifier)\n// v3: bg-[--brand-color]  -> v4: bg-(--brand-color) (CSS variable syntax)\n// v3: !bg-red-500         -> v4: bg-red-500! (important modifier at end)\n// v3: first:*:pt-0        -> v4: *:first:pt-0 (variant stacking left-to-right)\n```\n\nBorders default to `currentColor` in v4, not `gray-200`. Add explicit border colors if the v3 default was relied upon. Custom utilities via `@utility name {}` not `@layer components {}`. Safelist via `@source inline(\"...\")` not `safelist` array.\n"},"lastSynced":"2026-03-06T07:09:45.159Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing streamlined CSS integration with Tailwind CSS versions 3 and 4.","zh":"非常适合需要简化CSS集成的前端代理，支持Tailwind CSS版本3和4。","ja":"フロントエンドエージェントがストリームライン化されたCSS統合を必要とする場合に最適です。Tailwind CSSバージョン3と4をサポートしています。","ko":"스트림 라인화된 CSS 통합이 필요한 프론트엔드 에이전트에게 적합합니다. Tailwind CSS 버전 3 및 4를 지원합니다.","es":"Perfecto para Agentes Frontend que necesitan una integración de CSS optimizada con Tailwind CSS versiones 3 y 4.","fr":"Parfait pour les agents Frontend qui nécessitent une intégration de CSS rationalisée avec Tailwind CSS versions 3 et 4.","de":"Perfekt für Frontend-Agents, die eine optimierte CSS-Integration mit Tailwind CSS Versionen 3 und 4 benötigen.","pt":"Perfeito para agentes Frontend que necessitam de integração de CSS simplificada com as versões 3 e 4 do Tailwind CSS.","ru":"Идеально подходит для агентов Frontend, которым необходима упрощенная интеграция CSS с версиями 3 и 4 Tailwind CSS.","ar":"مثالي لعميل واجهة المستخدم الأمامية الذي يحتاج إلى دمج CSS مبسط مع الإصدارات 3 و 4 من Tailwind CSS."},"recommendation":{"en":"Empowers agents to match project conventions and infer local styles using `tailwind.config.js`, `@tailwindcss/postcss7`, and `@tailwindcss/vite` dependencies, streamlining the development process with `@import tailwindcss` and `@theme {}` blocks.","zh":"赋予代理匹配项目约定并使用`tailwind.config.js`、`@tailwindcss/postcss7`和`@tailwindcss/vite`依赖项来推断本地样式，使用`@import tailwindcss`和`@theme {}`块简化开发过程。","ja":"エージェントにプロジェクトの規約にマッチし、`tailwind.config.js`、`@tailwindcss/postcss7`、`@tailwindcss/vite`依存関係を使用してローカルスタイルを推論する権限を付与し、`@import tailwindcss`および`@theme {}`ブロックを使用して開発プロセスを簡素化します。","ko":"에이전트가 프로젝트 규약과 일치시키고 `tailwind.config.js`, `@tailwindcss/postcss7`, `@tailwindcss/vite` 의존성을 사용하여 로컬 스타일을 추론할 수 있도록 하며, `@import tailwindcss` 및 `@theme {}` 블록을 사용하여 개발 프로세스를 간소화합니다.","es":"Habilita a los agentes a coincidir con las convenciones del proyecto e inferir estilos locales utilizando las dependencias `tailwind.config.js`, `@tailwindcss/postcss7` y `@tailwindcss/vite`, racionalizando el proceso de desarrollo con bloques `@import tailwindcss` y `@theme {}`.","fr":"Permet aux agents de correspondre aux conventions de projet et d''inférer des styles locaux en utilisant les dépendances `tailwind.config.js`, `@tailwindcss/postcss7` et `@tailwindcss/vite`, rationalisant le processus de développement avec des blocs `@import tailwindcss` et `@theme {}`.","de":"Ermöglicht es den Agenten, den Projektvorgaben zu entsprechen und lokale Stile unter Verwendung der Abhängigkeiten `tailwind.config.js`, `@tailwindcss/postcss7` und `@tailwindcss/vite` abzuleiten, wodurch der Entwicklungsprozess mit `@import tailwindcss`- und `@theme {}`-Blöcken rationalisiert wird.","pt":"Habilita os agentes a corresponder às convenções do projeto e inferir estilos locais usando as dependências `tailwind.config.js`, `@tailwindcss/postcss7` e `@tailwindcss/vite`, simplificando o processo de desenvolvimento com blocos `@import tailwindcss` e `@theme {}`.","ru":"Позволяет агентам соответствовать проектным конвенциям и выводить местные стили, используя зависимости `tailwind.config.js`, `@tailwindcss/postcss7` и `@tailwindcss/vite`, упрощая процесс разработки с блоками `@import tailwindcss` и `@theme {}`.","ar":"تمكين العميل من مطابقة اتفاقيات المشروع واستنتاج الأساليب المحلية باستخدام الإعتماديات `tailwind.config.js` و `@tailwindcss/postcss7` و `@tailwindcss/vite`، وبذلك يبسّط عملية التطوير باستخدام كتلة `@import tailwindcss` و `@theme {}`."},"useCases":{"en":["Inferring local CSS styles from existing components","Integrating Tailwind CSS into projects with established conventions","Detecting Tailwind CSS versions using `package.json` and CSS directives","Automating CSS coding with Tailwind CSS v3 and v4 signals"],"zh":["从现有组件中推断本地CSS样式","将Tailwind CSS集成到具有既定约定的项目中","使用`package.json`和CSS指令检测Tailwind CSS版本","使用Tailwind CSS v3和v4信号自动CSS编码"],"ja":["既存のコンポーネントからローカルCSSスタイルを推論する","既存の規約を持つプロジェクトにTailwind CSSを統合する","`package.json`とCSSディレクティブを使用してTailwind CSSバージョンを検出する","Tailwind CSS v3およびv4シグナルを使用してCSSコードを自動化する"],"ko":["기존 컴포넌트에서 로컬 CSS 스타일을 추론하는 것","既存 규약을 가진 프로젝트에 Tailwind CSS를 통합하는 것","`package.json` 및 CSS 지시문을 사용하여 Tailwind CSS 버전을 감지하는 것","Tailwind CSS v3 및 v4 신호를 사용하여 CSS 코딩을 자동화하는 것"],"es":["Inferir estilos CSS locales a partir de componentes existentes","Integrar Tailwind CSS en proyectos con convenciones establecidas","Detectar versiones de Tailwind CSS mediante `package.json` y directivas CSS","Automatizar la codificación de CSS con señales de Tailwind CSS v3 y v4"],"fr":["Inférer des styles CSS locaux à partir de composants existants","Intégrer Tailwind CSS dans des projets avec des conventions établies","Détecter les versions de Tailwind CSS à l''aide de `package.json` et de directives CSS","Automatiser la codification de CSS avec des signaux de Tailwind CSS v3 et v4"],"de":["Lokale CSS-Stile aus bestehenden Komponenten ableiten","Tailwind CSS in Projekten mit etablierten Vorgaben integrieren","Tailwind-CSS-Versionen mithilfe von `package.json` und CSS-Direktiven erkennen","CSS-Codierung mit Tailwind-CSS-v3- und v4-Signalen automatisieren"],"pt":["Inferir estilos CSS locais a partir de componentes existentes","Integrar o Tailwind CSS em projetos com convenções estabelecidas","Detectar versões do Tailwind CSS usando `package.json` e diretivas CSS","Automatizar a codificação CSS com sinais do Tailwind CSS v3 e v4"],"ru":["Выводить местные CSS-стили из существующих компонентов","Интегрировать Tailwind CSS в проекты с устоявшимися конвенциями","Обнаруживать версии Tailwind CSS, используя `package.json` и директивы CSS","Автоматизировать кодирование CSS с помощью сигналов Tailwind CSS v3 и v4"],"ar":["استنتاج أساليب CSS المحلية من المكونات الحالية","دمج Tailwind CSS في المشاريع ذات الاتفاقيات المعروفة","كشف إصدارات Tailwind CSS باستخدام `package.json` وإرشادات CSS","تأتميم ترميز CSS باستخدام إشارات Tailwind CSS الإصدار 3 والإصدار 4"]},"limitations":{"en":["Requires access to project''s `package.json` and CSS files","Limited to Tailwind CSS versions 3 and 4","Needs existing components to infer local styles"],"zh":["需要访问项目的`package.json`和CSS文件","仅限Tailwind CSS版本3和4","需要现有组件来推断本地样式"],"ja":["プロジェクトの`package.json`とCSSファイルへのアクセスが必要","Tailwind CSSバージョン3と4に限定される","ローカルスタイルを推論するために既存のコンポーネントが必要"],"ko":["프로젝트의 `package.json` 및 CSS 파일에 대한 액세스가 필요합니다.","Tailwind CSS 버전 3 및 4로 제한됩니다.","로컬 스타일을 추론하기 위해 기존 컴포넌트가 필요합니다."],"es":["Requiere acceso al archivo `package.json` y a los archivos CSS del proyecto","Limitado a versiones de Tailwind CSS 3 y 4","Necesita componentes existentes para inferir estilos locales"],"fr":["Nécessite un accès au fichier `package.json` et aux fichiers CSS du projet","Limité aux versions de Tailwind CSS 3 et 4","Nécessite des composants existants pour inférer des styles locaux"],"de":["Benötigt Zugriff auf die Datei `package.json` und die CSS-Dateien des Projekts","Begrenzt auf Tailwind-CSS-Versionen 3 und 4","Benötigt bestehende Komponenten, um lokale Stile abzuleiten"],"pt":["Exige acesso ao arquivo `package.json` e aos arquivos CSS do projeto","Limitado às versões 3 e 4 do Tailwind CSS","Necessita de componentes existentes para inferir estilos locais"],"ru":["Требует доступа к файлу `package.json` и файлам CSS проекта","Ограничен версиями 3 и 4 Tailwind CSS","Требует существующих компонентов для вывода местных стилей"],"ar":["يتطلب الوصول إلى ملف `package.json` وملفات CSS للمشروع","محدود بالإصدارات 3 و 4 من Tailwind CSS","يحتاج إلى مكونات موجودة لاستنتاج الأساليب المحلية"]},"version":4},"contentHash":"016c5b9aa42c13f5ad252f03be235ae7398c0ab4c1b5afc181d