INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Dynokostya/just-works/tailwind-css-coding', 'tailwind-css-coding', 'Dynokostya', 'just-works', 'community', 'tailwind-css-coding Dynokostya just-works community The tailwind-css-coding skill provides instructions for integrating Tailwind CSS into any project, helping developers match existing conventions and infer local styles. This skill benefits developers working with Tailwind CSS versions 3 and 4. Tailwind CSS 编码设置指南，帮助您在项目中集成 Tailwind CSS Tailwind CSS コーディングセットアップガイド - プロジェクトに Tailwind CSS を統合する Tailwind CSS 코딩 설정 가이드 - 프로젝트에 Tailwind CSS를 통합하는 Tailwind CSS Coding es un conjunto de instrucciones para integrar Tailwind CSS en cualquier proyecto, siguiendo las convenciones existentes Tailwind CSS Coding est un ensemble d''instructions pour intégrer Tailwind CSS dans n''importe quel projet, en suivant les conventions existantes Tailwind CSS Coding ist ein Satz von Anweisungen, um Tailwind CSS in jedes Projekt zu integrieren, unter Berücksichtigung der bestehenden Konventionen O Tailwind CSS Coding é um conjunto de instruções para instalar a base de código Claude em qualquer projeto, seguindo as convenções existentes. Tailwind CSS Coding — это набор инструкций для установки базы кода Claude в любом проекте, соответствующий существующим соглашениям. Tailwind CSS Coding هو مجموعة من الإرشادات لتثبيت قاعدة كود كلود في أي مشروع، متوافق مع الاتفاقيات الحالية. how to use tailwind-css-coding tailwind-css-coding setup guide tailwind-css-coding vs bootstrap tailwind-css-coding install what is tailwind-css-coding tailwind-css-coding alternative tailwindcss version 4 tailwindcss version 3 tailwind css coding tutorial Tailwind CSS AI智能工具 编码设置 项目集成 版本检测 样式兼容性 前端开发 CSS 框架 Checks package.json for tailwindcss version Identifies v4 signals via @tailwindcss/postcss or @tailwindcss/vite dependencies Detects v3 signals through tailwind.config.js and autoprefixer Matches project''s existing conventions Infers local style by reading existing components Supports Tailwind CSS versions 3 and 4 tailwind-css-coding is a set of instructions for installing and integrating Tailwind CSS into a project, following existing conventions and styles');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ThiNepo/prompt-caller/framework-selection', 'community', 'ThiNepo', 'prompt-caller', 'ThiNepo/prompt-caller', 'framework-selection', 2, 0, 39, '2026-03-06T12:20:10Z', '2026-03-06T13:08:02.798Z', '3dd7830abba0c0194942d4bcdc083d2d2e401d0127a919737c6cc43ebc652520', '{"id":"ThiNepo/prompt-caller/framework-selection","name":"framework-selection","description":{"en":"The framework-selection skill enables AI agents to call prompts in a specific format using LangChain and OpenAI API, benefiting developers with layered architecture needs.","zh":"框架选择技能提供 LangChain 和 OpenAI API 的集成，用于构建高性能的 AI 代理","ja":"フレームワーク選択スキルは、LangChain と OpenAI API を組み合わせて、高パフォーマンスの AI エージェントを構築するために使用されます","ko":"프레임워크 선택 스킬은 LangChain 및 OpenAI API를 결합하여 고성능의 AI 에이전트를 구축하는 데 사용됩니다","es":"El paquete de framework-selection utiliza LangChain y OpenAI API para llamar a prompts en un formato específico.","fr":"Le package framework-selection utilise LangChain et OpenAI API pour appeler des prompts dans un format spécifique.","de":"Das framework-selection-Paket verwendet LangChain und OpenAI API, um Prompts in einem bestimmten Format aufzurufen.","pt":"O framework-selection é um pacote que utiliza LangChain e OpenAI API para chamar prompts em um formato específico, permitindo a seleção do framework correto para agentes de IA.","ru":"Фреймворк-селекция - это пакет, который использует LangChain и OpenAI API для вызова промтов в определенном формате, позволяя выбрать правильный фреймворк для ИИ агентов.","ar":"الإطار العمل للاختيار هو حزمة تستخدم LangChain و OpenAI API لدعوة الإشارات في تنسيق محدد، مما يسمح باختيار الإطار العمل المناسب لعمليات الذكاء الاصطناعي."},"seo":{"title":{"en":"framework-selection: LangChain Integration Setup Guide | ...","zh":"框架选择指南：LangChain 和 OpenAI API 集成","ja":"フレームワーク選択のベストプラクティス：LangChain と OpenAI API","ko":"프레임워크 선택 가이드: LangChain 및 OpenAI API 통합","es":"Guía de Selección de Framework para Agentes de IA","fr":"Guide de Sélection de Framework pour les Agents d''IA","de":"Framework-Auswahl-Leitfaden für KI-Agents","pt":"Guia de Seleção de Frameworks para Agentes de IA","ru":"Выбор Фреймворка для ИИ Агентов: Руководство","ar":"دليل اختيار الإطار العمل لعمليات الذكاء الاصطناعي"},"description":{"en":"Discover how to leverage framework-selection for AI agents, utilizing LangChain and OpenAI API for layered architecture benefits - get started now!","zh":"了解如何选择合适的框架，实现 LangChain 和 OpenAI API 的无缝集成，提升 AI 代理的性能","ja":"LangChain と OpenAI API を組み合わせたフレームワーク選択の方法を学び、AI エージェントのパフォーマンスを向上させましょう","ko":"LangChain 및 OpenAI API를 결합한 프레임워크 선택 방법을 알아보고 AI 에이전트의 성능을 향상시키세요","es":"Descubre cómo seleccionar el framework perfecto para tus agentes de IA con LangChain y OpenAI API. Mejora la eficiencia de tus proyectos de desarrollo.","fr":"Découvrez comment sélectionner le framework idéal pour vos agents d''IA avec LangChain et OpenAI API. Améliorez l''efficacité de vos projets de développement.","de":"Erfahren Sie, wie Sie das perfekte Framework für Ihre KI-Agents mit LangChain und OpenAI API auswählen. Verbessern Sie die Effizienz Ihrer Entwicklungsvorhaben.","pt":"Aprenda a selecionar o framework correto para seus agentes de IA com LangChain e OpenAI API. Melhore a eficiência e escalabilidade de seus projetos","ru":"Узнайте, как выбрать правильный фреймворк для ваших ИИ агентов с помощью LangChain и OpenAI API. Улучшите эффективность и масштабируемость ваших проектов","ar":"تعرف على كيفية اختيار الإطار العمل المناسب لعمليات الذكاء الاصطناعي باستخدام LangChain و OpenAI API. تحسين الكفاءة وال قابليّة التوسّع لمشاريعك"},"definition":{"en":"framework-selection is a package responsible for calling prompts in a specific format, utilizing LangChain, LangGraph, and Deep Agents for layered architecture","zh":"框架选择是指为 AI 代理选择合适的技术框架，例如 LangChain 和 OpenAI API","ja":"フレームワーク選択とは、AI エージェントに適した技術フレームワークを選択することです。たとえば、LangChain と OpenAI API など","ko":"프레임워크 선택은 AI 에이전트에 적합한 기술 프레임워크를 선택하는 것을 의미합니다. 예를 들어, LangChain 및 OpenAI API 등","es":"El framework-selection es un paquete que utiliza LangChain y OpenAI API para llamar a prompts en un formato específico.","fr":"Le framework-selection est un package qui utilise LangChain et OpenAI API pour appeler des prompts dans un format spécifique.","de":"Das framework-selection ist ein Paket, das LangChain und OpenAI API verwendet, um Prompts in einem bestimmten Format aufzurufen.","pt":"O framework-selection é uma técnica de seleção de frameworks para agentes de IA que utiliza LangChain e OpenAI API.","ru":"Фреймворк-селекция - это техника выбора фреймворков для ИИ агентов, которая использует LangChain и OpenAI API.","ar":"الإطار العمل للاختيار هو تقنية لاختيار الإطارات العمل لعمليات الذكاء الاصطناعي التي تستخدم LangChain و OpenAI API."},"features":{"en":["Utilizes LangChain for prompt calling","Integrates with OpenAI API for advanced capabilities","Supports layered architecture with Deep Agents","Employs LangGraph for orchestration and state management","Manages nodes, edges, and state for persistence","Enables batteries-included functionality with Deep Agents"],"zh":["LangChain 和 OpenAI API 的集成","支持 Deep Agents、LangGraph 和层次结构","提供节点、边和状态的持久化","实现计划、内存和技能的管理","支持文件和图的操作"],"ja":["LangChain と OpenAI API の統合","Deep Agents、LangGraph、層構造のサポート","ノード、エッジ、状態の永続化","計画、メモリ、スキルの管理","ファイルとグラフの操作のサポート"],"ko":["LangChain 및 OpenAI API의 통합","Deep Agents, LangGraph 및 계층 구조 지원","노드, 에지, 상태의 영속화","계획, 메모리, 스킬의 관리","파일 및 그래프의操作 지원"],"es":["Utiliza LangChain para la gestión de prompts","Integra OpenAI API para capacidades de IA avanzadas","Soporta la creación de grafos y nodos con LangGraph","Permite la persistencia de estado con Deep Agents","Incluye capacidades de planificación y memoria para agentes de IA"],"fr":["Utilise LangChain pour la gestion de prompts","Intègre OpenAI API pour des capacités d''IA avancées","Prend en charge la création de graphes et de nœuds avec LangGraph","Permet la persistance de l''état avec Deep Agents","Inclut des capacités de planification et de mémoire pour les agents d''IA"],"de":["Verwendet LangChain für die Verwaltung von Prompts","Integriert OpenAI API für erweiterte KI-Fähigkeiten","Unterstützt die Erstellung von Graphen und Knoten mit LangGraph","Ermöglicht die Persistenz von Zuständen mit Deep Agents","Beinhaltet Planungs- und Speicherfunktionen für KI-Agents"],"pt":["Utiliza LangChain para chamar prompts em um formato específico","Integração com OpenAI API para melhorar a eficiência","Permite a seleção do framework correto para agentes de IA","Suporta a criação de grafos e loops com LangGraph","Inclui recursos de planejamento, memória e habilidades com Deep Agents"],"ru":["Использует LangChain для вызова промтов в определенном формате","Интеграция с OpenAI API для улучшения эффективности","Позволяет выбрать правильный фреймворк для ИИ агентов","Поддерживает создание графов и циклов с LangGraph","Включает функции планирования, памяти и навыков с Deep Agents"],"ar":["تستخدم LangChain لدعوة الإشارات في تنسيق محدد","التكامل مع OpenAI API لتحسين الكفاءة","تمكن من اختيار الإطار العمل المناسب لعمليات الذكاء الاصطناعي","يدعم إنشاء الرسوم البيانية والدوائر مع LangGraph","يضم ميزات التخطيط والذاكرة والمهارات مع Deep Agents"]},"keywords":{"en":["how to use framework-selection","framework-selection alternative","framework-selection vs LangGraph","framework-selection install","framework-selection setup guide","what is framework-selection","framework-selection LangChain integration","framework-selection OpenAI API"],"zh":["AI 代理","LangChain","OpenAI API","框架选择","Deep Agents","LangGraph","层次结构","AI 工具","技术框架"],"ja":["AI エージェント","LangChain","OpenAI API","フレームワーク選択","Deep Agents","LangGraph","層構造","AI ツール","技術フレームワーク"],"ko":["AI 에이전트","LangChain","OpenAI API","프레임워크 선택","Deep Agents","LangGraph","계층 구조","AI 도구","기술 프레임워크"],"es":["agentes de IA","framework de IA","LangChain","OpenAI API","desarrollo de IA","framework-selection","IA avanzada","desarrollo de agentes de IA"],"fr":["agents d''IA","framework d''IA","LangChain","OpenAI API","développement d''IA","framework-selection","IA avancée","développement d''agents d''IA"],"de":["KI-Agents","KI-Framework","LangChain","OpenAI API","KI-Entwicklung","framework-selection","erweiterte KI","KI-Agents-Entwicklung"],"pt":["framework-selection","agentes de IA","LangChain","OpenAI API","seleção de frameworks","desenvolvimento de IA","tecnologias de IA","aplicativos de IA","soluções de IA"],"ru":["фреймворк-селекция","ИИ агенты","LangChain","OpenAI API","выбор фреймворков","разработка ИИ","технологии ИИ","приложения ИИ","решения ИИ"],"ar":["اختيار الإطار العمل","عمليات الذكاء الاصطناعي","LangChain","OpenAI API","اختيار الإطارات العمل","تطوير الذكاء الاصطناعي","تكنولوجيا الذكاء الاصطناعي","تطبيقات الذكاء الاصطناعي","حلول الذكاء الاصطناعي"]}},"owner":"ThiNepo","repo":"prompt-caller","repoPath":"ThiNepo/prompt-caller","stars":2,"forks":0,"updatedAt":"2026-03-06T12:20:10Z","topics":[],"category":"community","skillMd":{"name":"framework-selection","description":"INVOKE THIS SKILL at the START of any LangChain/LangGraph/Deep Agents project, before writing any agent code. Determines which framework layer is right for the task: LangChain, LangGraph, Deep Agents, or a combination. Must be consulted before other agent skills.","bodyPreview":"<overview>\nLangChain, LangGraph, and Deep Agents are **layered**, not competing choices. Each builds on the one below it:\n\n```\n┌─────────────────────────────────────────┐\n│              Deep Agents                │  ← highest level: batteries included\n│   (planning, memory, skills, files)     │\n├─────────────────────────────────────────┤\n│               LangGraph                 │  ← orchestration: graphs, loops, state\n│    (nodes, edges, state, persistence)   │\n├────────────────────────────────","body":"<overview>\nLangChain, LangGraph, and Deep Agents are **layered**, not competing choices. Each builds on the one below it:\n\n```\n┌─────────────────────────────────────────┐\n│              Deep Agents                │  ← highest level: batteries included\n│   (planning, memory, skills, files)     │\n├─────────────────────────────────────────┤\n│               LangGraph                 │  ← orchestration: graphs, loops, state\n│    (nodes, edges, state, persistence)   │\n├─────────────────────────────────────────┤\n│               LangChain                 │  ← foundation: models, tools, chains\n│      (models, tools, prompts, RAG)      │\n└─────────────────────────────────────────┘\n```\n\nPicking a higher layer does not cut you off from lower layers — you can use LangGraph graphs inside Deep Agents, and LangChain primitives inside both.\n\n> **This skill should be loaded at the top of any project before selecting other skills or writing agent code.** The framework you choose dictates which other skills to invoke next.\n</overview>\n\n---\n\n## Decision Guide\n\n<decision-table>\n\nAnswer these questions in order:\n\n| Question | Yes → | No → |\n|----------|-------|-------|\n| Does the task require breaking work into sub-tasks, managing files across a long session, persistent memory, or loading on-demand skills? | **Deep Agents** | ↓ |\n| Does the task require complex control flow — loops, dynamic branching, parallel workers, human-in-the-loop, or custom state? | **LangGraph** | ↓ |\n| Is this a single-purpose agent that takes input, runs tools, and returns a result? | **LangChain** (`create_agent`) | ↓ |\n| Is this a pure model call, chain, or retrieval pipeline with no agent loop? | **LangChain** (LCEL / chain) | — |\n\n</decision-table>\n\n---\n\n## Framework Profiles\n\n<langchain-profile>\n\n### LangChain — Use when the task is focused and self-contained\n\n**Best for:**\n- Single-purpose agents that use a fixed set of tools\n- RAG pipelines and document Q&A\n- Model calls, prompt templates, output parsing\n- Quick prototypes where agent logic is simple\n\n**Not ideal when:**\n- The agent needs to plan across many steps\n- State needs to persist across multiple sessions\n- Control flow is conditional or iterative\n\n**Skills to invoke next:** `langchain-models`, `langchain-rag`, `langchain-middleware`\n\n</langchain-profile>\n\n<langgraph-profile>\n\n### LangGraph — Use when you need to own the control flow\n\n**Best for:**\n- Agents with branching logic or loops (e.g. retry-until-correct, reflection)\n- Multi-step workflows where different paths depend on intermediate results\n- Human-in-the-loop approval at specific steps\n- Parallel fan-out / fan-in (map-reduce patterns)\n- Persistent state across invocations within a session\n\n**Not ideal when:**\n- You want planning, file management, and subagent delegation handled for you (use Deep Agents instead)\n- The workflow is straightforward enough for a simple agent\n\n**Skills to invoke next:** `langgraph-fundamentals`, `langgraph-human-in-the-loop`, `langgraph-persistence`\n\n</langgraph-profile>\n\n<deep-agents-profile>\n\n### Deep Agents — Use when the task is open-ended and multi-dimensional\n\n**Best for:**\n- Long-running tasks that require breaking work into a todo list\n- Agents that need to read, write, and manage files across a session\n- Delegating subtasks to specialized subagents\n- Loading domain-specific skills on demand\n- Persistent memory that survives across multiple sessions\n\n**Not ideal when:**\n- The task is simple enough for a single-purpose agent\n- You need precise, hand-crafted control over every graph edge (use LangGraph directly)\n\n**Middleware — built-in and extensible:**\n\nDeep Agents ships with a built-in middleware layer out of the box — you configure it, you don''t implement it. The following come pre-wired; you can also add your own on top:\n\n| Middleware | What it provides | Always on? |\n|------------|-----------------|------------|\n| `TodoListMiddleware` | `write_todos` tool — agent plans and tracks multi-step tasks | ✓ |\n| `FilesystemMiddleware` | `ls`, `read_file`, `write_file`, `edit_file`, `glob`, `grep` tools | ✓ |\n| `SubAgentMiddleware` | `task` tool — delegate work to named subagents | ✓ |\n| `SkillsMiddleware` | Load SKILL.md files on demand from a skills directory | Opt-in |\n| `MemoryMiddleware` | Long-term memory across sessions via a `Store` instance | Opt-in |\n| `HumanInTheLoopMiddleware` | Interrupt and request human approval before sensitive tool calls | Opt-in |\n\n**Skills to invoke next:** `deep-agents-core`, `deep-agents-memory`, `deep-agents-orchestration`\n\n</deep-agents-profile>\n\n---\n\n## Mixing Layers\n\n<mixing-layers>\nBecause the frameworks are layered, they can be combined in the same project. The most common pattern is using Deep Agents as the top-level orchestrator while dropping down to LangGraph for specialized subagents.\n\n### When to mix\n\n| Scenario | Recommended pattern |\n|----------|---------------------|\n| Main agent needs planning + memory, but one subtask requires precise graph control | Deep Agents orchestrator → LangGraph subagent |\n| Specialized pipeline (e.g. RAG, reflection loop) is called by a broader agent | LangGraph graph wrapped as a tool or subagent |\n| High-level coordination but low-level graph for a specific domain | Deep Agents + LangGraph compiled graph as a subagent |\n\n### How it works in practice\n\nA LangGraph compiled graph can be registered as a subagent inside Deep Agents. This means you can build a tightly-controlled LangGraph workflow (e.g. a retrieval-and-verify loop) and hand it off to the Deep Agents `task` tool as a named subagent — the Deep Agents orchestrator delegates to it without caring about its internal graph structure.\n\nLangChain tools, chains, and retrievers can be used freely inside both LangGraph nodes and Deep Agents tools — they are the shared building blocks at every level.\n\n</mixing-layers>\n\n---\n\n## Quick Reference\n\n<quick-reference>\n\n| | LangChain | LangGraph | Deep Agents |\n|---|-----------|-----------|-------------|\n| **Control flow** | Fixed (tool loop) | Custom (graph) | Managed (middleware) |\n| **Middleware layer** | Callbacks only | ✗ None | ✓ Explicit, configurable |\n| **Planning** | ✗ | Manual | ✓ TodoListMiddleware |\n| **File management** | ✗ | Manual | ✓ FilesystemMiddleware |\n| **Persistent memory** | ✗ | With checkpointer | ✓ MemoryMiddleware |\n| **Subagent delegation** | ✗ | Manual | ✓ SubAgentMiddleware |\n| **On-demand skills** | ✗ | ✗ | ✓ SkillsMiddleware |\n| **Human-in-the-loop** | ✗ | Manual interrupt | ✓ HumanInTheLoopMiddleware |\n| **Custom graph edges** | ✗ | ✓ Full control | Limited |\n| **Setup complexity** | Low | Medium | Low |\n| **Flexibility** | Medium | High | Medium |\n\n> **Middleware is a concept specific to LangChain (callbacks) and Deep Agents (explicit middleware layer). LangGraph has no middleware — you wire behavior directly into nodes and edges.**\n\n</quick-reference>\n"},"lastSynced":"2026-03-06T13:08:02.798Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents requiring structured framework integration, such as those built with LangChain and OpenAI API, to streamline development with layered architecture needs.","zh":"适合需要结构化框架集成的AI代理，例如使用LangChain和OpenAI API构建的代理，以实现具有分层架构需求的开发简化。","ja":"LangChainやOpenAI APIを使用して構築されたエージェントなど、構造化フレームワーク統合を必要とするAIエージェントに最適です。レイヤードアーキテクチャのニーズを備えた開発の簡素化を実現します。","ko":"LangChain 및 OpenAI API와 같은 구조화된 프레임워크 통합이 필요한 AI 에이전트에 적합합니다. 계층화된 아키텍처 요구 사항이 있는 개발을 간소화하는 데 도움이 됩니다.","es":"Ideal para agentes de IA que requieren integración de framework estructurada, como aquellos construidos con LangChain y OpenAI API, para agilizar el desarrollo con necesidades de arquitectura en capas.","fr":"Idéal pour les agents IA nécessitant une intégration de framework structurée, tels que ceux construits avec LangChain et OpenAI API, pour rationaliser le développement avec des besoins d''architecture en couches.","de":"Ideal für KI-Agents, die eine strukturierte Framework-Integration benötigen, wie z.B. solche, die mit LangChain und OpenAI API erstellt wurden, um die Entwicklung mit schichtbasierten Architektur-Anforderungen zu rationalisieren.","pt":"Ideal para Agentes de IA que requerem integração de estrutura de trabalho estruturada, como aqueles construídos com LangChain e OpenAI API, para agilizar o desenvolvimento com necessidades de arquitetura em camadas.","ru":"Идеально для агентов ИИ, требующих структурированной интеграции фреймворка, таких как те, которые построены с помощью LangChain и OpenAI API, для упрощения разработки с потребностями в многослойной архитектуре.","ar":"مثالي لعميل الذكاء الاصطناعي الذي يتطلب تكامل إطار عمل منظم ، مثل تلك التي تم بناؤها باستخدام LangChain و OpenAI API ، لتسريع التطوير مع احتياجات هيكلية متعددة الطبقات."},"recommendation":{"en":"Empowers agents to orchestrate complex tasks using LangGraph''s nodes, edges, and state persistence, while leveraging Deep Agents'' planning, memory, and skills for comprehensive framework selection and integration, utilizing protocols like OpenAI API for seamless interaction.","zh":"赋予代理使用LangGraph的节点、边和状态持久性编排复杂任务的能力，同时利用Deep Agents的规划、内存和技能进行全面框架选择和集成，利用OpenAI API等协议实现无缝交互。","ja":"LangGraphのノード、エッジ、状態の永続性を使用して複雑なタスクをオーケストレーションするエージェントの能力を提供し、Deep Agentsのプランニング、メモリ、スキルを利用して包括的なフレームワークの選択と統合を行い、OpenAI APIなどのプロトコルを使用してシームレスな相互作用を実現します。","ko":"LangGraph의 노드, 엣지, 상태 지속성을 사용하여 복잡한 작업을 오케스트레이션할 수 있는 에이전트의 능력을 부여하며, Deep Agents의 계획, 메모리, 스킬을 활용하여 포괄적인 프레임워크 선택 및 통합을 수행하며, OpenAI API와 같은 프로토콜을 사용하여 무결점 상호 작용을 구현합니다.","es":"Habilita a los agentes a orquestar tareas complejas utilizando los nodos, bordes y persistencia de estado de LangGraph, al mismo tiempo que aprovecha la planificación, la memoria y las habilidades de Deep Agents para una selección e integración de framework integral, utilizando protocolos como OpenAI API para una interacción sin problemas.","fr":"Permet aux agents d''orchestrer des tâches complexes en utilisant les nœuds, les arêtes et la persistance d''état de LangGraph, tout en exploitant la planification, la mémoire et les compétences de Deep Agents pour une sélection et une intégration de framework complètes, en utilisant des protocoles comme OpenAI API pour une interaction sans accroc.","de":"Ermöglicht es Agenten, komplexe Aufgaben mithilfe der Knoten, Kanten und Zustandspersistenz von LangGraph zu orchestrieren, während gleichzeitig die Planung, das Gedächtnis und die Fähigkeiten von Deep Agents für eine umfassende Framework-Auswahl und -Integration genutzt werden, unter Nutzung von Protokollen wie OpenAI API für eine nahtlose Interaktion.","pt":"Habilita os agentes a orquestrar tarefas complexas usando os nós, arestas e persistência de estado do LangGraph, ao mesmo tempo em que aproveita os planos, memória e habilidades dos Deep Agents para uma seleção e integração de estrutura de trabalho abrangente, utilizando protocolos como OpenAI API para interação sem problemas.","ru":"Наделяет агентов возможностью оркестрировать сложные задачи с помощью узлов, ребер и сохранения состояния LangGraph, при этом используя планирование, память и навыки Deep Agents для всестороннего выбора и интеграции фреймворка, используя протоколы như OpenAI API для бесшовного взаимодействия.","ar":"يمنح الوكلاء القدرة على تنسيق المهام المعقدة باستخدام العقد والهوامش وثبات الحالة من LangGraph ، وفي نفس الوقت يستفيد من التخطيط والذاكرة والمهارات من عميل عميق للتحديد الشامل وتكامل الإطار ، باستخدام بروتوكولات مثل OpenAI API للتفاعل السلس."},"useCases":{"en":["Integrating LangChain with OpenAI API for advanced prompt management","Orchestrating layered architecture with LangGraph for efficient task management","Utilizing Deep Agents for skills and memory management in framework selection"],"zh":["将LangChain与OpenAI API集成以实现高级提示管理","使用LangGraph编排分层架构以实现高效的任务管理","利用Deep Agents进行技能和内存管理以实现框架选择"],"ja":["LangChainとOpenAI APIを統合して高度なプロンプト管理を実現する","LangGraphを使用してレイヤードアーキテクチャをオーケストレーションしてタスク管理を効率化する","Deep Agentsを使用してスキルとメモリ管理を実行して包括的なフレームワークの選択と統合を実現する"],"ko":["LangChain과 OpenAI API를 통합하여 고급 프롬프트 관리를 구현하는 것","LangGraph를 사용하여 계층화된 아키텍처를 오케스트레이션하여 작업 관리를 효율화하는 것","Deep Agents를 사용하여 스킬과 메모리 관리를 수행하여 포괄적인 프레임워크 선택 및 통합을 구현하는 것"],"es":["Integración de LangChain con OpenAI API para una gestión avanzada de solicitudes","Orquestación de arquitectura en capas con LangGraph para una gestión eficiente de tareas","Utilización de Deep Agents para la gestión de habilidades y memoria en la selección de framework"],"fr":["Intégration de LangChain avec OpenAI API pour une gestion avancée des invites","Orchestration d''une architecture en couches avec LangGraph pour une gestion efficace des tâches","Utilisation de Deep Agents pour la gestion des compétences et de la mémoire dans la sélection de framework"],"de":["Integration von LangChain mit OpenAI API für ein erweitertes Anfrage-Management","Orchestrierung einer schichtbasierten Architektur mit LangGraph für ein effizientes Aufgaben-Management","Nutzen von Deep Agents für die Verwaltung von Fähigkeiten und Gedächtnis bei der Framework-Auswahl"],"pt":["Integrar LangChain com OpenAI API para gerenciamento de prompts avançado","Orquestrar arquitetura em camadas com LangGraph para gerenciamento de tarefas eficiente","Utilizar Deep Agents para gerenciamento de habilidades e memória na seleção de estrutura de trabalho"],"ru":["Интегрировать LangChain с OpenAI API для продвинутого управления подсказками","Оркестрировать многослойную архитектуру с помощью LangGraph для эффективного управления задачами","Использовать Deep Agents для управления навыками и памятью при выборе фреймворка"],"ar":["دمج LangChain مع OpenAI API لإدارة العرض المسبق المتقدم","تنسيق هيكل متعدد الطبقات مع LangGraph لإدارة المهمات الفعالة","استخدام عميل عميق لإدارة المهارات والذاكرة في اختيار الإطار"]},"limitations":{"en":["Requires LangChain and OpenAI API integration","Dependent on layered architecture compatibility","Needs understanding of LangGraph, Deep Agents, and OpenAI API protocols"],"zh":["需要LangChain和OpenAI API集成","依赖于分层架构的兼容性","需要理解LangGraph、Deep Agents和OpenAI API协议"],"ja":["LangChainとOpenAI APIの統合が必要","レイヤードアーキテクチャの互換性に依存","LangGraph、Deep Agents、OpenAI APIのプロトコルの理解が必要"],"ko":["LangChain 및 OpenAI API 통합이 필요함","계층화된 아키텍처의 호환성에 의존함","LangGraph, Deep Agents, OpenAI API 프로토콜의 이해가 필요함"],"es":["Requiere integración de LangChain y OpenAI API","Dependiente de la compatibilidad de la arquitectura en capas","Necesita comprensión de los protocolos de LangGraph, Deep Agents y OpenAI API"],"fr":["Nécessite une intégration de LangChain et OpenAI API","Dépendante de la compatibilité de l''architecture en couches","Nécessite une compréhension des protocoles de LangGraph, Deep Agents et OpenAI API"],"de":["Benötigt Integration von LangChain und OpenAI API","Abhängig von der Kompatibilität der schichtbasierten Architektur","Benötigt Verständnis für die Protokolle von LangGraph, Deep Agents und OpenAI API"],"pt":["Requer integração de LangChain e OpenAI API","Dependente da compatibilidade da arquitetura em camadas","Precisa de compreensão dos protocolos LangGraph, Deep Agents e OpenAI API"],"ru":["Требует интеграции LangChain и OpenAI API","Зависит от совместимости многослойной архитектуры","Требует понимания протоколов LangGraph, Deep Agents и OpenAI API"],"ar":["يتطلب تكامل LangChain و OpenAI API","يعتمد على توافق هيكل متعدد الطبقات","يحتاج إلى فهم بروتوكولات LangGraph وعميل عميق و OpenAI API"]},"version":4},"contentHash":"3dd7830abba0c0194942d4bcdc083d2d2e401d0127a919737c6cc43ebc652520","qualityScore":39}');
