INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ThiNepo/prompt-caller/framework-selection', 'framework-selection', 'ThiNepo', 'prompt-caller', 'community', 'framework-selection ThiNepo prompt-caller community The framework-selection skill enables AI agents to call prompts in a specific format using LangChain and OpenAI API, benefiting developers with layered architecture needs. 框架选择技能提供 LangChain 和 OpenAI API 的集成，用于构建高性能的 AI 代理 フレームワーク選択スキルは、LangChain と OpenAI API を組み合わせて、高パフォーマンスの AI エージェントを構築するために使用されます 프레임워크 선택 스킬은 LangChain 및 OpenAI API를 결합하여 고성능의 AI 에이전트를 구축하는 데 사용됩니다 El paquete de framework-selection utiliza LangChain y OpenAI API para llamar a prompts en un formato específico. Le package framework-selection utilise LangChain et OpenAI API pour appeler des prompts dans un format spécifique. Das framework-selection-Paket verwendet LangChain und OpenAI API, um Prompts in einem bestimmten Format aufzurufen. O framework-selection é um pacote que utiliza LangChain e OpenAI API para chamar prompts em um formato específico, permitindo a seleção do framework correto para agentes de IA. Фреймворк-селекция - это пакет, который использует LangChain и OpenAI API для вызова промтов в определенном формате, позволяя выбрать правильный фреймворк для ИИ агентов. الإطار العمل للاختيار هو حزمة تستخدم LangChain و OpenAI API لدعوة الإشارات في تنسيق محدد، مما يسمح باختيار الإطار العمل المناسب لعمليات الذكاء الاصطناعي. how to use framework-selection framework-selection alternative framework-selection vs LangGraph framework-selection install framework-selection setup guide what is framework-selection framework-selection LangChain integration framework-selection OpenAI API AI 代理 LangChain OpenAI API 框架选择 Deep Agents LangGraph 层次结构 AI 工具 技术框架 Utilizes LangChain for prompt calling Integrates with OpenAI API for advanced capabilities Supports layered architecture with Deep Agents Employs LangGraph for orchestration and state management Manages nodes, edges, and state for persistence Enables batteries-included functionality with Deep Agents framework-selection is a package responsible for calling prompts in a specific format, utilizing LangChain, LangGraph, and Deep Agents for layered architecture');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dzhechko/2026-jan-pu-manusim-clone-01/explore', 'community', 'dzhechko', '2026-jan-pu-manusim-clone-01', 'dzhechko/2026-jan-pu-manusim-clone-01', 'explore', 1, 1, 39, '2026-02-24T08:49:58Z', '2026-03-06T07:10:25.474Z', 'abb15a03ebf08bf7396f915177cf776dbc30f2ae17fdcbc4c7b396fbe6453572', '{"id":"dzhechko/2026-jan-pu-manusim-clone-01/explore","name":"explore","description":{"en":"Explore is a skill that helps AI agents transform vague requests into crystal-clear task specifications through systematic questioning. It benefits developers by ensuring the real problem is understood before proposing a solution.","zh":"Explore 技术通过系统化的 Socratic 问题解决，实现任务明确化和适应性任务阐明","ja":"Explore 機能は、システム化されたソクラテス式の質問でタスクを明確化し、AIエージェントによる適応性タスク阐明を実現","ko":"Explore 기술은 시스템적인 소크라테스식 질문으로 태스크를 명확하게 하고 적응형 태스크 명확화를 실현","es":"Explore utiliza preguntas socráticas para aclarar tareas y garantizar que se entiende el problema real antes de proponer una solución.","fr":"Explore utilise des questions socratiques pour clarifier les tâches et s''assurer que le problème réel est compris avant de proposer une solution.","de":"Explore nutzt socratische Fragen, um Aufgaben zu klären und sicherzustellen, dass das eigentliche Problem verstanden wird, bevor eine Lösung vorgeschlagen wird.","pt":"O Explore é uma habilidade que utiliza questionamento socrático para esclarecer tarefas, garantindo que o problema real seja entendido antes de qualquer solução.","ru":"ИИ Агент Explore - это навык, который использует систематическое сократическое вопросование для уточнения задач, обеспечивая понимание реальной проблемы перед предложением любого решения.","ar":"استكشاف هو مهارة تستخدم الاستفسار السقراطي لتوضيح المهام، مما يضمن فهم المشكلة الحقيقية قبل تقديم أي حل."},"seo":{"title":{"en":"Explore: Adaptive Task Clarification Setup Guide | AI Age...","zh":"Explore Setup Guide: 适应性任务阐明技术","ja":"Explore ベストプラクティス: AIエージェントによるタスク明確化","ko":"Explore 사용자 가이드: 적응형 태스크 명확화 기술","es":"Guía de configuración de Explore: Clarificación de tareas...","fr":"Guide de démarrage de Explore : Clarification de tâches a...","de":"Einrichtungsleitfaden für Explore: Adaptive Aufgabenklärung","pt":"Guia de Configuração do Explore: Esclarecimento de Tarefa...","ru":"Настройка ИИ Агента Explore: Адаптивное Уточнение Задач","ar":"دليل إعداد استكشاف: توضيح مهام قابل للتكيف"},"description":{"en":"Transform vague requests into clear task specs with Explore''s Socratic questioning. Learn how to unlock understanding and reveal hidden assumptions.","zh":"了解 Explore 技术，实现任务明确化和系统化的 Socratic 问题解决","ja":"AIエージェントの Explore 機能を利用して、タスクを明確化し、システム化されたソクラテス式の質問で問題を解決","ko":"Explore 기술을 사용하여 태스크를 명확하게 하고 시스템적인 소크라테스식 질문으로 문제를 해결","es":"Descubre cómo Explore utiliza preguntas socráticas para transformar solicitudes vagas en especificaciones de tareas claras y acciónables","fr":"Découvrez comment Explore utilise des questions socratiques pour transformer des demandes vagues en spécifications de tâches claires et actionnables","de":"Erfahren Sie, wie Explore mithilfe socratischer Fragen vage Anfragen in klare und umsetzbare Aufgabenspezifikationen umwandelt","pt":"Aprenda a transformar solicitações vagas em especificações de tarefas claras e ação com o Explore, utilizando questionamento socrático sistemático.","ru":"Изучите, как превратить неясные запросы в четкие и действенные спецификации задач с помощью ИИ Агента Explore и систематического сократического вопросования.","ar":"تعرف على كيفية تحويل الطلبات الغامضة إلى مواصفات مهام واضحة وقابلة للتنفيذ باستخدام استكشاف والاستفسار السقراطي المنظم."},"definition":{"en":"Explore is an adaptive task clarification skill that uses Socratic questioning to unlock understanding and reveal hidden assumptions in task specifications.","zh":"Explore 是一种适应性任务阐明技术，通过系统化的 Socratic 问题解决实现任务明确化","ja":"Explore は、AIエージェントによる適応性タスク阐明技術で、システム化されたソクラテス式の質問でタスクを明確化","ko":"Explore 는 적응형 태스크 명확화 기술로 시스템적인 소크라테스식 질문으로 태스크를 명확하게 함","es":"Explore es una habilidad de agente de inteligencia artificial que utiliza preguntas socráticas para aclarar tareas y entender el problema real","fr":"Explore est une compétence d''agent d''intelligence artificielle qui utilise des questions socratiques pour clarifier les tâches et comprendre le problème réel","de":"Explore ist eine Fähigkeit von künstlichen Intelligenz-Agenten, die socratische Fragen verwendet, um Aufgaben zu klären und das eigentliche Problem zu verstehen","pt":"O Explore é uma habilidade de esclarecimento de tarefas adaptativo que utiliza questionamento socrático para entender o problema real.","ru":"ИИ Агент Explore - это адаптивное уточнение задач, которое использует систематическое сократическое вопросование для понимания реальной проблемы.","ar":"استكشاف هو مهارة لتوضيح المهام قابل للتكيف يستخدم الاستفسار السقراطي لفهم المشكلة الحقيقية."},"features":{"en":["Utilizes systematic Socratic questioning to clarify task specifications","Employs the core philosophy of never solving before understanding","Reveals hidden assumptions and constraints in task requests","Unlocks understanding through questions, rather than relying on answers","Ensures the real problem is understood before proposing a solution","Applies key principles to transform vague requests into actionable task specs"],"zh":["系统化的 Socratic 问题解决","适应性任务阐明","任务明确化","Constraints revealer"," Questions unlock understanding"],"ja":["システム化されたソクラテス式の質問","AIエージェントによる適応性タスク阐明","タスク明確化","Constraints revealer","質問による理解の解放"],"ko":["시스템적인 소크라테스식 질문","적응형 태스크 명확화","태스크 명확화","Constraints revealer","질문으로 이해를 열어라"],"es":["Preguntas socráticas para aclarar tareas","Análisis de constraints para revelar oportunidades","Identificación de objetivos reales más allá de los objetivos declarados","Uso de la filosofía de nunca resolver antes de entender","Transformación de solicitudes vagas en especificaciones de tareas claras"],"fr":["Questions socratiques pour clarifier les tâches","Analyse des contraintes pour révéler des opportunités","Identification des objectifs réels au-delà des objectifs déclarés","Utilisation de la philosophie de ne jamais résoudre avant de comprendre","Transformation de demandes vagues en spécifications de tâches claires"],"de":["Socratische Fragen zur Aufgabenklärung","Analyse von Einschränkungen, um Chancen aufzudecken","Identifizierung der tatsächlichen Ziele jenseits der deklarierten Ziele","Anwendung der Philosophie, nie vor dem Verständnis zu lösen","Umwandlung vager Anfragen in klare Aufgabenspezifikationen"],"pt":["Questionamento socrático sistemático para esclarecer tarefas","Transformação de solicitações vagas em especificações de tarefas claras","Garantia de que o problema real seja entendido antes de qualquer solução","Utilização de constraints para revelar oportunidades","Integração com tecnologias de inteligência artificial para melhorar a eficiência"],"ru":["Систематическое сократическое вопросование для уточнения задач","Преобразование неясных запросов в четкие и действенные спецификации задач","Обеспечение понимания реальной проблемы перед предложением любого решения","Использование ограничений для выявления возможностей","Интеграция с технологиями искусственного интеллекта для повышения эффективности"],"ar":["الاستفسار السقراطي المنظم لتوضيح المهام","تحويل الطلبات الغامضة إلى مواصفات مهام واضحة وقابلة للتنفيذ","ضمان فهم المشكلة الحقيقية قبل تقديم أي حل","استخدام القيود ليكشف الفرص","التكامل مع تقنيات الذكاء الاصطناعي لتحسين الكفاءة"]},"keywords":{"en":["how to use explore","what is explore","explore alternative","explore vs adaptive task clarification","explore install","explore setup guide","socratic questioning for ai agents","task specification clarification","adaptive task clarification tools"],"zh":["Explore 技术","适应性任务阐明","系统化的 Socratic 问题解决","任务明确化","AI 工具","自动化任务处理"],"ja":["Explore 機能","AIエージェント","適応性タスク阐明","システム化されたソクラテス式の質問","タスク明確化","自動化タスク処理"],"ko":["Explore 기술","적응형 태스크 명확화","시스템적인 소크라테스식 질문","태스크 명확화","AI 에이전트","자동화 태스크 처리"],"es":["agente de inteligencia artificial","clarificación de tareas","preguntas socráticas","análisis de constraints","objetivos reales","filosofía de nunca resolver antes de entender","transformación de solicitudes vagas","especificaciones de tareas claras","herramientas de IA","desarrollo de software con IA"],"fr":["agent d''intelligence artificielle","clarification de tâches","questions socratiques","analyse de contraintes","objectifs réels","philosophie de ne jamais résoudre avant de comprendre","transformation de demandes vagues","spécifications de tâches claires","outils d''IA","développement de logiciels avec IA"],"de":["künstlicher Intelligenz-Agent","Aufgabenklärung","socratische Fragen","Analyse von Einschränkungen","tatsächliche Ziele","Philosophie, nie vor dem Verständnis zu lösen","Umwandlung vager Anfragen","klare Aufgabenspezifikationen","KI-Tools","Softwareentwicklung mit KI"],"pt":["Explore","esclarecimento de tarefas","questionamento socrático","inteligência artificial","desenvolvimento de software","técnicas de questionamento","análise de requisitos","desenvolvedores de software","ferramentas de inteligência artificial"],"ru":["ИИ Агент Explore","адаптивное уточнение задач","систематическое сократическое вопросование","искусственный интеллект","разработка программного обеспечения","техники вопросования","анализ требований","разработчики программного обеспечения","инструменты искусственного интеллекта"],"ar":["استكشاف","توضيح المهام","الاستفسار السقراطي","الذكاء الاصطناعي","تطوير البرمجيات","تقنيات الاستفسار","تحليل المتطلبات","مطورو البرمجيات","أدوات الذكاء الاصطناعي"]}},"owner":"dzhechko","repo":"2026-jan-pu-manusim-clone-01","repoPath":"dzhechko/2026-jan-pu-manusim-clone-01","stars":1,"forks":1,"updatedAt":"2026-02-24T08:49:58Z","topics":[],"category":"community","skillMd":{"name":"explore","description":">","bodyPreview":"# Explore: Adaptive Task Clarification\n\nTransform vague requests into crystal-clear, actionable task specifications through systematic Socratic questioning.\n\n## Core Philosophy\n\n**Never solve before you understand.** Most failed solutions solve the wrong problem. This skill ensures the real problem is understood before any solution is proposed.\n\nKey principles:\n- Questions unlock understanding; answers often hide assumptions\n- The stated goal is rarely the real goal\n- Constraints reveal opportun","body":"# Explore: Adaptive Task Clarification\n\nTransform vague requests into crystal-clear, actionable task specifications through systematic Socratic questioning.\n\n## Core Philosophy\n\n**Never solve before you understand.** Most failed solutions solve the wrong problem. This skill ensures the real problem is understood before any solution is proposed.\n\nKey principles:\n- Questions unlock understanding; answers often hide assumptions\n- The stated goal is rarely the real goal\n- Constraints reveal opportunities\n- Success criteria prevent scope creep\n\n## Task Classification\n\nBefore asking questions, classify the task type to select appropriate exploration dimensions:\n\n| Task Type | Indicators | Primary Dimensions |\n|-----------|------------|-------------------|\n| **Product/Feature** | \"build\", \"create app\", \"develop\" | Outcome, Users, Constraints, Success |\n| **Problem Solving** | \"fix\", \"solve\", \"issue with\" | Root Cause, Constraints, Attempted Solutions |\n| **Decision Making** | \"should I\", \"choose between\", \"evaluate\" | Criteria, Tradeoffs, Timeline, Reversibility |\n| **Creative** | \"write\", \"design\", \"make content\" | Audience, Tone, Format, Examples |\n| **Research** | \"find out\", \"analyze\", \"understand\" | Scope, Depth, Sources, Deliverable |\n| **Process/Workflow** | \"how to\", \"improve process\" | Current State, Desired State, Blockers |\n\n## Exploration Dimensions\n\nSelect 3-5 dimensions based on task type. Each dimension has multiple question variants—choose the most natural for context.\n\n### 1. The Real Objective\nUncover what success truly looks like, beyond the stated request.\n\n**Questions:**\n- \"If this worked perfectly, what would be different in your [work/life/business]?\"\n- \"What outcome would make you say ''this was absolutely worth it''?\"\n- \"Is this goal a means to something else, or the end itself?\"\n- \"If you could wave a magic wand and have any result, what would you choose?\"\n\n**Red flags to probe:** Generic goals (\"make it better\"), proxy metrics, solutions presented as requirements.\n\n### 2. Constraints & Boundaries\nIdentify hard limits that shape the solution space.\n\n**Questions:**\n- \"What''s absolutely off the table—budget, time, technology, or approach-wise?\"\n- \"What existing systems, processes, or decisions must this work with?\"\n- \"Who needs to approve this, and what are their non-negotiables?\"\n- \"What would disqualify a solution, even if it technically works?\"\n\n**Red flags to probe:** No constraints mentioned (usually means hidden ones), unrealistic expectations.\n\n### 3. Available Resources\nUnderstand leverage points and existing assets.\n\n**Questions:**\n- \"What do you already have that we could build on—data, tools, people, prior work?\"\n- \"Who else is involved, and what can they contribute?\"\n- \"What similar problems have you solved before, and what worked?\"\n- \"What''s your actual capacity to implement this?\"\n\n**Red flags to probe:** Overestimated capabilities, unacknowledged dependencies.\n\n### 4. Timeline & Urgency\nDistinguish real deadlines from arbitrary ones.\n\n**Questions:**\n- \"What happens if this takes 2x longer than expected?\"\n- \"Is there a hard deadline, and what''s driving it?\"\n- \"Would you prefer a quick 80% solution or a slower 100% solution?\"\n- \"What''s the cost of delay vs. the cost of getting it wrong?\"\n\n**Red flags to probe:** Artificial urgency, no clear driver for deadline.\n\n### 5. Success Criteria\nDefine what \"done\" actually means.\n\n**Questions:**\n- \"How will you know this is successful? What will you measure?\"\n- \"Who decides if this is good enough, and what will they look for?\"\n- \"What''s the minimum viable outcome that would still be valuable?\"\n- \"In 6 months, what would make you regret the approach we took?\"\n\n**Red flags to probe:** Vague criteria (\"stakeholders will be happy\"), moving targets.\n\n### 6. Attempted Solutions (for problems)\nLearn from what hasn''t worked.\n\n**Questions:**\n- \"What have you already tried, and why didn''t it work?\"\n- \"What solutions have you considered but rejected?\"\n- \"What would the obvious solution be, and why isn''t that good enough?\"\n\n### 7. Audience & Stakeholders (for products/content)\nUnderstand who this serves.\n\n**Questions:**\n- \"Who specifically will use this, and what''s their context when they do?\"\n- \"What does your audience already know or believe about this?\"\n- \"Who might be negatively affected, and does that matter?\"\n\n## Execution Protocol\n\n### Phase 1: Initial Assessment (1 turn)\n\n1. Parse the user''s request\n2. Identify what''s already clear from context\n3. Classify task type\n4. Select 3-5 most critical dimensions\n5. Note any immediate red flags or assumptions\n\n### Phase 2: Adaptive Questioning (3-7 turns)\n\n**Rules:**\n- Ask ONE question at a time\n- Make questions specific and decision-shaping, not generic\n- Challenge vague answers: \"Can you be more specific about...?\"\n- Acknowledge answers before next question\n- Skip dimensions already clarified\n- Stop when you have enough to create a clear brief\n\n**Question Sequencing:**\n1. Start with Real Objective (reveals the most)\n2. Follow with Constraints (narrows solution space)\n3. Then Success Criteria (defines done)\n4. Fill gaps with other dimensions as needed\n\n**Adaptive behavior:**\n- If user gives detailed answer → compress follow-ups\n- If user seems frustrated → summarize and ask if they want to continue\n- If contradiction detected → gently probe: \"Earlier you mentioned X, but now Y—help me understand?\"\n\n### Phase 3: Task Brief Synthesis (1 turn)\n\nAfter sufficient exploration, synthesize into a **Task Brief**:\n\n```\n## Task Brief\n\n**Objective:** [Clear statement of what we''re actually solving]\n\n**Context:** [Relevant background and constraints]\n\n**Success Criteria:**\n- [Measurable criterion 1]\n- [Measurable criterion 2]\n\n**Constraints:**\n- [Hard constraint 1]\n- [Hard constraint 2]\n\n**Resources Available:** [What we can leverage]\n\n**Timeline:** [Deadline and urgency level]\n\n**Key Assumptions:** [Things we''re assuming that could change the approach]\n\n**Out of Scope:** [Explicitly excluded items]\n```\n\nAsk user: \"Does this capture what you need? Anything to add or correct?\"\n\n### Phase 4: Handoff\n\nOnce validated, either:\n- Proceed to solution (if user wants immediate help)\n- Export brief for later use\n- Suggest appropriate next steps/skills\n\n## Anti-Patterns to Avoid\n\n❌ **Interrogation mode:** Don''t fire questions robotically\n❌ **Assuming context:** Don''t skip clarification because you \"think\" you understand\n❌ **Premature solutions:** Don''t hint at solutions before exploration is complete\n❌ **Over-questioning:** Stop when you have enough clarity\n❌ **Generic questions:** Each question should be tailored to this specific task\n❌ **Ignoring signals:** If user provides info proactively, don''t re-ask\n\n## Example Flow\n\n**User:** \"I want to create a dashboard for my team\"\n\n**Claude (Phase 1 assessment):**\n- Task type: Product/Feature\n- Unclear: Who uses it, what data, what decisions it enables, timeline\n- Dimensions needed: Real Objective, Audience, Constraints, Success Criteria\n\n**Claude:** \"Before we dive in—what decisions will your team make differently once they have this dashboard? What''s the main insight they''re missing today?\"\n\n*[User answers about tracking project delays]*\n\n**Claude:** \"Got it—so the core need is visibility into project health to catch delays early. How do you know a project is delayed today? What''s the current process for catching these issues?\"\n\n*[Continues adaptively based on answers...]*\n\n## Integration Notes\n\nAfter exploration, this skill can hand off to:\n- problem-solver-enhanced (for complex problems)\n- goap-research (for research tasks)\n- frontend-design (for UI/product tasks)\n- Any implementation skill with the structured Task Brief\n"},"lastSynced":"2026-03-06T07:10:25.474Z","agentAnalysis":{"suitability":{"en":"Ideal for Conversational AI Agents like Cursor, Windsurf, and Claude Code needing advanced task clarification capabilities through Socratic questioning.","zh":"适合于需要高级任务阐明能力的对话式 AI 代理，如 Cursor、Windsurf 和 Claude Code，通过苏格拉底式提问实现任务阐明。","ja":"Cursor、Windsurf、Claude Code などの会話型 AI エージェントが、ソクラティックな質問を通じて高度なタスクの明確化能力を必要とする場合に最適です。","ko":"Cursor, Windsurf, Claude Code 등의 대화형 AI 에이전트가 소크라테스식 질문을 통해 고급 태스크澄清 능력이 필요한 경우에 적합합니다.","es":"Ideal para agentes de IA Conversacional como Cursor, Windsurf y Claude Code que necesitan capacidades avanzadas de clarificación de tareas a través de preguntas socráticas.","fr":"Idéal pour les agents d''IA Conversationnels comme Cursor, Windsurf et Claude Code nécessitant des capacités de clarification de tâches avancées via des questions socratiques.","de":"Ideal für Conversational AI-Agents wie Cursor, Windsurf und Claude Code, die erweiterte Aufgabenklärungsfähigkeiten durch sokratisches Fragen benötigen.","pt":"Ideal para Agentes de IA Conversacional como Cursor, Windsurf e Claude Code que necessitam de capacidades avançadas de esclarecimento de tarefas por meio de questionamento socrático.","ru":"Идеально для разговорных агентов ИИ, таких как Cursor, Windsurf и Claude Code, которые требуют продвинутых возможностей по уточнению задач с помощью сократического вопроса.","ar":"مثالي لوكلاء الذكاء الاصطناعي للتعاملات مثل Cursor و Windsurf و Claude Code الذين يحتاجون إلى قدرات متقدمة لتوضيح المهام من خلال الاستفهام السقراطي."},"recommendation":{"en":"Empowers agents to transform vague requests into crystal-clear task specifications using systematic questioning, unlocking understanding and revealing constraints through adaptive task clarification protocols like systematic Socratic questioning.","zh":"赋予代理能力，通过系统性质问，将模糊的请求转化为清晰的任务规范，解锁理解并通过自适应任务阐明协议如系统性苏格拉底式提问揭示约束。","ja":"エージェントに、体系的な質問を通じて、漠然としたリクエストを明確なタスクの仕様に変換する能力を与え、理解を解放し、適応的なタスクの明確化プロトコルを通じて制約を明らかにします。","ko":"에이전트에 능력을 부여하여 체계적인 질문을 통해 모호한 요청을 명확한 태스크 사양으로 변환하고, 이해를 해방하며, 적응형 태스크澄清 프로토콜을 통해 제약을 밝히는 데 사용됩니다.","es":"Habilita a los agentes a transformar solicitudes vagas en especificaciones de tareas cristalinamente claras utilizando preguntas sistemáticas, desbloqueando la comprensión y revelando restricciones a través de protocolos de clarificación de tareas adaptativos como preguntas socráticas sistemáticas.","fr":"Permet aux agents de transformer des demandes vagues en spécifications de tâches cristallinement claires en utilisant des questions systématiques, débloquant la compréhension et révélant les contraintes à travers des protocoles de clarification de tâches adaptatifs comme des questions socratiques systématiques.","de":"Ermächtigt die Agenten, vage Anfragen in kristallklare Aufgabenbeschreibungen umzuwandeln, indem sie systematische Fragen verwenden, das Verständnis freigeben und Einschränkungen durch adaptive Aufgabenklärungsprotokolle wie systematische sokratische Fragen aufdecken.","pt":"Habilita os agentes a transformar solicitações vagas em especificações de tarefas cristalinamente claras usando questionamento sistemático, desbloqueando a compreensão e revelando restrições por meio de protocolos de esclarecimento de tarefas adaptativos como o questionamento socrático sistemático.","ru":"Наделяет агентов возможностью превратить расплывчатые запросы в кристально чистые задачи с помощью системного вопроса, разблокируя понимание и раскрывая ограничения посредством адаптивных протоколов уточнения задач, таких как системное сократическое вопрос.","ar":"تمكن الوكلاء من تحويل الطلبات الغامضة إلى مواصفات المهام واضحة như البلور باستخدام الاستفهام المنهجي، وفك شفرة الفهم و كشف القيود من خلال بروتوكولات توضيح المهام التكيفية مثل الاستفهام السقراطي المنهجي."},"useCases":{"en":["Clarifying ambiguous user requests","Identifying hidden assumptions in task specifications","Revealing opportunistic constraints for efficient problem-solving"],"zh":["阐明模糊的用户请求","识别任务规范中的隐含假设","揭示机会约束以实现高效问题解决"],"ja":["あいまいなユーザーのリクエストを明確化する","タスクの仕様における隠れた仮定を特定する","効率的な問題解決のために機会的制約を明らかにする"],"ko":["모호한 사용자 요청을澄清하는 것","태스크 사양中的 내재된 가정들을 식별하는 것","효율적인 문제 해결을 위한 기회 제약을 밝히는 것"],"es":["Clarificar solicitudes de usuarios ambiguas","Identificar suposiciones ocultas en las especificaciones de tareas","Revelar restricciones oportunistas para la resolución eficiente de problemas"],"fr":["Clarifier les demandes d''utilisateurs ambigües","Identifier les hypothèses cachées dans les spécifications de tâches","Révéler les contraintes opportunistes pour une résolution de problèmes efficace"],"de":["Ambigue Benutzeranfragen klären","Versteckte Annahmen in Aufgabenbeschreibungen identifizieren","Gelegenheitsbedingungen für effizientes Problemlösen aufdecken"],"pt":["Esclarecer solicitações de usuário ambíguas","Identificar suposições ocultas nas especificações de tarefas","Revelar restrições oportunistas para resolução eficiente de problemas"],"ru":["Уточнение неоднозначных запросов пользователей","Определение скрытых предположений в задачах","Раскрытие возможных ограничений для эффективного решения проблем"],"ar":["توضيح طلبات المستخدم الغامضة","تحديد الفرضيات الخفية في مواصفات المهام","كشف القيود الفرصية لل حل الكفء للمشكلات"]},"limitations":{"en":["Requires iterative user interaction","May not be effective for extremely vague or open-ended requests"],"zh":["需要迭代的用户交互","可能不适用于极其模糊或开放式的请求"],"ja":["反復的なユーザーのやり取りが必要","非常にあいまいな、またはオープンエンドのリクエストには効果的ではない可能性がある"],"ko":["반복적인 사용자 상호작용이 필요","극도로 모호하거나 개방형 요청에는 효과적이지 않을 수 있음"],"es":["Requiere interacción iterativa del usuario","Puede no ser efectivo para solicitudes extremadamente vagas o abiertas"],"fr":["Nécessite une interaction itérative de l''utilisateur","Peut ne pas être efficace pour des demandes extrêmement vagues ou ouvertes"],"de":["Benötigt iterative Benutzerinteraktion","Kann für extrem vage oder offene Anfragen nicht effektiv sein"],"pt":["Exige interação iterativa do usuário","Pode não ser eficaz para solicitações extremamente vagas ou abertas"],"ru":["Требует итеративного взаимодействия с пользователем","Может быть неэффективным для чрезвычайно расплывчатых или открытых запросов"],"ar":["يتطلب تفاعل متكرر من المستخدم","يمكن أن لا يكون فعالا للغاية对于 الطلبات الغامضة أو المفتوحة بشكل كبير"]},"version":4},"contentHash":"abb15a03ebf08bf7396f915177cf776dbc30f2ae17fdcbc4c7b396fbe6453572","qualityScore":39}');
DELETE FROM skills_fts WHERE id = 'dzhechko/2026-jan-pu-manusim-clone-01/explore';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dzhechko/2026-jan-pu-manusim-clone-01/explore', 'explore', 'dzhechko', '2026-jan-pu-manusim-clone-01', 'community', 'explore dzhechko 2026-jan-pu-manusim-clone-01 community Explore is a skill that helps AI agents transform vague requests into crystal-clear task specifications through systematic questioning. It benefits developers by ensuring the real problem is understood before proposing a solution. Explore 技术通过系统化的 Socratic 问题解决，实现任务明确化和适应性任务阐明 Explore 機能は、システム化されたソクラテス式の質問でタスクを明確化し、AIエージェントによる適応性タスク阐明を実現 Explore 기술은 시스템적인 소크라테스식 질문으로 태스크를 명확하게 하고 적응형 태스크 명확화를 실현 Explore utiliza preguntas socráticas para aclarar tareas y garantizar que se entiende el problema real antes de proponer una solución. Explore utilise des questions socratiques pour clarifier les tâches et s''assurer que le problème réel est compris avant de proposer une solution. Explore nutzt socratische Fragen, um Aufgaben zu klären und sicherzustellen, dass das eigentliche Problem verstanden wird, bevor eine Lösung vorgeschlagen wird. O Explore é uma habilidade que utiliza questionamento socrático para esclarecer tarefas, garantindo que o problema real seja entendido antes de qualquer solução. ИИ Агент Explore - это навык, который использует систематическое сократическое вопросование для уточнения задач, обеспечивая понимание реальной проблемы перед предложением любого решения. استكشاف هو مهارة تستخدم الاستفسار السقراطي لتوضيح المهام، مما يضمن فهم المشكلة الحقيقية قبل تقديم أي حل. how to use explore what is explore explore alternative explore vs adaptive task clarification explore install explore setup guide socratic questioning for ai agents task specification clarification adaptive task clarification tools Explore 技术 适应性任务阐明 系统化的 Socratic 问题解决 任务明确化 AI 工具 自动化任务处理 Utilizes systematic Socratic questioning to clarify task specifications Employs the core philosophy of never solving before understanding Reveals hidden assumptions and constraints in task requests Unlocks understanding through questions, rather than relying on answers Ensures the real problem is understood before proposing a solution Applies key principles to transform vague requests into actionable task specs Explore is an adaptive task clarification skill that uses Socratic questioning to unlock understanding and reveal hidden assumptions in task specifications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('DaccordProject/daccord/spring-clean', 'community', 'DaccordProject', 'daccord', 'DaccordProject/daccord', 'spring-clean', 1, 0, 39, '2026-03-06T12:18:48Z', '2026-03-06T13:11:26.495Z', 'da4c5dc2feaae78fa35ba28d0dd6c46dc318a54de847ac0886210abe542297f4', '{"id":"DaccordProject/daccord/spring-clean","name":"spring-clean","description":{"en":"spring-clean is a free, open-source chat app for communities that automates codebase refactoring. It benefits developers by providing a streamlined workflow for fixing issues and running unit tests.","zh":"Spring-Clean 是一个免费的开源聊天应用程序，用于社区。它提供了运行单元测试和调试的功能，帮助开发者提高代码质量","ja":"Spring-Clean はコミュニティ向けの無料オープンソースチャットアプリです。単体テストの実行とデバッグ機能を提供し、開発者のコード品質を向上させます","ko":"Spring-Clean은 커뮤니티를 위한 무료 오픈소스 채팅 애플리케이션입니다. 단위 테스트 실행 및 디버깅 기능을 제공하여 개발자의 코드 품질을 향상시킵니다","es":"spring-clean es una herramienta de código abierto para comunidades que permite a los desarrolladores realizar pruebas unitarias y depuración de forma eficiente","fr":"spring-clean est un outil open-source pour les communautés qui permet aux développeurs d''exécuter des tests unitaires et de déboguer de manière efficace","de":"spring-clean ist ein Open-Source-Tool für Communities, das es Entwicklern ermöglicht, Einheitstests und Fehlersuche effizient durchzuführen","pt":"O spring-clean é uma ferramenta de limpeza de código para comunidades que ajuda a melhorar a qualidade do código com testes unitários.","ru":"Spring-clean - это инструмент для очистки кодовой базы для сообществ ИИ Агентов, который помогает улучшить качество кода с помощью юнит-тестов.","ar":"spring-clean هو أداة تنظيف الكود لمجتمعات الإي آي التي تساعد على تحسين جودة الكود مع الاختبارات الوحدية."},"seo":{"title":{"en":"spring-clean: Automated Codebase Refactoring for AI Agent...","zh":"Spring-Clean 代码优化工具：测试和调试指南","ja":"Spring-Clean Setup Guide: AIエージェントによるテストとデバッグ","ko":"Spring-Clean 코드 정리 도구: 테스트 및 디버깅 가이드","es":"Guía de configuración de spring-clean para desarrolladores","fr":"Guide de mise en place de spring-clean pour les développeurs","de":"Einrichtungsleitfaden für spring-clean für Entwickler","pt":"Guia de Configuração do spring-clean: Ferramenta de Limpe...","ru":"Настройка spring-clean: Инструмент для Очистки Кодовой Ба...","ar":"إعدادspring-clean: أداة تنظيف الكود لمجتمعات الإي آي"},"description":{"en":"Discover how to streamline your codebase with spring-clean. Learn to fix issues and run unit tests with ease. Get started now and improve your development wo...","zh":"使用 Spring-Clean 代码优化工具，通过运行单元测试和调试来提高代码质量","ja":"Spring-Clean を使用してコードの品質を向上させる：テストとデバッグのベストプラクティス","ko":"Spring-Clean 코드 정리 도구를 사용하여 코드 품질을 향상시키는 방법: 테스트 및 디버깅","es":"Aprenda a utilizar spring-clean, una herramienta de código abierto para comunidades, y mejore su proyecto con pruebas unitarias y depuración","fr":"Découvrez comment utiliser spring-clean, un outil open-source pour les communautés, et améliorez votre projet avec des tests unitaires et du débogage","de":"Erfahren Sie, wie Sie spring-clean, ein Open-Source-Tool für Communities, verwenden können, und verbessern Sie Ihr Projekt mit Einheitstests und Fehlersuche","pt":"Aprenda a configurar o spring-clean, uma ferramenta de limpeza de código para comunidades, e melhore a qualidade do seu código com testes unitários","ru":"Узнайте, как настроить spring-clean, инструмент для очистки кодовой базы для сообществ ИИ Агентов, и улучшите качество вашего кода с помощью юнит-тестов","ar":"تعلم كيفية إعداد spring-clean، أداة تنظيف الكود لمجتمعات الإي آي، و تحسين جودة كودك مع الاختبارات الوحدية"},"definition":{"en":"spring-clean is a free, open-source tool for automating codebase refactoring, specifically designed for communities and developers.","zh":"Spring-Clean 是一个代码优化工具，用于运行单元测试和调试","ja":"Spring-Clean はコードの品質を向上させるためのツールで、単体テストの実行とデバッグを提供します","ko":"Spring-Clean은 코드 품질을 향상시키는 도구로 단위 테스트 실행 및 디버깅을 제공합니다","es":"spring-clean es una herramienta de código abierto que permite a los desarrolladores realizar pruebas unitarias y depuración","fr":"spring-clean est un outil open-source qui permet aux développeurs d''exécuter des tests unitaires et de déboguer","de":"spring-clean ist ein Open-Source-Tool, das es Entwicklern ermöglicht, Einheitstests und Fehlersuche durchzuführen","pt":"O que é spring-clean? É uma ferramenta de limpeza de código para comunidades que executa testes unitários para garantir a qualidade do código.","ru":"Что такое spring-clean? Это инструмент для очистки кодовой базы для сообществ ИИ Агентов, который выполняет юнит-тесты для обеспечения качества кода.","ar":"ما هو spring-clean؟ هو أداة تنظيف الكود لمجتمعات الإي آي التي تنفذ الاختبارات الوحدية لضمان جودة الكود."},"features":{"en":["Runs unit tests using ./test.sh unit command","Fixes source code bugs and test expectations","Determines root cause of failing tests","Re-runs ./test.sh for verification","Works through each phase of the daccord codebase refactoring"],"zh":["运行单元测试","调试代码","使用 ./test.sh unit 命令运行测试","支持代码优化和改进","免费开源","社区驱动"],"ja":["単体テストの実行","コードのデバッグ"," ./test.sh unit コマンドを使用してテストを実行","コードの最適化と改善をサポート","無料オープンソース","コミュニティ駆動"],"ko":["단위 테스트 실행","코드 디버깅"," ./test.sh unit 명령을 사용하여 테스트를 실행","코드 최적화 및 개선을 지원","무료 오픈소스","커뮤니티 주도"],"es":["Ejecución de pruebas unitarias con ./test.sh unit","Depuración de código fuente y tests","Corrección de errores en el código fuente y tests","Repetición de pruebas unitarias después de la corrección","Soporte para desarrollo de comunidades"],"fr":["Exécution de tests unitaires avec ./test.sh unit","Débogage de code source et de tests","Correction d''erreurs dans le code source et les tests","Répétition de tests unitaires après correction","Support pour le développement de communautés"],"de":["Ausführung von Einheitstests mit ./test.sh unit","Fehlersuche in Quellcode und Tests","Korrektur von Fehlern im Quellcode und Tests","Wiederholung von Einheitstests nach Korrektur","Unterstützung für Community-Entwicklung"],"pt":["Executa testes unitários com ./test.sh unit","Identifica e corrige problemas no código","Melhora a qualidade do código com testes automatizados","Fornece uma abordagem estruturada para limpeza de código","Permite a execução de testes sem servidor"],"ru":["Выполняет юнит-тесты с ./test.sh unit","Определяет и исправляет проблемы в коде","Улучшает качество кода с помощью автоматизированных тестов","Предоставляет структурированный подход для очистки кодовой базы","Позволяет выполнять тесты без сервера"],"ar":["تنفذ الاختبارات الوحدية مع ./test.sh unit","تحديد ومعالجة المشاكل في الكود","تحسين جودة الكود مع الاختبارات الآلية","توفر نهجًا منظمًا لتنظيف الكود","تمكن من تشغيل الاختبارات بدون خادم"]},"keywords":{"en":["how to use spring-clean","spring-clean setup guide","what is spring-clean","spring-clean alternative","spring-clean vs daccord","spring-clean install","automated codebase refactoring","unit testing with spring-clean","spring-clean for developers"],"zh":["Spring-Clean","代码优化","单元测试","调试","代码质量","开源","社区驱动","聊天应用程序","AI工具"],"ja":["Spring-Clean","コードの品質","単体テスト","デバッグ","コードの最適化","オープンソース","コミュニティ駆動","チャットアプリ","AIエージェント"],"ko":["Spring-Clean","코드 품질","단위 테스트","디버깅","코드 최적화","오픈소스","커뮤니티 주도","채팅 애플리케이션","AI 도구"],"es":["herramientas de código abierto para comunidades","pruebas unitarias","depuración de código","desarrollo de comunidades","spring-clean","tests unitarios","corrección de errores"],"fr":["outils open-source pour les communautés","tests unitaires","débogage de code","développement de communautés","spring-clean","tests unitaires","correction d''erreurs"],"de":["Open-Source-Tools für Communities","Einheitstests","Fehlersuche in Code","Community-Entwicklung","spring-clean","Einheitstests","Fehlerkorrektur"],"pt":["spring-clean","limpeza de código","testes unitários","qualidade de código","ferramenta de limpeza de código","desenvolvimento de software","teste de software","melhoria de código"],"ru":["spring-clean","очистка кодовой базы","юнит-тесты","качество кода","инструмент для очистки кодовой базы","разработка программного обеспечения","тестирование программного обеспечения","улучшение кода","ИИ Агенты"],"ar":["spring-clean","تنظيف الكود","اختبارات وحدية","جودة الكود","أداة تنظيف الكود","تطوير البرمجيات","اختبار البرمجيات","تحسين الكود","الإي آي"]}},"owner":"DaccordProject","repo":"daccord","repoPath":"DaccordProject/daccord","stars":1,"forks":0,"updatedAt":"2026-03-06T12:18:48Z","topics":[],"category":"community","skillMd":{"name":"spring-clean","description":"Run tests, fix lint errors, break down large files, and clean up debug artifacts","bodyPreview":"You are performing a \"spring clean\" of the daccord codebase. Work through each phase in order. Fix issues as you go rather than just reporting them.\n\n## Phase 1: Run Tests\n\nRun the unit tests (no server needed):\n\n```\n./test.sh unit\n```\n\nIf any tests fail:\n1. Read the failing test file and the source file it tests\n2. Determine whether the bug is in the source code or the test\n3. Fix the root cause (prefer fixing source code bugs; only fix tests if the test expectation is wrong)\n4. Re-run `./test.","body":"You are performing a \"spring clean\" of the daccord codebase. Work through each phase in order. Fix issues as you go rather than just reporting them.\n\n## Phase 1: Run Tests\n\nRun the unit tests (no server needed):\n\n```\n./test.sh unit\n```\n\nIf any tests fail:\n1. Read the failing test file and the source file it tests\n2. Determine whether the bug is in the source code or the test\n3. Fix the root cause (prefer fixing source code bugs; only fix tests if the test expectation is wrong)\n4. Re-run `./test.sh unit` to confirm the fix\n\nDo NOT skip failing tests or mark them as expected failures. Every test should pass.\n\n## Phase 2: Run Linter\n\nRun the project linter:\n\n```\nbash lint.sh\n```\n\nReview the output for:\n- **Naming convention violations** -- Rename files/folders to match the project convention (snake_case)\n- **gdlint errors** -- Fix GDScript static analysis issues (unused variables, naming, trailing whitespace, line length, etc.)\n- **Complexity warnings** -- Note any high-complexity functions for Phase 3\n\nFix all lint issues directly in the source files. Re-run `bash lint.sh` to confirm all issues are resolved.\n\n## Phase 3: Break Down Large Files\n\nFind all `.gd` files over 800 lines:\n\n```\nwc -l scripts/**/*.gd scenes/**/*.gd\n```\n\nFor each file over 800 lines:\n1. Read the file and identify logical groupings of functionality\n2. Extract cohesive groups into new files (helper classes, sub-components, or utility scripts)\n3. Update all references to the extracted code\n4. Keep the public API of the original file intact -- other files should not need changes beyond imports\n\nCommon extraction patterns:\n- Large `match` or `if/elif` blocks handling different cases -> separate handler functions or scripts\n- Utility/helper methods that don''t use instance state -> standalone utility script\n- Signal handler methods that form a logical group -> sub-component script\n- Data transformation / parsing logic -> dedicated parser script\n\nDo NOT extract code if it would create circular dependencies or files under ~50 lines.\n\n## Phase 4: Clean Up Debug Logs and Build Artifacts\n\n### Debug logs\nSearch for debug print statements that should not be in production code:\n\n- `print(` statements that are clearly debug/temporary (e.g., \"DEBUG\", \"TODO\", \"FIXME\", \"test\", variable dumps)\n- `print_debug(` calls\n- Commented-out `print(` statements\n\nRemove them. Keep `print(` statements that are intentional logging (error messages, warnings, startup info).\n\nUse your judgement: a `print(\"Error: ...\")` or `push_error(...)` is intentional. A `print(some_variable)` or `print(\"HERE\")` is debug noise.\n\n### Build artifacts\nSearch for and remove:\n- `.import` files for assets that no longer exist\n- Orphaned `.uid` files with no corresponding `.gd` or `.tscn`\n- Temporary files (`*.tmp`, `*.bak`, `*.orig`)\n- Empty directories under `scenes/` and `scripts/`\n\nDo NOT delete:\n- `.godot/` directory contents (managed by Godot)\n- `addons/` directory contents\n- Any file tracked by git that isn''t clearly an artifact\n\n## Phase 5: Verify\n\nAfter all phases:\n1. Run `./test.sh unit` one final time to confirm nothing is broken\n2. Run `bash lint.sh` one final time to confirm it''s clean\n3. Summarize what was done:\n   - Number of test failures fixed\n   - Number of lint issues fixed\n   - Files that were broken down (with before/after line counts)\n   - Debug logs and artifacts removed\n"},"lastSynced":"2026-03-06T13:11:26.495Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Refactoring Agents needing automated unit test execution and codebase analysis.","zh":"非常适合需要自动化单元测试执行和代码库分析的代码重构代理。","ja":"コードのリファクタリングエージェントが自動化されたユニットテストの実行とコードベースの分析を必要とする場合に最適です。","ko":"자동화된 단위 테스트 실행 및 코드베이스 분석이 필요한 코드 리팩토링 에이전트에 적합합니다.","es":"Perfecto para agentes de refactorización de código que necesitan ejecución automática de pruebas unitarias y análisis de código base.","fr":"Parfait pour les agents de refactoring de code nécessitant une exécution automatique de tests unitaires et une analyse de codebase.","de":"Perfekt für Code-Refactoring-Agents, die eine automatisierte Ausführung von Einheitstests und eine Codebase-Analyse benötigen.","pt":"Perfeito para Agentes de Refatoração de Código que necessitam de execução automática de testes unitários e análise de código-fonte.","ru":"Идеально подходит для агентов рефакторинга кода, которым требуется автоматическое выполнение модульных тестов и анализ кодовой базы.","ar":"مثالي لعميل إعادة هيكلة الكود الذي يحتاج إلى تشغيل تلقائي لاختبارات الوحدة وتحليل الكود"},"recommendation":{"en":"Empowers agents to automate codebase refactoring, providing a streamlined workflow for fixing issues and running unit tests using shell scripts like ./test.sh, and fixing root causes of bugs in source code or test files.","zh":"赋予代理自动化代码库重构的能力，提供了一个用于修复问题和使用 shell 脚本（如 ./test.sh）运行单元测试的简化工作流，并修复源代码或测试文件中 bug 的根因。","ja":"エージェントにコードベースのリファクタリングを自動化する力を与え、問題を修正し、シェルスクリプト（例： ./test.sh）を使用してユニットテストを実行するためのストリームライン化されたワークフローを提供し、ソースコードまたはテストファイルのバグの根本原因を修正します。","ko":"에이전트가 코드베이스를 자동화된 리팩토링 할 수 있는 능력을 부여하여 문제를 수정하고 쉘 스크립트(예: ./test.sh)를 사용하여 단위 테스트를 실행하는 위한 스트림 라인化된 워크플로우를 제공하고, 소스 코드 또는 테스트 파일의 버그의 근본 원인을 수정합니다.","es":"Habilita a los agentes a automatizar el refactoring de la codebase, proporcionando un flujo de trabajo optimizado para solucionar problemas y ejecutar pruebas unitarias utilizando scripts de shell como ./test.sh, y solucionar las causas raíz de los errores en el código fuente o en los archivos de prueba.","fr":"Permet aux agents d''automatiser le refactoring de la codebase, fournissant un flux de travail rationalisé pour résoudre les problèmes et exécuter les tests unitaires en utilisant des scripts shell comme ./test.sh, et résoudre les causes profondes des bogues dans le code source ou les fichiers de test.","de":"Ermöglicht es den Agents, die Refactoring der Codebase zu automatisieren, indem ein optimierter Workflow für die Behebung von Problemen und die Ausführung von Einheitstests mithilfe von Shell-Skripten wie ./test.sh bereitgestellt wird, und die Wurzeln der Fehler im Quellcode oder in den Testdateien zu beheben.","pt":"Habilita os agentes a automatizar a refatoração do código-fonte, fornecendo um fluxo de trabalho otimizado para corrigir problemas e executar testes unitários usando scripts de shell como ./test.sh, e corrigir as causas raiz de bugs no código-fonte ou arquivos de teste.","ru":"Позволяет агентам автоматизировать рефакторинг кодовой базы, обеспечивая оптимизированный рабочий процесс для исправления проблем и запуска модульных тестов с помощью скриптов командной строки, таких как ./test.sh, и исправления коренных причин ошибок в исходном коде или файлах тестов.","ar":"تمكين الوكيل من تلقين إعادة هيكلة الكود، وتوفير تدفق عمل متوائم ل修 Problemas تشغيل اختبارات الوحدة باستخدام سكربتات شل مثل ./test.sh، وتصحيح الأسباب الجذرية للأخطاء في الكود أو ملفات الاختبار"},"useCases":{"en":["Automating unit test execution","Debugging failing tests","Refactoring codebases for improved maintainability"],"zh":["自动化单元测试执行","调试失败的测试","重构代码库以提高可维护性"],"ja":["ユニットテストの実行の自動化","失敗したテストのデバッグ","コードベースのリファクタリングによるメンテナンス性の向上"],"ko":["단위 테스트 실행의 자동화","실패한 테스트의 디버깅","코드베이스 리팩토링을 통한 유지 보수성 향상"],"es":["Automatización de la ejecución de pruebas unitarias","Depuración de pruebas fallidas","Refactoring de codebases para una mejor mantenibilidad"],"fr":["Automatisation de l''exécution de tests unitaires","Débogage de tests défaillants","Refactoring de codebases pour une meilleure maintenabilité"],"de":["Automatisierung der Ausführung von Einheitstests","Fehlerbehebung bei fehlgeschlagenen Tests","Refactoring von Codebasen für eine verbesserte Wartbarkeit"],"pt":["Automatizar a execução de testes unitários","Depurar testes com falha","Refatorar código-fonte para melhorar a manutenibilidade"],"ru":["Автоматизировать выполнение модульных тестов","Отлаживать неудачные тесты","Рефакторить кодовую базу для улучшения поддерживаемости"],"ar":["تلقين تشغيل اختبارات الوحدة","تصحيح اختبارات فاشلة","إعادة هيكلة الكود لتحسين الصيانة"]},"limitations":{"en":["Requires shell access for script execution","Limited to unit tests, no server tests supported"],"zh":["需要 shell 访问以执行脚本","仅限于单元测试，不支持服务器测试"],"ja":["スクリプトの実行にはシェルアクセスが必要","ユニットテストのみに限定され、サーバーテストはサポートされません"],"ko":["스크립트 실행을 위해 쉘 접근이 필요","단위 테스트만 지원되며, 서버 테스트는 지원되지 않음"],"es":["Requiere acceso a shell para la ejecución de scripts","Limitado a pruebas unitarias, no se admiten pruebas de servidor"],"fr":["Nécessite un accès shell pour l''exécution de scripts","Limité aux tests unitaires, les tests de serveur ne sont pas pris en charge"],"de":["Benötigt Shell-Zugriff für die Skriptausführung","Begrenzt auf Einheitstests, Server-Tests werden nicht unterstützt"],"pt":["Requer acesso ao shell para execução de scripts","Limitado a testes unitários, sem suporte a testes de servidor"],"ru":["Требует доступа к командной строке для выполнения скриптов","Ограничен модульными тестами, не поддерживает тесты сервера"],"ar":["يتطلب الوصول إلى شل لتشغيل السكربتات","محدود باختبارات الوحدة، بدون دعم لاختبارات الخادم"]},"version":4},"contentHash":"da4c5dc2feaae78fa35ba28d0dd6c46dc318a54de847ac0886210abe542297f4","qualityScore":39}');
