INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('DaccordProject/daccord/spring-clean', 'spring-clean', 'DaccordProject', 'daccord', 'community', 'spring-clean DaccordProject daccord community spring-clean is a free, open-source chat app for communities that automates codebase refactoring. It benefits developers by providing a streamlined workflow for fixing issues and running unit tests. Spring-Clean 是一个免费的开源聊天应用程序，用于社区。它提供了运行单元测试和调试的功能，帮助开发者提高代码质量 Spring-Clean はコミュニティ向けの無料オープンソースチャットアプリです。単体テストの実行とデバッグ機能を提供し、開発者のコード品質を向上させます Spring-Clean은 커뮤니티를 위한 무료 오픈소스 채팅 애플리케이션입니다. 단위 테스트 실행 및 디버깅 기능을 제공하여 개발자의 코드 품질을 향상시킵니다 spring-clean es una herramienta de código abierto para comunidades que permite a los desarrolladores realizar pruebas unitarias y depuración de forma eficiente spring-clean est un outil open-source pour les communautés qui permet aux développeurs d''exécuter des tests unitaires et de déboguer de manière efficace spring-clean ist ein Open-Source-Tool für Communities, das es Entwicklern ermöglicht, Einheitstests und Fehlersuche effizient durchzuführen O spring-clean é uma ferramenta de limpeza de código para comunidades que ajuda a melhorar a qualidade do código com testes unitários. Spring-clean - это инструмент для очистки кодовой базы для сообществ ИИ Агентов, который помогает улучшить качество кода с помощью юнит-тестов. spring-clean هو أداة تنظيف الكود لمجتمعات الإي آي التي تساعد على تحسين جودة الكود مع الاختبارات الوحدية. how to use spring-clean spring-clean setup guide what is spring-clean spring-clean alternative spring-clean vs daccord spring-clean install automated codebase refactoring unit testing with spring-clean spring-clean for developers Spring-Clean 代码优化 单元测试 调试 代码质量 开源 社区驱动 聊天应用程序 AI工具 Runs unit tests using ./test.sh unit command Fixes source code bugs and test expectations Determines root cause of failing tests Re-runs ./test.sh for verification Works through each phase of the daccord codebase refactoring spring-clean is a free, open-source tool for automating codebase refactoring, specifically designed for communities and developers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('johncarpenter/knowledge-base/email-summary', 'community', 'johncarpenter', 'knowledge-base', 'johncarpenter/knowledge-base', 'email-summary', 0, 0, 39, '2026-02-12T17:37:57Z', '2026-03-07T03:41:09.074Z', '960566a6b8a6430fae275eb29183b95c06caf6d3d9c3f1ed8d9bff698f50a8ff', '{"id":"johncarpenter/knowledge-base/email-summary","name":"email-summary","description":{"en":"The email-summary skill automates email processing for developers, summarizing emails from Gmail and Exchange accounts and saving them to local markdown files. It benefits developers by streamlining email management.","zh":"Email Summary是一种自动化邮件摘要工具，支持Gmail和Exchange账户，能够自动化邮件的分类和保存","ja":"Emailサマリーはメールの要約を自動化するツールで、GmailとExchangeアカウントをサポートし、メールの分類と保存を自動化する","ko":"이메일 요약은 이메일 요약을 자동화하는 도구로 Gmail 및 Exchange 계정을 지원하며 이메일의 분류와 저장을 자동화합니다","es":"La habilidad de resumen de correo electrónico resume correos electrónicos de cuentas de Gmail y Exchange configuradas, los categoriza por tipo de acción y los guarda en un archivo markdown local","fr":"La compétence de résumé d''e-mail résume les e-mails des comptes Gmail et Exchange configurés, les catégorise par type d''action et les enregistre dans un fichier markdown local","de":"Die E-Mail-Zusammenfassungs-Fähigkeit fasst E-Mails von konfigurierten Gmail- und Exchange-Konten zusammen, kategorisiert sie nach Aktionstyp und speichert sie in einer lokalen Markdown-Datei","pt":"O Email Summary é uma ferramenta que resume emails de contas do Gmail e Exchange, categorizando-os por tipo de ação e salvando-os em um arquivo Markdown local","ru":"Email Summary - это инструмент, который суммирует письма из аккаунтов Gmail и Exchange, категоризируя их по типу действия и сохраняя в локальный файл Markdown","ar":"ملخص البريد الإلكتروني هو أداة تلخص رسائل البريد الإلكتروني من حسابات جيميل وإكسشينج، وتصنيفها حسب نوع الإجراء وتحويلها إلى ملف ماركداون محلي"},"seo":{"title":{"en":"email-summary: Automated Email Integration Setup Guide | ...","zh":"Email Summary Setup Guide - Gmail & Exchange Integration","ja":"Email サマリーの設定方法 - Gmail & Exchange統合","ko":"이메일 요약 설정 가이드 - Gmail & Exchange 통합","es":"Guía de configuración de resumen de correo electrónico","fr":"Guide de configuration du résumé d''email","de":"E-Mail-Zusammenfassungs-Setup-Leitfaden","pt":"Guia de Configuração de Email Summary - Integração com Gm...","ru":"Настройка Email Summary - Интеграция с Gmail и Exchange д...","ar":"دليل إعداد ملخص البريد الإلكتروني - دمج مع جيميل وإكسشينج..."},"description":{"en":"Discover how to automate email summaries with Gmail and Exchange integration. Learn to categorize emails by action type and save to markdown files with our e...","zh":"使用Email Summary AI工具自动化邮件摘要，支持Gmail和Exchange账户，实现高效的邮件管理","ja":"EmailサマリーAIツールを使用してメールの要約を自動化し、GmailとExchangeアカウントをサポートしてメール管理を効率化する","ko":"이메일 요약 AI 도구를 사용하여 이메일 요약을 자동화하고 Gmail 및 Exchange 계정을 지원하여 이메일 관리를 효율화합니다","es":"Automatice la gestión de correo electrónico con la habilidad de resumen de correo electrónico, compatible con Gmail y Exchange","fr":"Automatisez la gestion des e-mails avec la compétence de résumé d''e-mail, compatible avec Gmail et Exchange","de":"Automatisieren Sie die E-Mail-Verwaltung mit der E-Mail-Zusammenfassungs-Fähigkeit, kompatibel mit Gmail und Exchange","pt":"Aprenda a configurar o Email Summary para resumir emails de contas do Gmail e Exchange, categorizá-los por tipo de ação e salvá-los em um arquivo Markdown local","ru":"Узнайте, как настроить Email Summary для автоматического суммирования писем из аккаунтов Gmail и Exchange, категоризации их по типу действия и сохранения в л...","ar":"تعرف على كيفية إعداد ملخص البريد الإلكتروني لتلخيص رسائل البريد الإلكتروني من حسابات جيميل وإكسشينج، وتصنيفها حسب نوع الإجراء وتحويلها إلى ملف ماركداون محلي"},"definition":{"en":"email-summary is an automated memory system that integrates with Gmail and Exchange to summarize and categorize emails, saving them to markdown files for easy reference.","zh":"Email Summary是一种AI工具，用于自动化邮件的摘要和分类","ja":"Emailサマリーはメールの要約と分類を自動化するAIツール","ko":"이메일 요약은 이메일의 요약과 분류를 자동화하는 AI 도구","es":"La habilidad de resumen de correo electrónico es una herramienta que resume y categoriza correos electrónicos de cuentas de Gmail y Exchange","fr":"La compétence de résumé d''e-mail est un outil qui résume et catégorise les e-mails des comptes Gmail et Exchange","de":"Die E-Mail-Zusammenfassungs-Fähigkeit ist ein Tool, das E-Mails von Gmail- und Exchange-Konten zusammenfasst und kategorisiert","pt":"O que é Email Summary? É uma ferramenta de automação que resume emails de contas do Gmail e Exchange","ru":"Что такое Email Summary? Это инструмент автоматизации, который суммирует письма из аккаунтов Gmail и Exchange","ar":"ما هو ملخص البريد الإلكتروني? هو أداة آلية تلخص رسائل البريد الإلكتروني من حسابات جيميل وإكسشينج"},"features":{"en":["Integrates with Gmail and Exchange accounts using specific tools like mcp__gmail__gmail_list_accounts","Utilizes Gmail query syntax for searching emails with mcp__gmail__gmail_search","Retrieves full email threads by ID using mcp__gmail__gmail_get_thread","Saves summarized emails to local markdown files in operations/emails/","Categorizes emails by action type for organized reference"],"zh":["支持Gmail和Exchange账户","自动化邮件的分类和保存","使用Gmail查询语法搜索邮件","获取完整的邮件线程","将邮件摘要保存到本地Markdown文件"],"ja":["GmailとExchangeアカウントをサポート","メールの分類と保存を自動化","Gmailクエリ構文を使用してメールを検索","完全なメールスレッドを取得","メールの要約をローカルのMarkdownファイルに保存"],"ko":["Gmail 및 Exchange 계정을 지원","이메일의 분류와 저장을 자동화","Gmail 쿼리 구문을 사용하여 이메일을 검색","完整한 이메일 스레드를 가져옵니다","이메일 요약을 로컬 Markdown 파일에 저장"],"es":["Integración con Gmail y Exchange","Resumen de correos electrónicos por tipo de acción","Guardado de resúmenes en archivos markdown locales","Uso de la sintaxis de búsqueda de Gmail","Obtención de hilos de correo electrónico completos por ID"],"fr":["Intégration avec Gmail et Exchange","Résumé d''e-mails par type d''action","Enregistrement des résumés dans des fichiers markdown locaux","Utilisation de la syntaxe de recherche de Gmail","Obtention de threads d''e-mail complets par ID"],"de":["Integration mit Gmail und Exchange","Zusammenfassung von E-Mails nach Aktionstyp","Speicherung von Zusammenfassungen in lokalen Markdown-Dateien","Verwendung der Gmail-Suchsyntax","Abruf von vollständigen E-Mail-Threads per ID"],"pt":["Integração com contas do Gmail","Integração com contas do Exchange","Resumo de emails por tipo de ação","Salvar resumo em arquivo Markdown local","Utilização de sintaxe de consulta do Gmail para busca de emails","Obtenção de threads de email completas por ID"],"ru":["Интеграция с аккаунтами Gmail","Интеграция с аккаунтами Exchange","Суммирование писем по типу действия","Сохранение суммирования в локальный файл Markdown","Использование синтаксиса запроса Gmail для поиска писем","Получение полных-thread писем по ID"],"ar":["دمج مع حسابات جيميل","دمج مع حسابات إكسشينج","تلخيص رسائل البريد الإلكتروني حسب نوع الإجراء","حفظ التلخيص في ملف ماركداون محلي","استخدام بناء جملة بحث جيميل لتحديد رسائل البريد الإلكتروني","الحصول على threads كاملة من رسائل البريد الإلكتروني حسب الرقم التعريفي"]},"keywords":{"en":["how to use email-summary","email-summary setup guide","email-summary vs other automation tools","what is email-summary","email-summary install","gmail and exchange integration","automated email summarization","email-summary alternative","email-summary tutorial"],"zh":["Email Summary","Gmail","Exchange","AI工具","自动化邮件摘要","邮件管理","Emailサマリー","Gmail查询语法"],"ja":["Emailサマリー","Gmail","Exchange","AIツール","メールの要約","メール管理","Emailサマリーの設定方法","Gmailクエリ構文"],"ko":["이메일 요약","Gmail","Exchange","AI 도구","이메일 요약 자동화","이메일 관리","이메일 요약 설정 가이드","Gmail 쿼리 구문"],"es":["herramientas de resumen de correo electrónico","integración de Gmail y Exchange","automatización de correo electrónico","resumen de correo electrónico","gestión de correo electrónico","herramientas de productividad para desarrolladores"],"fr":["outils de résumé d''e-mail","intégration de Gmail et Exchange","automatisation d''e-mail","résumé d''e-mail","gestion d''e-mail","outils de productivité pour développeurs"],"de":["E-Mail-Zusammenfassungs-Tools","Integration von Gmail und Exchange","E-Mail-Automatisierung","E-Mail-Zusammenfassung","E-Mail-Verwaltung","Produktivitäts-Tools für Entwickler"],"pt":["email summary","integração com gmail","integração com exchange","resumo de emails","automatização de emails","ferramenta de automação","gmail api","exchange api","markdown"],"ru":["email summary","интеграция с gmail","интеграция с exchange","суммирование писем","автоматизация писем","инструмент автоматизации","gmail api","exchange api","markdown","ИИ Агенты"],"ar":["ملخص البريد الإلكتروني","دمج مع جيميل","دمج مع إكسشينج","تلخيص رسائل البريد الإلكتروني","آلية البريد الإلكتروني","أداة آلية","جيميل api","إكسشينج api","ماركداون","الأدوات الذكية"]}},"owner":"johncarpenter","repo":"knowledge-base","repoPath":"johncarpenter/knowledge-base","stars":0,"forks":0,"updatedAt":"2026-02-12T17:37:57Z","topics":[],"category":"community","skillMd":{"name":"email-summary","description":">","bodyPreview":"# Email Summary — Gmail & Exchange Integration\n\nSummarize emails from configured Gmail and Exchange accounts, categorize them by action type, and save to a local markdown file in `operations/emails/`.\n\n## Available MCP Tools\n\n### Gmail Tools\n| Tool | Purpose |\n|---|---|\n| `mcp__gmail__gmail_list_accounts` | List configured Gmail accounts |\n| `mcp__gmail__gmail_search` | Search emails with Gmail query syntax |\n| `mcp__gmail__gmail_get_thread` | Get full email thread by ID |\n| `mcp__gmail__gmail_s","body":"# Email Summary — Gmail & Exchange Integration\n\nSummarize emails from configured Gmail and Exchange accounts, categorize them by action type, and save to a local markdown file in `operations/emails/`.\n\n## Available MCP Tools\n\n### Gmail Tools\n| Tool | Purpose |\n|---|---|\n| `mcp__gmail__gmail_list_accounts` | List configured Gmail accounts |\n| `mcp__gmail__gmail_search` | Search emails with Gmail query syntax |\n| `mcp__gmail__gmail_get_thread` | Get full email thread by ID |\n| `mcp__gmail__gmail_summarize` | Get thread content formatted for summarization |\n\n### Exchange Tools\n| Tool | Purpose |\n|---|---|\n| `mcp__exchange__exchange_list_accounts` | List configured Exchange accounts |\n| `mcp__exchange__exchange_search` | Search emails with KQL syntax |\n| `mcp__exchange__exchange_get_message` | Get full message details |\n| `mcp__exchange__exchange_get_thread` | Get conversation thread |\n\n## Workflow\n\n### 1. Determine Time Period\n\nAsk the user for the date range if not specified. Common patterns:\n- \"today\" → current date\n- \"yesterday\" → previous day\n- \"this week\" → Monday to today\n- \"last week\" → previous Monday to Sunday\n- \"last 7 days\" → rolling 7 days\n- Custom range: \"from YYYY-MM-DD to YYYY-MM-DD\"\n\n### 2. List Available Accounts\n\n```\nmcp__gmail__gmail_list_accounts()\nmcp__exchange__exchange_list_accounts()\n```\n\nPresent the list and confirm which accounts to include (default: all).\n\n### 3. Fetch Emails\n\n**Gmail** (use date query syntax):\n```\nmcp__gmail__gmail_search(account=\"<name>\", query=\"after:2026/01/01 before:2026/01/08\", max_results=50, include_body=true)\n```\n\n**Exchange** (use KQL syntax):\n```\nmcp__exchange__exchange_search(account=\"<name>\", query=\"received:2026-01-01..2026-01-07\", max_results=50, include_body=true)\n```\n\n### 4. Categorize Each Email\n\nReview each email and assign to ONE category:\n\n| Category | Criteria | Examples |\n|---|---|---|\n| **Tasks** | Explicit action required, assignments, deadlines | \"Please complete by Friday\", \"Action required\", task assignments |\n| **Response Needed** | Awaiting your reply, questions directed at you | Direct questions, meeting requests pending response, approval requests |\n| **Informational** | FYI, newsletters, updates, notifications | Status updates, automated notifications, newsletters, announcements |\n| **Other** | Doesn''t fit above categories | Spam, promotional, unclear intent |\n\n### 5. Generate Summary Document\n\n**Filename convention:** `YYYY-MM-DD-email-summary.md` (use end date of range)\n\n**Output location:** `operations/emails/`\n\n**Markdown format:**\n\n```markdown\n# Email Summary: [Start Date] to [End Date]\n\n**Generated:** YYYY-MM-DD HH:MM\n**Accounts:** account1, account2, account3\n**Total Emails:** N\n\n---\n\n## Tasks That Need To Be Done\n\n| Source | From | Subject | Date | Details |\n|--------|------|---------|------|---------|\n| Gmail/Exchange | sender@example.com | Subject line | YYYY-MM-DD | Brief description of task required |\n\n### Task Details\n\n#### [Subject Line]\n- **From:** sender@example.com\n- **Date:** YYYY-MM-DD\n- **Account:** Gmail (account-name) / Exchange (account-name)\n- **Action Required:** [Clear description of what needs to be done]\n- **Deadline:** [If mentioned]\n\n---\n\n## Response Needed\n\n| Source | From | Subject | Date | Details |\n|--------|------|---------|------|---------|\n| Gmail/Exchange | sender@example.com | Subject line | YYYY-MM-DD | What response is needed |\n\n### Response Details\n\n#### [Subject Line]\n- **From:** sender@example.com\n- **Date:** YYYY-MM-DD\n- **Account:** Gmail (account-name) / Exchange (account-name)\n- **Question/Request:** [What they''re asking]\n\n---\n\n## Informational\n\n| Source | From | Subject | Date | Summary |\n|--------|------|---------|------|---------|\n| Gmail/Exchange | sender@example.com | Subject line | YYYY-MM-DD | One-line summary |\n\n---\n\n## Other\n\n| Source | From | Subject | Date | Notes |\n|--------|------|---------|------|-------|\n| Gmail/Exchange | sender@example.com | Subject line | YYYY-MM-DD | Why categorized here |\n\n---\n\n## Statistics\n\n- **Tasks:** N emails\n- **Response Needed:** N emails\n- **Informational:** N emails\n- **Other:** N emails\n```\n\n### 6. Save and Confirm\n\nWrite the file to `operations/emails/YYYY-MM-DD-email-summary.md` and confirm the path to the user.\n\n## Date Query Reference\n\n### Gmail Query Syntax\n- `after:YYYY/MM/DD` — emails after date\n- `before:YYYY/MM/DD` — emails before date\n- `newer_than:7d` — last 7 days\n- `older_than:1d` — older than 1 day\n\n### Exchange KQL Syntax\n- `received:YYYY-MM-DD` — specific date\n- `received:YYYY-MM-DD..YYYY-MM-DD` — date range\n- `received>=YYYY-MM-DD` — on or after date\n\n## Tips\n\n- **Large volumes:** If >50 emails, summarize in batches and combine.\n- **Priority emails:** Check `importance:high` (Exchange) or `is:important` (Gmail) first.\n- **Thread context:** Use `gmail_get_thread` or `exchange_get_thread` for full conversation context when categorization is unclear.\n- **Deduplication:** Emails may appear in multiple searches; dedupe by message ID.\n\n## Error Handling\n\n- Account not found → Run list accounts and verify configuration.\n- No emails in range → Confirm date format and expand range.\n- MCP not connected → Check MCP server configuration.\n"},"lastSynced":"2026-03-07T03:41:09.074Z","agentAnalysis":{"suitability":{"en":"Ideal for Productivity Agents requiring automated email processing and summarization capabilities for Gmail and Exchange accounts.","zh":"适用于需要自动化电子邮件处理和总结功能的生产力代理，支持Gmail和Exchange账户。","ja":"GmailとExchangeアカウントの自動化された電子メール処理と要約機能を必要とするProductivity Agentsに適しています。","ko":"Gmail 및 Exchange 계정에 대한 자동화된 이메일 처리 및 요약 기능이 필요한 생산성 에이전트에 적합합니다.","es":"Ideal para agentes de productividad que requieren procesamiento y resumen de correo electrónico automatizado para cuentas de Gmail y Exchange.","fr":"Idéal pour les agents de productivité nécessitant un traitement et un résumé de courrier électronique automatisés pour les comptes Gmail et Exchange.","de":"Ideal für Produktivitätsagenten, die ein automatisiertes Verarbeiten und Zusammenfassen von E-Mails für Gmail- und Exchange-Konten erfordern.","pt":"Ideal para Agentes de Produtividade que exigem processamento e resumo de e-mails automatizados para contas do Gmail e Exchange.","ru":"Идеально подходит для агентов продуктивности, требующих автоматизированной обработки и суммирования электронной почты для учетных записей Gmail и Exchange.","ar":"مثالي لعمليات وكيل الإنتاجية التي تتطلب معالجة و تلخيص البريد الإلكتروني التلقائي لبريد Gmail و Exchange."},"recommendation":{"en":"Empowers agents to streamline email management by summarizing emails, categorizing them by action type, and saving to local markdown files using Gmail query syntax and Exchange integration protocols.","zh":"使代理能够通过总结电子邮件、按操作类型对其进行分类，并使用Gmail查询语法和Exchange集成协议将其保存到本地markdown文件来简化电子邮件管理。","ja":"GmailクエリーシンタックスとExchange統合プロトコルを使用して、メールを要約し、操作タイプ別に分類し、ローカルのMarkdownファイルに保存することで、エージェントがメール管理を効率化できるようにします。","ko":"Gmail 쿼리 구문 및 Exchange 통합 프로토콜을 사용하여 이메일을 요약하고, 작업 유형별로 분류하여 로컬 Markdown 파일에 저장함으로써 에이전트가 이메일 관리를 간소화할 수 있도록 합니다.","es":"Permite a los agentes optimizar la gestión de correos electrónicos resumiendo correos electrónicos, categorizándolos por tipo de acción y guardándolos en archivos markdown locales utilizando la sintaxis de consulta de Gmail y los protocolos de integración de Exchange.","fr":"Permet aux agents de rationaliser la gestion des courriers électroniques en résumant les courriers électroniques, en les catégorisant par type d''action et en les sauvegardant dans des fichiers markdown locaux en utilisant la syntaxe de requête Gmail et les protocoles d''intégration Exchange.","de":"Ermöglicht es Agenten, die E-Mail-Verwaltung zu optimieren, indem sie E-Mails zusammenfassen, nach Aktionstyp kategorisieren und in lokale Markdown-Dateien speichern, die die Gmail-Abfragesyntax und die Exchange-Integrationssprotokolle verwenden.","pt":"Permite que os agentes otimizem a gestão de e-mails, resumindo-os, categorizando-os por tipo de ação e salvando-os em arquivos markdown locais usando a sintaxe de consulta do Gmail e protocolos de integração do Exchange.","ru":"Позволяет агентам оптимизировать управление электронной почтой, суммируя электронные письма, категоризируя их по типу действия и сохраняя в локальных файлах markdown с использованием синтаксиса запросов Gmail и протоколов интеграции Exchange.","ar":"تمكن الوكلاء من تحسين إدارة البريد الإلكتروني من خلال تلخيص البريد الإلكتروني و تصنيفه حسب نوع الإجراء و حفظه في ملفات markdown محلية باستخدام بناء جملة استعلام البريد الإلكتروني من جيميل و بروتوكولات التكامل من إكستشينج."},"useCases":{"en":["Automating email summaries for priority inbox management","Categorizing emails by action type for efficient response handling","Saving email threads to markdown files for offline reference"],"zh":["自动化电子邮件摘要以管理优先收件箱","根据操作类型对电子邮件进行分类以高效处理响应","将电子邮件线程保存到Markdown文件以供离线参考"],"ja":["優先受信トレイの管理のための自動電子メールの要約","効率的なレスポンス処理のための操作タイプ別のメールの分類","オフライン参照のためのメールスレッドをMarkdownファイルに保存"],"ko":["우선 순위 받은 편지함 관리를 위한 자동 이메일 요약","효율적인 응답 처리를 위한 작업 유형별 이메일 분류","오프라인 참조를 위한 메일 스레드를 Markdown 파일에 저장"],"es":["Automatizar resúmenes de correo electrónico para la gestión del buzón de prioridad","Categorizar correos electrónicos por tipo de acción para un manejo de respuestas eficiente","Guardar hilos de correo electrónico en archivos markdown para referencia sin conexión"],"fr":["Automatiser les résumés de courrier électronique pour la gestion du dossier de priorité","Catégoriser les courriers électroniques par type d''action pour un traitement de réponses efficace","Enregistrer les fils de courrier électronique dans des fichiers markdown pour référence hors ligne"],"de":["Automatisieren von E-Mail-Zusammenfassungen für die Verwaltung des Prioritätsposteingangs","E-Mails nach Aktionstyp kategorisieren für ein effizientes Antwort-Handling","E-Mail-Threads in Markdown-Dateien speichern für die Offline-Referenz"],"pt":["Automatizar resumos de e-mails para gestão de caixa de entrada de prioridade","Categorizar e-mails por tipo de ação para manipulação eficiente de respostas","Salvar threads de e-mails em arquivos markdown para referência offline"],"ru":["Автоматизировать суммирование электронных писем для управления приоритетной входящей почтой","Категоризировать электронные письма по типу действия для эффективного xửления ответов","Сохранять электронные письма в файлах markdown для офлайн-справки"],"ar":["تخليص تلخيص البريد الإلكتروني لادارة البريد الوارد ذات الأولوية","تصنيف البريد الإلكتروني حسب نوع الإجراء لمعالجة الاستجابة الفعالة","حفظ threads البريد الإلكتروني في ملفات markdown لمرجع غير متصل"]},"limitations":{"en":["Requires configured Gmail and Exchange accounts","Limited to saving summaries in markdown file format","Dependent on MCP tools for Gmail and Exchange integration"],"zh":["需要配置Gmail和Exchange账户","仅限保存摘要到Markdown文件格式","依赖MCP工具进行Gmail和Exchange集成"],"ja":["GmailとExchangeアカウントの設定が必要","要約をMarkdownファイル形式にのみ保存","GmailとExchangeの統合にはMCPツールに依存"],"ko":["Gmail 및 Exchange 계정 구성이 필요","요약을 Markdown 파일 형식으로만 저장","Gmail 및 Exchange 통합에는 MCP 도구에 의존"],"es":["Requiere cuentas de Gmail y Exchange configuradas","Limitado a guardar resúmenes en formato de archivo markdown","Dependiente de las herramientas MCP para la integración de Gmail y Exchange"],"fr":["Nécessite des comptes Gmail et Exchange configurés","Limité à l''enregistrement des résumés au format de fichier markdown","Dépendant des outils MCP pour l''intégration de Gmail et Exchange"],"de":["Erfordert konfigurierte Gmail- und Exchange-Konten","Begrenzt auf die Speicherung von Zusammenfassungen im Markdown-Dateiformat","Abhängig von den MCP-Tools für die Integration von Gmail und Exchange"],"pt":["Exige contas do Gmail e Exchange configuradas","Limitado a salvar resumos no formato de arquivo markdown","Dependente de ferramentas MCP para integração do Gmail e Exchange"],"ru":["Требует настроенных учетных записей Gmail и Exchange","Ограничен сохранением суммирований в формате файла markdown","Зависит от инструментов MCP для интеграции Gmail и Exchange"],"ar":["يتطلب حسابات جيميل و إكستشينج مضبوطة","محدود بحفظ الملخصات في تنسيق ملف markdown","يعتمد على أدوات MCP للتحكم في جيميل و إكستشينج"]},"version":4},"contentHash":"960566a6b8a6430fae275eb29183b95c06caf6d3d9c3f1ed8d9bff698f50a8ff","qualityScore":39}');
