INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ryanmaclean/tundra/tundra-cli-smoke', 'tundra-cli-smoke', 'ryanmaclean', 'tundra', 'community', 'tundra-cli-smoke ryanmaclean tundra community tundra-cli-smoke is a Vibecoded Rust scaffold for SAST testing and pipeline demos, benefiting developers with automated CI/CD testing and PR bot automation. Tundra CLI Smoke 是一个 Vibecoded Rust scaffold，用于 SAST 测试和 CI/CD 流程自动化 Tundra CLI Smoke は、SAST テストと CI/CD パイプライン自動化のための Vibecoded Rust scaffold です Tundra CLI Smoke 는 SAST 테스트 및 CI/CD 파이프라인 자동화를 위한 Rust 기반 scaffold 입니다 tundra-cli-smoke es un scaffold de Rust para pruebas de SAST y automatización de pipelines. Se utiliza para validar la compatibilidad de la API y el comportamiento de la CLI. tundra-cli-smoke est un scaffold Rust pour les tests de SAST et l''automatisation de pipelines. Il est utilisé pour valider la compatibilité de l''API et le comportement de la CLI. tundra-cli-smoke ist ein Rust-Scaffold für SAST-Tests und Pipeline-Automatisierung. Es wird verwendet, um die API-Kompatibilität und das CLI-Verhalten zu überprüfen. O tundra-cli-smoke é uma ferramenta de teste de SAST para pipelines e automação de PR bot com Vibecoded Rust. ИИ Агент tundra-cli-smoke - это инструмент для тестирования SAST для конвейеров и автоматизации ботов PR с помощью Vibecoded Rust. تندرا-سي-إل-إي-سموك هو أداة اختبار الساست للخطوط الأنابيب وتوضيح بوت البريد الإلكتروني باستخدام فيبيكودد روست how to use tundra-cli-smoke tundra-cli-smoke setup guide tundra-cli-smoke alternative tundra-cli-smoke vs other CI/CD tools automated SAST testing with Rust CI/CD pipeline demos with tundra-cli-smoke tundra-cli-smoke install tundra-cli-smoke tutorial Tundra CLI Smoke Vibecoded Rust scaffold SAST 测试 CI/CD 流程自动化 Rust 语言 CLI 行为变化检测 API 合同漂移验证 Runs cargo check and unit tests for at-cli Performs skill discovery and validation using cargo run Supports dry-run payload testing Validates API contract drift from the CLI side Triggers on CLI behavior changes in /Users/studio/rust-harness/crates/at-cli/ tundra-cli-smoke is a CI/CD testing tool using Rust scaffold for SAST testing, pipeline demos, and PR bot automation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('YuzhengShi/TAi/convert-to-docker', 'community', 'YuzhengShi', 'TAi', 'YuzhengShi/TAi', 'convert-to-docker', 0, 0, 39, '2026-02-23T19:13:26Z', '2026-03-07T03:44:42.940Z', '59fae12039b56627279c61082152e273c3a5585078b9b6e2ea7ecf6e6b37740c', '{"id":"YuzhengShi/TAi/convert-to-docker","name":"convert-to-docker","description":{"en":"The convert-to-docker skill migrates NanoClaw from Apple Container to Docker, enabling cross-platform support for macOS and Linux. This benefits developers seeking container runtime flexibility.","zh":"Convert to Docker 技术使 NanoClaw 从 Apple Container 迁移到 Docker，实现跨平台支持","ja":"Convert to Docker 機能は、NanoClaw を Apple Container から Docker に移行させ、クロスプラットフォーム サポートを実現します","ko":"컨테이너 마이그레이션을 위한 Convert to Docker 기능은 NanoClaw를 Apple Container에서 Docker로 전환하여 跨平台 지원을 제공합니다","es":"Convert-to-Docker migra NanoClaw de Apple Container a Docker para admitir varias plataformas. Cambia el tiempo de ejecución del contenedor y la sintaxis de montaje.","fr":"Convert-to-Docker migre NanoClaw d''Apple Container à Docker pour supporter plusieurs plateformes. Il modifie le runtime du conteneur et la syntaxe de montage.","de":"Convert-to-Docker migriert NanoClaw von Apple Container zu Docker, um mehrere Plattformen zu unterstützen. Es ändert die Containerruntime und die Mount-Syntax.","pt":"O Convert-to-Docker é um skill que migra o NanoClaw do Apple Container para o Docker, permitindo suporte a várias plataformas. Isso inclui a alteração do tempo de execução do contêiner e da sintaxe de montagem","ru":"Convert-to-Docker - это умение, которое мигрирует NanoClaw из Apple Container в Docker, обеспечивая кросс-платформенную поддержку. Это включает изменение времени выполнения контейнера и синтаксиса монтирования","ar":"Convert-to-Docker هو مهارة تنقل NanoClaw من Apple Container إلى Docker ، مما يسمح بدعم منصات متعددة. هذا يشمل تغيير وقت تشغيل الحاوية وتنسيق التثبيت"},"seo":{"title":{"en":"convert-to-docker: Docker Migration Setup Guide | AI Agen...","zh":"Convert to Docker 技术指南：跨平台支持","ja":"Docker への変換: クロスプラットフォーム サポートのためのベスト プラクティス","ko":"컨테이너 마이그레이션을 위한 Convert to Docker 가이드","es":"Guía de Configuración de Convert-to-Docker para Agentes d...","fr":"Guide de Configuration de Convert-to-Docker pour Outils d''IA","de":"Einrichtungsleitfaden für Convert-to-Docker für KI-Agents","pt":"Guia de Configuração do Convert-to-Docker para Desenvolve...","ru":"ИИ Агенты: Руководство по Настройке Convert-to-Docker","ar":"دليل إعداد Convert-to-Docker لأدوات الذكاء الاصطناعي"},"description":{"en":"Migrate NanoClaw to Docker with ease! Learn how to use convert-to-docker to switch from Apple Container to Docker for cross-platform support","zh":"了解 Convert to Docker 技术，实现从 Apple Container 到 Docker 的平滑迁移，支持跨平台部署","ja":"AIエージェントのConvert to Docker 機能を使用して、Apple Container から Docker への移行を実現し、クロスプラットフォーム サポートを向上させる","ko":"컨테이너 마이그레이션을 위한 Convert to Docker 기능을 사용하여 Apple Container에서 Docker로의 전환을 쉽게 구현하고,跨平台 지원을 향상시키세요","es":"Aprende a migrar de Apple Container a Docker con Convert-to-Docker y mejora la compatibilidad en macOS y Linux","fr":"Découvrez comment migrer d''Apple Container à Docker avec Convert-to-Docker et améliorer la compatibilité sur macOS et Linux","de":"Erfahren Sie, wie Sie mit Convert-to-Docker von Apple Container auf Docker umsteigen und die Kompatibilität auf macOS und Linux verbessern","pt":"Aprenda a migrar do Apple Container para o Docker com o skill Convert-to-Docker e melhore a compatibilidade entre plataformas","ru":"Переходите с Apple Container на Docker с помощью умения Convert-to-Docker и улучшайте кросс-платформенную совместимость","ar":"تعلم كيفية نقل البيانات من Apple Container إلى Docker باستخدام مهارة Convert-to-Docker وتحسين التوافق بين المنصات"},"definition":{"en":"convert-to-docker is a skill that migrates NanoClaw from Apple Container to Docker, changing container runtime, mount syntax, and startup checks","zh":"Convert to Docker 是一种技术，用于将 Apple Container 迁移到 Docker，实现跨平台支持","ja":"Convert to Docker は、Apple Container から Docker への移行を実現する技術であり、クロスプラットフォーム サポートを提供します","ko":"컨테이너 마이그레이션을 위한 Convert to Docker 는 Apple Container에서 Docker로의 전환을 위한 기술로 跨平台 지원을 제공합니다","es":"Convert-to-Docker es una habilidad que permite migrar aplicaciones de Apple Container a Docker para una mayor compatibilidad","fr":"Convert-to-Docker est une capacité qui permet de migrer des applications d''Apple Container à Docker pour une meilleure compatibilité","de":"Convert-to-Docker ist eine Fähigkeit, die es ermöglicht, Anwendungen von Apple Container auf Docker umzustellen, um eine bessere Kompatibilität zu erreichen","pt":"O Convert-to-Docker é um skill que permite a migração do Apple Container para o Docker","ru":"Convert-to-Docker - это умение, которое позволяет мигрировать из Apple Container в Docker","ar":"Convert-to-Docker هو مهارة يسمح بنقل البيانات من Apple Container إلى Docker"},"features":{"en":["Migrates container runtime from Apple Container to Docker","Changes mount syntax from `--mount type=bind` to `-v path:path:ro`","Replaces startup check from `container system status` to `docker info`","Updates build commands from `container build/run` to `docker build/run`","Retains existing Dockerfile compatibility"],"zh":["容器运行时从 Apple Container 到 Docker 的迁移","挂载语法从 `--mount type=bind,...,readonly` 到 `-v path:path:ro` 的转换","启动检查从 `container system status` 到 `docker info` 的更新","构建命令从 `container build/run` 到 `docker build/run` 的变更"],"ja":["コンテナランタイムのApple Container から Docker への移行","マウント構文の `--mount type=bind,...,readonly` から `-v path:path:ro` への変換","起動チェックの `container system status` から `docker info` への更新","ビルドコマンドの `container build/run` から `docker build/run` への変更"],"ko":["컨테이너 런타임의 Apple Container에서 Docker로의 전환","마운트 구문의 `--mount type=bind,...,readonly`에서 `-v path:path:ro`로의 전환","시작 점검의 `container system status`에서 `docker info`로의 업데이트","빌드 명령어의 `container build/run`에서 `docker build/run`로의 변경"],"es":["Cambio de tiempo de ejecución del contenedor de Apple Container a Docker","Actualización de la sintaxis de montaje a `-v path:path:ro`","Reemplazo de `container system status` por `docker info`","Compatibilidad con Dockerfile ya compatible con Docker"],"fr":["Changement du runtime du conteneur d''Apple Container à Docker","Mise à jour de la syntaxe de montage en `-v path:path:ro`","Remplacement de `container system status` par `docker info`","Compatibilité avec Dockerfile déjà compatible avec Docker"],"de":["Änderung der Containerruntime von Apple Container auf Docker","Aktualisierung der Mount-Syntax auf `-v path:path:ro`","Ersetzung von `container system status` durch `docker info`","Kompatibilität mit bereits Docker-kompatiblen Dockerfile"],"pt":["Migração do Apple Container para o Docker","Alteração do tempo de execução do contêiner","Alteração da sintaxe de montagem para `-v path:path:ro`","Substituição do comando `container system status` por `docker info`","Substituição dos comandos `container build/run` por `docker build/run`"],"ru":["Миграция из Apple Container в Docker","Изменение времени выполнения контейнера","Изменение синтаксиса монтирования на `-v path:path:ro`","Замена команды `container system status` на `docker info`","Замена команд `container build/run` на `docker build/run`"],"ar":["نقل البيانات من Apple Container إلى Docker","تغيير وقت تشغيل الحاوية","تغيير تنسيق التثبيت إلى `-v path:path:ro`","استبدال الأمر `container system status` بـ `docker info`","استبدال أوامر `container build/run` بـ `docker build/run`"]},"keywords":{"en":["how to use convert-to-docker","convert-to-docker setup guide","docker migration tutorial","convert-to-docker vs containerization","what is convert-to-docker","convert-to-docker install","docker cross-platform support","migrating to docker from apple container"],"zh":["Convert to Docker","容器迁移","跨平台支持","Apple Container","Docker","容器运行时","挂载语法","启动检查","构建命令"],"ja":["Docker への変換","コンテナ移行","クロスプラットフォーム サポート","AIエージェント","Apple Container","Docker","コンテナランタイム","マウント構文","起動チェック","ビルドコマンド"],"ko":["컨테이너 마이그레이션","跨平台 지원","AI 도구","Apple Container","Docker","컨테이너 런타임","마운트 구문","시작 점검","빌드 명령어","컨테이너 전환"],"es":["convert-to-docker","migrar a docker","apple container","compatibilidad de plataforma","docker para desarrolladores","agentes de ia","herramientas de ia","desarrollo de aplicaciones en docker"],"fr":["convert-to-docker","migration vers docker","apple container","compatibilité de plateforme","docker pour développeurs","outils d''ia","agents d''ia","développement d''applications en docker"],"de":["convert-to-docker","umstellung auf docker","apple container","plattformkompatibilität","docker für entwickler","ki-agents","ki-tools","anwendungsentwicklung in docker"],"pt":["Convert-to-Docker","Migração para Docker","Apple Container","NanoClaw","Desenvolvimento de software","Docker para desenvolvedores","Guia de configuração do Docker","Melhorias de compatibilidade entre plataformas"],"ru":["Convert-to-Docker","Миграция в Docker","Apple Container","NanoClaw","Разработка программного обеспечения","Docker для разработчиков","Руководство по настройке Docker","Улучшение кросс-платформенной совместимости"],"ar":["Convert-to-Docker","نقل البيانات إلى Docker","Apple Container","NanoClaw","تطوير البرمجيات","Docker لأدوات الذكاء الاصطناعي","دليل إعداد Docker","تحسين التوافق بين المنصات"]}},"owner":"YuzhengShi","repo":"TAi","repoPath":"YuzhengShi/TAi","stars":0,"forks":0,"updatedAt":"2026-02-23T19:13:26Z","topics":[],"category":"community","skillMd":{"name":"convert-to-docker","description":"Convert NanoClaw from Apple Container to Docker for cross-platform support. Use when user wants to run on Linux, switch to Docker, enable cross-platform deployment, or migrate away from Apple Container. Triggers on docker, linux support, convert to docker, cross-platform, or replace apple container.","bodyPreview":"# Convert to Docker\n\nThis skill migrates NanoClaw from Apple Container (macOS-only) to Docker for cross-platform support (macOS and Linux).\n\n**What this changes:**\n- Container runtime: Apple Container → Docker\n- Mount syntax: `--mount type=bind,...,readonly` → `-v path:path:ro`\n- Startup check: `container system status` → `docker info`\n- Build commands: `container build/run` → `docker build/run`\n\n**What stays the same:**\n- Dockerfile (already Docker-compatible)\n- Agent runner code\n- Mount securi","body":"# Convert to Docker\n\nThis skill migrates NanoClaw from Apple Container (macOS-only) to Docker for cross-platform support (macOS and Linux).\n\n**What this changes:**\n- Container runtime: Apple Container → Docker\n- Mount syntax: `--mount type=bind,...,readonly` → `-v path:path:ro`\n- Startup check: `container system status` → `docker info`\n- Build commands: `container build/run` → `docker build/run`\n\n**What stays the same:**\n- Dockerfile (already Docker-compatible)\n- Agent runner code\n- Mount security/allowlist validation\n- All other functionality\n\n## Prerequisites\n\nVerify Docker is installed before starting:\n\n```bash\ndocker --version && docker info >/dev/null 2>&1 && echo \"Docker ready\" || echo \"Install Docker first\"\n```\n\nIf Docker is not installed:\n- **macOS**: Download from https://docker.com/products/docker-desktop\n- **Linux**: `curl -fsSL https://get.docker.com | sh && sudo systemctl start docker`\n\n## 1. Update Container Runner\n\nEdit `src/container-runner.ts`:\n\n### 1a. Update module comment (around line 3)\n\n```typescript\n// Before:\n * Spawns agent execution in Apple Container and handles IPC\n\n// After:\n * Spawns agent execution in Docker container and handles IPC\n```\n\n### 1b. Update directory mount comment (around line 88)\n\n```typescript\n// Before:\n    // Apple Container only supports directory mounts, not file mounts\n\n// After:\n    // Docker bind mounts work with both files and directories\n```\n\n### 1c. Update env workaround comment (around line 120)\n\n```typescript\n// Before:\n  // Environment file directory (workaround for Apple Container -i env var bug)\n\n// After:\n  // Environment file directory (keeps credentials out of process listings)\n```\n\n### 1d. Update buildContainerArgs function\n\nReplace the entire function with Docker mount syntax:\n\n```typescript\nfunction buildContainerArgs(mounts: VolumeMount[]): string[] {\n  const args: string[] = [''run'', ''-i'', ''--rm''];\n\n  // Docker: -v with :ro suffix for readonly\n  for (const mount of mounts) {\n    if (mount.readonly) {\n      args.push(''-v'', `${mount.hostPath}:${mount.containerPath}:ro`);\n    } else {\n      args.push(''-v'', `${mount.hostPath}:${mount.containerPath}`);\n    }\n  }\n\n  args.push(CONTAINER_IMAGE);\n\n  return args;\n}\n```\n\n### 1e. Update spawn command (around line 204)\n\n```typescript\n// Before:\n    const container = spawn(''container'', containerArgs, {\n\n// After:\n    const container = spawn(''docker'', containerArgs, {\n```\n\n## 2. Update Startup Check\n\nEdit `src/index.ts`:\n\n### 2a. Replace the container system check function\n\nFind `ensureContainerSystemRunning()` and replace entirely with:\n\n```typescript\nfunction ensureDockerRunning(): void {\n  try {\n    execSync(''docker info'', { stdio: ''pipe'', timeout: 10000 });\n    logger.debug(''Docker daemon is running'');\n  } catch {\n    logger.error(''Docker daemon is not running'');\n    console.error(''\\n╔════════════════════════════════════════════════════════════════╗'');\n    console.error(''║  FATAL: Docker is not running                                  ║'');\n    console.error(''║                                                                ║'');\n    console.error(''║  Agents cannot run without Docker. To fix:                     ║'');\n    console.error(''║  macOS: Start Docker Desktop                                   ║'');\n    console.error(''║  Linux: sudo systemctl start docker                            ║'');\n    console.error(''║                                                                ║'');\n    console.error(''║  Install from: https://docker.com/products/docker-desktop      ║'');\n    console.error(''╚════════════════════════════════════════════════════════════════╝\\n'');\n    throw new Error(''Docker is required but not running'');\n  }\n}\n```\n\n### 2b. Update the function call in main()\n\n```typescript\n// Before:\n  ensureContainerSystemRunning();\n\n// After:\n  ensureDockerRunning();\n```\n\n## 3. Update Build Script\n\nEdit `container/build.sh`:\n\n### 3a. Update build command (around line 15-16)\n\n```bash\n# Before:\n# Build with Apple Container\ncontainer build -t \"${IMAGE_NAME}:${TAG}\" .\n\n# After:\n# Build with Docker\ndocker build -t \"${IMAGE_NAME}:${TAG}\" .\n```\n\n### 3b. Update test command (around line 23)\n\n```bash\n# Before:\necho \"  echo ''{...}'' | container run -i ${IMAGE_NAME}:${TAG}\"\n\n# After:\necho \"  echo ''{...}'' | docker run -i ${IMAGE_NAME}:${TAG}\"\n```\n\n## 4. Update Documentation\n\nUpdate references in documentation files:\n\n| File | Find | Replace |\n|------|------|---------|\n| `CLAUDE.md` | \"Apple Container (Linux VMs)\" | \"Docker containers\" |\n| `README.md` | \"Apple containers\" | \"Docker containers\" |\n| `README.md` | \"Apple Container\" | \"Docker\" |\n| `README.md` | Requirements section | Update to show Docker instead |\n| `docs/REQUIREMENTS.md` | \"Apple Container\" | \"Docker\" |\n| `docs/SPEC.md` | \"APPLE CONTAINER\" | \"DOCKER CONTAINER\" |\n| `docs/SPEC.md` | All Apple Container references | Docker equivalents |\n\n### Key README.md updates:\n\n**Requirements section:**\n```markdown\n## Requirements\n\n- macOS or Linux\n- Node.js 20+\n- [Claude Code](https://claude.ai/download)\n- [Docker](https://docker.com/products/docker-desktop)\n```\n\n**FAQ - \"Why Docker?\":**\n```markdown\n**Why Docker?**\n\nDocker provides cross-platform support (macOS and Linux), a large ecosystem, and mature tooling. Docker Desktop on macOS uses a lightweight Linux VM similar to other container solutions.\n```\n\n**FAQ - \"Can I run this on Linux?\":**\n```markdown\n**Can I run this on Linux?**\n\nYes. NanoClaw uses Docker, which works on both macOS and Linux. Just install Docker and run `/setup`.\n```\n\n## 5. Update Skills\n\n### 5a. Update `.claude/skills/setup/SKILL.md`\n\nReplace Section 2 \"Install Apple Container\" with Docker installation:\n\n```markdown\n## 2. Install Docker\n\nCheck if Docker is installed and running:\n\n\\`\\`\\`bash\ndocker --version && docker info >/dev/null 2>&1 && echo \"Docker is running\" || echo \"Docker not running or not installed\"\n\\`\\`\\`\n\nIf not installed or not running, tell the user:\n> Docker is required for running agents in isolated environments.\n>\n> **macOS:**\n> 1. Download Docker Desktop from https://docker.com/products/docker-desktop\n> 2. Install and start Docker Desktop\n> 3. Wait for the whale icon in the menu bar to stop animating\n>\n> **Linux:**\n> \\`\\`\\`bash\n> curl -fsSL https://get.docker.com | sh\n> sudo systemctl start docker\n> sudo usermod -aG docker $USER  # Then log out and back in\n> \\`\\`\\`\n>\n> Let me know when you''ve completed these steps.\n\nWait for user confirmation, then verify:\n\n\\`\\`\\`bash\ndocker run --rm hello-world\n\\`\\`\\`\n```\n\nUpdate build verification:\n```markdown\nVerify the build succeeded:\n\n\\`\\`\\`bash\ndocker images | grep nanoclaw-agent\necho ''{}'' | docker run -i --entrypoint /bin/echo nanoclaw-agent:latest \"Container OK\" || echo \"Container build failed\"\n\\`\\`\\`\n```\n\nUpdate troubleshooting section to reference Docker commands.\n\n### 5b. Update `.claude/skills/debug/SKILL.md`\n\nReplace all `container` commands with `docker` equivalents:\n\n| Before | After |\n|--------|-------|\n| `container run` | `docker run` |\n| `container system status` | `docker info` |\n| `container builder prune` | `docker builder prune` |\n| `container images` | `docker images` |\n| `--mount type=bind,source=...,readonly` | `-v ...:ro` |\n\nUpdate the architecture diagram header:\n```\nHost (macOS/Linux)                    Container (Docker)\n```\n\n## 6. Build and Verify\n\nAfter making all changes:\n\n```bash\n# Compile TypeScript\nnpm run build\n\n# Build Docker image\n./container/build.sh\n\n# Verify image exists\ndocker images | grep nanoclaw-agent\n```\n\n## 7. Test the Migration\n\n### 7a. Test basic container execution\n\n```bash\necho ''{}'' | docker run -i --entrypoint /bin/echo nanoclaw-agent:latest \"Container OK\"\n```\n\n### 7b. Test readonly mounts\n\n```bash\nmkdir -p /tmp/test-ro && echo \"test\" > /tmp/test-ro/file.txt\ndocker run --rm --entrypoint /bin/bash -v /tmp/test-ro:/test:ro nanoclaw-agent:latest \\\n  -c \"cat /test/file.txt && touch /test/new.txt 2>&1 || echo ''Write blocked (expected)''\"\nrm -rf /tmp/test-ro\n```\n\nExpected: Read succeeds, write fails with \"Read-only file system\".\n\n### 7c. Test read-write mounts\n\n```bash\nmkdir -p /tmp/test-rw\ndocker run --rm --entrypoint /bin/bash -v /tmp/test-rw:/test nanoclaw-agent:latest \\\n  -c \"echo ''test write'' > /test/new.txt && cat /test/new.txt\"\ncat /tmp/test-rw/new.txt && rm -rf /tmp/test-rw\n```\n\nExpected: Both operations succeed.\n\n### 7d. Full integration test\n\n```bash\nnpm run dev\n# Send @AssistantName hello via WhatsApp\n# Verify response received\n```\n\n## Troubleshooting\n\n**Docker not running:**\n- macOS: Start Docker Desktop from Applications\n- Linux: `sudo systemctl start docker`\n- Verify: `docker info`\n\n**Permission denied on Docker socket (Linux):**\n```bash\nsudo usermod -aG docker $USER\n# Log out and back in\n```\n\n**Image build fails:**\n```bash\n# Clean rebuild\ndocker builder prune -af\n./container/build.sh\n```\n\n**Container can''t write to mounted directories:**\nCheck directory permissions on the host. The container runs as uid 1000.\n\n## Summary of Changed Files\n\n| File | Type of Change |\n|------|----------------|\n| `src/container-runner.ts` | Mount syntax, spawn command, comments |\n| `src/index.ts` | Startup check function |\n| `container/build.sh` | Build and run commands |\n| `CLAUDE.md` | Quick context |\n| `README.md` | Requirements, FAQ |\n| `docs/REQUIREMENTS.md` | Architecture references |\n| `docs/SPEC.md` | Architecture diagram, tech stack |\n| `.claude/skills/setup/SKILL.md` | Installation instructions |\n| `.claude/skills/debug/SKILL.md` | Debug commands |\n"},"lastSynced":"2026-03-07T03:44:42.940Z","agentAnalysis":{"suitability":{"en":"Ideal for Cross-Platform Agents requiring seamless container runtime flexibility across macOS and Linux","zh":"适用于需要在 macOS 和 Linux 上实现无缝容器运行时灵活性的跨平台代理","ja":"macOS と Linux でシームレスなコンテナランタイムの柔軟性が必要なクロスプラットフォームエージェントに最適","ko":"macOS와 Linux에서 무중단 컨테이너 런타임 유연성이 필요한 크로스 플랫폼 에이전트에 적합","es":"Ideal para Agentes de Plataforma Cruzada que requieren flexibilidad de tiempo de ejecución de contenedor sin problemas en macOS y Linux","fr":"Idéal pour les agents de plate-forme croisée nécessitant une flexibilité de l''exécution de conteneur transparente sur macOS et Linux","de":"Ideal für Cross-Platform-Agents, die eine nahtlose Container-Laufzeitflexibilität unter macOS und Linux erfordern","pt":"Ideal para Agentes Cross-Platform que exigem flexibilidade de tempo de execução de contêiner sem interrupções em macOS e Linux","ru":"Идеально для агентов с поддержкой нескольких платформ, требующих бесшовной гибкости контейнера во время выполнения на macOS и Linux","ar":"مثالي لعميل متعدد المنصات الذي يتطلب مرونة وقت تشغيل الحاوية بدون انقطاع على نظام التشغيل macOS و Linux"},"recommendation":{"en":"Empowers agents to leverage Docker for cross-platform support, utilizing mount syntax like `-v path:path:ro` and startup checks via `docker info`, while maintaining compatibility with existing Dockerfiles and agent runner code","zh":"赋予代理使用 Docker 实现跨平台支持的能力，使用诸如 `-v path:path:ro` 的挂载语法和通过 `docker info` 进行的启动检查，同时保持与现有 Dockerfiles 和代理运行代码的兼容性","ja":"エージェントが `-v path:path:ro` のようなマウント構文や `docker info` による起動チェックを使用して Docker を利用し、既存の Dockerfile およびエージェントランナー コードとの互換性を維持しながらクロスプラットフォーム サポートを実現できるようにする","ko":"에이전트가 `-v path:path:ro`와 같은 마운트 구문 및 `docker info`를 통해 시작 확인을 사용하여 Docker를 활용하여 크로스 플랫폼 지원을 가능하게 하면서 기존 Dockerfiles 및 에이전트 런너 코드와의 호환성을 유지","es":"Habilita a los agentes a aprovechar Docker para el soporte de plataforma cruzada, utilizando la sintaxis de montaje como `-v path:path:ro` y comprobaciones de inicio a través de `docker info`, manteniendo la compatibilidad con los Dockerfiles y el código del ejecutor de agentes existentes","fr":"Permet aux agents d''utiliser Docker pour le support de plate-forme croisée, en utilisant la syntaxe de montage comme `-v path:path:ro` et les vérifications de démarrage via `docker info`, tout en maintenant la compatibilité avec les Dockerfiles et le code de l''exécuteur d''agents existants","de":"Ermächtigt die Agents, Docker für die Cross-Platform-Unterstützung zu nutzen, indem die Mount-Syntax wie `-v path:path:ro` und Startprüfungen über `docker info` verwendet werden, während die Kompatibilität mit den vorhandenen Dockerfiles und Agent-Runner-Code aufrechterhalten wird","pt":"Habilita os agentes a utilizar o Docker para suporte cross-platform, utilizando sintaxe de montagem como `-v path:path:ro` e verificações de inicialização via `docker info`, mantendo a compatibilidade com os Dockerfiles existentes e o código do agente","ru":"Предоставляет агентам возможность использовать Docker для поддержки нескольких платформ, используя синтаксис монтирования, такой как `-v path:path:ro` и проверки запуска через `docker info`, сохраняя совместимость с существующими Dockerfiles и кодом агента","ar":"تمكّن العميل من استخدام Docker لدعم منصات متعددة، باستخدام بناء الجملة المثبت مثل `-v path:path:ro` وعمليات الفحص في وقت التشغيل عبر `docker info`، مع الحفاظ على التوافق مع الملفات Docker الموجودة وكود العميل"},"useCases":{"en":["Migrating NanoClaw applications from Apple Container to Docker","Enabling cross-platform testing on macOS and Linux","Streamlining container runtime management with Docker"],"zh":["将 NanoClaw 应用从 Apple Container 迁移到 Docker","在 macOS 和 Linux 上实现跨平台测试","使用 Docker 简化容器运行时管理"],"ja":["NanoClaw アプリケーションを Apple Container から Docker に移行する","macOS と Linux でクロスプラットフォーム テストを可能にする","Docker を使用してコンテナランタイム管理を簡素化する"],"ko":["NanoClaw 애플리케이션을 Apple Container에서 Docker로 마이그레이션","macOS 및 Linux에서 크로스 플랫폼 테스트를 활성화","Docker를 사용하여 컨테이너 런타임 관리를 간소화"],"es":["Migrar aplicaciones NanoClaw de Apple Container a Docker","Habilitar pruebas de plataforma cruzada en macOS y Linux","Optimizar la administración de la ejecución de contenedores con Docker"],"fr":["Migrer des applications NanoClaw de Apple Container vers Docker","Activer les tests de plate-forme croisée sur macOS et Linux"," Rationaliser la gestion de l''exécution de conteneurs avec Docker"],"de":["NanoClaw-Anwendungen von Apple Container zu Docker migrieren","Cross-Platform-Tests auf macOS und Linux ermöglichen","Container-Laufzeitverwaltung mit Docker optimieren"],"pt":["Migrar aplicações NanoClaw do Apple Container para o Docker","Habilitar testes cross-platform em macOS e Linux","Otimizar a gestão do tempo de execução do contêiner com o Docker"],"ru":["Миграция приложений NanoClaw из Apple Container в Docker","Включение тестирования на нескольких платформах на macOS и Linux","Оптимизация управления временем выполнения контейнеров с помощью Docker"],"ar":["نقل تطبيقات NanoClaw من حاوية Apple إلى Docker","تمكين الاختبارات عبر المنصات على نظام التشغيل macOS و Linux","تبسيط إدارة وقت تشغيل الحاوية مع Docker"]},"limitations":{"en":["Requires Docker installation","Compatibility limited to macOS and Linux platforms"],"zh":["需要 Docker 安装","兼容性仅限于 macOS 和 Linux 平台"],"ja":["Docker のインストールが必要","互換性は macOS と Linux プラットフォームに限定される"],"ko":["Docker 설치가 필요","호환성은 macOS 및 Linux 플랫폼에만 제한"],"es":["Requiere instalación de Docker","Compatibilidad limitada a plataformas macOS y Linux"],"fr":["Nécessite l''installation de Docker","Compatibilité limitée aux plateformes macOS et Linux"],"de":["Benötigt Docker-Installation","Kompatibilität ist auf macOS- und Linux-Plattformen beschränkt"],"pt":["Exige instalação do Docker","Compatibilidade limitada às plataformas macOS e Linux"],"ru":["Требует установки Docker","Совместимость ограничена платформами macOS и Linux"],"ar":["يتطلب تثبيت Docker","التوافق مقيد بنظامي التشغيل macOS و Linux"]},"version":4},"contentHash":"59fae12039b56627279c61082152e273c3a5585078b9b6e2ea7ecf6e6b37740c","qualityScore":39}');
