INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('YuzhengShi/TAi/convert-to-docker', 'convert-to-docker', 'YuzhengShi', 'TAi', 'community', 'convert-to-docker YuzhengShi TAi community The convert-to-docker skill migrates NanoClaw from Apple Container to Docker, enabling cross-platform support for macOS and Linux. This benefits developers seeking container runtime flexibility. Convert to Docker 技术使 NanoClaw 从 Apple Container 迁移到 Docker，实现跨平台支持 Convert to Docker 機能は、NanoClaw を Apple Container から Docker に移行させ、クロスプラットフォーム サポートを実現します 컨테이너 마이그레이션을 위한 Convert to Docker 기능은 NanoClaw를 Apple Container에서 Docker로 전환하여 跨平台 지원을 제공합니다 Convert-to-Docker migra NanoClaw de Apple Container a Docker para admitir varias plataformas. Cambia el tiempo de ejecución del contenedor y la sintaxis de montaje. Convert-to-Docker migre NanoClaw d''Apple Container à Docker pour supporter plusieurs plateformes. Il modifie le runtime du conteneur et la syntaxe de montage. Convert-to-Docker migriert NanoClaw von Apple Container zu Docker, um mehrere Plattformen zu unterstützen. Es ändert die Containerruntime und die Mount-Syntax. O Convert-to-Docker é um skill que migra o NanoClaw do Apple Container para o Docker, permitindo suporte a várias plataformas. Isso inclui a alteração do tempo de execução do contêiner e da sintaxe de montagem Convert-to-Docker - это умение, которое мигрирует NanoClaw из Apple Container в Docker, обеспечивая кросс-платформенную поддержку. Это включает изменение времени выполнения контейнера и синтаксиса монтирования Convert-to-Docker هو مهارة تنقل NanoClaw من Apple Container إلى Docker ، مما يسمح بدعم منصات متعددة. هذا يشمل تغيير وقت تشغيل الحاوية وتنسيق التثبيت how to use convert-to-docker convert-to-docker setup guide docker migration tutorial convert-to-docker vs containerization what is convert-to-docker convert-to-docker install docker cross-platform support migrating to docker from apple container Convert to Docker 容器迁移 跨平台支持 Apple Container Docker 容器运行时 挂载语法 启动检查 构建命令 Migrates container runtime from Apple Container to Docker Changes mount syntax from `--mount type=bind` to `-v path:path:ro` Replaces startup check from `container system status` to `docker info` Updates build commands from `container build/run` to `docker build/run` Retains existing Dockerfile compatibility convert-to-docker is a skill that migrates NanoClaw from Apple Container to Docker, changing container runtime, mount syntax, and startup checks');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('charly-vibes/wai/research-review', 'community', 'charly-vibes', 'wai', 'charly-vibes/wai', 'research-review', 0, 0, 39, '2026-03-06T13:48:00Z', '2026-03-07T03:46:37.152Z', '4ee318840ca01f410a80764956493d6560948fbbb85bf2c95427696b132b5bb1', '{"id":"charly-vibes/wai/research-review","name":"research-review","description":{"en":"The research-review skill is a workflow manager for AI-driven development, enabling thorough research document reviews using the Rule of 5. It benefits AI developers and researchers by streamlining the review process.","zh":"研究审查工作流是一个基于Rule of 5的AI驱动开发工具，通过迭代的研究文档审查提高准确性和效率","ja":"研究レビューは、Rule of 5に基づくAIエージェントの開発ツールであり、反復的な研究文書のレビューにより、精度と効率を向上させます","ko":"연구 리뷰는 Rule of 5 기반의 AI 에이전트 개발 도구로서, 반복적인 연구 문서의 리뷰를 통해 정확성과 효율성을 높입니다","es":"Research-review es un gestor de flujos de trabajo para desarrollo impulsado por IA que utiliza la regla de 5 para la revisión y refinamiento iterativo de documentos de investigación","fr":"Research-review est un gestionnaire de flux de travail pour développement piloté par l''IA qui utilise la règle de 5 pour la révision et le raffinement itératif des documents de recherche","de":"Research-review ist ein Workflow-Manager für AI-getriebene Entwicklung, der die Regel von 5 für die Überprüfung und iterative Verfeinerung von Forschungsdokumenten verwendet","pt":"O research-review é um gerenciador de fluxo de trabalho para desenvolvimento dirigido por IA. Ele realiza revisões de pesquisa iterativas usando o Rule of 5.","ru":"ИИ Агент research-review является менеджером рабочего процесса для разработки, управляемой ИИ. Он выполняет итеративные обзоры исследований с помощью правила 5.","ar":"وظيفة الـ research-review هي مدير سير عمل لتنمية مدفوعة بالذكاء الاصطناعي. يقوم بإجراء مراجعات بحث متكررة باستخدام قانون 5."},"seo":{"title":{"en":"research-review: Iterative Refinement Workflow Manager fo...","zh":"研究审查工作流设置指南 - 基于Rule of 5的AI驱动开发","ja":"研究レビューの設定ガイド - Rule of 5に基づくAIエージェントの開発ワークフロー","ko":"연구 리뷰 워크플로우 설정 가이드 - Rule of 5 기반의 AI 에이전트 개발","es":"Guía de configuración para research-review: Gestión de fl...","fr":"Guide de configuration pour research-review : Gestion de ...","de":"Konfigurationsleitfaden für research-review: Workflow-Man...","pt":"Guia de Configuração do research-review para Desenvolvime...","ru":"Настройка ИИ Агента research-review для Управления Работой","ar":"دليل إعداد research-review لتنمية مدفوعة بالذكاء الاصطناعي"},"description":{"en":"Unlock efficient AI-driven development with research-review. Learn how to perform thorough research document reviews using the Rule of 5 and achieve converge...","zh":"了解研究审查工作流的设置和最佳实践，提高AI驱动开发的效率和准确性","ja":"研究レビューの設定とベストプラクティスを学び、AIエージェントの開発の効率と精度を向上させましょう","ko":"연구 리뷰 워크플로우의 설정과 최적의实践을 알아보고 AI 에이전트 개발의 효율과 정확성을 높여보세요","es":"Aprende a configurar research-review para gestionar flujos de trabajo de desarrollo impulsado por IA con nuestra guía paso a paso","fr":"Découvrez comment configurer research-review pour gérer les flux de travail de développement piloté par l''IA avec notre guide étape par étape","de":"Erfahren Sie, wie Sie research-review konfigurieren, um Workflows für AI-getriebene Entwicklung zu verwalten, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a configurar o research-review para melhorar o desenvolvimento de software com IA. Descubra como realizar revisões de pesquisa iterativas com o Rule ...","ru":"Узнайте, как настроить ИИ Агент research-review для улучшения разработки программного обеспечения с помощью ИИ. Откройте для себя, как выполнять итеративные ...","ar":"تعرف على كيفية إعداد research-review لتحسين تطوير البرمجيات بالذكاء الاصطناعي. اكتشف كيفية إجراء مراجعات بحث متكررة باستخدام قانون 5."},"definition":{"en":"research-review is a workflow management skill that performs iterative refinement of research documents using the Rule of 5, ensuring accuracy and convergence.","zh":"研究审查工作流是指使用Rule of 5的迭代研究文档审查过程，以提高AI驱动开发的准确性和效率","ja":"研究レビューとは、Rule of 5に基づく反復的な研究文書のレビュープロセスであり、AIエージェントの開発の精度と効率を向上させることを目的としています","ko":"연구 리뷰는 Rule of 5 기반의 반복적인 연구 문서의 리뷰 프로세스를 의미하며, AI 에이전트 개발의 정확성과 효율성을 높이는 것을 목적으로 합니다","es":"Research-review es un agente de IA que gestiona flujos de trabajo de desarrollo impulsado por IA mediante la revisión y refinamiento iterativo de documentos de investigación","fr":"Research-review est un agent IA qui gère les flux de travail de développement piloté par l''IA via la révision et le raffinement itératif des documents de recherche","de":"Research-review ist ein IA-Agent, der Workflows für AI-getriebene Entwicklung durch die Überprüfung und iterative Verfeinerung von Forschungsdokumenten verwaltet","pt":"O research-review é um recurso de gerenciamento de fluxo de trabalho que aplica o Rule of 5 para revisar documentos de pesquisa de forma iterativa.","ru":"ИИ Агент research-review является функцией управления рабочим процессом, которая применяет правило 5 для итеративного обзора исследовательских документов.","ar":"الـ research-review هو ميزة لإدارة سير العمل التي تطبق قانون 5 لمراجعة وثائق البحث بالتسلسل."},"features":{"en":["Performs 5 passes of review, focusing on different aspects such as accuracy and sources","Checks for convergence after each pass, starting with pass 2","Reads research documents completely if a path is provided","Asks for the research document path or lists available documents if no path is provided","Supports iterative refinement until convergence is achieved"],"zh":["基于Rule of 5的迭代研究文档审查","支持研究文档路径的提供和读取","实现5次审查过程，检查准确性和收敛性","每次审查后检查收敛性，确保结果的可靠性","提高AI驱动开发的效率和准确性"],"ja":["Rule of 5に基づく反復的な研究文書のレビュー","研究文書パスの提供と読み込みをサポート","5回のレビュープロセスを実施し、精度と収束性を確認","各レビュー後に収束性を確認し、結果の信頼性を確保","AIエージェントの開発の効率と精度を向上させる"],"ko":["Rule of 5 기반의 반복적인 연구 문서 리뷰","연구 문서 경로의 제공과 읽기를 지원","5회의 리뷰 프로세스를 수행하고, 정확성과 수렴성을 확인","각 리뷰 후에 수렴성을 확인하고, 결과의 신뢰성을 확보","AI 에이전트 개발의 효율과 정확성을 높임"],"es":["Revisión de documentos de investigación utilizando la regla de 5","Refinamiento iterativo hasta la convergencia","Compatibilidad con varios formatos de documentos de investigación","Integración con herramientas de desarrollo de IA","Gestión de flujos de trabajo personalizados para desarrollo impulsado por IA"],"fr":["Révision de documents de recherche utilisant la règle de 5","Raffinement itératif jusqu''à la convergence","Compatibilité avec plusieurs formats de documents de recherche","Intégration avec des outils de développement d''IA","Gestion de flux de travail personnalisés pour développement piloté par l''IA"],"de":["Überprüfung von Forschungsdokumenten unter Verwendung der Regel von 5","Iterative Verfeinerung bis zur Konvergenz","Unterstützung mehrerer Formate für Forschungsdokumente","Integration mit Entwicklungstools für künstliche Intelligenz","Verwaltung benutzerdefinierter Workflows für AI-getriebene Entwicklung"],"pt":["Revisão de documentos de pesquisa com o Rule of 5","Realização de 5 passes de revisão com foco em diferentes aspectos","Verificação de convergência após cada passo","Leitura completa de documentos de pesquisa","Solicitação do caminho do documento de pesquisa se não fornecido"],"ru":["Обзор исследовательских документов с помощью правила 5","Выполнение 5 проходов обзора с фокусом на разных аспектах","Проверка сходимости после каждого прохода","Полное чтение исследовательских документов","Запрос пути исследовательского документа, если он не предоставлен"],"ar":["مراجعة وثائق البحث باستخدام قانون 5","إجراء 5 مراحل من المراجعة بالتركيز على جوانب مختلفة","التحقق من التلاشي بعد كل مرحلة","قراءة كاملة لوثائق البحث","طلب مسار وثيقة البحث إذا لم يتم تقديمه"]},"keywords":{"en":["how to use research-review","what is research-review","research-review setup guide","research-review alternative","research-review vs workflow managers","install research-review","research-review for AI agents","iterative refinement workflow","Rule of 5 research review"],"zh":["研究审查工作流","AI驱动开发","Rule of 5","研究文档审查","迭代审查","准确性提高","效率提高","AI开发工具","研究审查最佳实践"],"ja":["研究レビュー","AIエージェント","Rule of 5","研究文書レビュー","反復レビュー","精度向上","効率向上","AI開発ツール","研究レビューベストプラクティス"],"ko":["연구 리뷰","AI 에이전트","Rule of 5","연구 문서 리뷰","반복 리뷰","정확성 향상","효율성 향상","AI 개발 도구","연구 리뷰 최적의实践"],"es":["agentes de IA para desarrollo","herramientas de IA para investigación","gestión de flujos de trabajo de IA","desarrollo impulsado por IA","regla de 5 para la revisión de documentos","refinamiento iterativo de documentos de investigación","integración con herramientas de desarrollo de IA"],"fr":["agents IA pour développement","outils IA pour recherche","gestion de flux de travail d''IA","développement piloté par l''IA","règle de 5 pour la révision de documents","raffinement itératif de documents de recherche","intégration avec des outils de développement d''IA"],"de":["IA-Agents für Entwicklung","IA-Tools für Forschung","Workflow-Management für künstliche Intelligenz","AI-getriebene Entwicklung","Regel von 5 für die Überprüfung von Dokumenten","iterative Verfeinerung von Forschungsdokumenten","Integration mit Entwicklungstools für künstliche Intelligenz"],"pt":["research-review","desenvolvimento dirigido por IA","gerenciamento de fluxo de trabalho","Rule of 5","revisão de documentos de pesquisa","desenvolvimento de software com IA"],"ru":["ИИ Агент research-review","разработка, управляемая ИИ","управление рабочим процессом","правило 5","обзор исследовательских документов","разработка программного обеспечения с помощью ИИ"],"ar":["الـ research-review","تنمية مدفوعة بالذكاء الاصطناعي","إدارة سير العمل","قانون 5","مراجعة وثائق البحث","تنمية البرمجيات بالذكاء الاصطناعي"]}},"owner":"charly-vibes","repo":"wai","repoPath":"charly-vibes/wai","stars":0,"forks":0,"updatedAt":"2026-03-06T13:48:00Z","topics":[],"category":"community","skillMd":{"name":"research-review","description":"Iterative review of research documents using Rule of 5","bodyPreview":"# Iterative Research Review (Rule of 5)\n\nPerform thorough research document review using the Rule of 5 - iterative refinement until convergence.\n\n## Setup\n\n**If research document path provided:** Read the document completely\n\n**If no path:** Ask for the research document path or list available research documents\n\n## Process\n\nPerform 5 passes, each focusing on different aspects. After each pass (starting with pass 2), check for convergence.\n\n### PASS 1 - Accuracy & Sources\n\n**Focus on:**\n- Claims","body":"# Iterative Research Review (Rule of 5)\n\nPerform thorough research document review using the Rule of 5 - iterative refinement until convergence.\n\n## Setup\n\n**If research document path provided:** Read the document completely\n\n**If no path:** Ask for the research document path or list available research documents\n\n## Process\n\nPerform 5 passes, each focusing on different aspects. After each pass (starting with pass 2), check for convergence.\n\n### PASS 1 - Accuracy & Sources\n\n**Focus on:**\n- Claims backed by evidence\n- Source credibility and recency\n- Correct interpretation of sources\n- Factual accuracy of technical details\n- Version/date relevance (is information outdated?)\n- Code references are correct (file:line exist and match claim)\n\n**Output format:**\n```\nPASS 1: Accuracy & Sources\n\nIssues Found:\n\n[ACC-001] [CRITICAL|HIGH|MEDIUM|LOW] - Section/Paragraph\nDescription: [What''s inaccurate or unsourced]\nEvidence: [Why this is problematic]\nRecommendation: [How to fix with specific guidance]\n\n[ACC-002] ...\n```\n\n**What to look for:**\n- \"This works by...\" without code reference\n- Claims about codebase without verification\n- Outdated information (library versions, deprecated APIs)\n- Misinterpretation of source code\n- Assumptions presented as facts\n\n### PASS 2 - Completeness & Scope\n\n**Focus on:**\n- Missing important topics or considerations\n- Unanswered questions that should be addressed\n- Gaps in the analysis\n- Scope creep (irrelevant tangents)\n- Depth appropriate for the topic\n- All research questions answered\n\n**Prefix:** COMP-001, COMP-002, etc.\n\n**What to look for:**\n- Research question asked but not answered\n- Obvious related topics not explored\n- Shallow treatment of complex topics\n- Too much detail on tangential topics\n- \"Further research needed\" without followthrough\n\n### PASS 3 - Clarity & Structure\n\n**Focus on:**\n- Logical flow and organization\n- Clear definitions of terms\n- Appropriate headings and sections\n- Readability for target audience\n- Jargon explained or avoided\n- Consistent terminology\n\n**Prefix:** CLAR-001, CLAR-002, etc.\n\n**What to look for:**\n- Jumping between topics without transitions\n- Technical terms used without definition\n- Conclusions before supporting evidence\n- Redundant sections\n- Confusing or ambiguous language\n\n### PASS 4 - Actionability & Conclusions\n\n**Focus on:**\n- Clear takeaways and recommendations\n- Conclusions supported by the research\n- Practical applicability to the project\n- Trade-offs clearly articulated\n- Next steps identified\n- Decision-making guidance provided\n\n**Prefix:** ACT-001, ACT-002, etc.\n\n**What to look for:**\n- Research without recommendations\n- Conclusions that don''t follow from findings\n- \"Interesting but...\" without actionable insight\n- Missing implementation guidance\n- No clear \"what should we do?\"\n\n### PASS 5 - Integration & Context\n\n**Focus on:**\n- Alignment with existing research\n- Connections to specs and requirements\n- Relevance to current project goals\n- Contradictions with established decisions\n- Impact on existing plans\n- References to related work\n\n**Prefix:** INT-001, INT-002, etc.\n\n**What to look for:**\n- Contradicts previous research without acknowledgment\n- Ignores existing patterns in codebase\n- Doesn''t reference related specs or docs\n- Recommendations conflict with project direction\n- Missing cross-references\n\n## Convergence Check\n\nAfter each pass (starting with pass 2), report:\n\n```\nConvergence Check After Pass [N]:\n\n1. New CRITICAL issues: [count]\n2. Total new issues this pass: [count]\n3. Total new issues previous pass: [count]\n4. Estimated false positive rate: [percentage]\n\nStatus: [CONVERGED | ITERATE | NEEDS_HUMAN]\n```\n\n**Convergence criteria:**\n- **CONVERGED**: No new CRITICAL, <10% new issues vs previous pass, <20% false positives\n- **ITERATE**: Continue to next pass\n- **NEEDS_HUMAN**: Found blocking issues requiring human judgment\n\n**If CONVERGED before Pass 5:** Stop and report final findings.\n\n## Final Report\n\nAfter convergence or completing all passes:\n\n```\n## Research Review Final Report\n\n**Research:** [path/to/research.md]\n\n### Summary\n\nTotal Issues by Severity:\n- CRITICAL: [count] - Must fix before using research\n- HIGH: [count] - Should fix before using research\n- MEDIUM: [count] - Consider addressing\n- LOW: [count] - Nice to have\n\nConvergence: Pass [N]\n\n### Top 3 Most Critical Findings\n\n1. [ACC-001] [Description] - Section [N]\n   Impact: [Why this matters]\n   Fix: [What to do]\n\n2. [COMP-003] [Description] - Section [N]\n   Impact: [Why this matters]\n   Fix: [What to do]\n\n3. [ACT-002] [Description] - Conclusions\n   Impact: [Why this matters]\n   Fix: [What to do]\n\n### Recommended Revisions\n\n1. [Action 1 - specific and actionable]\n2. [Action 2 - specific and actionable]\n3. [Action 3 - specific and actionable]\n\n### Verdict\n\n[READY | NEEDS_REVISION | NEEDS_MORE_RESEARCH]\n\n**Rationale:** [1-2 sentences explaining the verdict]\n\n### Research Quality Assessment\n\n- **Accuracy**: [Excellent|Good|Fair|Poor] - [brief comment]\n- **Completeness**: [Excellent|Good|Fair|Poor] - [brief comment]\n- **Actionability**: [Excellent|Good|Fair|Poor] - [brief comment]\n- **Clarity**: [Excellent|Good|Fair|Poor] - [brief comment]\n```\n\n## Rules\n\n1. **Be specific** - Reference sections/paragraphs, provide file:line for code claims\n2. **Verify claims** - Actually check code references and factual statements\n3. **Validate actionability** - Research should drive decisions, not just inform\n4. **Prioritize correctly**:\n   - CRITICAL: Factually wrong or misleading\n   - HIGH: Significant gaps or unclear conclusions\n   - MEDIUM: Could be clearer or more complete\n   - LOW: Minor improvements\n5. **If converged before pass 5** - Stop and report, don''t continue needlessly\n"},"lastSynced":"2026-03-07T03:46:37.152Z","agentAnalysis":{"suitability":{"en":"Perfect for Research Agents needing iterative document review and analysis using the Rule of 5.","zh":"非常适合需要使用5规则进行迭代文档审查和分析的研究代理","ja":"Rule of 5を使用した反復的な文書レビューと分析が必要な研究エージェントに最適","ko":"5규칙을 사용하여 반복적인 문서 검토 및 분석이 필요한 연구 에이전트에 적합","es":"Perfecto para Agentes de Investigación que necesitan una revisión y análisis de documentos iterativos utilizando la Regla de 5.","fr":"Parfait pour les agents de recherche nécessitant une revue et une analyse de documents itératifs en utilisant la Règle de 5.","de":"Perfekt für Forschungsagenten, die eine iterative Dokumentenprüfung und -analyse unter Verwendung der Regel von 5 benötigen.","pt":"Perfeito para Agentes de Pesquisa que necessitam de revisão e análise iterativa de documentos usando a Rule of 5.","ru":"Идеально подходит для Исследовательских Агентов, которым требуется итерационный обзор и анализ документов с использованием Rule of 5.","ar":"مثالي لوكلاء الأبحاث الذين يحتاجون إلى مراجعة وتحليل مستندات تكراري باستخدام Rule of 5."},"recommendation":{"en":"Empowers agents to perform thorough research document reviews using iterative refinement until convergence, leveraging the Rule of 5 for accuracy and sources, and streamlining the review process with automated passes.","zh":"赋予代理人使用5规则进行彻底的研究文档审查的能力，通过反复精化直到收敛，提高准确性和来源，并通过自动化流程简化审查过程","ja":"エージェントがRule of 5を使用して徹底的な研究文書のレビューを行い、収束するまで反復的に精査し、精度と情報源を高め、自動化されたパスでレビュー処理をストリームライン化する","ko":"에이전트가 5규칙을 사용하여 철저한 연구 문서의 검토를 수행하고 수렴할 때까지 반복적으로 정제하여 정확도와 출처를 높이고 자동화된 패스를 통해 검토 과정을 간소화하는 기능을 제공","es":"Habilita a los agentes a realizar revisiones exhaustivas de documentos de investigación utilizando un refinamiento iterativo hasta la convergencia, aprovechando la Regla de 5 para la precisión y las fuentes, y racionalizando el proceso de revisión con pases automatizados.","fr":"Permet aux agents d''effectuer des revues de documents de recherche approfondies en utilisant un raffinement itératif jusqu''à la convergence, en exploitant la Règle de 5 pour l''exactitude et les sources, et en rationalisant le processus de revue avec des passes automatisées.","de":"Ermöglicht es Agenten, gründliche Forschungsdokumenten-Reviews durchzuführen, indem sie ein iteratives Verfeinern bis zur Konvergenz verwenden, die Regel von 5 für Genauigkeit und Quellen nutzen und den Überprüfungsprozess mit automatisierten Durchläufen rationalisieren.","pt":"Capacita os agentes a realizar revisões completas de documentos de pesquisa usando refinamento iterativo até a convergência, aproveitando a Rule of 5 para precisão e fontes, e agilizando o processo de revisão com passagens automatizadas.","ru":"Позволяет агентам выполнять тщательный обзор исследовательских документов с использованием итерационного уточнения до достижения конвергенции, используя Rule of 5 для точности и источников, и оптимизируя процесс проверки с помощью автоматизированных проходов.","ar":"يمكّن الوكلاء من إجراء مراجعات شاملة لوثائق البحث باستخدام التحسين التكراري حتى الالتقاء، والاستفادة من Rule of 5 لتحقيق الدقة والمصادر، وتبسيط عملية المراجعة مع تمريرات آلية."},"useCases":{"en":["Automating research document review using the Rule of 5","Generating iterative refinement reports for research papers","Streamlining the review process for AI-driven development"],"zh":["使用5规则自动化研究文档审查","为研究论文生成迭代精化报告","简化AI驱动开发的审查过程"],"ja":["Rule of 5を使用した研究文書の自動化レビュー","研究論文のための反復的な精査レポートの生成","AI駆動開発のレビュー処理のストリームライン化"],"ko":["5규칙을 사용한 연구 문서 자동 검토","연구 논문에 대한 반복적인 정제 보고서 생성","AI 주도 개발의 검토 과정을 간소화"],"es":["Automatizar la revisión de documentos de investigación utilizando la Regla de 5","Generar informes de refinamiento iterativo para artículos de investigación","Racionalizar el proceso de revisión para el desarrollo impulsado por IA"],"fr":["Automatiser la revue de documents de recherche en utilisant la Règle de 5","Générer des rapports de raffinement itératif pour les articles de recherche","Rationaliser le processus de revue pour le développement piloté par l''IA"],"de":["Automatisieren der Überprüfung von Forschungsdokumenten unter Verwendung der Regel von 5","Erzeugen von Berichten zum iterativen Verfeinern für Forschungsarbeiten","Rationalisieren des Überprüfungsprozesses für die von KI angetriebene Entwicklung"],"pt":["Automatização da revisão de documentos de pesquisa usando a Rule of 5","Geração de relatórios de refinamento iterativo para artigos de pesquisa","Simplificação do processo de revisão para desenvolvimento orientado por IA"],"ru":["Автоматизация обзора исследовательских документов с использованием Rule of 5","Создание отчетов итерационного уточнения для научных статей","Оптимизация процесса проверки для разработки на основе ИИ"],"ar":["أتمتة مراجعة وثائق البحث باستخدام Rule of 5","إنشاء تقارير تحسين تكراري لأوراق البحث","تبسيط عملية المراجعة للتطوير القائم على الذكاء الاصطناعي"]},"limitations":{"en":["Requires research document path or list of available documents","Limited to 5 iterative passes"],"zh":["需要研究文档路径或可用文档列表","仅限5次迭代传递"],"ja":["研究文書のパスまたは利用可能な文書のリストが必要","5回の反復パスに限定"],"ko":["연구 문서 경로 또는 사용 가능한 문서 목록이 필요","5회 반복 패스에 제한"],"es":["Requiere ruta del documento de investigación o lista de documentos disponibles","Limitado a 5 pases iterativos"],"fr":["Nécessite le chemin du document de recherche ou la liste des documents disponibles","Limité à 5 passes itératives"],"de":["Benötigt Pfad des Forschungsdokuments oder Liste der verfügbaren Dokumente","Begrenzt auf 5 iterative Durchläufe"],"pt":["Requer o caminho do documento de pesquisa ou lista de documentos disponíveis","Limitado a 5 passagens iterativas"],"ru":["Требуется путь к исследовательскому документу или список доступных документов","Ограничено 5 итерационными проходами"],"ar":["يتطلب مسار وثيقة البحث أو قائمة الوثائق المتاحة","مقتصر على 5 تمريرات تكرارية"]},"version":4},"contentHash":"4ee318840ca01f410a80764956493d6560948fbbb85bf2c95427696b132b5bb1","qualityScore":39}');
