INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('charly-vibes/wai/research-review', 'research-review', 'charly-vibes', 'wai', 'community', 'research-review charly-vibes wai community The research-review skill is a workflow manager for AI-driven development, enabling thorough research document reviews using the Rule of 5. It benefits AI developers and researchers by streamlining the review process. 研究审查工作流是一个基于Rule of 5的AI驱动开发工具，通过迭代的研究文档审查提高准确性和效率 研究レビューは、Rule of 5に基づくAIエージェントの開発ツールであり、反復的な研究文書のレビューにより、精度と効率を向上させます 연구 리뷰는 Rule of 5 기반의 AI 에이전트 개발 도구로서, 반복적인 연구 문서의 리뷰를 통해 정확성과 효율성을 높입니다 Research-review es un gestor de flujos de trabajo para desarrollo impulsado por IA que utiliza la regla de 5 para la revisión y refinamiento iterativo de documentos de investigación Research-review est un gestionnaire de flux de travail pour développement piloté par l''IA qui utilise la règle de 5 pour la révision et le raffinement itératif des documents de recherche Research-review ist ein Workflow-Manager für AI-getriebene Entwicklung, der die Regel von 5 für die Überprüfung und iterative Verfeinerung von Forschungsdokumenten verwendet O research-review é um gerenciador de fluxo de trabalho para desenvolvimento dirigido por IA. Ele realiza revisões de pesquisa iterativas usando o Rule of 5. ИИ Агент research-review является менеджером рабочего процесса для разработки, управляемой ИИ. Он выполняет итеративные обзоры исследований с помощью правила 5. وظيفة الـ research-review هي مدير سير عمل لتنمية مدفوعة بالذكاء الاصطناعي. يقوم بإجراء مراجعات بحث متكررة باستخدام قانون 5. how to use research-review what is research-review research-review setup guide research-review alternative research-review vs workflow managers install research-review research-review for AI agents iterative refinement workflow Rule of 5 research review 研究审查工作流 AI驱动开发 Rule of 5 研究文档审查 迭代审查 准确性提高 效率提高 AI开发工具 研究审查最佳实践 Performs 5 passes of review, focusing on different aspects such as accuracy and sources Checks for convergence after each pass, starting with pass 2 Reads research documents completely if a path is provided Asks for the research document path or lists available documents if no path is provided Supports iterative refinement until convergence is achieved research-review is a workflow management skill that performs iterative refinement of research documents using the Rule of 5, ensuring accuracy and convergence.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('evengul/mc-org/docs-htmx', 'community', 'evengul', 'mc-org', 'evengul/mc-org', 'docs-htmx', 0, 0, 39, '2026-03-04T10:35:46Z', '2026-03-07T03:52:03.904Z', '8e378611757107f4c190a40f5064f815d5312f072fe98ffda0222baae8a099b8', '{"id":"evengul/mc-org/docs-htmx","name":"docs-htmx","description":{"en":"The docs-htmx skill provides HTMX helper functions and interaction patterns for efficient development. It benefits developers working with HTMX and Kotlin.","zh":"docs-htmx 提供 HTMX 模式和交互，包括 hx.kt 帮助函数和自定义组件。通过本指南了解如何设置和使用","ja":"docs-htmx は HTMX パターンとインタラクションを提供します。hx.kt ヘルパー関数とカスタムコンポーネントを含むセットアップ方法を学びましょう","ko":"docs-htmx는 HTMX 패턴 및 상호작용을 제공합니다. hx.kt 헬퍼 함수 및 사용자 지정 구성 요소를 포함하여 설정 방법을 알아보세요","es":"docs-htmx proporciona funciones de ayuda HTMX y patrones de interacción para MC-ORG. Mejora tu desarrollo con nuestras funciones hxGet, hxPost, hxPut, hxPatch y hxDelete","fr":"docs-htmx fournit des fonctions d''aide HTMX et des modèles d''interaction pour MC-ORG. Améliorez votre développement avec nos fonctions hxGet, hxPost, hxPut, hxPatch et hxDelete","de":"docs-htmx bietet HTMX-Hilfsfunktionen und Interaktionsmuster für MC-ORG. Verbessern Sie Ihre Entwicklung mit unseren Funktionen hxGet, hxPost, hxPut, hxPatch und hxDelete","pt":"O docs-htmx fornece funções de ajuda HTMX para melhorar a interação do usuário. Aprenda a configurá-lo e usá-lo.","ru":"Docs-htmx предоставляет функции HTMX для улучшения взаимодействия с пользователем. Узнайте, как его настроить и использовать.","ar":"يوفر docs-htmx وظائف مساعدة HTMX لتحسين تجربة المستخدم. تعرف على كيفية إعداده واستخدامه."},"seo":{"title":{"en":"docs-htmx: HTMX Patterns Reference for AI Agents | AI Age...","zh":"docs-htmx 设置指南：HTMX 模式和交互","ja":"docs-htmx セットアップガイド：HTMX パターンとインタラクション","ko":"docs-htmx 설정 가이드: HTMX 패턴 및 상호작용","es":"Guía de configuración de docs-htmx para desa