INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('evengul/mc-org/docs-htmx', 'docs-htmx', 'evengul', 'mc-org', 'community', 'docs-htmx evengul mc-org community The docs-htmx skill provides HTMX helper functions and interaction patterns for efficient development. It benefits developers working with HTMX and Kotlin. docs-htmx 提供 HTMX 模式和交互，包括 hx.kt 帮助函数和自定义组件。通过本指南了解如何设置和使用 docs-htmx は HTMX パターンとインタラクションを提供します。hx.kt ヘルパー関数とカスタムコンポーネントを含むセットアップ方法を学びましょう docs-htmx는 HTMX 패턴 및 상호작용을 제공합니다. hx.kt 헬퍼 함수 및 사용자 지정 구성 요소를 포함하여 설정 방법을 알아보세요 docs-htmx proporciona funciones de ayuda HTMX y patrones de interacción para MC-ORG. Mejora tu desarrollo con nuestras funciones hxGet, hxPost, hxPut, hxPatch y hxDelete docs-htmx fournit des fonctions d''aide HTMX et des modèles d''interaction pour MC-ORG. Améliorez votre développement avec nos fonctions hxGet, hxPost, hxPut, hxPatch et hxDelete docs-htmx bietet HTMX-Hilfsfunktionen und Interaktionsmuster für MC-ORG. Verbessern Sie Ihre Entwicklung mit unseren Funktionen hxGet, hxPost, hxPut, hxPatch und hxDelete O docs-htmx fornece funções de ajuda HTMX para melhorar a interação do usuário. Aprenda a configurá-lo e usá-lo. Docs-htmx предоставляет функции HTMX для улучшения взаимодействия с пользователем. Узнайте, как его настроить и использовать. يوفر docs-htmx وظائف مساعدة HTMX لتحسين تجربة المستخدم. تعرف على كيفية إعداده واستخدامه. how to use docs-htmx docs-htmx setup guide HTMX helper functions Kotlin HTMX integration docs-htmx alternative HTMX patterns reference docs-htmx HTMX 模式 hx.kt Kotlin HTTP 方法 AI 工具 HTMX 交互 自定义组件 删除确认模态框 Provides HTMX helper functions via hx.kt Supports HTTP methods like hxGet, hxPost, hxPut, hxPatch, and hxDelete Includes hxDeleteWithConfirm for delete operations with confirmation modals Utilizes Kotlin for HTMX interaction patterns Offers a reference for HTMX patterns in MC-ORG docs-htmx is a collection of HTMX helper functions and interaction patterns for MC-ORG, utilizing Kotlin for enhanced development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('created-by-forge/synchrony-social/pillar-analysis', 'community', 'created-by-forge', 'synchrony-social', 'created-by-forge/synchrony-social', 'pillar-analysis', 0, 0, 39, '2026-02-25T23:55:06Z', '2026-03-07T03:53:10.346Z', '66584ed829726a3ef3880e9b72991753321b32805e3b31a242f4f8273ec75a90', '{"id":"created-by-forge/synchrony-social/pillar-analysis","name":"pillar-analysis","description":{"en":"Pillar-analysis is a skill that analyzes a single content pillar across all platforms and time periods, providing insights into performance and areas for improvement. It benefits developers and marketers seeking to optimize their campaigns.","zh":"pillar-analysis是一种分析单个内容支柱的技术，回答如何优化其性能和哪里最有效的问题","ja":"pillar-analysisは、単一のコンテンツピラーを分析する技術であり、そのパフォーマンスを最適化し、どこで最も効果的かを回答する","ko":"pillar-analysis는 단일 콘텐츠 기둥을 분석하는 기술로, 그 성능을 최적화하고 어디서 가장 효과적인지回答","es":"Análisis de pilares es una herramienta que analiza un pilar de contenido en todas las plataformas y periodos de tiempo disponibles","fr":"L''analyse de piliers est un outil qui analyse un pilier de contenu sur toutes les plateformes et périodes de temps disponibles","de":"Die Pillar-Analyse ist ein Tool, das einen Content-Pillar auf allen Plattformen und verfügbaren Zeitperioden analysiert","pt":"A análise de pilar é uma técnica que analisa um pilar de conteúdo específico em diferentes plataformas e períodos de tempo","ru":"Анализ пилара - это метод, который анализирует отдельный контент-пилар на разных платформах и во времени","ar":"تحليل العمود هو تقنية تحليل ركن محتوى معين على منصات ومراحل زمنية مختلفة"},"seo":{"title":{"en":"Pillar-Analysis: Campaign Performance Setup Guide | AI Ag...","zh":"pillar-analysis_SETUP GUIDE: AI工具内容支柱分析","ja":"pillar-analysis_BEST PRACTICES: AIエージェントによるコンテンツピラー分析","ko":"pillar-analysis_SETUP GUIDE: AI 에이전트를 이용한 콘텐츠 기둥 분석","es":"Guía de configuración de análisis de pilares","fr":"Guide de mise en place de l''analyse de piliers","de":"Einrichtungsleitfaden für Pillar-Analyse","pt":"Guia de Configuração de Análise de Pilar","ru":"ИИ Агенты: Настройка Анализа Пилара","ar":"إعداد أداة تحليل العمود"},"description":{"en":"Unlock insights into your content pillars with pillar-analysis. Discover how to optimize campaign performance across platforms and time periods. Get started ...","zh":"了解pillar-analysis的技术细节，并发现如何分析内容支柱以优化性能","ja":"pillar-analysisの技術的側面を学び、コンテンツピラーを分析してパフォーマンスを最適化する方法を発見","ko":"pillar-analysis의 기술 세부 사항을 알아보고 콘텐츠 기둥을 분석하여 성능을 최적화하는 방법을 발견","es":"Descubre cómo analizar un pilar de contenido con nuestra herramienta de análisis de pilares y mejora tus estrategias de marketing","fr":"Découvrez comment analyser un pilier de contenu avec notre outil d''analyse de piliers et améliorez vos stratégies de marketing","de":"Erfahren Sie, wie Sie einen Content-Pillar mit unserem Pillar-Analyse-Tool analysieren und Ihre Marketingstrategien verbessern können","pt":"Aprenda a configurar a análise de pilar para otimizar suas campanhas de conteúdo em diferentes plataformas","ru":"Настройте анализ пилара с помощью ИИ Агентов, чтобы оптимизировать ваши контент-кампании на разных платформах","ar":"تعلم كيفية إعداد أداة تحليل العمود لتحسين حملاتك الترويجية على منصات متعددة"},"definition":{"en":"Pillar-analysis is a technique that evaluates the performance of a specific content pillar, providing answers to questions like ''How is this pillar performing?'' and ''What should we do differently?''","zh":"pillar-analysis是一种AI工具，用于分析内容支柱的性能和效果","ja":"pillar-analysisは、コンテンツピラーのパフォーマンスと効果を分析するAIエージェントの一種","ko":"pillar-analysis는 콘텐츠 기둥의 성능과 효과를 분석하는 AI 에이전트의 일종","es":"Análisis de pilares es una técnica que evalúa el rendimiento de un pilar de contenido en diferentes plataformas","fr":"L''analyse de piliers est une technique qui évalue les performances d''un pilier de contenu sur différentes plateformes","de":"Die Pillar-Analyse ist eine Technik, die die Leistung eines Content-Pillers auf verschiedenen Plattformen bewertet","pt":"Análise de pilar é uma técnica de análise de desempenho de conteúdo","ru":"Анализ пилара - это метод анализа эффективности контента","ar":"تحليل العمود هو تقنية لتحليل أداء المحتوى"},"features":{"en":["Loads knowledge from metric-glossary.md for ER formulas and benchmarks","Supports analysis of content pillars across multiple platforms","Provides insights into campaign performance over available time periods","Triggers analysis with user requests like ''analyze [pillar]'' or ''pillar deep dive''","Utilizes knowledge from knowledge/metric-glossary.md for informed analysis"],"zh":["分析单个内容支柱的性能","支持多个平台和时间段","使用ER公式和基准进行分析","提供内容优化建议"],"ja":["単一のコンテンツピラーのパフォーマンスを分析","複数のプラットフォームと時間帯をサポート","ER式とベンチマークを使用した分析","コンテンツ最適化の提案を提供"],"ko":["단일 콘텐츠 기둥의 성능을 분석","여러 플랫폼과 시간대를 지원","ER 수식과 벤치마크를 사용한 분석","콘텐츠 최적화 제안을 제공"],"es":["Análisis de rendimiento de un pilar de contenido en todas las plataformas","Carga de conocimientos de fórmulas ER y benchmarks","Análisis de métricas y KPIs clave","Identificación de áreas de mejora","Soporte para múltiples periodos de tiempo"],"fr":["Analyse des performances d''un pilier de contenu sur toutes les plateformes","Chargement des connaissances de formules ER et de benchmarks","Analyse de métriques et de KPI clés","Identification des domaines d''amélioration","Prise en charge de plusieurs périodes de temps"],"de":["Leistungsanalyse eines Content-Pillers auf allen Plattformen","Laden von ER-Formel- und Benchmark-Kennwissen","Analyse von Schlüsselmetriken und KPIs","Identifizierung von Verbesserungsbereichen","Unterstützung für mehrere Zeitperioden"],"pt":["Análise de desempenho de conteúdo em diferentes plataformas","Carga de conhecimento de fórmulas ER e benchmarks","Análise de pilares de conteúdo específicos","Suporte a diferentes períodos de tempo","Integração com conhecimento de métricas e glossário"],"ru":["Анализ эффективности контента на разных платформах","Загрузка знаний о формулах ER и бенчмарках","Анализ отдельных контент-пиларов","Поддержка разных периодов времени","Интеграция с знаниями о метриках и глоссарии"],"ar":["تحليل أداء المحتوى على منصات متعددة","تحميل معرفة الصيغ ER والمراجع","تحليل أركان المحتوى المحددة","دعم الفترات الزمنية المختلفة","التكامل مع معرفة المetrics والقواميس"]},"keywords":{"en":["how to use pillar-analysis","what is pillar-analysis","pillar-analysis alternative","pillar-analysis vs competitor","pillar-analysis install","pillar-analysis setup guide","content pillar optimization","campaign performance analysis"],"zh":["pillar-analysis","AI工具","内容支柱分析","性能优化","ER公式","基准分析"],"ja":["pillar-analysis","AIエージェント","コンテンツピラー分析","パフォーマンス最適化","ER式","ベンチマーク分析"],"ko":["pillar-analysis","AI 에이전트","콘텐츠 기둥 분석","성능 최적화","ER 수식","벤치마크 분석"],"es":["análisis de pilares","herramienta de análisis de contenido","marketing de contenido","estrategias de marketing","análisis de rendimiento","métricas de marketing","KPIs de marketing"],"fr":["analyse de piliers","outil d''analyse de contenu","marketing de contenu","stratégies de marketing","analyse de performances","métriques de marketing","KPI de marketing"],"de":["Pillar-Analyse","Content-Analyse-Tool","Content-Marketing","Marketingstrategien","Leistungsanalyse","Marketing-Metriken","Marketing-KPIs"],"pt":["análise de pilar","otimização de conteúdo","análise de desempenho","plataformas de conteúdo","fórmulas ER","benchmarks","conhecimento de métricas","glossário"],"ru":["анализ пилара","оптимизация контента","анализ эффективности","платформы контента","формулы ER","бенчмарки","знания о метриках","глоссарий"],"ar":["تحليل العمود","تحسين المحتوى","تحليل الأداء","منصات المحتوى","صيغ ER","المراجع","معرفة المetrics","القواميس"]}},"owner":"created-by-forge","repo":"synchrony-social","repoPath":"created-by-forge/synchrony-social","stars":0,"forks":0,"updatedAt":"2026-02-25T23:55:06Z","topics":[],"category":"community","skillMd":{"name":"pillar-analysis","description":"Deep dive into a single content pillars performance across all platforms and reporting periods. Shows how the same pillar performs differently on each surface, identifies format and platform fit, and provides coaching on strategic direction per the clients pillar goals.","bodyPreview":"# Pillar Analysis\n\nAnalyzes a single content pillar (campaign) across all platforms and available time periods. Answers: \"How is this pillar performing? Where does it work best? What should we do differently?\"\n\n---\n\n## Trigger\n\nUser says: \"analyze [pillar]\", \"how is Stay Gold doing?\", \"pillar deep dive on Money Talks\", \"pillar analysis\", or any request focused on a specific content pillar.\n\n---\n\n## Step 0: Load Knowledge\n\n1. `knowledge/metric-glossary.md` — ER formulas, benchmarks\n2. `knowledge/","body":"# Pillar Analysis\n\nAnalyzes a single content pillar (campaign) across all platforms and available time periods. Answers: \"How is this pillar performing? Where does it work best? What should we do differently?\"\n\n---\n\n## Trigger\n\nUser says: \"analyze [pillar]\", \"how is Stay Gold doing?\", \"pillar deep dive on Money Talks\", \"pillar analysis\", or any request focused on a specific content pillar.\n\n---\n\n## Step 0: Load Knowledge\n\n1. `knowledge/metric-glossary.md` — ER formulas, benchmarks\n2. `knowledge/platform-behavior.md` — Why a pillar may perform differently per platform\n3. `knowledge/engagement-taxonomy.md` — Behavioral signal interpretation\n4. `knowledge/format-playbook.md` — Format-to-pillar strategy mapping (has recommended formats per pillar)\n\nAlso load the pillar''s strategic context:\n5. Check `docs/synchrony/q2-2026-pillar-goals.md` for the client''s stated direction for this pillar\n6. Check `docs/synchrony/signals/corrections.md` for any corrections related to this pillar\n7. Check `docs/synchrony/signals/wins.md` for any wins related to this pillar\n\n---\n\n## Step 1: Identify the Pillar\n\n1. Map the user''s input to a canonical campaign slug from the `campaigns` table\n2. If ambiguous, query all campaigns and present options\n3. Pull the campaign record:\n```sql\nSELECT * FROM campaigns WHERE slug = $1;\n```\n\n---\n\n## Step 2: Pull All Data for This Pillar\n\n### 2a. All posts ever published for this pillar\n```sql\nSELECT p.*, rp.name as period_name, rp.start_date, rp.end_date\nFROM posts p\nJOIN reporting_periods rp ON p.reporting_period_id = rp.id\nWHERE p.campaign_id = $1\nORDER BY p.platform, p.published_at;\n```\n\n### 2b. Campaign period summaries across all periods and platforms\n```sql\nSELECT cps.*, rp.name as period_name\nFROM campaign_period_summaries cps\nJOIN reporting_periods rp ON cps.reporting_period_id = rp.id\nWHERE cps.campaign_id = $1\nORDER BY rp.start_date, cps.platform;\n```\n\n### 2c. Platform benchmarks for comparison\n```sql\nSELECT pb.*, rp.name as period_name\nFROM platform_benchmarks pb\nJOIN reporting_periods rp ON pb.reporting_period_id = rp.id\nORDER BY rp.start_date, pb.platform;\n```\n\n### 2d. Campaign notes for this pillar\n```sql\nSELECT * FROM campaign_notes\nWHERE campaign_id = $1\nORDER BY source_date DESC;\n```\n\n---\n\n## Step 3: Pillar Identity Card\n\nPresent a quick reference card:\n\n```\n## [Pillar Name]\n\n**Strategic Goal:** [from q2-2026-pillar-goals.md or campaigns.strategy]\n**Tone/Voice:** [from campaigns.tone_voice if set]\n**Status:** [active/paused/retired/proposed]\n**Total Posts (all time):** X across Y platforms\n**Active Platforms:** [list platforms with post counts]\n```\n\n---\n\n## Step 4: Cross-Platform Performance Comparison\n\nShow how this pillar performs on each platform it''s published on:\n\n| Platform | Posts | Avg ER | Avg ER (excl cmts) | Avg Views | Avg Reach | Benchmark ER | vs Benchmark |\n|---|---|---|---|---|---|---|---|\n\nFor each platform row, add a coaching note:\n\n- **Above benchmark:** \"This pillar is outperforming the platform average — the content-platform fit is strong. [Explain why based on platform behavior knowledge]\"\n- **At benchmark:** \"Performing in line with the platform average — the content is solid. To push it higher, consider [format or approach suggestion].\"\n- **Below benchmark:** \"This pillar is performing below the platform average. This isn''t necessarily a concern — [explain why: new pillar, experimental format, wrong platform fit, etc.]. Worth exploring: [specific suggestion].\"\n\n---\n\n## Step 5: Platform-Specific Breakdown\n\nFor each platform this pillar publishes on:\n\n### [Platform Name]\n\n**Post Inventory:**\n| Date | Format | Views | Reach | ER | Saves | Shares | [Platform-specific] |\n|---|---|---|---|---|---|---|---|\n\n**Engagement Mix Analysis:**\n- Total saves vs shares vs comments ratio\n- What the mix tells us about audience response (utility? resonance? conversation?)\n- Reference `engagement-taxonomy.md` for interpretation\n\n**Format Analysis (if multiple formats used):**\n- Which format performed better for this pillar on this platform?\n- Does the data support the recommended format from `format-playbook.md`?\n\n**Follower/Non-Follower Analysis:**\n- Average split for this pillar vs platform average\n- Is this pillar driving discovery (high non-follower) or deepening loyalty (high follower)?\n\n---\n\n## Step 6: Time-Series Analysis (if multiple periods available)\n\nIf data exists for 2+ reporting periods:\n\n### MoM Performance Trend\n| Period | Platform | Posts | Avg ER | Total Engagements | Total Views |\n|---|---|---|---|---|---|\n\n**Direction:** Is this pillar trending up, flat, or declining?\n\n**Correlation analysis:**\n- Did any content changes correlate with metric shifts? (Format change? Copy approach? Posting cadence?)\n- Did any client corrections from the corrections log impact performance? (e.g., \"After correcting to ''financing partner'' language, ER moved from X to Y\")\n- Were there external factors? (Algorithm changes, seasonal effects, posting time changes)\n\n**Coaching note:** Frame the trend within the available data horizon:\n- 2 months: \"Early direction — [observation]. Let''s watch this for another month before drawing conclusions.\"\n- 3+ months: \"We''re seeing a trend — [observation]. This is significant enough to [act on / investigate / celebrate].\"\n\n---\n\n## Step 7: Client Intelligence Integration\n\nPull relevant signals from the vault:\n\n### Corrections Related to This Pillar\n- Summarize any language corrections, positioning feedback, or creative direction from `corrections.md`\n- Note if corrections have been applied in recent posts\n\n### Wins Related to This Pillar\n- Summarize any positive signals, compliments, alignment from `wins.md`\n- Connect wins to specific post performance where possible\n\n### Strategic Direction\n- Summarize the client''s Q2 goals for this pillar from `q2-2026-pillar-goals.md`\n- Assess: Is the current performance aligned with where the client wants this pillar to go?\n\n---\n\n## Step 8: Recommendations\n\nSynthesize everything into 3-5 recommendations for this pillar:\n\nFor each recommendation:\n```\n**Observation:** [What the data shows — factual, neutral]\n**Platform context:** [Why this matters on [platform] specifically]\n**Client context:** [How this connects to the client''s stated goals or corrections]\n**Worth exploring:** [Specific action to test]\n```\n\nRecommendation categories:\n- **Platform fit:** Should this pillar be on all its current platforms, or would it perform better focused on fewer?\n- **Format optimization:** Is the current format mix optimal, or should it shift?\n- **Content approach:** What does the engagement mix suggest about content adjustments?\n- **Cadence:** Is the posting frequency right for this pillar on each platform?\n- **Strategic alignment:** Is the pillar''s actual performance matching its strategic intent?\n\n---\n\n## Step 9: Next Steps\n\n```\nWant me to:\n- Compare this to another pillar? `/pillar-analysis [other pillar]`\n- See the full platform picture? `/platform-pulse [platform]`\n- Generate a content brief for this pillar? `/content-brief [pillar]`\n- Check for multi-month trends? `/trend-report`\n```\n\n---\n\n## Important Rules\n\n1. **Always reference the client''s strategic goal for the pillar.** Performance without strategic context is meaningless.\n2. **Compare to platform benchmarks, not other pillars.** Each pillar has a different purpose — Stay Gold (awareness) shouldn''t be judged by the same ER standard as Engagement (interaction).\n3. **Integrate vault intelligence.** Corrections, wins, and goals from the Obsidian vault are as important as the metrics.\n4. **Frame underperformance as learning.** \"MTIBF isn''t working\" (from client feedback) should be explored analytically — what specifically about it isn''t landing, and what does the data suggest trying?\n5. **Think format × platform.** A pillar may need different formats on different platforms. Carousel for IG Feed (education), Reel for YouTube (discovery), Poll for Stories (interaction).\n"},"lastSynced":"2026-03-07T03:53:10.346Z","agentAnalysis":{"suitability":{"en":"Perfect for Data Analysis Agents needing cross-platform content performance insights.","zh":"非常适合需要跨平台内容性能洞察的数据分析代理。","ja":"クロスプラットフォームのコンテンツパフォーマンスの洞察が必要なデータ分析エージェントに最適です。","ko":"크로스 플랫폼 콘텐츠 성능 분석이 필요한 데이터 분석 에이전트에게 적합합니다.","es":"Perfecto para agentes de análisis de datos que necesitan información sobre el rendimiento de contenido entre plataformas.","fr":"Parfait pour les agents d''analyse de données nécessitant des informations sur les performances de contenu multiplateformes.","de":"Perfekt für Data-Analytics-Agents, die cross-plattformübergreifende Inhaltsleistungsanalysen benötigen.","pt":"Perfeito para Agentes de Análise de Dados que necessitam de insights de desempenho de conteúdo cross-plataforma.","ru":"Идеально для агентов анализа данных, которым необходимы межплатформенные сведения о производительности контента.","ar":"مثالي لوكلاء تحليل البيانات الذين يحتاجون إلى رؤى أداء المحتوى عبر منصات متعددة."},"recommendation":{"en":"Empowers agents to analyze content pillars across multiple platforms and time periods, providing actionable insights using ER formulas and benchmarks, and leveraging knowledge from metric glossaries.","zh":"赋予代理分析跨多个平台和时间段的内容支柱的能力，利用 ER 公式和基准提供可行的洞察，并利用指标词典的知识。","ja":"複数のプラットフォームと期間を横断してコンテンツピラーを分析するエージェントをEmpowerし、ER式とベンチマークを使用して実行可能な洞察を提供し、メトリクス用語集の知識を活用します。","ko":"複수 플랫폼 및 기간을 걸쳐 콘텐츠 기둥을 분석할 수 있는 에이전트를 강화하여 ER 수식 및 벤치마크를 사용하여 실행 가능한 통찰력을 제공하고 메트릭 사전의 지식을 활용합니다.","es":"Habilita a los agentes a analizar pilares de contenido en varias plataformas y períodos de tiempo, proporcionando información accionable utilizando fórmulas ER y puntos de referencia, y aprovechando conocimientos de glosarios de métricas.","fr":"Permet aux agents d''analyser les piliers de contenu sur plusieurs plateformes et périodes de temps, fournissant des informations exploitables à l''aide de formules ER et de références, et exploitant les connaissances des glossaires de métriques.","de":"Ermächtigt Agenten, Inhalts-Säulen über mehrere Plattformen und Zeiträume hinweg zu analysieren und handhabbare Erkenntnisse unter Verwendung von ER-Formeln und Benchmark-Werten bereitzustellen, und nutzt Wissen aus Metric-Glossaren.","pt":"Habilita os agentes a analisar pilares de conteúdo em várias plataformas e períodos de tempo, fornecendo insights ação utilizando fórmulas ER e benchmarks, e aproveitando o conhecimento de glossários de métricas.","ru":"Наделяет агентов возможностью анализировать столпы контента на нескольких платформах и за разные периоды времени, предоставляя действенные сведения с использованием формул ER и эталонов, а также используя знания из глоссариев метрик.","ar":"يمنح الوكلاء khảية تحليل أعمدة المحتوى عبر منصات متعددة وفترات زمنية، وتقديم رؤى قابلة للتنفيذ باستخدام صيغ ER والمقاييس، وتفعيل المعرفة من قواميس المقاييس."},"useCases":{"en":["Analyzing campaign performance","Identifying top-performing platforms","Informing data-driven marketing strategies"],"zh":["分析活动表现","确定顶级表现平台","为数据驱动的营销策略提供信息"],"ja":["キャンペーンのパフォーマンスを分析する","トップパフォーマンスのプラットフォームを特定する","データ駆動型のマーケティング戦略に情報を提供する"],"ko":["캠페인 성과 분석","최상위 성과 플랫폼 식별","데이터 주도 마케팅 전략에 대한 정보 제공"],"es":["Análisis del rendimiento de las campañas","Identificación de las plataformas con mejor rendimiento","Información de estrategias de marketing basadas en datos"],"fr":["Analyse des performances des campagnes","Identification des plateformes à haut rendement","Information des stratégies de marketing basées sur les données"],"de":["Analyse der Kampagnenleistung","Identifizierung der leistungsstärksten Plattformen","Informieren datengetriebener Marketingstrategien"],"pt":["Analisar o desempenho da campanha","Identificar plataformas de alto desempenho","Informar estratégias de marketing baseadas em dados"],"ru":["Анализ производительности кампании","Определение платформ с высоким производительностью","Информирование маркетинговых стратегий на основе данных"],"ar":["تحليل أداء الحملة","تحديد المنصات ذات الأداء العالي","إعلام استراتيجيات التسويق القائمة على البيانات"]},"limitations":{"en":["Requires access to content metrics and benchmarks","Limited to analyzing single content pillars"],"zh":["需要访问内容指标和基准","仅限分析单个内容支柱"],"ja":["コンテンツメトリクスとベンチマークへのアクセスが必要","単一のコンテンツピラーの分析のみ"],"ko":["콘텐츠 메트릭 및 벤치마크에 대한 액세스 필요","단일 콘텐츠 기둥 분석만 제한"],"es":["Requiere acceso a métricas de contenido y puntos de referencia","Limitado a analizar pilares de contenido individuales"],"fr":["Nécessite un accès aux métriques de contenu et aux références","Limité à l''analyse de piliers de contenu individuels"],"de":["Benötigt Zugriff auf Inhaltsmetriken und Benchmark-Werte","Eingeschränkt auf die Analyse einzelner Inhalts-Säulen"],"pt":["Exige acesso às métricas e benchmarks de conteúdo","Limitado à análise de pilares de conteúdo único"],"ru":["Требует доступа к метрикам и эталонам контента","Ограничен анализом единственного столпа контента"],"ar":["يتطلب الوصول إلى مقاييس ومقاييس المحتوى","محدود بتحليل عمود محتوى واحد"]},"version":4},"contentHash":"66584ed829726a3ef3880e9b72991753321b32805e3b31a242f4f8273ec75a90","qualityScore":39}');
